window.QUESTIONS = [{"id": "H28_kouki_01", "source": "H28後 No.1", "category": "一般基礎", "type": "single", "question": "次の指標のうち、室内空気環境と関係のないものはどれか。", "choices": [{"label": "1", "text": "新有効温度(ET*)"}, {"label": "2", "text": "揮発性有機化合物(VOCs)濃度"}, {"label": "3", "text": "化学的酸素要求量(COD)"}, {"label": "4", "text": "作用温度(OT)"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["化学的酸素要求量(COD)"], "answerHints": [["化学的酸素要求量(COD)"]], "mnemonic": "CODは水質（水の汚れ）の指標。ET*・VOCs・OTが室内空気環境の指標。", "block": 1, "group": 1}, {"id": "H28_kouki_04", "source": "H28後 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "熱が低温の物体から高温の物体へ自然に移ることはない。"}, {"label": "2", "text": "真空中では、熱放射による熱エネルギーの移動はない。"}, {"label": "3", "text": "0°Cの氷が0°Cの水になるために必要な熱は潜熱である。"}, {"label": "4", "text": "物体の温度を1°C上げるのに必要な熱量を熱容量という。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["真空中では、熱放射による熱エネルギーの移動はない。"], "answerHints": [["移動はない"]], "mnemonic": "正しくは：熱放射は物質を介さないので、真空中でも熱エネルギーが移動する。", "block": 1, "group": 1}, {"id": "H29_kouki_01", "source": "H29後 No.1", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "空気中に含むことのできる水蒸気量は、温度が高くなるほど多くなる。"}, {"label": "2", "text": "飽和湿り空気の相対湿度は、100%である。"}, {"label": "3", "text": "露点温度は、その空気と同じ絶対湿度をもつ飽和空気の温度である。"}, {"label": "4", "text": "絶対湿度は、湿り空気中の水蒸気の質量と湿り空気の質量の比である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["絶対湿度は、湿り空気中の水蒸気の質量と湿り空気の質量の比である。"], "answerHints": [["湿り空気の質量の比"]], "mnemonic": "正しくは：絶対湿度は、水蒸気の質量と「乾き空気」の質量の比。", "block": 1, "group": 1}, {"id": "H29_kouki_04", "source": "H29後 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "物質内部に温度差があるとき、温度が高い方から低い方に熱エネルギーが移動する現象を熱伝導という。"}, {"label": "2", "text": "気体を断熱圧縮した場合、温度は変化しない。"}, {"label": "3", "text": "熱放射による熱エネルギーの移動には、熱を伝える物質は不要である。"}, {"label": "4", "text": "体積を一定に保ったまま気体を冷却した場合、圧力は低くなる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["気体を断熱圧縮した場合、温度は変化しない。"], "answerHints": [["温度は変化しない"]], "mnemonic": "正しくは：断熱圧縮すると気体の温度は上昇する。", "block": 1, "group": 1}, {"id": "H30_zenki_02", "source": "H30前 No.2", "category": "一般基礎", "type": "single", "question": "水に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "1気圧における水の密度は、0°Cの氷の密度より大きい。"}, {"label": "2", "text": "1気圧における空気の水に対する溶解度は、温度上昇とともに増加する。"}, {"label": "3", "text": "pHが7である水は、中性である。"}, {"label": "4", "text": "DOは、水中に溶けている酸素の量である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["1気圧における空気の水に対する溶解度は、温度上昇とともに増加する。"], "answerHints": [["増加する"]], "mnemonic": "正しくは：空気の水への溶解度は、温度が上がると減少する。", "block": 1, "group": 1}, {"id": "H30_zenki_06", "source": "H30前 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート造の鉄筋工事に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "鉄筋のかぶり厚さは、建築基準法に定められている。"}, {"label": "2", "text": "鉄筋のかぶり厚さが大きくなると、一般的に、鉄筋コンクリートの耐久性が高くなる。"}, {"label": "3", "text": "現場での鉄筋の折曲げ加工は、加熱して行う。"}, {"label": "4", "text": "鉄筋の継手は、一か所への集中を避け、応力の小さいところに設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["現場での鉄筋の折曲げ加工は、加熱して行う。"], "answerHints": [["加熱して行う"]], "mnemonic": "正しくは：鉄筋の折曲げ加工は常温（冷間）で行う。", "block": 1, "group": 1}, {"id": "H28_kouki_10", "source": "H28後 No.10", "category": "空調・衛生", "type": "single", "question": "ろ過式エアフィルターのろ材に求められる特性として、適当でないものはどれか。", "choices": [{"label": "1", "text": "空気抵抗が大きいこと。"}, {"label": "2", "text": "吸湿性が小さいこと。"}, {"label": "3", "text": "腐食及びかびの発生が少ないこと。"}, {"label": "4", "text": "難燃性又は不燃性であること。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["空気抵抗が大きいこと。"], "answerHints": [["大きい"]], "mnemonic": "正しくは：ろ材の空気抵抗は小さいこと。", "block": 1, "group": 1}, {"id": "H28_kouki_13", "source": "H28後 No.13", "category": "空調・衛生", "type": "single", "question": "換気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "厨房の換気に、給排気側にそれぞれ送風機を設けた。"}, {"label": "2", "text": "ボイラー室の換気に、給排気側にそれぞれ送風機を設けた。"}, {"label": "3", "text": "便所や浴室の換気に、排気側のみに送風機を設けた。"}, {"label": "4", "text": "有害なガスが発生する部屋の換気に、給気側のみに送風機を設けた。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["有害なガスが発生する部屋の換気に、給気側のみに送風機を設けた。"], "answerHints": [["給気側のみ"]], "mnemonic": "正しくは：有害ガスが出る部屋は排気側のみに送風機（第3種換気・負圧）で外に漏らさない。", "block": 1, "group": 1}, {"id": "H28_kouki_18", "source": "H28後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する文中、 内に当てはまる数値、用語の組合せとして、適当なものはどれか。\nガス瞬間湯沸器の能力は、一般に号数で呼ばれ、水温の上昇温度を A °Cとした場\n合の出湯量1L/minを1号としている。住宅のシャワーなどへの給湯用には、 B が適している。\n--(A)------(B)", "choices": [{"label": "1", "text": "15-----元止め式"}, {"label": "2", "text": "25-----元止め式"}, {"label": "3", "text": "15-----先止め式"}, {"label": "4", "text": "25-----先止め式"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["25-----先止め式"], "answerHints": [["25", "先止め式"]], "mnemonic": "号数＝水温25℃上昇で1L/minが1号。シャワー等の給湯は先止め式。", "block": 1, "group": 1}, {"id": "H28_kouki_21", "source": "H28後 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋内消火栓設備には、非常電源を設ける。"}, {"label": "2", "text": "屋内消火栓箱の上部には、設置の標示のために赤色の灯火を設ける。"}, {"label": "3", "text": "広範囲型を除く2号消火栓は、防火対象物の階ごとに、その階の各部分からの水平距離が25m以下となるように設置する。"}, {"label": "4", "text": "屋内消火栓の開閉弁は、自動式のものでない場合、床面からの高さが 1.5m以下の位置に設置する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["広範囲型を除く2号消火栓は、防火対象物の階ごとに、その階の各部分からの水平距離が25m以下となるように設置する。"], "answerHints": [["25m以下"]], "mnemonic": "正しくは：広範囲型を除く2号消火栓は水平距離15m以下（1号・広範囲型2号が25m以下）。", "block": 1, "group": 1}, {"id": "H29_kouki_08", "source": "H29後 No.8", "category": "空調・衛生", "type": "single", "question": "変風量単一ダクト方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "部屋ごとに個別制御が可能である。"}, {"label": "2", "text": "送風量の減少時においても必要外気量を確保する必要がある。"}, {"label": "3", "text": "定風量単一ダクト方式に比べて搬送エネルギーが大きくなる。"}, {"label": "4", "text": "室内の気流分布が悪くならないように最小風量設定が必要となる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["定風量単一ダクト方式に比べて搬送エネルギーが大きくなる。"], "answerHints": [["大きくなる"]], "mnemonic": "正しくは：変風量方式は送風量を絞れるので、定風量方式より搬送エネルギーが小さい。", "block": 1, "group": 1}, {"id": "H29_kouki_11", "source": "H29後 No.11", "category": "空調・衛生", "type": "single", "question": "空冷ヒートポンプパッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋外機と屋内機の設置場所の高低差には制限がある。"}, {"label": "2", "text": "暖房運転において、外気温度が低いときには屋外機コイルに霜が付着することがある。"}, {"label": "3", "text": "冷房の場合、外気温度が高いほど成績係数が向上する。"}, {"label": "4", "text": "ガスエンジンヒートポンプ方式は、圧縮機の駆動機としてガスエンジンを使用するものである。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["冷房の場合、外気温度が高いほど成績係数が向上する。"], "answerHints": [["向上する"]], "mnemonic": "正しくは：冷房時、外気温度が高いほど成績係数は低下する。", "block": 1, "group": 1}, {"id": "H29_kouki_14", "source": "H29後 No.14", "category": "空調・衛生", "type": "single", "question": "換気方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "第一種機械換気方式では、換気対象室内の圧力の制御を容易に行うことができる。"}, {"label": "2", "text": "第二種機械換気方式では、換気対象室内の圧力は正圧となる。"}, {"label": "3", "text": "第三種機械換気方式では、換気対象室内の圧力は負圧となる。"}, {"label": "4", "text": "温度差を利用する自然換気方式では、換気対象室のなるべく高い位置に給気口を設ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["温度差を利用する自然換気方式では、換気対象室のなるべく高い位置に給気口を設ける。"], "answerHints": [["高い位置に給気口"]], "mnemonic": "正しくは：温度差換気は低い位置に給気口、高い位置に排気口。", "block": 1, "group": 1}, {"id": "H29_kouki_17", "source": "H29後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水道直結方式は、高置タンク方式に比べて、水質汚染の可能性が高い。"}, {"label": "2", "text": "高置タンク方式の揚水ポンプは、一般的に、水道直結増圧ポンプに比べて、送水量は小さくできる。"}, {"label": "3", "text": "高置タンク方式で重力により給水する場合、高置タンクの高さは、最上階器具等の必要給水圧力が確保できるよう決定する。"}, {"label": "4", "text": "受水タンクの上部には、原則として、飲料水以外の配管を設けてはならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水道直結方式は、高置タンク方式に比べて、水質汚染の可能性が高い。"], "answerHints": [["可能性が高い"]], "mnemonic": "正しくは：水道直結方式はタンクを経由しないので、水質汚染の可能性が低い。", "block": 1, "group": 1}, {"id": "H29_kouki_22", "source": "H29後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液化石油ガス(LPG)は、調整器により3.3~2.3 kPa に減圧されて供給される。"}, {"label": "2", "text": "液化石油ガス(LPG)用のガス漏れ警報器の有効期間は、8年である。"}, {"label": "3", "text": "液化石油ガス(LPG)のバルク供給方式は、一般的に、工場などに用いられる"}, {"label": "4", "text": "液化石油ガス(LPG)は、空気より重い。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化石油ガス(LPG)用のガス漏れ警報器の有効期間は、8年である。"], "answerHints": [["8年"]], "mnemonic": "正しくは：LPG用ガス漏れ警報器の有効期間は5年。", "block": 1, "group": 1}, {"id": "H30_zenki_09", "source": "H30前 No.9", "category": "空調・衛生", "type": "single", "question": "冷房の熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "照明器具による熱負荷は、顕熱のみである。"}, {"label": "2", "text": "人体や事務機器からの負荷を室内負荷として考慮する。"}, {"label": "3", "text": "外気負荷は、潜熱のみである。"}, {"label": "4", "text": "ガラス面からの熱負荷には、温度差による通過熱負荷と透過日射熱負荷がある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["外気負荷は、潜熱のみである。"], "answerHints": [["潜熱のみ"]], "mnemonic": "正しくは：外気負荷は顕熱と潜熱の両方。", "block": 1, "group": 1}, {"id": "H30_zenki_12", "source": "H30前 No.12", "category": "空調・衛生", "type": "single", "question": "直だき吸収冷温水機の冷房運転時の特徴に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "運転時の振動は、圧縮式冷凍機に比べて小さい。"}, {"label": "2", "text": "立上がり時間は、一般的に、圧縮式冷凍機に比べて長い。"}, {"label": "3", "text": "電力消費量は、圧縮式冷凍機に比べて大きい。"}, {"label": "4", "text": "冷却塔の能力は、圧縮式冷凍機に比べて大きくなる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["電力消費量は、圧縮式冷凍機に比べて大きい。"], "answerHints": [["比べて大きい"]], "mnemonic": "正しくは：直だき吸収冷温水機の電力消費量は、圧縮式冷凍機より小さい。", "block": 1, "group": 1}, {"id": "H30_zenki_16", "source": "H30前 No.16", "category": "空調・衛生", "type": "single", "question": "硬質土の地盤に、可とう性を有する下水道管きょを布設する場合、管きょの基礎として、適当なものはどれか。", "choices": [{"label": "1", "text": "コンクリート基礎"}, {"label": "2", "text": "はしご胴木基礎"}, {"label": "3", "text": "くい打ち基礎"}, {"label": "4", "text": "砂基礎"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["砂基礎"], "answerHints": [["砂基礎"]], "mnemonic": "硬質土 × 可とう性のある管きょ → 砂基礎。", "block": 1, "group": 1}, {"id": "H30_zenki_20", "source": "H30前 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "伸頂通気方式は、通気立て管を設けず、排水立て管上部を延長し通気管として使用するものである。"}, {"label": "2", "text": "ループ通気管は、通気立て管又は伸頂通気管に接続するか、あるいは大気に開放する。"}, {"label": "3", "text": "伸頂通気方式は、ループ通気方式に比べて機能上優れている。"}, {"label": "4", "text": "最上階を除き、大便器8個以上を受け持つ排水横枝管には、ループ通気管を設けるほかに、逃し通気管を設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["伸頂通気方式は、ループ通気方式に比べて機能上優れている。"], "answerHints": [["機能上優れている"]], "mnemonic": "正しくは：伸頂通気方式は、ループ通気方式より通気の機能が劣る。", "block": 1, "group": 1}, {"id": "H30_zenki_23", "source": "H30前 No.23", "category": "空調・衛生", "type": "single", "question": "FRP製浄化槽の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "槽本体の固定金具や浮上防止金具の取付け位置の墨出しは、均しコンクリート上に行う。"}, {"label": "2", "text": "槽本体の水平は、内壁に示されている水準目安線、水位などで確認する。"}, {"label": "3", "text": "槽本体の漏水検査は、満水状態にして24時間放置し、漏水のないことを確認する。"}, {"label": "4", "text": "槽周囲の埋戻しは、水張りしない状態で、良質土又は山砂により行う。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["槽周囲の埋戻しは、水張りしない状態で、良質土又は山砂により行う。"], "answerHints": [["水張りしない状態"]], "mnemonic": "正しくは：埋戻しは槽に水張りした状態で行う（浮上・変形防止）。", "block": 1, "group": 1}, {"id": "H28_kouki_26", "source": "H28後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "硬質ポリ塩化ビニル管は、その種類により設計圧力の範囲が異なる。"}, {"label": "2", "text": "仕切弁は、玉形弁に比べて流量を調整するのに適している。"}, {"label": "3", "text": "水道用硬質塩化ビニルライニング鋼管D(SGP-VD)は、地中埋設配管に用いられる。"}, {"label": "4", "text": "定水位調整弁は、受水タンクへの給水に使用される。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["仕切弁は、玉形弁に比べて流量を調整するのに適している。"], "answerHints": [["仕切弁は、玉形弁に比べて"]], "mnemonic": "正しくは：流量調整に適するのは玉形弁。仕切弁は全開・全閉で使う。", "block": 1, "group": 1}, {"id": "H29_kouki_25", "source": "H29後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備系の制御や監視に用いられる機器と制御対象の組合せのうち、適当でないものはどれか。\n---(機器) ------(制御対象)", "choices": [{"label": "1", "text": "サーモスタット---室内の湿度制御"}, {"label": "2", "text": "電極棒-------受水タンクの水位監視(制御)"}, {"label": "3", "text": "電動二方弁-----冷温水の流量制御"}, {"label": "4", "text": "レベルスイッチ---汚物用水中モーターポンプの運転制御"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["サーモスタット---室内の湿度制御"], "answerHints": [["湿度制御"]], "mnemonic": "正しくは：サーモスタットは温度制御。湿度はヒューミディスタット。", "block": 1, "group": 1}, {"id": "H30_zenki_24", "source": "H30前 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "遠心ポンプに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ポンプの吐出量の調整は、吸込み側に設けた弁で行う。"}, {"label": "2", "text": "実用範囲における揚程は、吐出量の増加とともに低くなる。"}, {"label": "3", "text": "同一系統において、ポンプを並列運転して得られる吐出量は、それぞれのポンプを単独運転した吐出量の和よりも小さくなる。"}, {"label": "4", "text": "軸動力は、吐出量の増加とともに増加する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ポンプの吐出量の調整は、吸込み側に設けた弁で行う。"], "answerHints": [["吸込み側"]], "mnemonic": "正しくは：吐出量の調整は吐出し側の弁で行う（吸込み側で絞るとキャビテーションの原因）。", "block": 1, "group": 1}, {"id": "H30_zenki_27", "source": "H30前 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "長方形ダクトのアスペクト比(長辺/短辺)は、小さい方が圧力損失の面から有利である。"}, {"label": "2", "text": "防火ダンパーは、ヒューズが溶解してダンパーが閉じるものである。"}, {"label": "3", "text": "長方形ダクトの板厚は、ダクトの周長により決定する。"}, {"label": "4", "text": "ダクトの曲り部にガイドベーンを入れると、局部抵抗を減少できる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["長方形ダクトの板厚は、ダクトの周長により決定する。"], "answerHints": [["周長"]], "mnemonic": "正しくは：長方形ダクトの板厚は長辺の長さで決める。", "block": 1, "group": 1}, {"id": "H28_kouki_32", "source": "H28後 No.32", "category": "施工管理法", "type": "single", "question": "品質を確認するための試験・検査に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "防火区画貫通箇所の穴埋めの確認は、抜取検査とした。"}, {"label": "2", "text": "ダクトの板厚や寸法などの確認は、抜取検査とした。"}, {"label": "3", "text": "排水配管の通水試験実施にあたり、立会計画を立て監督員に試験の立会いを求めた。"}, {"label": "4", "text": "完成検査時に、契約書や設計図書のほか、工事記録写真、試運転記録などを用意した。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火区画貫通箇所の穴埋めの確認は、抜取検査とした。"], "answerHints": [["抜取検査"]], "mnemonic": "正しくは：防火区画貫通部の穴埋めは全数検査。", "block": 1, "group": 1}, {"id": "H28_kouki_35", "source": "H28後 No.35", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "揚水ポンプの吐出し側に、ポンプに近い順に、防振継手、仕切弁、逆止め弁を取り付けた。"}, {"label": "2", "text": "飲料用受水タンクの上部に、空調配管、排水管等を設けないようにした。"}, {"label": "3", "text": "パッケージ形空気調和機の屋外機の騒音対策として、防音壁を設置した。"}, {"label": "4", "text": "飲料用受水タンクを高さ60cmの梁形コンクリート基礎上に据え付けた。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["揚水ポンプの吐出し側に、ポンプに近い順に、防振継手、仕切弁、逆止め弁を取り付けた。"], "answerHints": [["仕切弁、逆止め弁"]], "mnemonic": "正しくは：ポンプに近い順に 防振継手 → 逆止め弁 → 仕切弁。", "block": 1, "group": 1}, {"id": "H28_kouki_38", "source": "H28後 No.38", "category": "施工管理法", "type": "single", "question": "ダクトの施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "長方形ダクトの長辺と短辺の比は、4以下とした。"}, {"label": "2", "text": "共板フランジ工法ダクトのフランジは、ダクトの端部を折り曲げて成形したものである。"}, {"label": "3", "text": "長方形ダクトの板厚は、ダクトの長辺の長さにより決定した。"}, {"label": "4", "text": "送風機の吐出口直後におけるダクトの曲げ方向は、送風機の回転方向と逆の方向とした。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送風機の吐出口直後におけるダクトの曲げ方向は、送風機の回転方向と逆の方向とした。"], "answerHints": [["逆の方向"]], "mnemonic": "正しくは：吐出口直後の曲げ方向は送風機の回転方向と同じ方向。", "block": 1, "group": 1}, {"id": "H28_kouki_41", "source": "H28後 No.41", "category": "施工管理法", "type": "single", "question": "配管とその試験方法の組合せのうち、適当でないものはどれか。\n---(配管)----(試験方法)", "choices": [{"label": "1", "text": "給水配管----水圧試験"}, {"label": "2", "text": "油配管-----水圧試験"}, {"label": "3", "text": "冷媒配管----気密試験"}, {"label": "4", "text": "ガス配管----気密試験"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["油配管-----水圧試験"], "answerHints": [["油配管", "水圧試験"]], "mnemonic": "正しくは：油配管は空気圧試験（水を入れない）。", "block": 1, "group": 1}, {"id": "H29_kouki_32", "source": "H29後 No.32", "category": "施工管理法", "type": "single", "question": "次の試験・検査のうち、全数試験・検査が必要なものはどれか。", "choices": [{"label": "1", "text": "防火ダンパー用温度ヒューズの作動試験"}, {"label": "2", "text": "給水栓から吐出した水の残留塩素濃度試験"}, {"label": "3", "text": "ボイラ用安全弁の作動試験"}, {"label": "4", "text": "配管のねじ加工の検査"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["必要なもの"], "answerTexts": ["ボイラ用安全弁の作動試験"], "answerHints": [["ボイラ用安全弁"]], "mnemonic": "安全に直結する機器（ボイラの安全弁）は全数試験。", "block": 1, "group": 1}, {"id": "H29_kouki_36", "source": "H29後 No.36", "category": "施工管理法", "type": "single", "question": "配管系に設ける弁類に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給水管の流路を遮断するための止め弁として仕切弁を使用する。"}, {"label": "2", "text": "揚水管の水撃を防止するためにスイング式逆止め弁を使用する。"}, {"label": "3", "text": "配管に混入した空気を排出するために自動空気抜き弁を使用する。"}, {"label": "4", "text": "ユニット形空気調和機の冷温水流量を調整するために玉形弁を使用する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["揚水管の水撃を防止するためにスイング式逆止め弁を使用する。"], "answerHints": [["スイング式逆止め弁"]], "mnemonic": "正しくは：揚水管の水撃防止には衝撃吸収式（スモレンスキー）逆止め弁。", "block": 1, "group": 1}, {"id": "H29_kouki_39", "source": "H29後 No.39", "category": "施工管理法", "type": "single", "question": "ダクトの施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "スパイラルダクトの差込み接合では、継手、シール材、鋼製ビス、ダクト用テープを使用する。"}, {"label": "2", "text": "2枚の鉄板を組み合せて製作されるダクトは、はぜの位置によりL字型、U字型などがある。"}, {"label": "3", "text": "リブ補強は、ダクトの板振動による騒音を防止するために設ける。"}, {"label": "4", "text": "長方形ダクトは、アスペクト比を変えても圧力損失は変わらない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["長方形ダクトは、アスペクト比を変えても圧力損失は変わらない。"], "answerHints": [["変わらない"]], "mnemonic": "正しくは：アスペクト比が大きいほど圧力損失は大きくなる。", "block": 1, "group": 1}, {"id": "H29_kouki_42", "source": "H29後 No.42", "category": "施工管理法", "type": "single", "question": "接合する異種管と接合方法の組合せのうち、適当でないものはどれか。\n---(接合する異種管)---------------(接合方法)", "choices": [{"label": "1", "text": "配管用炭素鋼鋼管と塩化ビニル管--------ユニオン接合"}, {"label": "2", "text": "配管用ステンレス鋼鋼管と配管用炭素鋼鋼管---絶縁フランジ接合"}, {"label": "3", "text": "銅管と配管用ステンレス鋼鋼管---------ルーズフランジ接合"}, {"label": "4", "text": "配管用炭素鋼鋼管と銅管------------フレア接合"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["配管用炭素鋼鋼管と銅管------------フレア接合"], "answerHints": [["フレア接合"]], "mnemonic": "正しくは：炭素鋼鋼管と銅管は絶縁継手（絶縁フランジ）で接合する。", "block": 1, "group": 1}, {"id": "H30_zenki_33", "source": "H30前 No.33", "category": "施工管理法", "type": "single", "question": "建設工事現場の安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "一つの荷物で重量が100kg以上のものを貨物自動車に積む作業を行うときは、当該作業を指揮する者を定める。"}, {"label": "2", "text": "ゴンドラの操作の業務を行う作業に労働者をつかせるときは、当該業務に関する安全又は衛生の特別の教育を行う。"}, {"label": "3", "text": "作業床の高さが1mの可搬式作業台には、手掛かり棒を取り付ける。"}, {"label": "4", "text": "高さが2mの作業場所に作業床を設ける場合は、床材間のすき間は4cm以下になるようにする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["高さが2mの作業場所に作業床を設ける場合は、床材間のすき間は4cm以下になるようにする。"], "answerHints": [["4cm以下"]], "mnemonic": "正しくは：作業床の床材間のすき間は3cm以下。", "block": 1, "group": 1}, {"id": "H30_zenki_36", "source": "H30前 No.36", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか", "choices": [{"label": "1", "text": "呼び径100Aの屋内排水管の勾配(最小)は、1/100とする。"}, {"label": "2", "text": "飲料用タンクに設ける間接排水管の排水口空間(最小)は、100mmとする。"}, {"label": "3", "text": "合流式の敷地排水管に雨水管を接続する場合には、トラップますを介して接続する。"}, {"label": "4", "text": "屋外排水管の方向変換箇所には、原則として、排水ますを設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用タンクに設ける間接排水管の排水口空間(最小)は、100mmとする。"], "answerHints": [["100mm"]], "mnemonic": "正しくは：飲料用タンクの間接排水の排水口空間は最小150mm。", "block": 1, "group": 1}, {"id": "H30_zenki_39", "source": "H30前 No.39", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "横走りのダクトには、形鋼による振れ止めを行う。"}, {"label": "2", "text": "外壁ガラリに接続するチャンバーは、浸入した雨水を排除できるように勾配を設ける。"}, {"label": "3", "text": "吹出し口を配置する際は、煙感知器と近接しないよう離隔距離を確保する。"}, {"label": "4", "text": "共板フランジ工法ダクトの接続は、フランジ押え金具のみで行い、ボルト・ナットを使用しない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["共板フランジ工法ダクトの接続は、フランジ押え金具のみで行い、ボルト・ナットを使用しない。"], "answerHints": [["フランジ押え金具のみで行い、ボルト・ナットを使用しない"]], "mnemonic": "正しくは：共板フランジは押え金具に加え、四隅をボルト・ナットで締める。", "block": 1, "group": 1}, {"id": "H28_kouki_43", "source": "H28後 No.43", "category": "法規", "type": "single", "question": "建設工事現場における安全管理体制に関する文中、 内に当てはまる「労働安全衛生法」上に定められている数値の組合せとして、正しいものはどれか。\n事業者は、労働者の数が常時 A 人以上の事業場においては、安全管理者を選任し、その者に法に定める業務のうち安全に係る技術的事項を管理させなければならない。また、労働者の数が常時 B 人以上 A 人未満の事業場においては、安全衛生推進者を選任しなければならない。\n--(A)-------(B)", "choices": [{"label": "1", "text": "50-------10"}, {"label": "2", "text": "100-------20"}, {"label": "3", "text": "100-------50"}, {"label": "4", "text": "200-------50"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["50-------10"], "answerHints": [["50", "10"]], "mnemonic": "安全管理者は常時50人以上、安全衛生推進者は10人以上50人未満。", "block": 1, "group": 1}, {"id": "H28_kouki_46", "source": "H28後 No.46", "category": "法規", "type": "single", "question": "建築物に設ける配管設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "地階に居室を有する建築物に設ける換気設備の風道は、防火上支障がある場合、難燃材料で造らなければならない。"}, {"label": "2", "text": "雨水排水立て管は、通気管と兼用してはならない。"}, {"label": "3", "text": "排水のための配管設備で、汚水に接する部分は、不浸透質の耐水材料で造らなければならない。"}, {"label": "4", "text": "給水管及び排水管は、エレベーターの昇降路内に設けてはならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["地階に居室を有する建築物に設ける換気設備の風道は、防火上支障がある場合、難燃材料で造らなければならない。"], "answerHints": [["難燃材料"]], "mnemonic": "正しくは：防火上支障がある場合、換気設備の風道は不燃材料で造る。", "block": 1, "group": 1}, {"id": "H28_kouki_49", "source": "H28後 No.49", "category": "法規", "type": "single", "question": "危険物の種類と指定数量の組合せのうち、「消防法」上、誤っているものはどれか。\n--(危険物の種類)---(指定数量)", "choices": [{"label": "1", "text": "ガソリン------200 L"}, {"label": "2", "text": "灯油--------500 L"}, {"label": "3", "text": "軽油--------1,000 L"}, {"label": "4", "text": "重油--------2,000 L"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["灯油--------500 L"], "answerHints": [["500"]], "mnemonic": "正しくは：灯油の指定数量は1,000L（軽油と同じ）。", "block": 1, "group": 1}, {"id": "H28_kouki_52", "source": "H28後 No.52", "category": "法規", "type": "single", "question": "建設資材廃棄物の再資源化等に関する文中、 内に当てはまる数値及び語句の組合せとして、「建設工事に係る資材の再資源化等に関する法律」上、正しいものはどれか。\n床面積の合計が A m2以上の建築工事の新築に伴って副次的に生じた特定建設資材廃棄物は、再資源化等をしなければならない。なお、特定建設資材とは、コンクリート、コンクリート及び鉄から成る建設資材、 B 及びアスファルト・コンクリートである。\n--(A)-------(B)", "choices": [{"label": "1", "text": "50------プラスチック"}, {"label": "2", "text": "50------木材"}, {"label": "3", "text": "500------プラスチック"}, {"label": "4", "text": "500------木材"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["500------木材"], "answerHints": [["500", "木材"]], "mnemonic": "新築は床面積500m²以上で再資源化義務。特定建設資材は木材（プラスチックは含まない）。", "block": 1, "group": 1}, {"id": "H29_kouki_45", "source": "H29後 No.45", "category": "法規", "type": "single", "question": "建築物の用語に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "屋根は、主要構造部である。"}, {"label": "2", "text": "屋内避難階段は、主要構造部である。"}, {"label": "3", "text": "外壁は、主要構造部である。"}, {"label": "4", "text": "基礎ぐいは、主要構造部である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["基礎ぐいは、主要構造部である。"], "answerHints": [["基礎ぐい"]], "mnemonic": "基礎ぐいは主要構造部ではない（構造耐力上主要な部分）。", "block": 1, "group": 1}, {"id": "H29_kouki_48", "source": "H29後 No.48", "category": "法規", "type": "single", "question": "管工事業の許可を受けた建設業者が現場に置く主任技術者に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "主任技術者は、請負契約の履行を確保するため、請負人に代わって工事の施工に関する一切の事項を処理しなければならない。"}, {"label": "2", "text": "請負代金の額が3,500万円未満の管工事においては、主任技術者は、当該工事現場に専任の者でなくてもよい。"}, {"label": "3", "text": "2級管工事施工管理技術検定に合格した者は、管工事の主任技術者になることができる。"}, {"label": "4", "text": "発注者から直接請け負った工事を下請契約を行わずに自ら施工する場合、当該工事現場における建設工事の施工の技術上の管理をつかさどるものとして建設業者が置くのは、主任技術者でよい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["主任技術者は、請負契約の履行を確保するため、請負人に代わって工事の施工に関する一切の事項を処理しなければならない。"], "answerHints": [["請負人に代わって工事の施工に関する一切の事項を処理"]], "mnemonic": "それは現場代理人の役割。主任技術者は施工の技術上の管理（計画・工程・品質・指導監督）。", "block": 1, "group": 1}, {"id": "H29_kouki_51", "source": "H29後 No.51", "category": "法規", "type": "single", "question": "特定建設作業における騒音の規制に関する文中、 内に当てはまる語句として、「騒音規制法」上、正しいものはどれか。\n特定建設作業の騒音は、 、85デシベルを超えてはならない。", "choices": [{"label": "1", "text": "特定建設作業の場所の敷地から一番近い建物内において"}, {"label": "2", "text": "特定建設作業の場所の敷地から一番近い居住者のいる建物内において"}, {"label": "3", "text": "特定建設作業の場所の敷地の境界線において"}, {"label": "4", "text": "特定建設作業の作業機械から発生する騒音値が"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["特定建設作業の場所の敷地の境界線において"], "answerHints": [["敷地の境界線"]], "mnemonic": "特定建設作業の騒音は、敷地の境界線で85デシベル以下。", "block": 1, "group": 1}, {"id": "H30_zenki_44", "source": "H30前 No.44", "category": "法規", "type": "single", "question": "未成年者の労働に関する記述のうち、「労働基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "親権者又は後見人は、未成年者に代って労働契約を締結することができる。"}, {"label": "2", "text": "親権者若しくは後見人又は行政官庁は、労働契約が未成年者に不利であると認める場合においては、将来に向ってこれを解除することができる。"}, {"label": "3", "text": "未成年者は、独立して賃金を請求することができる。"}, {"label": "4", "text": "親権者又は後見人は、未成年者の賃金を代って受け取ってはならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["親権者又は後見人は、未成年者に代って労働契約を締結することができる。"], "answerHints": [["締結することができる"]], "mnemonic": "正しくは：親権者・後見人は未成年者に代わって労働契約を締結してはならない。", "block": 1, "group": 1}, {"id": "H30_zenki_47", "source": "H30前 No.47", "category": "法規", "type": "single", "question": "「建設業法」の用語に関する記述のうち、誤っているものはどれか。", "choices": [{"label": "1", "text": "「発注者」とは、建設工事の注文者のうち、他の者から請け負った建設工事の注文者を除いた者をいう。"}, {"label": "2", "text": "「元請負人」とは、下請契約における注文者をいい、建設業者であるものに限らない。"}, {"label": "3", "text": "「建設業」とは、建設工事の完成を請け負う営業をいい、元請、下請その他いかなる名義をもってするかは問わない。"}, {"label": "4", "text": "管工事は、「建設工事」に含まれる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["「元請負人」とは、下請契約における注文者をいい、建設業者であるものに限らない。"], "answerHints": [["限らない"]], "mnemonic": "正しくは：元請負人は、下請契約の注文者で建設業者であるものに限る。", "block": 1, "group": 1}, {"id": "H30_zenki_50", "source": "H30前 No.50", "category": "法規", "type": "single", "question": "解体工事の届け出に関する文中、 内に当てはまる数値及び語句の組合せとして、「建設工事に係る資材の再資源化等に関する法律」上、正しいものはどれか。\n特定建設資材を用いた建築物等に係る解体工事であって、その規模が政令等で定める基準以上のものの発注者又は自主施工者は、工事に着手する日の A 日前までに、主務省令で定めるところにより、解体する建築物等の構造、工事着手の時期及び工程の概要等の事項を B に届け出なければならない。\n--(A)------(B)", "choices": [{"label": "1", "text": "7-----都道府県知事"}, {"label": "2", "text": "7-----国土交通大臣"}, {"label": "3", "text": "14-----都道府県知事"}, {"label": "4", "text": "14-----国土交通大臣"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["7-----都道府県知事"], "answerHints": [["7", "都道府県知事"]], "mnemonic": "解体工事の届出は着手7日前までに都道府県知事へ。", "block": 1, "group": 1}, {"id": "H28_kouki_02", "source": "H28後 No.2", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飽和湿り空気の乾球温度と湿球温度は等しい。"}, {"label": "2", "text": "相対湿度とは、湿り空気中に含まれる乾き空気1kgに対する水蒸気の質量をいう。"}, {"label": "3", "text": "湿球温度とは、一般に、感熱部を水で湿らせた布で包んだアスマン通風乾湿計で測定した温度をいう。"}, {"label": "4", "text": "湿り空気がその露点温度より低い物体に触れると、物体の表面に結露が生じる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["相対湿度とは、湿り空気中に含まれる乾き空気1kgに対する水蒸気の質量をいう。"], "answerHints": [["相対湿度"]], "mnemonic": "正しくは：乾き空気1kgに対する水蒸気の質量で表すのは「絶対湿度」。相対湿度は水蒸気分圧と飽和水蒸気分圧の比。", "block": 2, "group": 1}, {"id": "H28_kouki_05", "source": "H28後 No.5", "category": "一般基礎", "type": "single", "question": "交流電気回路に設けた進相コンデンサによる力率改善の効果と最も関係のないものはどれか。", "choices": [{"label": "1", "text": "電路及び変圧器内の電力損失の軽減"}, {"label": "2", "text": "電圧降下の改善"}, {"label": "3", "text": "電力供給設備余力の増加"}, {"label": "4", "text": "感電事故の予防"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["感電事故の予防"], "answerHints": [["感電事故の予防"]], "mnemonic": "力率改善の効果は電力損失の軽減・電圧降下の改善・設備余力の増加。感電防止は接地や漏電遮断器の役目。", "block": 2, "group": 1}, {"id": "H29_kouki_02", "source": "H29後 No.2", "category": "一般基礎", "type": "single", "question": "次の指標のうち、室内環境と関係のないものはどれか。", "choices": [{"label": "1", "text": "気流"}, {"label": "2", "text": "予想平均申告(PMV)"}, {"label": "3", "text": "浮遊物質(SS)"}, {"label": "4", "text": "平均放射温度"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["浮遊物質(SS)"], "answerHints": [["浮遊物質(SS)"]], "mnemonic": "SS（浮遊物質）は水質の指標。気流・PMV・平均放射温度が室内環境の指標。", "block": 2, "group": 1}, {"id": "H29_kouki_05", "source": "H29後 No.5", "category": "一般基礎", "type": "single", "question": "合成樹脂製可とう電線管を金属管と比較した場合の長所として、適当でないものはどれか。", "choices": [{"label": "1", "text": "耐食性にすぐれている。"}, {"label": "2", "text": "軽量である。"}, {"label": "3", "text": "機械的強度にすぐれている。"}, {"label": "4", "text": "非磁性体である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["機械的強度にすぐれている。"], "answerHints": [["機械的強度にすぐれている"]], "mnemonic": "正しくは：合成樹脂製可とう電線管は金属管より機械的強度が劣る（長所は耐食性・軽量・非磁性）。", "block": 2, "group": 1}, {"id": "H30_zenki_03", "source": "H30前 No.3", "category": "一般基礎", "type": "single", "question": "水平管中の流体について、全圧、静圧及び動圧の関係を表した式として、正しいものはどれか。\nただし、Pt:全圧、Ps:静圧、ρ:流体の密度、v:流速とする。", "choices": [{"label": "1", "text": "Pt = Ps + ρv"}, {"label": "2", "text": "Ps = Pt + ρv"}, {"label": "3", "text": "Pt = Ps + ρv^2 / 2"}, {"label": "4", "text": "Ps = Pt + ρv^2 / 2"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["Pt = Ps + ρv^2 / 2"], "answerHints": [["Pt = Ps + ρv^2 / 2"]], "mnemonic": "全圧＝静圧＋動圧、動圧は ρv²/2。", "block": 2, "group": 1}, {"id": "H28_kouki_07", "source": "H28後 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクト併用ファンコイルユニット方式は、全空気方式に比べてダクトスペースが大きくなる。"}, {"label": "2", "text": "ダクト併用ファンコイルユニット方式は、空調する室に熱媒体として空気と水を供給する方式である。"}, {"label": "3", "text": "マルチパッケージ形空気調和方式は、屋内機ごとに運転、停止ができる。"}, {"label": "4", "text": "マルチパッケージ形空気調和方式では、屋内機に加湿器を組み込んだものがある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクト併用ファンコイルユニット方式は、全空気方式に比べてダクトスペースが大きくなる。"], "answerHints": [["大きくなる"]], "mnemonic": "正しくは：ダクト併用ファンコイルユニット方式は、全空気方式よりダクトスペースが小さくなる。", "block": 2, "group": 1}, {"id": "H28_kouki_11", "source": "H28後 No.11", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "天井カセット形では、ドレン配管の自由度を高めるためドレンアップする方式のものが多い。"}, {"label": "2", "text": "ヒートポンプ式には、空気熱源ヒートポンプと水熱源ヒートポンプがある。"}, {"label": "3", "text": "ヒートポンプ式では、屋外機を屋内機より高い位置に設置することはできない。"}, {"label": "4", "text": "ガスエンジンヒートポンプ式は、エンジンの排熱が利用できるため寒冷地にも適している。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ヒートポンプ式では、屋外機を屋内機より高い位置に設置することはできない。"], "answerHints": [["設置することはできない"]], "mnemonic": "正しくは：屋外機を屋内機より高い位置に設置することもできる（高低差の制限内）。", "block": 2, "group": 1}, {"id": "H28_kouki_15", "source": "H28後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道に関する文中、 内に当てはまる用語の組合せとして、適当なものはどれか。\n給水管を不断水工法により配水支管から取り出す場合、一般に、給水管の口径が25mm以下のときにはサドル付分水栓、75mm以上のときには A によって取り出す。この給水管及びこれに直結する給水用具を、「水道法」上、 B という。\n---(A)--------(B)", "choices": [{"label": "1", "text": "T字管-------給水設備"}, {"label": "2", "text": "割T字管------給水装置"}, {"label": "3", "text": "T字管-------給水装置"}, {"label": "4", "text": "割T字管------給水設備"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["割T字管------給水装置"], "answerHints": [["割T字管", "給水装置"]], "mnemonic": "口径75mm以上の不断水取出しは割T字管。給水管と直結する給水用具は水道法上「給水装置」。", "block": 2, "group": 1}, {"id": "H28_kouki_19", "source": "H28後 No.19", "category": "空調・衛生", "type": "single", "question": "排水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "間接排水とする水受け容器には、トラップを設けない。"}, {"label": "2", "text": "ドラムトラップは、非サイホン式のトラップである。"}, {"label": "3", "text": "排水横主管の管径は、これに接続する排水立て管の管径以上とする。"}, {"label": "4", "text": "サイホン式のトラップは、封水が少なく、非サイホン式のトラップに比較して封水が破れやすい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["間接排水とする水受け容器には、トラップを設けない。"], "answerHints": [["トラップを設けない"]], "mnemonic": "正しくは：間接排水の水受け容器にはトラップを設ける。", "block": 2, "group": 1}, {"id": "H28_kouki_22", "source": "H28後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "LPG用のガス漏れ警報器の取付け高さは、その下端が天井面等の下方0.3m以内となるようにする。"}, {"label": "2", "text": "LPG用の充てん容器には、10kg容器、20kg容器、50kg容器などがある。"}, {"label": "3", "text": "都市ガスの内管とは、需要家に引き込まれる導管のうち、敷地境界線からガス栓までの導管をいう。"}, {"label": "4", "text": "LNGは、メタンを主成分とした天然ガスを液化したものである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["LPG用のガス漏れ警報器の取付け高さは、その下端が天井面等の下方0.3m以内となるようにする。"], "answerHints": [["天井面等の下方0.3m以内"]], "mnemonic": "正しくは：LPGは空気より重いので、警報器はその上端が床面の上方0.3m以内（天井面下方0.3m以内は空気より軽い都市ガス）。", "block": 2, "group": 1}, {"id": "H29_kouki_09", "source": "H29後 No.9", "category": "空調・衛生", "type": "single", "question": "空気清浄装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "HEPAフィルターは、クリーンルームなどの最終段フィルターとして使用される。"}, {"label": "2", "text": "エアフィルターの性能試験方法のうち質量法は、主に粗じん用フィルターに用いられる。"}, {"label": "3", "text": "自動巻取形は、フィルター前後の差圧又はタイマーなどにより自動的に巻取りが行われる。"}, {"label": "4", "text": "ろ材は、特性の一つとして空気抵抗が大きいことが求められる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ろ材は、特性の一つとして空気抵抗が大きいことが求められる。"], "answerHints": [["大きい"]], "mnemonic": "正しくは：ろ材は空気抵抗が小さいことが求められる。", "block": 2, "group": 1}, {"id": "H29_kouki_12", "source": "H29後 No.12", "category": "空調・衛生", "type": "single", "question": "温水床パネル式の低温放射暖房に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "室内空気の上下温度むらにより、室内気流を生じやすい。"}, {"label": "2", "text": "放熱器や配管が室内に露出しないので、火傷などの危険性が少ない。"}, {"label": "3", "text": "放射パネルの構造によっては、パネルの熱容量が大きく放射量の調節に時間がかかる。"}, {"label": "4", "text": "室内空気温度を低く設定しても、平均放射温度を上げることにより、ほぼ同様の温熱感が得られる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["室内空気の上下温度むらにより、室内気流を生じやすい。"], "answerHints": [["室内気流を生じやすい"]], "mnemonic": "正しくは：床パネル放射暖房は上下温度むらが少なく、室内気流を生じにくい。", "block": 2, "group": 1}, {"id": "H29_kouki_15", "source": "H29後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道の取水施設から配水施設に至るまでのフローとして、適当なものはどれか。", "choices": [{"label": "1", "text": "取水施設 → 浄水施設 → 導水施設 → 送水施設 → 配水施設"}, {"label": "2", "text": "取水施設 → 導水施設 → 浄水施設 → 送水施設 → 配水施設"}, {"label": "3", "text": "取水施設 → 送水施設 → 浄水施設 → 導水施設 → 配水施設"}, {"label": "4", "text": "取水施設 → 浄水施設 → 送水施設 → 導水施設 → 配水施設"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["取水施設 → 導水施設 → 浄水施設 → 送水施設 → 配水施設"], "answerHints": [["導水施設 → 浄水施設 → 送水施設"]], "mnemonic": "取水 → 導水 → 浄水 → 送水 → 配水（導水は浄水前、送水は浄水後）。", "block": 2, "group": 1}, {"id": "H29_kouki_19", "source": "H29後 No.19", "category": "空調・衛生", "type": "single", "question": "建築物の排水に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水は、汚水、雑排水、雨水などに分類される。"}, {"label": "2", "text": "大小便器及びこれと類似の用途をもつ器具から排出される排水を汚水という。"}, {"label": "3", "text": "厨房排水は、建物内の排水管を閉塞させやすい。"}, {"label": "4", "text": "雨水は、建物内で雑排水系統と合流させてもよい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["雨水は、建物内で雑排水系統と合流させてもよい。"], "answerHints": [["雑排水系統と合流させてもよい"]], "mnemonic": "正しくは：雨水は建物内で汚水・雑排水系統と合流させず、単独系統とする。", "block": 2, "group": 1}, {"id": "H29_kouki_23", "source": "H29後 No.23", "category": "空調・衛生", "type": "single", "question": "「建築物の用途別による屎尿浄化槽の処理対象人員算定基準(JIS A 3302)」において、処理対象人員の算定式に延べ面積が用いられている建築用途に該当しないものはどれか。", "choices": [{"label": "1", "text": "映画館"}, {"label": "2", "text": "旅館"}, {"label": "3", "text": "事務所"}, {"label": "4", "text": "保育園"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["保育園"], "answerHints": [["保育園"]], "mnemonic": "保育園（保育所・幼稚園）は定員で算定。映画館・旅館・事務所は延べ面積を用いる。", "block": 2, "group": 1}, {"id": "H30_zenki_10", "source": "H30前 No.10", "category": "空調・衛生", "type": "single", "question": "エアフィルターの種類と主な除去対象又は用途との組合せのうち、適当でないものはどれか。\n---(種類)---------(主な除去対象又は用途)", "choices": [{"label": "1", "text": "活性炭フィルター------屋外粉じんの除去"}, {"label": "2", "text": "電気集じん器--------屋内粉じんの除去"}, {"label": "3", "text": "HEPA フィルター------クリーンルーム用"}, {"label": "4", "text": "パネルフィルター------ファンコイルユニット用"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["活性炭フィルター------屋外粉じんの除去"], "answerHints": [["屋外粉じんの除去"]], "mnemonic": "正しくは：活性炭フィルターは有害ガス・臭気の除去用。", "block": 2, "group": 1}, {"id": "H30_zenki_13", "source": "H30前 No.13", "category": "空調・衛生", "type": "single", "question": "次の室のうち、第三種機械換気方式を用いることが、適当でないものはどれか。", "choices": [{"label": "1", "text": "便所"}, {"label": "2", "text": "ボイラー室"}, {"label": "3", "text": "浴室"}, {"label": "4", "text": "更衣室"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボイラー室"], "answerHints": [["ボイラー室"]], "mnemonic": "ボイラー室は燃焼用空気が必要なので給気側に送風機（第一種・第二種）。便所・浴室・更衣室は第三種。", "block": 2, "group": 1}, {"id": "H30_zenki_17", "source": "H30前 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飲料用給水タンクのオーバーフロー管にはトラップを設け、虫の侵入を防止する。"}, {"label": "2", "text": "散水栓のホース接続水栓は、バキュームブレーカ付きとする。"}, {"label": "3", "text": "ウォーターハンマーを防止するには、給水管内の流速を小さくする。"}, {"label": "4", "text": "逆サイホン作用とは、水受け容器中に吐き出された水等が、給水管内に逆流することである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用給水タンクのオーバーフロー管にはトラップを設け、虫の侵入を防止する。"], "answerHints": [["トラップを設け"]], "mnemonic": "正しくは：飲料用タンクのオーバーフロー管は排水口空間をとり、管端に防虫網を設ける（トラップは設けない）。", "block": 2, "group": 1}, {"id": "H30_zenki_21", "source": "H30前 No.21", "category": "空調・衛生", "type": "single", "question": "次の設備のうち、「消防法」上、消防の用に供する設備に該当しないものはどれか。", "choices": [{"label": "1", "text": "屋内消火栓設備"}, {"label": "2", "text": "連結散水設備"}, {"label": "3", "text": "スプリンクラー設備"}, {"label": "4", "text": "泡消火設備"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["連結散水設備"], "answerHints": [["連結散水設備"]], "mnemonic": "連結散水設備・連結送水管は「消火活動上必要な施設」。屋内消火栓・スプリンクラー・泡消火は消防の用に供する設備。", "block": 2, "group": 1}, {"id": "H28_kouki_24", "source": "H28後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "遠心ポンプに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "実用範囲における揚程は、吐出量の増加とともに低くなる。"}, {"label": "2", "text": "ポンプの吐出量の調整は、吸込み側に設けた弁で行う。"}, {"label": "3", "text": "同一配管系において、ポンプを並列運転して得られる吐出量は、それぞれのポンプを単独運転した吐出量の和よりも小さくなる。"}, {"label": "4", "text": "軸動力は、吐出量の増加とともに増加する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ポンプの吐出量の調整は、吸込み側に設けた弁で行う。"], "answerHints": [["吸込み側に設けた弁"]], "mnemonic": "正しくは：吐出量の調整は吐出し側の弁で行う（吸込み側で絞るとキャビテーションの原因）。", "block": 2, "group": 1}, {"id": "H28_kouki_27", "source": "H28後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクトに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "コーナーボルト工法には、共板フランジ工法とスライドオンフランジ工法がある。"}, {"label": "2", "text": "ダクトの拡大は、15度以内とすることが望ましい。"}, {"label": "3", "text": "ダクトの拡大部・縮小部における空気のうず流は、縮小部の方が発生しやすい。"}, {"label": "4", "text": "長方形ダクトの曲り部の圧力損失が大きい箇所に、案内羽根(ガイドベーン)付きエルボを設置した。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクトの拡大部・縮小部における空気のうず流は、縮小部の方が発生しやすい。"], "answerHints": [["縮小部の方が発生しやすい"]], "mnemonic": "正しくは：うず流は拡大部の方が発生しやすい（拡大15度以内、縮小30度以内）。", "block": 2, "group": 1}, {"id": "H29_kouki_26", "source": "H29後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "逆止め弁は、チャッキ弁とも呼ばれ、スイング、リフト式などがある。"}, {"label": "2", "text": "水道用ポリエチレン二層管は、外層及び内層ともポリエチレンで構成されている管である。"}, {"label": "3", "text": "ストレーナーは、配管内の不要物をろ過して、下流側の弁類や機器類を保護するものである。"}, {"label": "4", "text": "玉形弁は、仕切弁に比べて全開時の流体抵抗が小さい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["玉形弁は、仕切弁に比べて全開時の流体抵抗が小さい。"], "answerHints": [["流体抵抗が小さい"]], "mnemonic": "正しくは：玉形弁は仕切弁より全開時の流体抵抗が大きい（流量調整向き）。", "block": 2, "group": 1}, {"id": "H30_zenki_25", "source": "H30前 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "保温材に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ロックウール保温材の最高使用温度は、グラスウール保温材より高い。"}, {"label": "2", "text": "グラスウール保温板は、その密度により区分されている。"}, {"label": "3", "text": "ポリスチレンフォーム保温材は、蒸気管には使用できない。"}, {"label": "4", "text": "ポリエチレンフォーム保温筒は、吸湿性が高い。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ポリエチレンフォーム保温筒は、吸湿性が高い。"], "answerHints": [["吸湿性が高い"]], "mnemonic": "正しくは：ポリエチレンフォーム保温筒は独立気泡で吸湿性がほとんどない。", "block": 2, "group": 1}, {"id": "H28_kouki_29", "source": "H28後 No.29", "category": "施工管理法", "type": "single", "question": "公共工事における施工計画に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "施工計画書は、作業員に工事の詳細を徹底させるために使用されるもので、監督員の承諾は必要ない。"}, {"label": "2", "text": "工事に使用する機材は、設計図書に特別の定めがない場合は新品とするが、仮設材は新品でなくてもよい。"}, {"label": "3", "text": "着工前業務には、工事組織の編成、実行予算書の作成、工程・労務計画の作成などがある。"}, {"label": "4", "text": "施工図は、作成範囲、順序、作成予定日等を定めた施工図作成計画表に基づき、時機を失うことのないように完成させる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["施工計画書は、作業員に工事の詳細を徹底させるために使用されるもので、監督員の承諾は必要ない。"], "answerHints": [["監督員の承諾は必要ない"]], "mnemonic": "正しくは：施工計画書は監督員に提出し承諾を受ける。", "block": 2, "group": 1}, {"id": "H28_kouki_33", "source": "H28後 No.33", "category": "施工管理法", "type": "single", "question": "建設工事現場の安全に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "脚立は、脚と水平面との角度を80度とし、その角度を保つための金具を備えたものとした。"}, {"label": "2", "text": "事業者は、作業主任者を選任したので、その者の氏名及び行わせる事項を作業場の見やすい箇所に掲示した。"}, {"label": "3", "text": "移動はしごは、すべり止め装置の取付けその他転位を防止するために必要な措置を講じたものとした。"}, {"label": "4", "text": "つり上げ荷重5トンの移動式クレーンを使用した玉掛け業務に、玉掛け技能講習を修了した者を就けた。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["脚立は、脚と水平面との角度を80度とし、その角度を保つための金具を備えたものとした。"], "answerHints": [["80度"]], "mnemonic": "正しくは：脚立は脚と水平面との角度を75度以下とする。", "block": 2, "group": 1}, {"id": "H28_kouki_36", "source": "H28後 No.36", "category": "施工管理法", "type": "single", "question": "給水管及び排水管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "横走り給水管から枝管を取り出す際に、配管の上部から取り出した。"}, {"label": "2", "text": "便所の床下排水管は、勾配を考慮して、排水管を給水管より優先して施工した。"}, {"label": "3", "text": "飲料用冷水器の排水は、雑排水系統の排水管に直接接続した。"}, {"label": "4", "text": "横走り給水管の管径を縮小する際に、径違いソケットを使用した。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用冷水器の排水は、雑排水系統の排水管に直接接続した。"], "answerHints": [["雑排水系統の排水管に直接接続"]], "mnemonic": "正しくは：飲料用冷水器の排水は間接排水とする。", "block": 2, "group": 1}, {"id": "H28_kouki_39", "source": "H28後 No.39", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "変風量(VAV)ユニットの入口側に、整流のためのダクト直管部を設けた。"}, {"label": "2", "text": "風量測定口は、風量調整ダンパー下流の気流が整流されたところに設けた。"}, {"label": "3", "text": "ユニバーサル形吹出口は、天井の汚れを防ぐため、天井と吹出口上端との間隔を150mm以上離して取り付けた。"}, {"label": "4", "text": "防火区画と防火ダンパーとの間の被覆をしないダクトは、1.2mmの鋼板製とした。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火区画と防火ダンパーとの間の被覆をしないダクトは、1.2mmの鋼板製とした。"], "answerHints": [["1.2mm"]], "mnemonic": "正しくは：防火区画貫通部と防火ダンパー間のダクトは厚さ1.5mm以上の鋼板製。", "block": 2, "group": 1}, {"id": "H28_kouki_42", "source": "H28後 No.42", "category": "施工管理法", "type": "single", "question": "測定対象と測定機器の組合せのうち、適当でないものはどれか。\n--(測定対象)------(測定機器)", "choices": [{"label": "1", "text": "風量---------熱線風速計"}, {"label": "2", "text": "流量(石油類)-----容積流量計"}, {"label": "3", "text": "騒音---------検知管"}, {"label": "4", "text": "圧力---------マノメーター"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["騒音---------検知管"], "answerHints": [["検知管"]], "mnemonic": "正しくは：騒音は騒音計で測定する（検知管はガス濃度の測定）。", "block": 2, "group": 1}, {"id": "H29_kouki_33", "source": "H29後 No.33", "category": "施工管理法", "type": "single", "question": "建設工事現場の安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "回転する刃物を使用する作業は、手を巻き込むおそれがあるので、手袋の使用を禁止する。"}, {"label": "2", "text": "安全施工サイクルとは、安全朝礼から始まり、安全ミーティング、安全巡回、工程打合せ、片付けまでの日常活動サイクルのことである。"}, {"label": "3", "text": "高さが2mの箇所の作業で、作業床を設けることが困難な場合は、防網を張り、作業者に安全帯を使用させる。"}, {"label": "4", "text": "交流アーク溶接機を用いた作業の継続期間中、自動電撃防止装置の点検は、一週間に一度行わなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["交流アーク溶接機を用いた作業の継続期間中、自動電撃防止装置の点検は、一週間に一度行わなければならない。"], "answerHints": [["一週間に一度"]], "mnemonic": "正しくは：自動電撃防止装置の点検は、その日の作業を開始する前に行う。", "block": 2, "group": 1}, {"id": "H29_kouki_37", "source": "H29後 No.37", "category": "施工管理法", "type": "single", "question": "配管の施工に関する文中、 内に当てはまる語句の組合せのうち、適当なものはどれか。\n樹脂ライニング鋼管を切断する場合は、高速に切断できて切断精度がよい A などを使用し、 B などは使用してはならない。\n---(A)------(B)", "choices": [{"label": "1", "text": "バンドソー-----パイプカッター"}, {"label": "2", "text": "バンドソー-----丸のこ盤"}, {"label": "3", "text": "高速カッター----パイプカッター"}, {"label": "4", "text": "高速カッター----丸のこ盤"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["バンドソー-----パイプカッター"], "answerHints": [["バンドソー", "パイプカッター"]], "mnemonic": "樹脂ライニング鋼管の切断はバンドソー等。パイプカッター・高速砥石・ガス切断は使用不可（ライニングを傷める）。", "block": 2, "group": 1}, {"id": "H29_kouki_40", "source": "H29後 No.40", "category": "施工管理法", "type": "single", "question": "保温、保冷及び塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷温水配管の支持部には、合成樹脂製の支持受けを使用する。"}, {"label": "2", "text": "グラスウール保温材は、ポリスチレンフォーム保温材に比べ、防湿性がよい。"}, {"label": "3", "text": "亜鉛めっきが施されている鋼管に塗装を行う場合は、下地処理としてエッチングプライマーを使用する。"}, {"label": "4", "text": "アルミニウムペイントは、耐水性、耐候性及び耐食性がよく、蒸気管や放熱器の塗装に使用される。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["グラスウール保温材は、ポリスチレンフォーム保温材に比べ、防湿性がよい。"], "answerHints": [["防湿性がよい"]], "mnemonic": "正しくは：グラスウールはポリスチレンフォームより防湿性が劣るが、高温域で使用できる。", "block": 2, "group": 1}, {"id": "H30_zenki_30", "source": "H30前 No.30", "category": "施工管理法", "type": "single", "question": "工程表と関連する用語の組合せのうち、適当でないものはどれか。\n--(工程表)--------(関連する用語)", "choices": [{"label": "1", "text": "ネットワーク工程表---イベント"}, {"label": "2", "text": "ネットワーク工程表---アクティビティー"}, {"label": "3", "text": "バーチャート工程表---予定進度曲線"}, {"label": "4", "text": "バーチャート工程表---ダミー"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表---ダミー"], "answerHints": [["ダミー"]], "mnemonic": "正しくは：ダミーはネットワーク工程表の用語。バーチャート工程表には予定進度曲線（バナナ曲線）。", "block": 2, "group": 1}, {"id": "H30_zenki_34", "source": "H30前 No.34", "category": "施工管理法", "type": "single", "question": "機器の基礎に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ポンプのコンクリート基礎は、基礎表面の排水溝に排水目皿を設け、間接排水できるものとする。"}, {"label": "2", "text": "ユニット形空気調和機の基礎の高さは、ドレンパンからの排水管に空調機用トラップを設けるため150mm程度とする。"}, {"label": "3", "text": "大型ボイラーの基礎は、床スラブ上に打設した無筋コンクリート基礎とする。"}, {"label": "4", "text": "送風機のコンクリート基礎の幅は、送風機架台より100〜200mm程度大きくする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["大型ボイラーの基礎は、床スラブ上に打設した無筋コンクリート基礎とする。"], "answerHints": [["無筋コンクリート基礎"]], "mnemonic": "正しくは：大型ボイラーの基礎は、床スラブと一体の鉄筋コンクリート基礎とする。", "block": 2, "group": 1}, {"id": "H30_zenki_37", "source": "H30前 No.37", "category": "施工管理法", "type": "single", "question": "配管の支持及び固定に関する記述のうち、適当でないものはどれか", "choices": [{"label": "1", "text": "伸縮する配管は、横走り管のすべての支持点で堅固に固定する。"}, {"label": "2", "text": "屋内立て管には、管の座屈を防止するため振れ止めを設ける。"}, {"label": "3", "text": "立て管最下部の固定は、配管荷重に十分耐えうる構造とする。"}, {"label": "4", "text": "配管の曲がり部、分岐部は、その近くの位置で支持する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["伸縮する配管は、横走り管のすべての支持点で堅固に固定する。"], "answerHints": [["すべての支持点で堅固に固定"]], "mnemonic": "正しくは：伸縮する配管は固定点を限定し、他の支持点は伸縮を妨げない支持（ローラー等）とする。", "block": 2, "group": 1}, {"id": "H30_zenki_41", "source": "H30前 No.41", "category": "施工管理法", "type": "single", "question": "自然流下の排水設備の試験として、適当でないものはどれか。", "choices": [{"label": "1", "text": "満水試験"}, {"label": "2", "text": "通水試験"}, {"label": "3", "text": "煙試験"}, {"label": "4", "text": "水圧試験"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水圧試験"], "answerHints": [["水圧試験"]], "mnemonic": "自然流下の排水設備は満水試験・通水試験・煙試験。水圧試験は給水など圧力配管の試験。", "block": 2, "group": 1}, {"id": "H28_kouki_44", "source": "H28後 No.44", "category": "法規", "type": "single", "question": "休日及び有給休暇に関する文中、 内に当てはまる「労働基準法」上に定められている数値の組合せとして、正しいものはどれか。\n使用者は、労働者に対して、毎週少なくとも回の休日を与えなければならない。ただし、4週間を通じ A 日以上の休日を与える使用者については、この限りではない。また、使用者は、雇入れの日から起算して6箇月間継続勤務し、全労働日の8割以上出勤した労働者(一週間の所定労働時間が厚生労働省令で定める時間以上の者)に対して、継続し、又は分割した B 労働日の有給休暇を与えなければならない。\n--(A)-----(B)", "choices": [{"label": "1", "text": "4-------5"}, {"label": "2", "text": "4-------10"}, {"label": "3", "text": "6-------5"}, {"label": "4", "text": "6-------10"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["4-------10"], "answerHints": [["4", "10"]], "mnemonic": "休日は毎週1回または4週4日以上。6箇月継続・8割以上出勤で年次有給休暇10労働日。", "block": 2, "group": 1}, {"id": "H28_kouki_47", "source": "H28後 No.47", "category": "法規", "type": "single", "question": "建設業の許可を受けた建設業者が、工事現場に掲げる標識の記載項目として、「建設業法」上、定められていないものはどれか。", "choices": [{"label": "1", "text": "許可年月日、許可番号及び許可を受けた建設業"}, {"label": "2", "text": "現場代理人の氏名"}, {"label": "3", "text": "主任技術者又は監理技術者の氏名"}, {"label": "4", "text": "一般建設業又は特定建設業の別"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["現場代理人の氏名"], "answerHints": [["現場代理人の氏名"]], "mnemonic": "工事現場の標識に現場代理人の氏名は不要。許可番号等・一般/特定の別・主任技術者/監理技術者の氏名を掲げる。", "block": 2, "group": 1}, {"id": "H28_kouki_50", "source": "H28後 No.50", "category": "法規", "type": "single", "question": "次の建築設備のうち、「エネルギーの使用の合理化等に関する法律」上、エネルギーの効率的利用のための措置を実施することが定められていないものはどれか。", "choices": [{"label": "1", "text": "給湯設備"}, {"label": "2", "text": "照明設備"}, {"label": "3", "text": "給水設備"}, {"label": "4", "text": "空気調和設備"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["給水設備"], "answerHints": [["給水設備"]], "mnemonic": "省エネ法の対象建築設備は空気調和・換気・照明・給湯・昇降機。給水設備は対象外。", "block": 2, "group": 1}, {"id": "H29_kouki_43", "source": "H29後 No.43", "category": "法規", "type": "single", "question": "労働者に対する教育に関する文中、 内に当てはまる語句の組合せとして、「労働安全衛生法」上、正しいものはどれか。\n事業者は、労働者を雇い入れたとき、又は労働者の A を変更したときは、当該労働者に対し、その従事する業務に関する B のための教育を行わなければならない。\n---(A)--------(B)", "choices": [{"label": "1", "text": "作業場-------安全又は衛生"}, {"label": "2", "text": "作業内容------技術の習得"}, {"label": "3", "text": "作業内容------安全又は衛生"}, {"label": "4", "text": "作業場-------技術の習得"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["作業内容------安全又は衛生"], "answerHints": [["作業内容", "安全又は衛生"]], "mnemonic": "雇入れ時・作業内容変更時に「安全又は衛生」のための教育を行う。", "block": 2, "group": 1}, {"id": "H29_kouki_46", "source": "H29後 No.46", "category": "法規", "type": "single", "question": "建築物に設ける排水のための配管設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "排水管は、給水ポンプ、空気調和機その他これらに類する機器の排水管に直接連結してはならない。"}, {"label": "2", "text": "排水トラップの深さは、阻集器を兼ねない場合、15cm以上としなければならない。"}, {"label": "3", "text": "延べ面積が500m2を超える建築物に設ける阻集器は、汚水から油脂、ガソリン、土砂等を有効に分離することができる構造としなければならない。"}, {"label": "4", "text": "排水再利用配管設備の水栓には、排水再利用水であることを示す表示をしなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["排水トラップの深さは、阻集器を兼ねない場合、15cm以上としなければならない。"], "answerHints": [["15cm以上"]], "mnemonic": "正しくは：排水トラップの封水深は5cm以上10cm以下（阻集器を兼ねるものを除く）。", "block": 2, "group": 1}, {"id": "H29_kouki_49", "source": "H29後 No.49", "category": "法規", "type": "single", "question": "次の消防用設備のうち、「消防法」上、非常電源を附置する必要のないものはどれか。", "choices": [{"label": "1", "text": "屋内消火栓設備"}, {"label": "2", "text": "連結散水設備"}, {"label": "3", "text": "不活性ガス消火設備"}, {"label": "4", "text": "スプリンクラー設備"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["必要のないもの"], "answerTexts": ["連結散水設備"], "answerHints": [["連結散水設備"]], "mnemonic": "連結散水設備は消防隊が送水するため非常電源不要。屋内消火栓・スプリンクラー・不活性ガス消火設備は必要。", "block": 2, "group": 1}, {"id": "H29_kouki_52", "source": "H29後 No.52", "category": "法規", "type": "single", "question": "廃棄物の処理に関する文中、 内に当てはまる用語の組合せとして、「廃棄物の処理及び清掃に関する法律」上、正しいものはどれか。\n廃エアコンディショナー(国内における日常生活に伴って生じたものに限る。)に含まれるポリ塩化ビフェニルを使用する部品は A として、また、木くず(建設業に係るもの(工作物の新築、改築又は除去に伴って生じたものに限る。))は B として、適正に処理しなければならない。\n----(A)---------(B)", "choices": [{"label": "1", "text": "特別管理一般廃棄物---一般廃棄物"}, {"label": "2", "text": "特別管理一般廃棄物----産業廃棄物"}, {"label": "3", "text": "特別管理産業廃棄物---一般廃棄物"}, {"label": "4", "text": "特別管理産業廃棄物----産業廃棄物"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["特別管理一般廃棄物----産業廃棄物"], "answerHints": [["特別管理一般廃棄物", "産業廃棄物"]], "mnemonic": "家庭の廃エアコン等のPCB部品は特別管理一般廃棄物。建設業の木くずは産業廃棄物。", "block": 2, "group": 1}, {"id": "H30_zenki_45", "source": "H30前 No.45", "category": "法規", "type": "single", "question": "次の建築物のうち、「建築基準法」上、特殊建築物でないものはどれか。", "choices": [{"label": "1", "text": "寄宿舎"}, {"label": "2", "text": "共同住宅"}, {"label": "3", "text": "事務所"}, {"label": "4", "text": "自動車車庫"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["特殊建築物でないもの"], "answerTexts": ["事務所"], "answerHints": [["事務所"]], "mnemonic": "事務所は特殊建築物でない。寄宿舎・共同住宅・自動車車庫は特殊建築物。", "block": 2, "group": 1}, {"id": "H30_zenki_48", "source": "H30前 No.48", "category": "法規", "type": "single", "question": "建設業の許可に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "都道府県知事の許可を受けた建設業者は、許可を受けた都道府県以外では、工事を請け負うことができない。"}, {"label": "2", "text": "一般建設業の許可を受けた建設業者は、工事の一部を下請負人として請け負った場合でも、主任技術者を置く必要がある。"}, {"label": "3", "text": "2級管工事施工管理技士は、管工事業に係る一般建設業の許可を受ける建設業者が営業所ごとに専任で置く技術者としての要件を満たしている。"}, {"label": "4", "text": "一般建設業の許可を受けた建設業者は、請け負おうとする工事を自ら施工する場合、請負金額の大小にかかわらず請け負うことができる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["都道府県知事の許可を受けた建設業者は、許可を受けた都道府県以外では、工事を請け負うことができない。"], "answerHints": [["工事を請け負うことができない"]], "mnemonic": "正しくは：知事許可の建設業者でも、許可を受けた都道府県以外で工事を請け負い施工できる（制限は営業所の所在地）。", "block": 2, "group": 1}, {"id": "H30_zenki_51", "source": "H30前 No.51", "category": "法規", "type": "single", "question": "指定地域内において行われる特定建設作業に伴って発生する騒音について、災害その他非常の事態の発生により当該特定建設作業を緊急に行う必要がある場合においても、「騒音規制法」上の規制が適用されるものはどれか。", "choices": [{"label": "1", "text": "深夜に行われる作業に伴って発生する騒音"}, {"label": "2", "text": "作業の場所の敷地の境界線において、85デシベルを超える大きさの騒音"}, {"label": "3", "text": "日曜日に行われる作業に伴って発生する騒音"}, {"label": "4", "text": "1日14時間を超えて行われる作業に伴って発生する騒音"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["上の規制が適用されるもの"], "answerTexts": ["作業の場所の敷地の境界線において、85デシベルを超える大きさの騒音"], "answerHints": [["85デシベルを超える"]], "mnemonic": "緊急時でも敷地境界で85デシベルを超える騒音の規制は適用。夜間・日曜・作業時間の規制は適用除外。", "block": 2, "group": 1}, {"id": "H28_kouki_03", "source": "H28後 No.3", "category": "一般基礎", "type": "single", "question": "ピトー管に関する文中、 内に当てはまる用語の組合せとして、適当なものはどれか。\nピトー管は、全圧と A の差を測定する計器で、この測定値から B を算出することができる。\n---(A)------(B)", "choices": [{"label": "1", "text": "静圧------流速"}, {"label": "2", "text": "静圧------摩擦損失"}, {"label": "3", "text": "動圧------流速"}, {"label": "4", "text": "動圧------摩擦損失"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["静圧------流速"], "answerHints": [["静圧", "流速"]], "mnemonic": "ピトー管は全圧と静圧の差（＝動圧）を測り、流速を算出する。", "block": 3, "group": 1}, {"id": "H28_kouki_06", "source": "H28後 No.6", "category": "一般基礎", "type": "single", "question": "コンクリート工事に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "打込み後、硬化中のコンクリートに振動及び外力を加えないようにする。"}, {"label": "2", "text": "型枠の最小存置期間は、平均気温が低いほど長くする。"}, {"label": "3", "text": "コンクリートのスランプ値が大きくなると、ワーカビリティーが悪くなる。"}, {"label": "4", "text": "夏期の打込み後のコンクリートは、急激な乾燥を防ぐために湿潤養生を行う。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["コンクリートのスランプ値が大きくなると、ワーカビリティーが悪くなる。"], "answerHints": [["ワーカビリティーが悪くなる"]], "mnemonic": "正しくは：スランプ値が大きいほど軟らかく、ワーカビリティーは良くなる。", "block": 3, "group": 1}, {"id": "H29_kouki_03", "source": "H29後 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "流体の粘性の影響は、流体に接する壁面近くでは無視できる。"}, {"label": "2", "text": "レイノルズ数は、層流と乱流の判定の目安になる。"}, {"label": "3", "text": "毛管現象は、液体の表面張力によるものである。"}, {"label": "4", "text": "ベルヌーイの定理は、エネルギー保存の法則を示したものである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["流体の粘性の影響は、流体に接する壁面近くでは無視できる。"], "answerHints": [["無視できる"]], "mnemonic": "正しくは：粘性の影響は壁面近くで大きく、無視できない。", "block": 3, "group": 1}, {"id": "H30_zenki_01", "source": "H30前 No.1", "category": "一般基礎", "type": "single", "question": "空気環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "二酸化炭素は、直接人体に有害ではない気体で、空気より軽い。"}, {"label": "2", "text": "一酸化炭素は、無色無臭で、人体に有害な気体である。"}, {"label": "3", "text": "浮遊粉じん量は、室内空気の汚染度を示す指標の一つである。"}, {"label": "4", "text": "揮発性有機化合物(VOCs)は、シックハウス症候群の主要因とされている。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["二酸化炭素は、直接人体に有害ではない気体で、空気より軽い。"], "answerHints": [["空気より軽い"]], "mnemonic": "正しくは：二酸化炭素は空気より重い。", "block": 3, "group": 1}, {"id": "H30_zenki_04", "source": "H30前 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "固体が直接気体になる相変化を昇華という。"}, {"label": "2", "text": "単位質量の物体の温度を1°C上げるのに必要な熱量を比熱という。"}, {"label": "3", "text": "気体では、定容比熱より定圧比熱のほうが大きい。"}, {"label": "4", "text": "温度変化を伴わずに、物体の相変化のみに消費される熱を顕熱という。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["温度変化を伴わずに、物体の相変化のみに消費される熱を顕熱という。"], "answerHints": [["顕熱"]], "mnemonic": "正しくは：温度変化を伴わず相変化のみに使われる熱は「潜熱」。", "block": 3, "group": 1}, {"id": "H28_kouki_09", "source": "H28後 No.9", "category": "空調・衛生", "type": "single", "question": "空気調和の熱負荷計算に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "暖房負荷計算では、一般に、日射負荷は考慮しない。"}, {"label": "2", "text": "構造体の構成材質が同じであれば、厚さの薄い方が熱通過率は小さくなる。"}, {"label": "3", "text": "外気による熱負荷を計算する場合、顕熱と潜熱を考慮する。"}, {"label": "4", "text": "窓ガラス面からの冷房負荷計算では、ひさしや袖壁の影響も考慮する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["構造体の構成材質が同じであれば、厚さの薄い方が熱通過率は小さくなる。"], "answerHints": [["薄い方"]], "mnemonic": "正しくは：同じ材質なら厚さの厚い方が熱通過率は小さくなる。", "block": 3, "group": 1}, {"id": "H28_kouki_12", "source": "H28後 No.12", "category": "空調・衛生", "type": "single", "question": "温水暖房における膨張タンクに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "密閉式膨張タンクを用いる場合には、安全弁などの安全装置が必要である。"}, {"label": "2", "text": "密閉式膨張タンクは、一般に、ダイヤフラム内に封入された空気の圧縮性を利用している。"}, {"label": "3", "text": "開放式膨張タンクは、装置内の空気の排出口として利用できる。"}, {"label": "4", "text": "開放式膨張タンクに接続する膨張管は、循環ポンプの吸込み側には設けない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["開放式膨張タンクに接続する膨張管は、循環ポンプの吸込み側には設けない。"], "answerHints": [["吸込み側には設けない"]], "mnemonic": "正しくは：開放式膨張タンクの膨張管は循環ポンプの吸込み側の配管に接続する。", "block": 3, "group": 1}, {"id": "H28_kouki_17", "source": "H28後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "クロスコネクションとは、飲料水配管とそれ以外の配管とが直接接続されることをいう。"}, {"label": "2", "text": "ウォーターハンマーを防止するため、給水管にエアチャンバーを設置した。"}, {"label": "3", "text": "水道直結増圧方式の給水栓にかかる圧力は、水道本管の圧力に応じて変化する。"}, {"label": "4", "text": "水道直結増圧方式は、高置タンク方式に比べて、ポンプの吐出量が大きくなる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水道直結増圧方式の給水栓にかかる圧力は、水道本管の圧力に応じて変化する。"], "answerHints": [["水道本管の圧力に応じて変化する"]], "mnemonic": "正しくは：水道直結増圧方式は増圧ポンプで給水圧力をほぼ一定に保つ。", "block": 3, "group": 1}, {"id": "H28_kouki_20", "source": "H28後 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "伸頂通気方式は、通気立て管を設けず、排水立て管上部を延長し通気管として使用するものである。"}, {"label": "2", "text": "ループ通気方式は、各個通気方式に比べて機能上優れている。"}, {"label": "3", "text": "ループ通気管は、通気立て管又は伸頂通気管に接続するか、あるいは大気に開放する。"}, {"label": "4", "text": "最上階を除き、大便器8個以上を受け持つ排水横枝管には、ループ通気管を設けるほかに、逃し通気管を設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ループ通気方式は、各個通気方式に比べて機能上優れている。"], "answerHints": [["機能上優れている"]], "mnemonic": "正しくは：各個通気方式の方がループ通気方式より機能上優れている。", "block": 3, "group": 1}, {"id": "H28_kouki_23", "source": "H28後 No.23", "category": "空調・衛生", "type": "single", "question": "工場生産浄化槽の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "地下水位による槽の浮上防止対策として、槽の周囲に山砂を入れ、突き固めて水締めを行う。"}, {"label": "2", "text": "本体の水平調整はライナーなどで行い、槽と底版コンクリートの隙間が大きいときは、隙間にモルタルを充てんする。"}, {"label": "3", "text": "埋戻しは、土圧による本体及び内部設備の変形を防止するため、槽に水張りした状態で行う。"}, {"label": "4", "text": "底版コンクリートは、打設後、所要の強度が確認できるまで養生する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["地下水位による槽の浮上防止対策として、槽の周囲に山砂を入れ、突き固めて水締めを行う。"], "answerHints": [["山砂を入れ、突き固めて水締め"]], "mnemonic": "正しくは：浮上防止は浮上防止金具等で槽を底版コンクリートに固定する（山砂の水締めは埋戻し方法）。", "block": 3, "group": 1}, {"id": "H29_kouki_10", "source": "H29後 No.10", "category": "空調・衛生", "type": "single", "question": "冷房の熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "窓ガラス面からの熱負荷を計算するときは、ブラインドの有無も考慮する。"}, {"label": "2", "text": "OA機器による熱負荷は、顕熱と潜熱がある。"}, {"label": "3", "text": "日射負荷は、顕熱のみである。"}, {"label": "4", "text": "人体による熱負荷は、作業形態と室温によって異なる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["OA機器による熱負荷は、顕熱と潜熱がある。"], "answerHints": [["顕熱と潜熱がある"]], "mnemonic": "正しくは：OA機器による熱負荷は顕熱のみ。", "block": 3, "group": 1}, {"id": "H29_kouki_13", "source": "H29後 No.13", "category": "空調・衛生", "type": "single", "question": "特殊建築物の居室に機械換気設備を設ける場合、有効換気量の最小値を算出する式として、「建築基準法」上、正しいものはどれか。\nただし、V:有効換気量 [m3/h]・Af:居室の床面積[m2]・N:実況に応じた1人当たりの占有面積[m2]", "choices": [{"label": "1", "text": "V= 10Af / N"}, {"label": "2", "text": "V= 20Af / N"}, {"label": "3", "text": "V= 50Af / N"}, {"label": "4", "text": "V=100Af / N"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["V= 20Af / N"], "answerHints": [["20Af / N"]], "mnemonic": "特殊建築物の居室の有効換気量 V＝20Af／N（1人1時間あたり20m³）。", "block": 3, "group": 1}, {"id": "H29_kouki_16", "source": "H29後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道管きょに関する文中、 内に当てはまる用語の組合せとして、適当なものはどれか。\n下水道管きょは、原則として、放流管きょを除いて A とする。また、合流式の下水道管きょ径が変化する場合の接合方法は、原則として、 B 又は管頂接合とする。\n---(A)--------(B)", "choices": [{"label": "1", "text": "開きょ------水面接合"}, {"label": "2", "text": "暗きょ------管底接合"}, {"label": "3", "text": "暗きょ------水面接合"}, {"label": "4", "text": "開きょ------管底接合"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["暗きょ------水面接合"], "answerHints": [["暗きょ", "水面接合"]], "mnemonic": "下水道管きょは原則暗きょ。管径が変わる接合は水面接合又は管頂接合。", "block": 3, "group": 1}, {"id": "H29_kouki_20", "source": "H29後 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "間接排水を受ける水受け容器として、手洗い器、洗面器を利用してはならない。"}, {"label": "2", "text": "通気管の主な目的は、排水トラップの封水が破れないようにすることである。"}, {"label": "3", "text": "通気管は、管内の水滴が自然流下によって排水管に流れるように勾配をとる。"}, {"label": "4", "text": "ループ通気管は、床下で横引きし、床下で直接通気立て管に接続する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ループ通気管は、床下で横引きし、床下で直接通気立て管に接続する。"], "answerHints": [["床下で直接通気立て管に接続"]], "mnemonic": "正しくは：ループ通気管は最上位器具のあふれ縁より150mm以上立ち上げてから通気立て管に接続する（床下で横引きしない）。", "block": 3, "group": 1}, {"id": "H30_zenki_07", "source": "H30前 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクト併用ファンコイルユニット方式では、空調対象室への熱媒体として空気と水の両方が使用される。"}, {"label": "2", "text": "ダクト併用ファンコイルユニット方式は、全空気方式に比べてダクトスペースが大きくなる。"}, {"label": "3", "text": "マルチパッケージ形空気調和方式は、屋内機ごとに運転、停止ができる。"}, {"label": "4", "text": "マルチパッケージ形空気調和方式には、屋内機に加湿器を組み込んだものがある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクト併用ファンコイルユニット方式は、全空気方式に比べてダクトスペースが大きくなる。"], "answerHints": [["大きくなる"]], "mnemonic": "正しくは：ダクト併用ファンコイルユニット方式は、全空気方式よりダクトスペースが小さくなる。", "block": 3, "group": 1}, {"id": "H30_zenki_11", "source": "H30前 No.11", "category": "空調・衛生", "type": "single", "question": "温水暖房設備の特徴に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配管径は、一般的に、蒸気暖房に比べて小さくなる。"}, {"label": "2", "text": "室内の温度制御は、蒸気暖房に比べて容易である。"}, {"label": "3", "text": "ウォーミングアップにかかる時間は、蒸気暖房に比べて長い。"}, {"label": "4", "text": "配管の耐食性は、一般的に、蒸気暖房に比べて優れている。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["配管径は、一般的に、蒸気暖房に比べて小さくなる。"], "answerHints": [["小さくなる"]], "mnemonic": "正しくは：温水暖房の配管径は蒸気暖房より大きくなる。", "block": 3, "group": 1}, {"id": "H30_zenki_15", "source": "H30前 No.15", "category": "空調・衛生", "type": "single", "question": "上水道における配水管の布設に関する文中、 内に当てはまる数値及び語句の組合せとして、適当なものはどれか。\n配水管を他の地下埋設物と交差又は近接して布設するときは、少なくとも A m以上の間隔を保って布設する。また、地下水位が高い場所に布設する場合には、管の B を講じる。\n--(A)--------(B)", "choices": [{"label": "1", "text": "0.3-------沈下対策"}, {"label": "2", "text": "0.6-------沈下対策"}, {"label": "3", "text": "0.3-------浮上防止策"}, {"label": "4", "text": "0.6-------浮上防止策"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["0.3-------浮上防止策"], "answerHints": [["0.3", "浮上防止策"]], "mnemonic": "配水管は他の埋設物と0.3m以上離す。地下水位が高い場所では浮上防止策。", "block": 3, "group": 1}, {"id": "H30_zenki_18", "source": "H30前 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する文中、 内に当てはまる数値及び語句の組合せとして、適当なものはどれか。\nガス瞬間湯沸器の能力は、水温の上昇温度を A °C とした場合の出湯量1L/minを1号としている。住宅のシャワーなどへの給湯用にガス瞬間湯沸器を使用する場合には、 B が適している。\n--(A)------(B)", "choices": [{"label": "1", "text": "15-----元止め式"}, {"label": "2", "text": "25-----先止め式"}, {"label": "3", "text": "15-----先止め式"}, {"label": "4", "text": "25-----元止め式"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["25-----先止め式"], "answerHints": [["25", "先止め式"]], "mnemonic": "号数＝水温25℃上昇で1L/minが1号。シャワー等の給湯は先止め式。", "block": 3, "group": 1}, {"id": "H30_zenki_22", "source": "H30前 No.22", "category": "空調・衛生", "type": "single", "question": "ガス漏れ警報器に関する文中、 内に当てはまる数値及び語句の組合せとして、適当なものはどれか。\n液化石油ガスのガス漏れ警報器の検知部は、ガス機器からの水平距離が A m 以内で、かつ、 B から30cm以内の位置に設置しなければならない。\n--(A)-----(B)", "choices": [{"label": "1", "text": "8------床面"}, {"label": "2", "text": "4------床面"}, {"label": "3", "text": "8------天井面"}, {"label": "4", "text": "4------天井面"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["4------床面"], "answerHints": [["4", "床面"]], "mnemonic": "LPG警報器の検知部はガス機器から水平距離4m以内、床面から30cm以内（LPGは空気より重い）。", "block": 3, "group": 1}, {"id": "H28_kouki_25", "source": "H28後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "保温材に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "グラスウール保温材は、ポリスチレンフォーム保温材に比べて透湿性が小さい。"}, {"label": "2", "text": "ポリスチレンフォーム保温材は、主に保冷用として使用される。"}, {"label": "3", "text": "ロックウール保温板、グラスウール保温板の種類は、密度によって区分される。"}, {"label": "4", "text": "繊維系保温材の種類には、保温板、保温帯、保温筒などがある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["グラスウール保温材は、ポリスチレンフォーム保温材に比べて透湿性が小さい。"], "answerHints": [["透湿性が小さい"]], "mnemonic": "正しくは：グラスウールはポリスチレンフォームより透湿性が大きい（その代わり高温域で使用できる）。", "block": 3, "group": 1}, {"id": "H29_kouki_24", "source": "H29後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吸収冷温水機の吸収溶液には、臭化リチウム水溶液が用いられている。"}, {"label": "2", "text": "冷却塔は、冷却水の蒸発潜熱により冷却水の水温を下げる装置である。"}, {"label": "3", "text": "多翼送風機は、構造上高速回転に適しているため、高い圧力を出すことができる。"}, {"label": "4", "text": "ろ過式の粗じん用エアフィルターの構造は、パネル型が主体となっている。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["多翼送風機は、構造上高速回転に適しているため、高い圧力を出すことができる。"], "answerHints": [["構造上高速回転に適している", "高い圧力を出すことができる"]], "mnemonic": "正しくは：多翼送風機は高速回転に適さず、高い圧力は出せない（低圧・大風量向き）。", "block": 3, "group": 1}, {"id": "H29_kouki_27", "source": "H29後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "エルボの圧力損失は、曲率半径が大きいほど大きくなる。"}, {"label": "2", "text": "シーリングディフューザー形吹出口は、誘引作用が大きく気流分布が優れた吹出口である。"}, {"label": "3", "text": "スパイラルダクトの接続には、差込み継手又はフランジ継手が用いられる。"}, {"label": "4", "text": "たわみ継手は、送風機等からの振動がダクトに伝わることを防止するために用いられる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["エルボの圧力損失は、曲率半径が大きいほど大きくなる。"], "answerHints": [["大きくなる"]], "mnemonic": "正しくは：エルボの圧力損失は曲率半径が大きいほど小さくなる。", "block": 3, "group": 1}, {"id": "H30_zenki_26", "source": "H30前 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "伸縮管継手は、流体の温度変化に伴う配管の伸縮を吸収するために設ける。"}, {"label": "2", "text": "硬質ポリ塩化ビニル管のVU管は、VP管に比べ耐圧性が高い。"}, {"label": "3", "text": "銅管は、肉厚の大きい順にK、L、Mタイプがあり、一般的に、Mタイプを用いることが多い。"}, {"label": "4", "text": "フレキシブルジョイントは、ゴム製とステンレス製に大別され、使用流体の種類、温度及び圧力により使い分ける必要がある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["硬質ポリ塩化ビニル管のVU管は、VP管に比べ耐圧性が高い。"], "answerHints": [["耐圧性が高い"]], "mnemonic": "正しくは：VU管はVP管より肉厚が薄く、設計圧力が低い。", "block": 3, "group": 1}, {"id": "H28_kouki_31", "source": "H28後 No.31", "category": "施工管理法", "type": "single", "question": "工程表に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ガントチャート工程表は、各作業の現時点における進行状態が達成度により把握でき、作成も容易である。"}, {"label": "2", "text": "ネットワーク工程表は、ガントチャート工程表に比べて、他工事との関係がわかりやすい。"}, {"label": "3", "text": "バーチャート工程表は、ネットワーク工程表より遅れに対する対策が立てやすい。"}, {"label": "4", "text": "バーチャート工程表は、通常、横軸に暦日がとられ、各作業の施工時期や所要日数がわかりやすい。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表は、ネットワーク工程表より遅れに対する対策が立てやすい。"], "answerHints": [["遅れに対する対策が立てやすい"]], "mnemonic": "正しくは：遅れに対する対策は、ネットワーク工程表の方がバーチャートより立てやすい。", "block": 3, "group": 1}, {"id": "H28_kouki_34", "source": "H28後 No.34", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷凍機の据付けにあっては、凝縮器のチューブ引出し用として、有効な空間を確保する。"}, {"label": "2", "text": "遠心送風機の据付けにあっては、レベルを水準器で検査し、水平が出ていない場合は基礎と共通架台の間にライナーを入れて調整する。"}, {"label": "3", "text": "壁掛け形ルームエアコンの取付けにあっては、内装材や下地材に応じて補強を施す。"}, {"label": "4", "text": "地上設置のポンプの吸込み管は、ポンプに向かって下がり勾配とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["地上設置のポンプの吸込み管は、ポンプに向かって下がり勾配とする。"], "answerHints": [["下がり勾配"]], "mnemonic": "正しくは：ポンプの吸込み管はポンプに向かって上がり勾配とする（空気だまり防止）。", "block": 3, "group": 1}, {"id": "H28_kouki_37", "source": "H28後 No.37", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか", "choices": [{"label": "1", "text": "フレキシブルジョイントは、温水配管の収縮を吸収するために使用される。"}, {"label": "2", "text": "給水配管において、電位差が大きい異種金属を接合する場合は、絶縁フランジなどによる措置が必要である。"}, {"label": "3", "text": "さや管ヘッダー配管方式のさや管と実管を同時に施工してはならない。"}, {"label": "4", "text": "ポンプ振動の配管への伝播を防止するためには、防振継手を設ける。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["フレキシブルジョイントは、温水配管の収縮を吸収するために使用される。"], "answerHints": [["温水配管の収縮を吸収する"]], "mnemonic": "正しくは：配管の伸縮吸収は伸縮管継手。フレキシブルジョイントは変位・振動の吸収用。", "block": 3, "group": 1}, {"id": "H28_kouki_40", "source": "H28後 No.40", "category": "施工管理法", "type": "single", "question": "保温・塗装工事に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋外の外装金属板の継目は、シーリング材によりシールを施す。"}, {"label": "2", "text": "機器廻り配管の保温・保冷工事は、水圧試験後に行う。"}, {"label": "3", "text": "ロックウール保温材は、グラスウール保温材に比べ、使用できる最高温度が低い。"}, {"label": "4", "text": "アルミニウム面やステンレス面は、一般に、塗装を行わない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ロックウール保温材は、グラスウール保温材に比べ、使用できる最高温度が低い。"], "answerHints": [["最高温度が低い"]], "mnemonic": "正しくは：ロックウールはグラスウールより最高使用温度が高い。", "block": 3, "group": 1}, {"id": "H29_kouki_29", "source": "H29後 No.29", "category": "施工管理法", "type": "single", "question": "総合的な施工計画を立てる際に行うべき業務として、適当でないものはどれか。", "choices": [{"label": "1", "text": "設計図書にくい違いがある場合は、現場代理人が判断し、その結果の記録を残す。"}, {"label": "2", "text": "材料及び機器について、メーカーリストを作成し、発注、納期、製品検査の日程などを計画する。"}, {"label": "3", "text": "設計図書により、工事内容を把握し、諸官庁へ提出が必要な書類を確認する。"}, {"label": "4", "text": "敷地の状況、近隣関係、道路関係を調査し、設計図書で示されない概況を把握する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["設計図書にくい違いがある場合は、現場代理人が判断し、その結果の記録を残す。"], "answerHints": [["現場代理人が判断し"]], "mnemonic": "正しくは：設計図書にくい違いがあれば、監督員に確認して指示を受ける。", "block": 3, "group": 1}, {"id": "H29_kouki_35", "source": "H29後 No.35", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷凍機の保守点検のため、周囲に1m以上のスペースを確保する。"}, {"label": "2", "text": "送風機は、製造者によりあらかじめ心出し調整されているので、据付け後に再心出しを行う必要はない。"}, {"label": "3", "text": "汚物排水槽に設ける排水用水中モーターポンプは、点検、引き上げに支障がないように、点検用マンホールの真下近くに設置する。"}, {"label": "4", "text": "ポンプは、現場にて軸心の狂いのないことを確認し、カップリング外周の段違いや面間の誤差がないようにする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送風機は、製造者によりあらかじめ心出し調整されているので、据付け後に再心出しを行う必要はない。"], "answerHints": [["再心出しを行う必要はない"]], "mnemonic": "正しくは：送風機は据付け後に再度心出し調整を行う（輸送・据付けで狂うため）。", "block": 3, "group": 1}, {"id": "H29_kouki_38", "source": "H29後 No.38", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "厨房の排気ダクトには、油や結露水が滞留するおそれがあるため、継手部に耐熱性の材料のシールを施す。"}, {"label": "2", "text": "送風機の接続ダクトに取り付ける風量測定口は、送風機の吐出し口の直後に取り付ける。"}, {"label": "3", "text": "長方形ダクトのエルボの内側半径は、ダクト幅の 1/2 以上とする。"}, {"label": "4", "text": "低圧ダクトに用いるコーナーボルト工法ダクトの板厚は、アングルフランジ工法ダクトと同じとしてもよい。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送風機の接続ダクトに取り付ける風量測定口は、送風機の吐出し口の直後に取り付ける。"], "answerHints": [["吐出し口の直後"]], "mnemonic": "正しくは：風量測定口は吐出し口直後を避け、気流が整流された直管部に設ける。", "block": 3, "group": 1}, {"id": "H29_kouki_41", "source": "H29後 No.41", "category": "施工管理法", "type": "single", "question": "渦巻きポンプの試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "呼水栓等から注水してポンプ内を満水にすることにより、ポンプ内のエア抜きを行う。"}, {"label": "2", "text": "吸込み側の弁を全開にして、吐出し側の弁を閉じた状態から徐々に弁を開いて水量を調整する。"}, {"label": "3", "text": "メカニカルシール部から一定量の漏れ量があることを確認する。"}, {"label": "4", "text": "瞬時運転を行い、ポンプの回転方向と異常音や異常振動が無いことを確認する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["メカニカルシール部から一定量の漏れ量があることを確認する。"], "answerHints": [["メカニカルシール部", "一定量の漏れ量がある"]], "mnemonic": "正しくは：メカニカルシールは漏れがほとんどないことを確認する（一定量の滴下を確認するのはグランドパッキン）。", "block": 3, "group": 1}, {"id": "H30_zenki_31", "source": "H30前 No.31", "category": "施工管理法", "type": "single", "question": "工程表に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "バーチャート工程表は、ネットワーク工程表に比べて作業遅れへの対策が立てやすい。"}, {"label": "2", "text": "ネットワーク工程表は、ガントチャート工程表に比べて、各作業の関係がわかりやすい。"}, {"label": "3", "text": "ガントチャート工程表は、各作業の現時点における進行状態を達成度により示すものである。"}, {"label": "4", "text": "バーチャート工程表は、一般的に、横軸に暦日がとられ、各作業の施工時期や所要日数がわかりやすい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表は、ネットワーク工程表に比べて作業遅れへの対策が立てやすい。"], "answerHints": [["作業遅れへの対策が立てやすい"]], "mnemonic": "正しくは：バーチャート工程表はネットワーク工程表に比べて作業遅れへの対策が立てにくい。", "block": 3, "group": 1}, {"id": "H30_zenki_35", "source": "H30前 No.35", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか", "choices": [{"label": "1", "text": "飲料用受水タンクの上部には、空調用配管、排水管等を設けないようにする。"}, {"label": "2", "text": "揚水ポンプの吐出し側には、ポンプに近い順に、防振継手、仕切弁、逆止め弁を取り付ける。"}, {"label": "3", "text": "パッケージ形空気調和機の屋外機の騒音対策として、防音壁を設置する。"}, {"label": "4", "text": "飲料用受水タンクは、高さ60cmの梁形コンクリート基礎上に据え付ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["揚水ポンプの吐出し側には、ポンプに近い順に、防振継手、仕切弁、逆止め弁を取り付ける。"], "answerHints": [["仕切弁、逆止め弁"]], "mnemonic": "正しくは：ポンプ吐出し側はポンプに近い順に防振継手 → 逆止め弁 → 仕切弁。", "block": 3, "group": 1}, {"id": "H30_zenki_38", "source": "H30前 No.38", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "浴室の排気に長方形ダクトを使用する場合は、ダクトの継目が下面にならないように取り付ける。"}, {"label": "2", "text": "共板フランジ工法ダクトの最大つり支持間隔は、アングルフランジ工法ダクトより短い。"}, {"label": "3", "text": "防火ダンパーの温度ヒューズの溶融温度は、一般排気系統及び厨房排気系統ともに72°Cとする。"}, {"label": "4", "text": "風量調整ダンパーは、原則として、気流の整流されたところに取り付ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火ダンパーの温度ヒューズの溶融温度は、一般排気系統及び厨房排気系統ともに72°Cとする。"], "answerHints": [["厨房排気系統ともに72°C"]], "mnemonic": "正しくは：温度ヒューズの溶融温度は一般排気系統72℃、厨房排気系統120℃。", "block": 3, "group": 1}, {"id": "H30_zenki_42", "source": "H30前 No.42", "category": "施工管理法", "type": "single", "question": "多翼送風機の試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "Vベルトの張り具合は、たわみ量が適正値に収まるように調整する。"}, {"label": "2", "text": "送風機の軸を手で回し、接触や異常音がなく円滑に回転することを確認する。"}, {"label": "3", "text": "吐出し側の風量調整ダンパーを全開の状態から徐々に絞って、規定風量になるように調整する。"}, {"label": "4", "text": "瞬時運転を行い、回転方向が正しいことを確認する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["吐出し側の風量調整ダンパーを全開の状態から徐々に絞って、規定風量になるように調整する。"], "answerHints": [["全開の状態から徐々に絞って"]], "mnemonic": "正しくは：吐出し側ダンパーを全閉から徐々に開いて規定風量に調整する（全開起動は過負荷のおそれ）。", "block": 3, "group": 1}, {"id": "H28_kouki_45", "source": "H28後 No.45", "category": "法規", "type": "single", "question": "建築の用語に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建築物に設ける煙突は、建築設備である。"}, {"label": "2", "text": "モルタルは、不燃材料である。"}, {"label": "3", "text": "熱源機器の過半を更新する工事は、大規模の修繕である。"}, {"label": "4", "text": "継続的に使用される会議室は、居室である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["熱源機器の過半を更新する工事は、大規模の修繕である。"], "answerHints": [["大規模の修繕である"]], "mnemonic": "正しくは：熱源機器の更新は大規模の修繕ではない（大規模の修繕は主要構造部の一種以上の過半の修繕）。", "block": 3, "group": 1}, {"id": "H28_kouki_48", "source": "H28後 No.48", "category": "法規", "type": "single", "question": "建設業の許可に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "一般建設業の許可を受けた建設業者は、請け負おうとする工事を自ら施工する場合、請負金額の大小にかかわらず請け負うことができる。"}, {"label": "2", "text": "建設業の許可を受けた建設業者は、工事の一部を下請負人として請け負った場合でも、主任技術者を置く必要がある。"}, {"label": "3", "text": "2級管工事施工管理技士は、管工事業に係る一般建設業の許可を受ける建設業者が営業所ごとに専任で置く技術者としての要件を満たしている。"}, {"label": "4", "text": "都道府県知事の許可を受けた建設業者は、許可を受けた都道府県以外では、工事を請け負うことができない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["都道府県知事の許可を受けた建設業者は、許可を受けた都道府県以外では、工事を請け負うことができない。"], "answerHints": [["工事を請け負うことができない"]], "mnemonic": "正しくは：知事許可の建設業者でも、許可を受けた都道府県以外で工事を請け負い施工できる（制限は営業所の所在地）。", "block": 3, "group": 1}, {"id": "H28_kouki_51", "source": "H28後 No.51", "category": "法規", "type": "single", "question": "浄化槽工事に関する記述のうち、「浄化槽法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "浄化槽を設置した場合は、使用を開始する前に、指定検査機関の行う水質検査を受けなければならない。"}, {"label": "2", "text": "浄化槽を工場で製造する場合、型式について、国土交通大臣の認定を受けた。"}, {"label": "3", "text": "浄化槽工事を行う場合、浄化槽設備士の資格を有する浄化槽工事業者が自ら実地に監督した。"}, {"label": "4", "text": "浄化槽工事業者は、営業所ごとに、氏名又は名称、登録番号等を記載した標識を見やすい場所に掲げなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["浄化槽を設置した場合は、使用を開始する前に、指定検査機関の行う水質検査を受けなければならない。"], "answerHints": [["使用を開始する前に"]], "mnemonic": "正しくは：新設浄化槽の水質検査は使用開始後一定期間内（3か月経過後5か月以内）に受ける。", "block": 3, "group": 1}, {"id": "H29_kouki_44", "source": "H29後 No.44", "category": "法規", "type": "single", "question": "労働者名簿及び賃金台帳に関する記述のうち、「労働基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "使用者は、各事業場ごとに、日々雇い入れる者を除き、労働者名簿を作成しなければならない。"}, {"label": "2", "text": "使用者は、各事業場ごとに、賃金計算の基礎となる事項等を記入した賃金台帳を作成しなければならない。"}, {"label": "3", "text": "労働者名簿には、労働者の性別、戸籍、住所等を記入しなければならない。"}, {"label": "4", "text": "賃金台帳には、労働者の氏名、性別、労働日数等を記入しなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["労働者名簿には、労働者の性別、戸籍、住所等を記入しなければならない。"], "answerHints": [["戸籍"]], "mnemonic": "正しくは：労働者名簿に戸籍の記入は不要（氏名・生年月日・履歴・性別・住所・業務の種類・雇入年月日など）。", "block": 3, "group": 1}, {"id": "H29_kouki_47", "source": "H29後 No.47", "category": "法規", "type": "single", "question": "建設業を営もうとする者のうち、「建設業法」上、必要となる建設業の許可が国土交通大臣の許可に限られる者はどれか。ただし、政令で定める軽微な建設工事のみを請け負う者を除く。", "choices": [{"label": "1", "text": "2以上の都道府県の区域内に営業所を設けて営業をしようとする者"}, {"label": "2", "text": "2以上の都道府県の区域にまたがる建設工事を施工しようとする者"}, {"label": "3", "text": "請負代金の額が3,500万円以上の建設工事を施工しようとする者"}, {"label": "4", "text": "4,000万円以上の下請契約を締結して建設工事を施工しようとする者"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["国土交通大臣の許可に限られる者"], "answerTexts": ["2以上の都道府県の区域内に営業所を設けて営業をしようとする者"], "answerHints": [["2以上の都道府県の区域内に営業所"]], "mnemonic": "大臣許可が必要なのは2以上の都道府県に営業所を設ける場合。工事場所・金額は無関係。", "block": 3, "group": 1}, {"id": "H29_kouki_50", "source": "H29後 No.50", "category": "法規", "type": "single", "question": "特定建設資材廃棄物の再資源化に関する文中、 内に当てはまる語句として、「建設工事に係る資材の再資源化等に関する法律」上、正しいものはどれか。\n建築物に係る の受注者は、当該工事に係る部分の床面積の合計が80m2以上の場合、分別解体等に伴って生じた特定建設資材廃棄物について、再資源化をしなければならない。ただし、指定建設資材廃棄物に該当する特定建設資材廃棄物については、地理的条件、交通事情その他の事情により再資源化をすることには相当程度に経済性の面での制約があるものとして主務省令で定める場合には、再資源化に代えて縮減をすれば足りる。", "choices": [{"label": "1", "text": "新築工事"}, {"label": "2", "text": "解体工事"}, {"label": "3", "text": "増築工事"}, {"label": "4", "text": "改修工事"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["解体工事"], "answerHints": [["解体工事"]], "mnemonic": "建設リサイクル法：建築物の解体工事は床面積80m²以上が対象（新築・増築は500m²以上）。", "block": 3, "group": 1}, {"id": "H30_zenki_43", "source": "H30前 No.43", "category": "法規", "type": "single", "question": "移動式クレーンの運転業務に関する文中、 内に当てはまる、「労働安全衛生法」上に定められている数値として、正しいものはどれか。\n事業者は、つり上げ荷重が1トン以上の移動式クレーンの運転(道路交通法に規定する道路上を走行させる運転を除く。)の業務については、移動式クレーン運転士免許を受けた者でなければ、当該業務に就かせてはならない。ただし、つり上げ荷重が1トン以上、 トン未満の移動式クレーンの運転の業務については、小型移動式クレーン運転技能講習を修了した者を当該業務に就かせることができる。", "choices": [{"label": "1", "text": "3"}, {"label": "2", "text": "4"}, {"label": "3", "text": "5"}, {"label": "4", "text": "6"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["5"], "answerHints": [["5"]], "mnemonic": "移動式クレーン：5t以上は免許、1t以上5t未満は小型移動式クレーン運転技能講習。", "block": 3, "group": 1}, {"id": "H30_zenki_46", "source": "H30前 No.46", "category": "法規", "type": "single", "question": "建築物に設ける中央管理方式の空気調和設備によって、居室の空気が適合しなければならない基準として、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "一酸化炭素の含有率は、おおむね 100万分の 10以下とする。"}, {"label": "2", "text": "炭酸ガスの含有率は、おおむね 100万分の 1,000以下とする。"}, {"label": "3", "text": "相対湿度は、おおむね 40 %以上 70 %以下とする。"}, {"label": "4", "text": "気流は、おおむね1秒間につき 1.0m以上 2.0m以下とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["気流は、おおむね1秒間につき 1.0m以上 2.0m以下とする。"], "answerHints": [["1.0m以上 2.0m以下"]], "mnemonic": "正しくは：気流はおおむね0.5m/s以下。", "block": 3, "group": 1}, {"id": "H30_zenki_49", "source": "H30前 No.49", "category": "法規", "type": "single", "question": "屋内消火栓設備に関する文中、 内に当てはまる数値として、「消防法」上、正しいものはどれか。\n消防用ホースの構造を一人で操作できるものとした2号消火栓(広範囲型を除く)は、その階の各部分から一のホース接続口までの水平距離が m以下となるように設けなければならない。", "choices": [{"label": "1", "text": "15"}, {"label": "2", "text": "20"}, {"label": "3", "text": "25"}, {"label": "4", "text": "30"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["15"], "answerHints": [["15"]], "mnemonic": "2号消火栓（広範囲型を除く）は水平距離15m以下。1号・広範囲型2号は25m以下。", "block": 3, "group": 1}, {"id": "H30_zenki_52", "source": "H30前 No.52", "category": "法規", "type": "single", "question": "廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "紙くず(建設業に係るもの(工作物の新築、改築又は除去に伴って生じたものに限る。))は、産業廃棄物である。"}, {"label": "2", "text": "建設発生土(建設工事に伴い副次的に得られた土砂(浚渫土を含む。)をいう。)は、産業廃棄物である。"}, {"label": "3", "text": "廃電子レンジ(国内における日常生活に伴って生じたものに限る。)に含まれるポリ塩化ビフェニルを使用する部品は、特別管理一般廃棄物である。"}, {"label": "4", "text": "建築物等に用いられる材料であって石綿を含むもののうち石綿建材除去事業により除去された石綿保温材は、特別管理産業廃棄物である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設発生土(建設工事に伴い副次的に得られた土砂(浚渫土を含む。)をいう。)は、産業廃棄物である。"], "answerHints": [["産業廃棄物である"]], "mnemonic": "正しくは：建設発生土は廃棄物ではない（産業廃棄物に該当しない）。", "block": 3, "group": 1}, {"id": "H30_kouki_01", "source": "H30後 No.1", "category": "一般基礎", "type": "single", "question": "室内環境に関する用語の組合せのうち、関係のないものはどれか。", "choices": [{"label": "1", "text": "新有効温度(ET*) 体感温度"}, {"label": "2", "text": "騒音 NC 曲線"}, {"label": "3", "text": "予想平均申告(PMV) 予想不満足者率(PPD)"}, {"label": "4", "text": "着衣量 メット(met)"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["着衣量 メット(met)"], "answerHints": [["メット(met)"]], "mnemonic": "正しくは：着衣量の単位はクロ(clo)。メット(met)は代謝量（作業強度）の単位。", "block": 4, "group": 2}, {"id": "H30_kouki_04", "source": "H30後 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "物体の温度を1°C上げるのに必要な熱量を、熱容量という。"}, {"label": "2", "text": "温度変化を伴わず、物体の状態変化のみに消費される熱を顕熱という。"}, {"label": "3", "text": "熱は、低温の物体から高温の物体へ自然に移ることはない。"}, {"label": "4", "text": "気体を断熱圧縮すると、温度が変化する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["温度変化を伴わず、物体の状態変化のみに消費される熱を顕熱という。"], "answerHints": [["顕熱"]], "mnemonic": "正しくは：温度変化を伴わず状態変化のみに消費される熱は潜熱。", "block": 4, "group": 2}, {"id": "R01_zenki_01", "source": "R1前 No.1", "category": "一般基礎", "type": "single", "question": "空気環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ホルムアルデヒドは、内装仕上げ材や家具などから発生する無色無臭の気体である。"}, {"label": "2", "text": "PM2.5は、大気中に浮遊する微小粒子状物質を表すもので、環境基準が定められている。"}, {"label": "3", "text": "室内空気中の二酸化炭素の許容濃度は、一酸化炭素より高い。"}, {"label": "4", "text": "臭気は、二酸化炭素と同じように空気汚染を知る指標とされている。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ホルムアルデヒドは、内装仕上げ材や家具などから発生する無色無臭の気体である。"], "answerHints": [["無色無臭"]], "mnemonic": "正しくは：ホルムアルデヒドは無色で刺激臭のある気体。", "block": 4, "group": 2}, {"id": "R01_zenki_04", "source": "R1前 No.4", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "相対湿度とは、湿り空気に含まれている乾き空気1kg に対する水分の質量をいう。"}, {"label": "2", "text": "飽和湿り空気とは、ある温度で、もうそれ以上水蒸気として水分を含み得ない状態の空気をいう。"}, {"label": "3", "text": "露点温度とは、その空気と同じ絶対湿度を持つ飽和湿り空気の温度をいう。"}, {"label": "4", "text": "常温以下の温度では、相対湿度と飽和度は、ほぼ等しくなる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["相対湿度とは、湿り空気に含まれている乾き空気1kg に対する水分の質量をいう。"], "answerHints": [["相対湿度"]], "mnemonic": "正しくは：乾き空気1kgに対する水蒸気の質量で表すのは絶対湿度。", "block": 4, "group": 2}, {"id": "R01_kouki_01", "source": "R1後 No.1", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飽和湿り空気の相対湿度は100%である。"}, {"label": "2", "text": "絶対湿度は、湿り空気中に含まれる乾き空気1kgに対する水蒸気の質量で表す。"}, {"label": "3", "text": "空気中に含むことのできる水蒸気量は、温度が高くなるほど少なくなる。"}, {"label": "4", "text": "飽和湿り空気の乾球温度と湿球温度は等しい。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["空気中に含むことのできる水蒸気量は、温度が高くなるほど少なくなる。"], "answerHints": [["少なくなる"]], "mnemonic": "正しくは：空気中に含める水蒸気量は、温度が高いほど多くなる。", "block": 4, "group": 2}, {"id": "R01_kouki_04", "source": "R1後 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "体積を一定に保ったまま気体を冷却すると、圧力は低くなる。"}, {"label": "2", "text": "0°Cの水が0°Cの氷に変化するときに失う熱は、顕熱である。"}, {"label": "3", "text": "国際単位系(SI)では、熱量の単位としてジュール[J]を用いる。"}, {"label": "4", "text": "熱と仕事はともにエネルギーの一種であり、これらは相互に変換することができる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["0°Cの水が0°Cの氷に変化するときに失う熱は、顕熱である。"], "answerHints": [["顕熱"]], "mnemonic": "正しくは：0℃の水が0℃の氷になるとき（状態変化）に失う熱は潜熱。", "block": 4, "group": 2}, {"id": "H30_kouki_07", "source": "H30後 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和設備の計画に関する記述のうち、省エネルギーの観点から、適当でないものはどれか。", "choices": [{"label": "1", "text": "熱源機器は、部分負荷性能の高いものにする。"}, {"label": "2", "text": "熱源機器を、複数台に分割する。"}, {"label": "3", "text": "暖房時に外気導入量を多くする。"}, {"label": "4", "text": "空気調和機にインバータを導入する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["暖房時に外気導入量を多くする。"], "answerHints": [["外気導入量を多くする"]], "mnemonic": "正しくは：外気負荷を減らすため、外気導入量は必要最小限にする。", "block": 4, "group": 2}, {"id": "H30_kouki_10", "source": "H30後 No.10", "category": "空調・衛生", "type": "single", "question": "ろ過式エアフィルターのろ材に求められる特性として、適当でないものはどれか。", "choices": [{"label": "1", "text": "空気抵抗が小さいこと。"}, {"label": "2", "text": "難燃性又は不燃性であること。"}, {"label": "3", "text": "腐食及びカビの発生が少ないこと。"}, {"label": "4", "text": "吸湿性が高いこと。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["吸湿性が高いこと。"], "answerHints": [["吸湿性が高い"]], "mnemonic": "正しくは：ろ材は吸湿性が小さいこと。", "block": 4, "group": 2}, {"id": "H30_kouki_13", "source": "H30後 No.13", "category": "空調・衛生", "type": "single", "question": "第三種機械換気における排気ガラリの面積 A(m2)の算出式として、適当なものはどれか。\nただし、排気風量をQ(m3/h)、有効開口面風速をv(m/s)、ガラリの有効開口率をαとする。", "choices": [{"label": "1", "text": "A=(v×α) / Q"}, {"label": "2", "text": "A=(3,600×v×α) / Q"}, {"label": "3", "text": "A=Q / (v×α)"}, {"label": "4", "text": "A=Q / (3,600×v×α)"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["A=Q / (3,600×v×α)"], "answerHints": [["Q / (3,600×v×α)"]], "mnemonic": "A＝Q／(3,600×v×α)：m3/hを3,600で割ってm3/sにし、風速×開口率で割る。", "block": 4, "group": 2}, {"id": "H30_kouki_16", "source": "H30後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道の宅地ますに関する文中、 内に当てはまる「数値」及び「語句」の組合せとして、適当なものはどれか。\n宅地ますは、内径又は内のり A cm 以上の円形又は角形とし、雨水ますの底部には B を設ける。\n--(A)-----(B)", "choices": [{"label": "1", "text": "15-----インバート"}, {"label": "2", "text": "20-----泥だめ"}, {"label": "3", "text": "15-----泥だめ"}, {"label": "4", "text": "20-----インバート"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["15-----泥だめ"], "answerHints": [["15", "泥だめ"]], "mnemonic": "宅地ますは内径15cm以上。雨水ますは泥だめ、汚水ますはインバート。", "block": 4, "group": 2}, {"id": "H30_kouki_19", "source": "H30後 No.19", "category": "空調・衛生", "type": "single", "question": "排水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水管径を決定する代表的な方法として、器具排水負荷単位法と定常流量法がある。"}, {"label": "2", "text": "排水管の管径は、最小30mm、かつ、器具トラップ口径より小さくしてはならない。"}, {"label": "3", "text": "地中埋設管の管径は、50mm以上が望ましい。"}, {"label": "4", "text": "間接排水の水受け容器には、排水トラップを設けてはならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["間接排水の水受け容器には、排水トラップを設けてはならない。"], "answerHints": [["設けてはならない"]], "mnemonic": "正しくは：間接排水の水受け容器には排水トラップを設ける。", "block": 4, "group": 2}, {"id": "R01_zenki_07", "source": "R1前 No.7", "category": "空調・衛生", "type": "single", "question": "定風量単一ダクト方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "送風量が多いため、室内の清浄度を保ちやすい。"}, {"label": "2", "text": "各室ごとの部分的な空調の運転・停止ができない。"}, {"label": "3", "text": "換気量を定常的に十分確保できる。"}, {"label": "4", "text": "熱負荷の変動パターンが異なる室への対応が容易である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["熱負荷の変動パターンが異なる室への対応が容易である。"], "answerHints": [["対応が容易である"]], "mnemonic": "正しくは：定風量単一ダクト方式は、負荷変動パターンが異なる室への対応が困難。", "block": 4, "group": 2}, {"id": "R01_zenki_11", "source": "R1前 No.11", "category": "空調・衛生", "type": "single", "question": "温水暖房における膨張タンクに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "密閉式膨張タンクは、配管系の最上部に設ける必要がある。"}, {"label": "2", "text": "開放式膨張タンクに接続する膨張管は、ポンプの吸込み側の配管に接続する。"}, {"label": "3", "text": "密閉式膨張タンクを用いる場合には、安全弁などの安全装置が必要である。"}, {"label": "4", "text": "開放式膨張タンクは、装置内の空気抜きとして利用できる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["密閉式膨張タンクは、配管系の最上部に設ける必要がある。"], "answerHints": [["最上部"]], "mnemonic": "正しくは：密閉式膨張タンクは設置位置の制限がない。最上部に設けるのは開放式。", "block": 4, "group": 2}, {"id": "R01_zenki_14", "source": "R1前 No.14", "category": "空調・衛生", "type": "single", "question": "換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "第三種機械換気方式では、換気対象室内は負圧となる。"}, {"label": "2", "text": "第二種機械換気方式は、他室の汚染した空気の侵入を嫌う室や、燃焼空気を必要とする室の換気に適している。"}, {"label": "3", "text": "臭気、燃焼ガスなどの汚染源の異なる換気は、各々独立した換気系統とする。"}, {"label": "4", "text": "局所換気は、汚染質を汚染源の近くで捕そくする換気で、全般換気に比べて換気量を多くする必要がある。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["局所換気は、汚染質を汚染源の近くで捕そくする換気で、全般換気に比べて換気量を多くする必要がある。"], "answerHints": [["換気量を多くする必要がある"]], "mnemonic": "正しくは：局所換気は汚染源で捕そくするので、全般換気より少ない換気量で済む。", "block": 4, "group": 2}, {"id": "R01_zenki_17", "source": "R1前 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給水管に設置するエアチャンバーは、ウォーターハンマー防止のために設ける。"}, {"label": "2", "text": "飲料用給水タンクには、内径60cm以上のマンホールを設ける。"}, {"label": "3", "text": "給水管への逆サイホン作用による汚染の防止は、排水口空間の確保が基本となる。"}, {"label": "4", "text": "大気圧式バキュームブレーカーは、大便器洗浄弁などと組み合わせて使用される。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給水管への逆サイホン作用による汚染の防止は、排水口空間の確保が基本となる。"], "answerHints": [["排水口空間"]], "mnemonic": "正しくは：逆サイホン作用による汚染防止は吐水口空間の確保が基本。", "block": 4, "group": 2}, {"id": "R01_zenki_20", "source": "R1前 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "管径が65mm以下の排水横枝管の最小勾配は、1/100とする"}, {"label": "2", "text": "排水横主管の管径は、これに接続する排水立て管の管径以上とする。"}, {"label": "3", "text": "ループ通気管の最小管径は、30mmとする。"}, {"label": "4", "text": "屋外埋設排水管の勾配が著しく変化する箇所には、排水ますを設ける。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["管径が65mm以下の排水横枝管の最小勾配は、1/100とする"], "answerHints": [["1/100"]], "mnemonic": "正しくは：管径65mm以下の排水横枝管の最小勾配は1/50。", "block": 4, "group": 2}, {"id": "R01_zenki_23", "source": "R1前 No.23", "category": "空調・衛生", "type": "single", "question": "FRP 製浄化槽の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "掘削が深すぎた場合、捨てコンクリートで所定の深さに調整する。"}, {"label": "2", "text": "地下水位による槽の浮上防止策として、固定金具や浮上防止金具などで槽本体を基礎コンクリートに固定する。"}, {"label": "3", "text": "槽の水張りは、水圧による本体及び内部設備の変形を防止するため、槽の周囲を埋戻してから行う。"}, {"label": "4", "text": "槽に接続する流入管、放流管等は、管の埋設深さまで槽の周囲を埋戻してから接続する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["槽の水張りは、水圧による本体及び内部設備の変形を防止するため、槽の周囲を埋戻してから行う。"], "answerHints": [["槽の周囲を埋戻してから行う"]], "mnemonic": "正しくは：水張りは埋戻し前に行い、水張りしてから埋め戻す（変形・浮上の防止）。", "block": 4, "group": 2}, {"id": "R01_kouki_12", "source": "R1後 No.12", "category": "空調・衛生", "type": "single", "question": "吸収冷凍機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "機内が大気圧以下であり、圧力による破裂等のおそれがない。"}, {"label": "2", "text": "圧縮冷凍機に比べて回転部分が少なく、振動及び騒音が小さい。"}, {"label": "3", "text": "電力消費量は、遠心冷凍機に比べて大きい。"}, {"label": "4", "text": "法令上の運転資格者が不要である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["電力消費量は、遠心冷凍機に比べて大きい。"], "answerHints": [["比べて大きい"]], "mnemonic": "正しくは：吸収冷凍機の電力消費量は、遠心冷凍機より小さい。", "block": 4, "group": 2}, {"id": "R01_kouki_15", "source": "R1後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道施設に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "取水施設は、河川、湖沼又は地下の水源より水を取り入れ、粗いごみや砂を取り除く施設である。"}, {"label": "2", "text": "導水施設は、取水施設から浄水施設まで原水を送る施設である。"}, {"label": "3", "text": "浄水施設は、原水を水質基準に適合させるために、沈殿、ろ過、消毒等を行う施設である。"}, {"label": "4", "text": "送水施設は、浄水場で浄化した水を需要者に送水するための施設である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送水施設は、浄水場で浄化した水を需要者に送水するための施設である。"], "answerHints": [["需要者に送水"]], "mnemonic": "正しくは：送水施設は浄水場から配水池まで送る施設。需要者へ送るのは配水施設。", "block": 4, "group": 2}, {"id": "R01_kouki_18", "source": "R1後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給湯配管で上向き供給方式の場合、給湯管は先上がり、返湯管は先下がりとする。"}, {"label": "2", "text": "湯沸室の給茶用の給湯には、一般的に、局所式給湯設備が採用される。"}, {"label": "3", "text": "ホテル、病院等の給湯量の大きな建物には、中央式給湯設備が採用されることが多い。"}, {"label": "4", "text": "給湯管に使用される架橋ポリエチレン管の線膨張係数は、銅管の線膨張係数に比べて小さい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給湯管に使用される架橋ポリエチレン管の線膨張係数は、銅管の線膨張係数に比べて小さい。"], "answerHints": [["小さい"]], "mnemonic": "正しくは：架橋ポリエチレン管の線膨張係数は、銅管より大きい。", "block": 4, "group": 2}, {"id": "R01_kouki_22", "source": "R1後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液化石油ガスの一般家庭用のガス容器には、10kg、20kg、50kg等のものがある。"}, {"label": "2", "text": "都市ガスの中圧供給方式は、供給量が多い場合、又は、供給先までの距離が長い場合に採用される。"}, {"label": "3", "text": "マイコンメーターは、災害発生のおそれのある大きさの地震動を検知した場合、ガスを遮断する機能を有している。"}, {"label": "4", "text": "液化石油ガスは、プロパン、ブタン等を主成分としており、空気より軽いため、漏洩すると高いところに滞留する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化石油ガスは、プロパン、ブタン等を主成分としており、空気より軽いため、漏洩すると高いところに滞留する。"], "answerHints": [["空気より軽い", "高いところ"]], "mnemonic": "正しくは：液化石油ガスは空気より重く、漏洩すると低いところに滞留する。", "block": 4, "group": 2}, {"id": "H30_kouki_25", "source": "H30後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備系の制御や監視に用いられる「機器」と「制御・監視対象」の組合せのうち、適当でないものはどれか。\n---(機器)-----(制御・監視対象)", "choices": [{"label": "1", "text": "電極棒-------受水タンクの水位監視"}, {"label": "2", "text": "サーモスタット---室内の湿度制御"}, {"label": "3", "text": "電動二方弁-----冷温水の流量制御"}, {"label": "4", "text": "レベルスイッチ---汚物用水中モーターポンプの運転制御"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["サーモスタット---室内の湿度制御"], "answerHints": [["サーモスタット", "湿度制御"]], "mnemonic": "正しくは：サーモスタットは温度制御。湿度制御はヒューミディスタット。", "block": 4, "group": 2}, {"id": "R01_zenki_24", "source": "R1前 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吸収冷凍機は、吸収溶液として臭化リチウムと水の溶液、冷媒として水を使用している。"}, {"label": "2", "text": "冷却塔は、冷却水の一部を蒸発させることにより、冷却水の温度を下げる装置である。"}, {"label": "3", "text": "軸流送風機は、構造的に小型で、高圧力、小風量に適した送風機である。"}, {"label": "4", "text": "渦巻ポンプの実用範囲における揚程は、吐出し量の増加と共に低くなる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["軸流送風機は、構造的に小型で、高圧力、小風量に適した送風機である。"], "answerHints": [["高圧力、小風量"]], "mnemonic": "正しくは：軸流送風機は低圧力・大風量に適した送風機。", "block": 4, "group": 2}, {"id": "R01_zenki_27", "source": "R1前 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "たわみ継手は、ダクトと当該ダクトを接続する機器との位置合わせに使用する。"}, {"label": "2", "text": "案内羽根(ガイドベーン)は、直角エルボなどに設け、圧力損失を低減する。"}, {"label": "3", "text": "スパイラルダクトは、亜鉛鉄板をスパイラル状に甲はぜ掛け機械巻きしたものである。"}, {"label": "4", "text": "フレキシブルダクトは、一般的に、ダクトと吹出口等との接続用として用いられる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["たわみ継手は、ダクトと当該ダクトを接続する機器との位置合わせに使用する。"], "answerHints": [["位置合わせ"]], "mnemonic": "正しくは：たわみ継手は送風機等の振動をダクトに伝えないために使用する。", "block": 4, "group": 2}, {"id": "R01_kouki_26", "source": "R1後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配管用炭素鋼鋼管には黒管と白管があり、白管は、黒管に溶融亜鉛めっきを施したものである。"}, {"label": "2", "text": "銅及び銅合金の継目無管のうち、りん脱酸銅の硬質管は、肉厚によりK、L及びMタイプに分類される。"}, {"label": "3", "text": "水道用硬質塩化ビニルライニング鋼管のうち、SGP-VAは、配管用炭素鋼鋼管の内面と外面に硬質ポリ塩化ビニルをライニングしたものである。"}, {"label": "4", "text": "排水用硬質塩化ビニルライニング鋼管は、ねじ加工ができないため、MD継手等を使用する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水道用硬質塩化ビニルライニング鋼管のうち、SGP-VAは、配管用炭素鋼鋼管の内面と外面に硬質ポリ塩化ビニルをライニングしたものである。"], "answerHints": [["SGP-VA"]], "mnemonic": "正しくは：内面と外面にライニングしたものはSGP-VD。SGP-VAは黒管の内面ライニング。", "block": 4, "group": 2}, {"id": "H30_kouki_31", "source": "H29後 No.31 / H30後 No.31", "category": "施工管理法", "type": "single", "question": "工程表に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "バーチャート工程表は、各作業の施工時期や所要日数が明確で、クリティカルパスを把握しやすい。"}, {"label": "2", "text": "バーチャート工程表は、工事の進捗状況を把握しやすいので、詳細工程表に用いられることが多い。"}, {"label": "3", "text": "バーチャート工程表は、作業間の関連が明確ではないという欠点がある。"}, {"label": "4", "text": "ネットワーク工程表は、フロート(余裕時間)がわかるため、労務計画及び材料計画を立てやすい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表は、各作業の施工時期や所要日数が明確で、クリティカルパスを把握しやすい。"], "answerHints": [["クリティカルパスを把握しやすい"]], "mnemonic": "正しくは：バーチャートは作業間の関連が不明確で、クリティカルパスを把握しにくい（ネットワーク工程表で把握）。", "block": 4, "group": 2}, {"id": "H30_kouki_35", "source": "H30後 No.35", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "パッケージ形空気調和機の屋外機を設置する場合、空気がショートサーキットしないよう周囲に空間を確保する。"}, {"label": "2", "text": "遠心ポンプの設置において、吸水面がポンプより低い場合、ポンプの設置高さは、吸込み管がポンプに向かって上り勾配となるようにする。"}, {"label": "3", "text": "埋込式アンカーボルトを使用して機器を固定する場合、機器設置後、ナットからねじ山が出ないようにアンカーボルトの埋込み深さを調整する。"}, {"label": "4", "text": "あと施工アンカーボルトを使用して機器を固定する場合、あと施工アンカーボルトは、機器をコンクリート基礎上に据える前に打設する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["埋込式アンカーボルトを使用して機器を固定する場合、機器設置後、ナットからねじ山が出ないようにアンカーボルトの埋込み深さを調整する。"], "answerHints": [["ナットからねじ山が出ないように"]], "mnemonic": "正しくは：アンカーボルトはナットからねじ山が3山程度出るようにする。", "block": 4, "group": 2}, {"id": "H30_kouki_38", "source": "H30後 No.38", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "長方形ダクトのアスペクト比(長辺/短辺)は、4以下とする。"}, {"label": "2", "text": "長方形ダクトの板厚は、ダクトの長辺の長さにより決定する。"}, {"label": "3", "text": "スパイラルダクトの差込み接合では、継目をダクト用テープで1重巻きする。"}, {"label": "4", "text": "スパイラルダクトは、一般的に、形鋼による補強は不要である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["スパイラルダクトの差込み接合では、継目をダクト用テープで1重巻きする。"], "answerHints": [["1重巻き"]], "mnemonic": "正しくは：スパイラルダクトの差込み接合の継目はダクト用テープで2重巻き。", "block": 4, "group": 2}, {"id": "H30_kouki_41", "source": "H30後 No.41", "category": "施工管理法", "type": "single", "question": "次の「配管」と「試験方法」の組合せのうち、適当でないものはどれか。\n--(配管)----(試験方法)", "choices": [{"label": "1", "text": "給水管------水圧試験"}, {"label": "2", "text": "排水管------満水試験"}, {"label": "3", "text": "油管-------水圧試験"}, {"label": "4", "text": "冷媒管------気密試験"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["油管-------水圧試験"], "answerHints": [["油管", "水圧試験"]], "mnemonic": "正しくは：油管は空気圧試験（水を入れない）。給水管＝水圧、排水管＝満水、冷媒管＝気密。", "block": 4, "group": 2}, {"id": "R01_zenki_33", "source": "R1前 No.33", "category": "施工管理法", "type": "single", "question": "建設工事現場の安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "軟弱地盤上にクレーンを設置する場合、クレーンの下に強度のある鉄板を敷く。"}, {"label": "2", "text": "高所作業には、高血圧症、低血圧症、心臓疾患等を有する作業員を配置しない。"}, {"label": "3", "text": "気温の高い日に作業を行う場合、熱中症予防のため、暑さ指数(WBGT 値)を確認する。"}, {"label": "4", "text": "既設汚水ピット内の作業前における酸素濃度の測定は、酸素欠乏症等に関する特別の教育を受けた作業員が行う。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["既設汚水ピット内の作業前における酸素濃度の測定は、酸素欠乏症等に関する特別の教育を受けた作業員が行う。"], "answerHints": [["特別の教育を受けた作業員"]], "mnemonic": "正しくは：酸素濃度の測定は酸素欠乏危険作業主任者が行う。", "block": 4, "group": 2}, {"id": "R01_zenki_36", "source": "R1前 No.36", "category": "施工管理法", "type": "single", "question": "配管の接合に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "銅管の接合には、差込接合、メカニカル接合、フランジ接合等がある。"}, {"label": "2", "text": "硬質ポリ塩化ビニル管の接着接合では、テーパ形状の受け口側のみに接着剤を塗布する。"}, {"label": "3", "text": "架橋ポリエチレン管の接合方式には、電気融着式等がある。"}, {"label": "4", "text": "鋼管の突合せ溶接による接合は、開先加工を行い、ルート間隔を保持して行う。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["硬質ポリ塩化ビニル管の接着接合では、テーパ形状の受け口側のみに接着剤を塗布する。"], "answerHints": [["受け口側のみ"]], "mnemonic": "正しくは：接着接合では、受け口と差し口の両方に接着剤を塗布する。", "block": 4, "group": 2}, {"id": "R01_zenki_39", "source": "R1前 No.39", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "共板フランジ工法ダクトのフランジは、四隅のボルト・ナットと専用のフランジ押え金具で接続する。"}, {"label": "2", "text": "風量測定口は、ダクト内の気流が安定している位置に取り付ける。"}, {"label": "3", "text": "共板フランジ工法ダクトのフランジは、ダクトの端部を折り曲げて成形したものである。"}, {"label": "4", "text": "送風機の吐出し口に接続するダクトは、急拡大させてダクト内の抵抗を緩和する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送風機の吐出し口に接続するダクトは、急拡大させてダクト内の抵抗を緩和する。"], "answerHints": [["急拡大"]], "mnemonic": "正しくは：送風機の吐出し口直後は急拡大を避け、緩やかに拡大（15°以下）する。", "block": 4, "group": 2}, {"id": "R01_kouki_31", "source": "R1後 No.31", "category": "施工管理法", "type": "single", "question": "工程表に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "横線式工程表には、ガントチャートとバーチャートがある。"}, {"label": "2", "text": "曲線式工程表は、上方許容限界曲線と下方許容限界曲線とで囲まれた形からS字曲線とも呼ばれる。"}, {"label": "3", "text": "作業内容を矢線で表示するネットワーク工程表は、アロー型ネットワーク工程表と呼ばれる。"}, {"label": "4", "text": "タクト工程表は、同一作業が繰り返される工事を効率的に行うために用いられる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["曲線式工程表は、上方許容限界曲線と下方許容限界曲線とで囲まれた形からS字曲線とも呼ばれる。"], "answerHints": [["S字曲線"]], "mnemonic": "正しくは：上方・下方許容限界曲線で囲まれた形からバナナ曲線と呼ばれる。", "block": 4, "group": 2}, {"id": "R01_kouki_35", "source": "R1後 No.35", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "直焚き式の吸収冷温水機は、振動の振幅が大きいため、一般的に、防振基礎に据え付ける。"}, {"label": "2", "text": "パッケージ形空気調和機を室内の床上に設置する場合、前面に1m程度の保守スペースを確保する。"}, {"label": "3", "text": "小型温水ボイラーをボイラー室内に設置する場合、ボイラー側面からボイラー室の壁面までの距離は450mm以上とする。"}, {"label": "4", "text": "送風機やポンプのコンクリート基礎をあと施工する場合、当該コンクリート基礎は、ダボ鉄筋等で床スラブと一体化する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["直焚き式の吸収冷温水機は、振動の振幅が大きいため、一般的に、防振基礎に据え付ける。"], "answerHints": [["振動の振幅が大きい", "防振基礎に据え付ける"]], "mnemonic": "正しくは：吸収冷温水機は回転部分が少なく振動が小さいので、一般に防振基礎は不要。", "block": 4, "group": 2}, {"id": "R01_kouki_38", "source": "R1後 No.38", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "建物の外壁に設置する給排気ガラリの面風速は、騒音の発生や雨水の浸入を考慮して決定する。"}, {"label": "2", "text": "送風機のダクト接続に使用するたわみ継手は、送風機の振動をダクトに伝えないために用いる。"}, {"label": "3", "text": "ダクト内を流れる風量が同一の場合、ダクトの断面寸法を小さくすると、必要となる送風動力は小さくなる。"}, {"label": "4", "text": "ダクトに設けるリブ補強は、ダクトの変形や、騒音及び振動の発生を防止するために設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクト内を流れる風量が同一の場合、ダクトの断面寸法を小さくすると、必要となる送風動力は小さくなる。"], "answerHints": [["小さくなる"]], "mnemonic": "正しくは：風量同一で断面を小さくすると風速・抵抗が増え、送風動力は大きくなる。", "block": 4, "group": 2}, {"id": "R01_kouki_41", "source": "R1後 No.41", "category": "施工管理法", "type": "single", "question": "「機器又は配管」と「試験方法」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "受水タンク ――― 満水試験"}, {"label": "2", "text": "浄化槽 ――――― 満水試験"}, {"label": "3", "text": "排水管 ――――― 通水試験"}, {"label": "4", "text": "ガス管 ――――― 通水試験"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ガス管 ――――― 通水試験"], "answerHints": [["ガス管", "通水試験"]], "mnemonic": "正しくは：ガス管は気密試験（空気圧試験）。", "block": 4, "group": 2}, {"id": "H30_kouki_44", "source": "H30後 No.44", "category": "法規", "type": "single", "question": "労働時間と年次有給休暇に関する文中、 内に当てはまる「労働基準法」上に定められた数値の組合せとして、正しいものはどれか。\nただし、労働組合等との協定等による別の定めがある場合を除く。\n使用者は、労働者に、休憩時間を除き週間について A 時間を超えて労働させてはならない。また、使用者は、その雇入の日から起算して6箇月間継続勤務し全労働日の8割以上出勤した労働者に対して、継続し、又は分割した B 労働日の有給休暇を与えなければならない。\n--(A)----(B)", "choices": [{"label": "1", "text": "35-----7"}, {"label": "2", "text": "35-----10"}, {"label": "3", "text": "40-----7"}, {"label": "4", "text": "40-----10"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["40-----10"], "answerHints": [["40", "10"]], "mnemonic": "労働時間は週40時間まで。6箇月継続勤務・8割以上出勤で10労働日の有給休暇。", "block": 4, "group": 2}, {"id": "H30_kouki_47", "source": "H30後 No.47", "category": "法規", "type": "single", "question": "建設業の許可及び技術者に関する文中、 内に当てはまる用語の組合せとして、「建設業法」上、正しいものはどれか。\n建設業を営もうとする者であって、発注者から直接請け負う一件の管工事につき、4,000万円以上となる下請契約を締結して施工しようとする場合は、 A の許可が必要で、当該工事現場に B を置かなければならない。\n---(A)--------(B)", "choices": [{"label": "1", "text": "一般建設業-----主任技術者"}, {"label": "2", "text": "一般建設業-----監理技術者"}, {"label": "3", "text": "特定建設業-----主任技術者"}, {"label": "4", "text": "特定建設業-----監理技術者"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["特定建設業-----監理技術者"], "answerHints": [["特定建設業", "監理技術者"]], "mnemonic": "元請として下請契約の総額が所定額以上（出題当時4,000万円）なら、特定建設業の許可と監理技術者の配置が必要。", "block": 4, "group": 2}, {"id": "H30_kouki_50", "source": "H30後 No.50", "category": "法規", "type": "single", "question": "次の建設資材のうち、「建設工事に係る資材の再資源化等に関する法律」上、再資源化が特に必要とされる「特定建設資材」として規定されていないものはどれか。", "choices": [{"label": "1", "text": "コンクリート"}, {"label": "2", "text": "プラスチック"}, {"label": "3", "text": "木材"}, {"label": "4", "text": "アスファルト・コンクリート"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["として規定されていないもの"], "answerTexts": ["プラスチック"], "answerHints": [["プラスチック"]], "mnemonic": "特定建設資材はコンクリート、コンクリート及び鉄から成る建設資材、木材、アスファルト・コンクリートの4つ。プラスチックは含まない。", "block": 4, "group": 2}, {"id": "R01_zenki_43", "source": "R1前 No.43", "category": "法規", "type": "single", "question": "建設工事現場における作業のうち、「労働安全衛生法」上、その作業を指揮する作業主任者の選任が必要でない作業はどれか。", "choices": [{"label": "1", "text": "掘削面の高さがm以上となる地山の掘削(ずい道及びたて坑以外の坑の掘削を除く。)"}, {"label": "2", "text": "高さが5m以上の構造の足場の組立て"}, {"label": "3", "text": "作業床の高さが10m未満の高所作業車の運転(道路上を走行させる運転を除く。)"}, {"label": "4", "text": "ボイラー(小型ボイラーを除く。)の取扱い"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["選任が必要でない作業"], "answerTexts": ["作業床の高さが10m未満の高所作業車の運転(道路上を走行させる運転を除く。)"], "answerHints": [["高所作業車の運転"]], "mnemonic": "高所作業車の運転は作業主任者の選任対象外（10m未満は特別教育）。地山掘削2m以上・足場5m以上・ボイラー取扱いは作業主任者が必要。", "block": 4, "group": 2}, {"id": "R01_zenki_46", "source": "R1前 No.46", "category": "法規", "type": "single", "question": "建築物に設ける配管設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "飲料水の配管設備は、その他の配管設備と直接連結させてはならない。"}, {"label": "2", "text": "給水立て主管から各階への分岐管等主要な分岐管には、止水弁を設けなければならない。"}, {"label": "3", "text": "雨水排水立て管は、汚水排水管若しくは通気管と兼用し、又はこれらの管に連結してはならない。"}, {"label": "4", "text": "地階を除く階数が3以上の建築物に設ける給水管は、不燃材料で造らなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["地階を除く階数が3以上の建築物に設ける給水管は、不燃材料で造らなければならない。"], "answerHints": [["給水管"]], "mnemonic": "正しくは：階数3以上の建築物等で不燃材料とするのは風道・ダストシュート等。給水管にこの規定はない。", "block": 4, "group": 2}, {"id": "R01_zenki_50", "source": "R1前 No.50", "category": "法規", "type": "single", "question": "次の建築設備のうち、「建築物のエネルギー消費性能の向上に関する法律」上、エネルギー消費性能評価の対象として規定されていないものはどれか。", "choices": [{"label": "1", "text": "空気調和設備"}, {"label": "2", "text": "給水設備"}, {"label": "3", "text": "給湯設備"}, {"label": "4", "text": "照明設備"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["対象として規定されていないもの"], "answerTexts": ["給水設備"], "answerHints": [["給水設備"]], "mnemonic": "省エネ法の評価対象は空気調和・換気・照明・給湯・昇降機。給水設備は対象外。", "block": 4, "group": 2}, {"id": "R01_kouki_43", "source": "R1後 No.43", "category": "法規", "type": "single", "question": "建設業の事業場において、安全衛生推進者が行う業務として、「労働安全衛生法」上、規定されていないものはどれか。", "choices": [{"label": "1", "text": "労働者の危険又は健康障害を防止するための措置に関すること"}, {"label": "2", "text": "労働者の安全又は衛生のための教育の実施に関すること"}, {"label": "3", "text": "労働災害の原因の調査及び再発防止対策に関すること"}, {"label": "4", "text": "労働者の雇用期間の延長及び賃金の改定に関すること"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["規定されていないもの"], "answerTexts": ["労働者の雇用期間の延長及び賃金の改定に関すること"], "answerHints": [["雇用期間の延長及び賃金の改定"]], "mnemonic": "安全衛生推進者の業務は危険・健康障害の防止、安全衛生教育、労災の原因調査・再発防止など。雇用・賃金は対象外。", "block": 4, "group": 2}, {"id": "R01_kouki_46", "source": "R1後 No.46", "category": "法規", "type": "single", "question": "建築物に設ける配管設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "給水管及び排水管は、エレベーターの昇降路内に設けてはならない。"}, {"label": "2", "text": "飲料水の配管設備の水栓の開口部は、流し台のあふれ面との垂直距離を適当に保つ等有効な水の逆流防止のための措置を講じなければならない。"}, {"label": "3", "text": "排水槽の通気管は、伸頂通気管又は通気立て管に連結しなければならない。"}, {"label": "4", "text": "飲料水の配管設備とその他の配管設備とは、直接連結させてはならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["排水槽の通気管は、伸頂通気管又は通気立て管に連結しなければならない。"], "answerHints": [["連結しなければならない"]], "mnemonic": "正しくは：排水槽の通気管は単独で直接外気に衛生上有効に開放する（他の通気管と連結しない）。", "block": 4, "group": 2}, {"id": "R01_kouki_49", "source": "R1後 No.49", "category": "法規", "type": "single", "question": "屋内消火栓設備に関する文中、 内に当てはまる数値の組合せとして、「消防法」上、正しいものはどれか。\n消防用ホースの構造を一人で操作できるものとした易操作性1号消火栓は、その階の各部分から一のホース接続口までの水平距離が A m以下となるように設け、2号消火栓(広範囲型を除く。)は、 B m以下となるように設けなければならない。", "choices": [{"label": "1", "text": "15 ――― 15"}, {"label": "2", "text": "15 ――― 25"}, {"label": "3", "text": "25 ――― 15"}, {"label": "4", "text": "25 ――― 25"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["25 ――― 15"], "answerHints": [["25", "15"]], "mnemonic": "1号・易操作性1号消火栓は水平距離25m以下、2号（広範囲型を除く）は15m以下。", "block": 4, "group": 2}, {"id": "R01_kouki_52", "source": "R1後 No.52", "category": "法規", "type": "single", "question": "廃棄物の処分に関する文中、 内に当てはまる用語の組合せとして「廃棄物の処理及び清掃に関する法律」上、正しいものはどれか。\n建設工事に伴って伐採した樹木を A として処分する。建設工事に使用する資材の梱包に使用された段ボールを B として処分する。", "choices": [{"label": "1", "text": "一般廃棄物 ――― 一般廃棄物"}, {"label": "2", "text": "一般廃棄物 ――― 産業廃棄物"}, {"label": "3", "text": "産業廃棄物 ――― 一般廃棄物"}, {"label": "4", "text": "産業廃棄物 ――― 産業廃棄物"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["産業廃棄物 ――― 産業廃棄物"], "answerHints": [["産業廃棄物"]], "mnemonic": "建設工事で出る伐採木（木くず）も梱包の段ボール（紙くず）も産業廃棄物。", "block": 4, "group": 2}, {"id": "H30_kouki_02", "source": "H30後 No.2", "category": "一般基礎", "type": "single", "question": "居室内の表面結露を防止する対策に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "壁体の熱通過率を大きくする。"}, {"label": "2", "text": "絶対湿度を一定にして、内壁の表面温度を上昇させる。"}, {"label": "3", "text": "内壁表面近くの空気を流動させる。"}, {"label": "4", "text": "室内空気に比べて絶対湿度が低い外気との換気を行う。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["壁体の熱通過率を大きくする。"], "answerHints": [["熱通過率を大きくする"]], "mnemonic": "正しくは：表面結露防止には、壁体の熱通過率を小さく（断熱を強化）する。", "block": 5, "group": 2}, {"id": "H30_kouki_05", "source": "H30後 No.5", "category": "一般基礎", "type": "single", "question": "電気設備の制御機器に関する「文字記号」と「用語」の組合せとして、適当でないものはどれか。\n---(文字記号)-----(用 語)", "choices": [{"label": "1", "text": "MCCB-------配線用遮断器"}, {"label": "2", "text": "ELCB-------漏電遮断器"}, {"label": "3", "text": "SC---------過負荷欠相継電器"}, {"label": "4", "text": "F----------ヒューズ"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["SC---------過負荷欠相継電器"], "answerHints": [["SC"]], "mnemonic": "正しくは：SCは進相コンデンサ。過負荷欠相継電器は2E。", "block": 5, "group": 2}, {"id": "R01_zenki_02", "source": "R1前 No.2", "category": "一般基礎", "type": "single", "question": "水の性状に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "pHは、水素イオン濃度の大小を示す指標である。"}, {"label": "2", "text": "BODは、水中に含まれる有機物質の量を示す指標である。"}, {"label": "3", "text": "DOは、水中に含まれる大腸菌群数を示す指標である。"}, {"label": "4", "text": "マグネシウムイオンの多い水は、硬度が高い。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["DOは、水中に含まれる大腸菌群数を示す指標である。"], "answerHints": [["大腸菌群数"]], "mnemonic": "正しくは：DOは水中に溶けている酸素の量（溶存酸素）を示す指標。", "block": 5, "group": 2}, {"id": "R01_zenki_05", "source": "H30前 No.5 / R1前 No.5", "category": "一般基礎", "type": "single", "question": "電気工事に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飲料用冷水機の電源回路には、漏電遮断器を設置する。"}, {"label": "2", "text": "CD管は、コンクリートに埋設して施設する。"}, {"label": "3", "text": "絶縁抵抗の測定には、接地抵抗計を用いる。"}, {"label": "4", "text": "電動機の電源配線は、金属管内で接続しない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["絶縁抵抗の測定には、接地抵抗計を用いる。"], "answerHints": [["接地抵抗計"]], "mnemonic": "正しくは：絶縁抵抗の測定には絶縁抵抗計（メガー）を用いる。", "block": 5, "group": 2}, {"id": "R01_kouki_02", "source": "R1後 No.2", "category": "一般基礎", "type": "single", "question": "水と環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "1気圧における空気の水に対する溶解度は、温度の上昇とともに減少する。"}, {"label": "2", "text": "濁度は水の濁りの程度を示し、色度は水の着色の程度を示す度数である。"}, {"label": "3", "text": "DOは、水中に溶けている酸素の量である。"}, {"label": "4", "text": "CODは、水中に含まれる浮遊物質の量で、水の汚濁度を判断する指標である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["CODは、水中に含まれる浮遊物質の量で、水の汚濁度を判断する指標である。"], "answerHints": [["浮遊物質の量"]], "mnemonic": "正しくは：CODは化学的酸素要求量（有機物を酸化剤で分解するときに消費される酸素量）。浮遊物質量はSS。", "block": 5, "group": 2}, {"id": "R01_kouki_05", "source": "R1後 No.5", "category": "一般基礎", "type": "single", "question": "電気設備の制御機器に関する「文字記号」と「用語」の組合せとして、適当でないものはどれか。", "choices": [{"label": "1", "text": "F ―――――― ヒューズ"}, {"label": "2", "text": "ELCB ――― 漏電遮断器"}, {"label": "3", "text": "SC ――――― 過負荷欠相継電器"}, {"label": "4", "text": "MCCB ――― 配線用遮断器"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["SC ――――― 過負荷欠相継電器"], "answerHints": [["SC"]], "mnemonic": "正しくは：SCは進相コンデンサ。過負荷欠相継電器は2E。", "block": 5, "group": 2}, {"id": "H30_kouki_08", "source": "H30後 No.8", "category": "空調・衛生", "type": "single", "question": "変風量単一ダクト方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "定風量単一ダクト方式に比べて、搬送エネルギーが大きくなる。"}, {"label": "2", "text": "送風量の減少時においても、必要外気量を確保する必要がある。"}, {"label": "3", "text": "部屋ごとの個別制御が可能である。"}, {"label": "4", "text": "室内の気流分布が悪くならないように、最小風量設定が必要となる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["定風量単一ダクト方式に比べて、搬送エネルギーが大きくなる。"], "answerHints": [["搬送エネルギーが大きくなる"]], "mnemonic": "正しくは：変風量方式は送風量を絞れるので、定風量方式より搬送エネルギーが小さい。", "block": 5, "group": 2}, {"id": "H30_kouki_11", "source": "H30後 No.11", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ガスエンジンヒートポンプ方式は、暖房運転時にガスエンジンの排熱が利用できる。"}, {"label": "2", "text": "空気熱源ヒートポンプ方式では、冷媒配管の長短は能力に影響しない。"}, {"label": "3", "text": "ヒートポンプ方式のマルチパッケージ形空気調和機には、屋内機ごとに冷房運転又は暖房運転の選択ができる方式がある。"}, {"label": "4", "text": "ヒートポンプ方式には、空気熱源ヒートポンプ方式と水熱源ヒートポンプ方式がある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["空気熱源ヒートポンプ方式では、冷媒配管の長短は能力に影響しない。"], "answerHints": [["影響しない"]], "mnemonic": "正しくは：冷媒配管が長くなるほど能力は低下する。", "block": 5, "group": 2}, {"id": "H30_kouki_14", "source": "H30後 No.14", "category": "空調・衛生", "type": "single", "question": "換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排気ダクトの途中に送風機を設ける場合、送風機は、吸込側のダクトが短く、吐出側のダクトが長くなる位置に設置する。"}, {"label": "2", "text": "開放式燃焼器具を設けた台所において機械換気を行う場合、所定の排気フードを設けることにより換気量を低減することができる。"}, {"label": "3", "text": "自然換気は、室内外温度差による浮力と外界の自然風によって生じる圧力を利用した換気方式である。"}, {"label": "4", "text": "第一種機械換気方式は、換気対象室内の圧力を正圧・負圧のいずれにも制御することができる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排気ダクトの途中に送風機を設ける場合、送風機は、吸込側のダクトが短く、吐出側のダクトが長くなる位置に設置する。"], "answerHints": [["吸込側のダクトが短く", "吐出側のダクトが長くなる"]], "mnemonic": "正しくは：吸込側のダクトを長く、吐出側（正圧部）を短くして、排気の漏れを防ぐ。", "block": 5, "group": 2}, {"id": "H30_kouki_17", "source": "H30後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "建物内に飲料用給水タンクを設置する場合は、周囲及び下部に 60 cm 以上、上部に 100 cm 以上の保守スペースを設ける。"}, {"label": "2", "text": "クロスコネクションとは、飲料水系統とその他の系統が配管・装置等により直接接続されることをいう。"}, {"label": "3", "text": "飲料用給水タンクは、タンク清掃時の断水を避けられるようにタンクを複数設けるか、1基の場合には仕切りを入れ分割することが望ましい。"}, {"label": "4", "text": "直結増圧方式の給水ポンプの給水量は、一般的に、高置タンク方式の揚水ポンプの揚水量に比べて、小さくなる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["直結増圧方式の給水ポンプの給水量は、一般的に、高置タンク方式の揚水ポンプの揚水量に比べて、小さくなる。"], "answerHints": [["小さくなる"]], "mnemonic": "正しくは：直結増圧ポンプは瞬時最大給水量に対応するので、揚水ポンプより給水量が大きい。", "block": 5, "group": 2}, {"id": "H30_kouki_21", "source": "H29後 No.21 / H30後 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓ポンプまわりの配管に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吸水管は、ポンプごとに専用とする。"}, {"label": "2", "text": "水源の水位がポンプより低い位置にあるものにあっては、吸水管に止水弁を設ける。"}, {"label": "3", "text": "吸水管には、機能の低下を防止するためにろ過装置を設ける。"}, {"label": "4", "text": "ポンプ吐出側直近部分の配管には、逆止弁及び止水弁を設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水源の水位がポンプより低い位置にあるものにあっては、吸水管に止水弁を設ける。"], "answerHints": [["止水弁"]], "mnemonic": "正しくは：水源の水位がポンプより低い場合は、吸水管にフート弁を設ける。", "block": 5, "group": 2}, {"id": "R01_zenki_09", "source": "R1前 No.9", "category": "空調・衛生", "type": "single", "question": "冷房負荷計算に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "外気による熱負荷は、顕熱と潜熱を考慮する。"}, {"label": "2", "text": "OA機器による熱負荷は、顕熱のみを考慮する。"}, {"label": "3", "text": "ガラス窓からの熱負荷は、ガラス窓を透過した日射による顕熱のみを考慮する。"}, {"label": "4", "text": "人体による熱負荷は、顕熱と潜熱を考慮する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ガラス窓からの熱負荷は、ガラス窓を透過した日射による顕熱のみを考慮する。"], "answerHints": [["顕熱のみ"]], "mnemonic": "正しくは：ガラス窓からは透過日射に加え、室内外温度差による貫流熱も考慮する。", "block": 5, "group": 2}, {"id": "R01_zenki_12", "source": "R1前 No.12", "category": "空調・衛生", "type": "single", "question": "強制対流型放熱器の特徴に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "伝熱面積当たりの加熱量が大きいため、自然対流型放熱器に比べて、空気加熱用熱交換器を小型にできる。"}, {"label": "2", "text": "自然対流型放熱器に比べて、暖房開始から所定の室内温度に達するまでの時間が長い。"}, {"label": "3", "text": "熱媒は温水又は蒸気であり、放熱量は熱媒温度、流量及び風量により変化する。"}, {"label": "4", "text": "熱媒の温度を高くすると、室内の温度分布の不均一を生じることがある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["自然対流型放熱器に比べて、暖房開始から所定の室内温度に達するまでの時間が長い。"], "answerHints": [["時間が長い"]], "mnemonic": "正しくは：強制対流型は自然対流型より、所定の室温に達するまでの時間が短い。", "block": 5, "group": 2}, {"id": "R01_zenki_15", "source": "R1前 No.15", "category": "空調・衛生", "type": "single", "question": "上水道の配水管及び給水装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "市街地等の道路部分に布設する外径80mm以上の配水管には、管理者名、布設年次等を明示するテープを取り付ける。"}, {"label": "2", "text": "配水管の水圧試験は、管路に充水後、一昼夜程度経過してから行うことが望ましい。"}, {"label": "3", "text": "水道事業者は、配水管への取付口からメーターまでの給水装置について、工法、工期その他工事上の条件を付すことができる。"}, {"label": "4", "text": "配水管から分水栓又はサドル付分水栓により給水管を取り出す場合、他の給水管の取り出し位置との間隔を15cm以上とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["配水管から分水栓又はサドル付分水栓により給水管を取り出す場合、他の給水管の取り出し位置との間隔を15cm以上とする。"], "answerHints": [["15cm以上"]], "mnemonic": "正しくは：給水管の取り出し位置は、他の給水管の取り出し位置と30cm以上離す。", "block": 5, "group": 2}, {"id": "R01_zenki_18", "source": "R1前 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "潜熱回収型給湯器は、燃焼ガス中の水蒸気の凝縮潜熱を回収することで熱効率を向上させている。"}, {"label": "2", "text": "循環式給湯設備の給湯温度は、レジオネラ属菌の繁殖を防止するため、45°Cに維持する。"}, {"label": "3", "text": "ガス瞬間湯沸器の先止め式は、給湯先の湯栓の開閉により給湯するもので、給湯配管が接続できるものである。"}, {"label": "4", "text": "給湯管に銅管を用いる場合は、かい食を防ぐため、管内の流速は1.5m/s以下とする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["循環式給湯設備の給湯温度は、レジオネラ属菌の繁殖を防止するため、45°Cに維持する。"], "answerHints": [["45°C"]], "mnemonic": "正しくは：レジオネラ属菌防止のため、循環式の給湯温度は55℃以上（貯湯槽は60℃以上）に保つ。", "block": 5, "group": 2}, {"id": "R01_zenki_21", "source": "R1前 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "1号消火栓のノズル先端での放水量は、120L/min以上とする。"}, {"label": "2", "text": "1号消火栓は、防火対象物の階ごとに、その階の各部からの水平距離が25m以下となるように設置する。"}, {"label": "3", "text": "2号消火栓(広範囲型を除く。)のノズル先端での放水量は、60L/min以上とする。"}, {"label": "4", "text": "2号消火栓(広範囲型を除く。)は、防火対象物の階ごとに、その階の各部からの水平距離が15m以下となるように設置する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["1号消火栓のノズル先端での放水量は、120L/min以上とする。"], "answerHints": [["120L/min以上"]], "mnemonic": "正しくは：1号消火栓の放水量は130L/min以上（2号は60L/min以上）。", "block": 5, "group": 2}, {"id": "R01_kouki_09", "source": "R1後 No.9", "category": "空調・衛生", "type": "single", "question": "冷房時の熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "窓ガラス面からの熱負荷を算定するときは、ブラインドの有無を考慮する。"}, {"label": "2", "text": "人体や事務機器からの熱負荷を室内負荷として考慮する。"}, {"label": "3", "text": "潜熱負荷に対する顕熱負荷の割合を顕熱比(SHF)という。"}, {"label": "4", "text": "OA機器による熱負荷は、顕熱のみである。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["潜熱負荷に対する顕熱負荷の割合を顕熱比(SHF)という。"], "answerHints": [["潜熱負荷に対する"]], "mnemonic": "正しくは：SHFは全熱負荷（顕熱＋潜熱）のうち顕熱負荷が占める割合。", "block": 5, "group": 2}, {"id": "R01_kouki_13", "source": "R1後 No.13", "category": "空調・衛生", "type": "single", "question": "中央管理方式の空気調和設備により居室の換気を行う場合、居室内の空気に関する「事項」と当該空気がおおむね適合すべきとされる「基準」の組合せのうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "浮遊粉じんの量 ―――― 0.15mg/m3以下"}, {"label": "2", "text": "一酸化炭素の含有率 ―― 100/100万以下"}, {"label": "3", "text": "炭酸ガスの含有率 ――― 1,000/100万以下"}, {"label": "4", "text": "気流 ――――――――― 0.5m/s以下"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["一酸化炭素の含有率 ―― 100/100万以下"], "answerHints": [["100/100万以下"]], "mnemonic": "正しくは：一酸化炭素の含有率は10/100万以下（現行は6/100万以下）。", "block": 5, "group": 2}, {"id": "R01_kouki_16", "source": "R1後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "下水道は、生活あるいは事業に起因する汚水ならびに雨水を排除処理するものである。"}, {"label": "2", "text": "分流式は、汚水と雨水とを別々の管路系統で排除する方式である。"}, {"label": "3", "text": "排水管の管内流速は、掃流力を考慮して3.0m/s以上とする。"}, {"label": "4", "text": "下水道施設の処理機能に障害を与えるような排水には、除害施設を設けなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水管の管内流速は、掃流力を考慮して3.0m/s以上とする。"], "answerHints": [["3.0m/s以上"]], "mnemonic": "正しくは：管内流速の上限が3.0m/s（汚水管きょは0.6〜3.0m/s）。", "block": 5, "group": 2}, {"id": "R01_kouki_19", "source": "R1後 No.19", "category": "空調・衛生", "type": "single", "question": "排水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "特殊継手排水システムは、ホテル客室系統、共同住宅等に多く使用されている。"}, {"label": "2", "text": "ルームエアコンのドレン管は、直接雑排水管に接続する。"}, {"label": "3", "text": "阻集器にはトラップ機能を持つものが多く、器具トラップを設けると二重トラップになるおそれがある。"}, {"label": "4", "text": "ドラムトラップは、排水混入物をトラップ底部に堆積させ、後に回収できる構造になっている。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ルームエアコンのドレン管は、直接雑排水管に接続する。"], "answerHints": [["直接雑排水管に接続する"]], "mnemonic": "正しくは：ルームエアコンのドレン管は間接排水とする。", "block": 5, "group": 2}, {"id": "R01_kouki_23", "source": "H30後 No.23 / R1後 No.23", "category": "空調・衛生", "type": "single", "question": "JISに規定する「建築物の用途別による屎尿浄化槽の処理対象人員算定基準」において、処理対象人員の算定式に、延べ面積が用いられていない建築用途はどれか。", "choices": [{"label": "1", "text": "集会場"}, {"label": "2", "text": "公衆便所"}, {"label": "3", "text": "事務所"}, {"label": "4", "text": "共同住宅"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["用いられていない建築用途"], "answerTexts": ["公衆便所"], "answerHints": [["公衆便所"]], "mnemonic": "公衆便所は総便器数で算定。集会場・事務所・共同住宅は延べ面積で算定。", "block": 5, "group": 2}, {"id": "H30_kouki_26", "source": "H30後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "フレキシブルジョイントは、屋外埋設配管の建物導入部における変位吸収継手としても使用される。"}, {"label": "2", "text": "架橋ポリエチレン管は、構造により単層管と二層管に分類される。"}, {"label": "3", "text": "ポリブテン管継手には、メカニカル式、電気融着式及び熱融着式がある。"}, {"label": "4", "text": "ベローズ形伸縮管継手は、スリーブ形伸縮管継手よりも伸縮吸収量が大きい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ベローズ形伸縮管継手は、スリーブ形伸縮管継手よりも伸縮吸収量が大きい。"], "answerHints": [["伸縮吸収量が大きい"]], "mnemonic": "正しくは：伸縮吸収量はスリーブ形の方が大きい（ベローズ形は小さい）。", "block": 5, "group": 2}, {"id": "R01_zenki_25", "source": "R1前 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "飲料用給水タンクの構造に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋外に設置するFRP製タンクは、藻類の増殖防止に有効な遮光性を有するものとする。"}, {"label": "2", "text": "2槽式タンクの中仕切り板は、一方のタンクを空にした場合であっても、地震等により損傷しない構造のものとする。"}, {"label": "3", "text": "タンク底部は、水の滞留防止のため、吸込みピットを設けてはならない。"}, {"label": "4", "text": "通気口は、衛生上有害なものが入らない構造とし、防虫網を設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["タンク底部は、水の滞留防止のため、吸込みピットを設けてはならない。"], "answerHints": [["設けてはならない"]], "mnemonic": "正しくは：タンク底部には勾配を付け、吸込みピットを設ける。", "block": 5, "group": 2}, {"id": "R01_kouki_24", "source": "R1後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "給湯設備の機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "密閉式ガス湯沸器は、燃焼空気を室内から取り入れ、燃焼ガスを直接屋外に排出するものである。"}, {"label": "2", "text": "空気熱源ヒートポンプ給湯器は、大気中の熱エネルギーを給湯の加熱に利用するものである。"}, {"label": "3", "text": "真空式温水発生機は、本体に封入されている熱媒水の補給が不要である。"}, {"label": "4", "text": "小型貫流ボイラーは、保有水量が極めて少ないため起動時間が短く、負荷変動への追従性が良い。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["密閉式ガス湯沸器は、燃焼空気を室内から取り入れ、燃焼ガスを直接屋外に排出するものである。"], "answerHints": [["室内から取り入れ"]], "mnemonic": "正しくは：密閉式は燃焼空気を屋外から取り入れ屋外に排出。室内から取り入れるのは半密閉式。", "block": 5, "group": 2}, {"id": "R01_kouki_27", "source": "R1後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクトに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "保温付きフレキシブルダクトはグラスウールを主材としたもので、補強として鋼線がスパイラル状に巻かれている。"}, {"label": "2", "text": "スパイラルダクトの接続には、差込み継手又はフランジ継手を用いる。"}, {"label": "3", "text": "コーナーボルト工法には、共板フランジ工法とスライドオンフランジ工法がある。"}, {"label": "4", "text": "長方形ダクトの板厚は、ダクトの周長により決定する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["長方形ダクトの板厚は、ダクトの周長により決定する。"], "answerHints": [["周長"]], "mnemonic": "正しくは：長方形ダクトの板厚は、ダクトの長辺の長さで決定する。", "block": 5, "group": 2}, {"id": "H30_kouki_33", "source": "H30後 No.33", "category": "施工管理法", "type": "single", "question": "建設工事現場の安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "回転する刃物を使用する作業は、手を巻き込むおそれがあるので、手袋の使用を禁止する。"}, {"label": "2", "text": "交流アーク溶接機を用いた作業の継続期間中、自動電撃防止装置の点検は、一週間に一度行わなければならない。"}, {"label": "3", "text": "高さが2mの箇所の作業で、墜落により労働者に危険を及ぼすおそれのあるときは、作業床を設け、作業床の端、開口部等には囲い、手すり、覆い等を設ける。"}, {"label": "4", "text": "安全施工サイクルとは、安全朝礼から始まり、安全ミーティング、安全巡回、工程打合せ、片付けまでの日常活動サイクルのことである。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["交流アーク溶接機を用いた作業の継続期間中、自動電撃防止装置の点検は、一週間に一度行わなければならない。"], "answerHints": [["一週間に一度"]], "mnemonic": "正しくは：自動電撃防止装置は、その日の作業開始前に点検する。", "block": 5, "group": 2}, {"id": "H30_kouki_36", "source": "H30後 No.36", "category": "施工管理法", "type": "single", "question": "排水管及び通気管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ループ通気管の取出し位置は、最上流の器具排水管を排水横枝管に接続した直後の下流側とする。"}, {"label": "2", "text": "排水横枝管から通気管を取り出す場合は、排水横枝管の中心線から垂直上方ないし垂直上方から 45°以内の角度で取り出す。"}, {"label": "3", "text": "排水用硬質塩化ビニルライニング鋼管の接続に、排水鋼管用可とう継手(MDジョイント)を使用する。"}, {"label": "4", "text": "管径50Aの排水横枝管の勾配は、最小1/150とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["管径50Aの排水横枝管の勾配は、最小1/150とする。"], "answerHints": [["最小1/150"]], "mnemonic": "正しくは：管径65mm以下の排水横枝管の勾配は1/50以上。", "block": 5, "group": 2}, {"id": "H30_kouki_39", "source": "H30後 No.39", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクトの断面を拡大、縮小する場合の角度は、圧力損失を小さくするため、拡大は 15°以下、縮小は 30°以下とする。"}, {"label": "2", "text": "防火区画貫通部と防火ダンパーとの間のダクトは、厚さ1.5mm 以上の鋼板製とする。"}, {"label": "3", "text": "防火ダンパーは、火災による脱落がないように、小形のものを除き、2点吊りとする。"}, {"label": "4", "text": "浴室の排気ダクトは、凝縮水の滞留を防止するため、排気ガラリに向けて下り勾配とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火ダンパーは、火災による脱落がないように、小形のものを除き、2点吊りとする。"], "answerHints": [["2点吊り"]], "mnemonic": "正しくは：防火ダンパーは、原則として4本吊りとする。", "block": 5, "group": 2}, {"id": "R01_zenki_30", "source": "R1前 No.30", "category": "施工管理法", "type": "single", "question": "「工程表」と「関連する用語」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "バーチャート工程表 ――― ダミー"}, {"label": "2", "text": "バーチャート工程表 ――― 予定進度曲線"}, {"label": "3", "text": "ネットワーク工程表 ――― フロート"}, {"label": "4", "text": "ネットワーク工程表 ――― アクティビティー"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表 ――― ダミー"], "answerHints": [["ダミー"]], "mnemonic": "ダミーはネットワーク工程表の用語（作業の前後関係のみ示す点線矢印）。バーチャートとは関係ない。", "block": 5, "group": 2}, {"id": "R01_zenki_34", "source": "R1前 No.34", "category": "施工管理法", "type": "single", "question": "機器の基礎に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "大型ボイラーの基礎は、床スラブ上に打設した無筋コンクリート基礎とする。"}, {"label": "2", "text": "ユニット形空気調和機の基礎の高さは、ドレンパンからの排水管に空調機用トラップを設けるため、150mm程度とする。"}, {"label": "3", "text": "冷温水ポンプのコンクリート基礎は、基礎表面の排水溝に排水目皿を設け、間接排水できるものとする。"}, {"label": "4", "text": "送風機のコンクリート基礎の幅は、送風機架台より100〜200mm程度大きくする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["大型ボイラーの基礎は、床スラブ上に打設した無筋コンクリート基礎とする。"], "answerHints": [["無筋コンクリート基礎"]], "mnemonic": "正しくは：大型ボイラーの基礎は、床スラブと一体化した鉄筋コンクリート基礎とする。", "block": 5, "group": 2}, {"id": "R01_zenki_37", "source": "R1前 No.37", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "青銅製の水栓と硬質塩化ビニルライニング鋼管との接続には、絶縁継手又はコア付き青銅製継手を使用する。"}, {"label": "2", "text": "排水横枝管に大便器の器具排水管を接続する場合の接続角度は、水平から上方45°以内とする。"}, {"label": "3", "text": "鋼管のねじ加工の検査では、テーパねじリングゲージをパイプレンチで締め込み、ねじ径を確認する。"}, {"label": "4", "text": "給水管と排水管を平行して埋設する場合、両配管の間隔は500mm以上とし、かつ、給水管を排水管の上方に配置する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鋼管のねじ加工の検査では、テーパねじリングゲージをパイプレンチで締め込み、ねじ径を確認する。"], "answerHints": [["パイプレンチで締め込み"]], "mnemonic": "正しくは：テーパねじリングゲージは手で締め込み、管端の位置で合否を確認する。", "block": 5, "group": 2}, {"id": "R01_zenki_40", "source": "H30前 No.40 / R1前 No.40", "category": "施工管理法", "type": "single", "question": "保温、保冷及び塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "保温施工において、ポリエチレンフィルムは、保温材の脱落を防ぐために使用する。"}, {"label": "2", "text": "ポンプ廻りの防振継手は、原則として、保温を行わない。"}, {"label": "3", "text": "保温の厚さとは、一般的に、保温材、外装材、補助材のうち保温材自体の厚さのことである。"}, {"label": "4", "text": "配管の塗装仕上げには、一般的に、合成樹脂調合ペイント等が使用される。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["保温施工において、ポリエチレンフィルムは、保温材の脱落を防ぐために使用する。"], "answerHints": [["保温材の脱落を防ぐ"]], "mnemonic": "正しくは：ポリエチレンフィルムは防湿（湿気の侵入防止）のために使用する。", "block": 5, "group": 2}, {"id": "R01_kouki_32", "source": "H30後 No.32 / R1後 No.32", "category": "施工管理法", "type": "single", "question": "品質を確認するための検査に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "コンクリートの圧縮強度は、抜取検査で確認する。"}, {"label": "2", "text": "埋設排水配管の勾配は、抜取検査で確認する。"}, {"label": "3", "text": "抜取検査は、全数検査と比較して、検査費用が安くなる。"}, {"label": "4", "text": "抜取検査では、ロットとして、合格、不合格が判定される。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["埋設排水配管の勾配は、抜取検査で確認する。"], "answerHints": [["抜取検査"]], "mnemonic": "正しくは：埋設排水配管の勾配は全数検査で確認する。", "block": 5, "group": 2}, {"id": "R01_kouki_36", "source": "R1後 No.36", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "帯のこ盤は、硬質塩化ビニルライニング鋼管の切断に使用できる。"}, {"label": "2", "text": "一般配管用ステンレス鋼管の管継手には、メカニカル形、ハウジング形等がある。"}, {"label": "3", "text": "給湯配管の熱伸縮の吸収には、フレキシブルジョイントを使用する。"}, {"label": "4", "text": "絶縁フランジ接合は、鋼管とステンレス鋼管を接続する場合等に用いられる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給湯配管の熱伸縮の吸収には、フレキシブルジョイントを使用する。"], "answerHints": [["フレキシブルジョイント"]], "mnemonic": "正しくは：給湯配管の熱伸縮の吸収には伸縮管継手（ベローズ形・スリーブ形）を使用する。", "block": 5, "group": 2}, {"id": "R01_kouki_39", "source": "R1後 No.39", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "コーナーボルト工法ダクトの板厚は、ダクトの寸法が同一の場合、アングルフランジ工法ダクトの板厚より薄い板厚としてよい。"}, {"label": "2", "text": "フレキシブルダクトは、気密に、かつ、有効断面積を損なわないように取り付ける。"}, {"label": "3", "text": "消音エルボや消音チャンバーの内貼り吸音材には、一般的に、グラスウール保温材が用いられる。"}, {"label": "4", "text": "防火ダンパを天井内に設ける場合、保守点検が容易に行える位置に天井点検口を設ける。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["コーナーボルト工法ダクトの板厚は、ダクトの寸法が同一の場合、アングルフランジ工法ダクトの板厚より薄い板厚としてよい。"], "answerHints": [["薄い板厚としてよい"]], "mnemonic": "正しくは：寸法が同一なら、コーナーボルト工法ダクトの板厚はアングルフランジ工法ダクトと同じ。", "block": 5, "group": 2}, {"id": "R01_kouki_42", "source": "H30後 No.42 / R1後 No.42", "category": "施工管理法", "type": "single", "question": "多翼送風機の試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "送風機停止時に、Vベルトがたわみなく強く張られた状態であることを確認する。"}, {"label": "2", "text": "手元スイッチで瞬時運転し、回転方向が正しいことを確認する。"}, {"label": "3", "text": "風量調整は、風量調整ダンパが全閉となっていることを確認してから開始する。"}, {"label": "4", "text": "風量測定口がない場合の風量調整は、試験成績表の電流値を参考にする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送風機停止時に、Vベルトがたわみなく強く張られた状態であることを確認する。"], "answerHints": [["たわみなく強く張られた"]], "mnemonic": "正しくは：Vベルトは指で押して適度なたわみがある状態に張る。", "block": 5, "group": 2}, {"id": "H30_kouki_45", "source": "H30後 No.45", "category": "法規", "type": "single", "question": "建築物の確認申請書の提出に関する記述のうち、「建築基準法」上、誤っているものはどれか。\nただし、次の用途に供する部分の床面積の合計は、100m2を超えるものとする。", "choices": [{"label": "1", "text": "ホテルから旅館への用途変更は、確認申請書を提出しなければならない。"}, {"label": "2", "text": "病院の大規模の模様替えは、確認申請書を提出しなければならない。"}, {"label": "3", "text": "共同住宅の大規模の模様替えは、確認申請書を提出しなければならない。"}, {"label": "4", "text": "中学校の大規模の修繕は、確認申請書を提出しなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["ホテルから旅館への用途変更は、確認申請書を提出しなければならない。"], "answerHints": [["ホテルから旅館"]], "mnemonic": "正しくは：ホテルから旅館への変更は類似用途間の変更なので、確認申請は不要。", "block": 5, "group": 2}, {"id": "H30_kouki_48", "source": "H30後 No.48", "category": "法規", "type": "single", "question": "管工事業に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "管工事業の許可を受けた者は、管工事に附帯する電気工事も合わせて請け負うことができる。"}, {"label": "2", "text": "管工事業の許可は、5年ごとに更新を受けなければ、その効力を失う。"}, {"label": "3", "text": "管工事を下請負人としてのみ工事を施工する者は、請負代金の額にかかわらず管工事業の許可を受けなくてよい。"}, {"label": "4", "text": "管工事業の許可を受けた者は、工事件の請負代金の額が 500 万円未満の工事を施工する場合であっても、主任技術者を置かなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["管工事を下請負人としてのみ工事を施工する者は、請負代金の額にかかわらず管工事業の許可を受けなくてよい。"], "answerHints": [["請負代金の額にかかわらず"]], "mnemonic": "正しくは：下請負人でも、軽微な工事（500万円未満）以外は管工事業の許可が必要。", "block": 5, "group": 2}, {"id": "H30_kouki_51", "source": "H30後 No.51", "category": "法規", "type": "single", "question": "次の「測定項目」と「法律」の組合せのうち、当該測定項目がその法律に規定されていないものはどれか。\n--(測定項目)------------(法律)", "choices": [{"label": "1", "text": "生物化学的酸素要求量(BOD)---浄化槽法"}, {"label": "2", "text": "二酸化炭素の含有率---------建築物における衛生的環境の確保に関する法律"}, {"label": "3", "text": "浮遊物質量(SS)---------大気汚染防止法"}, {"label": "4", "text": "水素イオン濃度-----------水質汚濁防止法"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["その法律に規定されていないもの"], "answerTexts": ["浮遊物質量(SS)---------大気汚染防止法"], "answerHints": [["大気汚染防止法"]], "mnemonic": "浮遊物質量(SS)は水質の項目（水質汚濁防止法など）。大気汚染防止法には規定されていない。", "block": 5, "group": 2}, {"id": "R01_zenki_44", "source": "R1前 No.44", "category": "法規", "type": "single", "question": "労働条件における休憩に関する記述のうち、「労働基準法」上、誤っているものはどれか。ただし、労働組合等との協定による別の定めがある場合を除く。", "choices": [{"label": "1", "text": "使用者は、休憩時間を自由に利用させなければならない。"}, {"label": "2", "text": "使用者は、労働時間が6時間を超える場合においては少なくとも30分の休憩時間を労働時間の途中に与えなければならない。"}, {"label": "3", "text": "使用者は、労働時間が8時間を超える場合においては少なくとも1時間の休憩時間を労働時間の途中に与えなければならない。"}, {"label": "4", "text": "使用者は、休憩時間を一斉に与えなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["使用者は、労働時間が6時間を超える場合においては少なくとも30分の休憩時間を労働時間の途中に与えなければならない。"], "answerHints": [["30分"]], "mnemonic": "正しくは：労働時間が6時間を超える場合は少なくとも45分（8時間を超える場合は1時間）。", "block": 5, "group": 2}, {"id": "R01_zenki_47", "source": "R1前 No.47", "category": "法規", "type": "single", "question": "建設業者が請け負った管工事の、当該工事現場に置かなければならない主任技術者の要件に、「建設業法」上、該当しないものはどれか。", "choices": [{"label": "1", "text": "管工事施工管理を検定種目とする級の技術検定に合格した者"}, {"label": "2", "text": "一級建築士免許の交付を受けた者"}, {"label": "3", "text": "管工事に関し、大学の建築学に関する学科を卒業した後3年以上実務の経験を有する者"}, {"label": "4", "text": "管工事に関し、10年以上実務の経験を有する者"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["一級建築士免許の交付を受けた者"], "answerHints": [["一級建築士免許"]], "mnemonic": "一級建築士は管工事の主任技術者の要件に該当しない。", "block": 5, "group": 2}, {"id": "R01_zenki_51", "source": "R1前 No.51", "category": "法規", "type": "single", "question": "騒音の規制に関する記述のうち、「騒音規制法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "特定建設作業とは、建設工事として行われる作業のうち、著しい騒音を発生する所定の作業をいう。"}, {"label": "2", "text": "特定施設とは、工場又は事業場に設置される施設のうち、著しい騒音を発生する所定の施設をいう。"}, {"label": "3", "text": "指定地域内において特定建設作業を伴う建設工事を施工しようとする者は、当該作業の開始日の5日前までに、市町村長に所定の事項を届け出なければならない。"}, {"label": "4", "text": "規制基準とは、特定工場等において発生する騒音の特定工場等の敷地の境界線における大きさの許容限度をいう。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["指定地域内において特定建設作業を伴う建設工事を施工しようとする者は、当該作業の開始日の5日前までに、市町村長に所定の事項を届け出なければならない。"], "answerHints": [["5日前"]], "mnemonic": "正しくは：特定建設作業の開始日の7日前までに市町村長に届け出る。", "block": 5, "group": 2}, {"id": "R01_kouki_44", "source": "R1後 No.44", "category": "法規", "type": "single", "question": "労働条件に関する記述のうち、「労働基準法」上、誤っているものはどれか。ただし、労働組合との協定等又は法令若しくは労働協約に別の定めがある場合等を除く。", "choices": [{"label": "1", "text": "労働者が業務上負傷し、労働することができないために賃金を受けない場合において、使用者は、平均賃金の30/100の休業補償を行わなければならない。"}, {"label": "2", "text": "使用者は、労働者に、休憩時間を除き1日について8時間を超えて労働させてはならない。"}, {"label": "3", "text": "使用者から明示された労働条件が事実と相違する場合、労働者は、即時に労働契約を解除することができる。"}, {"label": "4", "text": "賃金は、通貨で、直接労働者に、その全額を支払わなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["労働者が業務上負傷し、労働することができないために賃金を受けない場合において、使用者は、平均賃金の30/100の休業補償を行わなければならない。"], "answerHints": [["30/100"]], "mnemonic": "正しくは：休業補償は平均賃金の60/100。", "block": 5, "group": 2}, {"id": "R01_kouki_47", "source": "R1後 No.47", "category": "法規", "type": "single", "question": "建設業に関する用語の記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建設業者とは、建設業の許可を受けて建設業を営む者をいう。"}, {"label": "2", "text": "下請契約とは、建設工事を他の者から請け負った建設業を営む者と他の建設業を営む者との間で当該建設工事について締結される請負契約をいう。"}, {"label": "3", "text": "発注者とは、下請契約における注文者で、建設業者である者をいう。"}, {"label": "4", "text": "主任技術者とは、建設業者が施工する建設工事に関し、建設業法で規定する要件に該当する者で、当該工事現場における建設工事の施工の技術上の管理をつかさどるものをいう。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["発注者とは、下請契約における注文者で、建設業者である者をいう。"], "answerHints": [["下請契約における注文者"]], "mnemonic": "正しくは：発注者は建設工事の最初の注文者。下請契約の注文者で建設業者である者は元請負人。", "block": 5, "group": 2}, {"id": "R01_kouki_50", "source": "R1後 No.50", "category": "法規", "type": "single", "question": "浄化槽に関する記述のうち、「浄化槽法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "浄化槽からの放流水の水質は、生物化学的酸素要求量を1Lにつき20mg以下としなければならない。"}, {"label": "2", "text": "浄化槽を新たに設置する場合、使用開始後一定期間内に、指定検査機関が行う水質に関する検査を受けなければならない。"}, {"label": "3", "text": "浄化槽を工場で製造する者は、型式について都道府県知事の認定を受けなければならない。"}, {"label": "4", "text": "浄化槽工事業を営もうとする者は、当該業を行おうとする区域を管轄する都道府県知事の登録を受けなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["浄化槽を工場で製造する者は、型式について都道府県知事の認定を受けなければならない。"], "answerHints": [["都道府県知事の認定"]], "mnemonic": "正しくは：浄化槽を工場で製造する場合、型式について国土交通大臣の認定を受ける。", "block": 5, "group": 2}, {"id": "H30_kouki_03", "source": "H30後 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する記述のうち、適当でないものはどれか", "choices": [{"label": "1", "text": "液体は、気体に比べて圧縮しにくい。"}, {"label": "2", "text": "大気圧の1気圧の大きさは、概ね深さ10mの水圧に相当する。"}, {"label": "3", "text": "水の粘性係数は、空気の粘性係数より大きい。"}, {"label": "4", "text": "レイノルズ数が大きくなると、層流になる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["レイノルズ数が大きくなると、層流になる。"], "answerHints": [["層流"]], "mnemonic": "正しくは：レイノルズ数が大きくなると乱流になる。", "block": 6, "group": 2}, {"id": "H30_kouki_06", "source": "H29後 No.6 / H30後 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリートに関する記述のうち、適当でないものはどれか", "choices": [{"label": "1", "text": "鉄筋とコンクリートの線膨張係数は、大きく異なる。"}, {"label": "2", "text": "鉄筋コンクリートは、主にコンクリートが圧縮力を負担し、鉄筋が引張力を負担する。"}, {"label": "3", "text": "柱の帯筋は、柱のせん断破壊を防止する補強筋である。"}, {"label": "4", "text": "コンクリートはアルカリ性であるため、鉄筋のさびを防止する効果がある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鉄筋とコンクリートの線膨張係数は、大きく異なる。"], "answerHints": [["大きく異なる"]], "mnemonic": "正しくは：鉄筋とコンクリートの線膨張係数はほぼ等しい。", "block": 6, "group": 2}, {"id": "R01_zenki_03", "source": "R1前 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する用語の組合せのうち、関係のないものはどれか。", "choices": [{"label": "1", "text": "粘性係数 ――――― 摩擦応力"}, {"label": "2", "text": "パスカルの原理 ―― 圧力"}, {"label": "3", "text": "動圧 ――――――― 表面張力"}, {"label": "4", "text": "オリフィス ―――― 流量計測"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["動圧 ――――――― 表面張力"], "answerHints": [["動圧", "表面張力"]], "mnemonic": "動圧は流速（ピトー管）に関係。表面張力は毛管現象に関係。", "block": 6, "group": 2}, {"id": "R01_zenki_06", "source": "R1前 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート造の建築物の構造に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "バルコニーなど片持ち床版は、設計荷重を割増すなどにより、版厚及び配筋に余裕を持たせる。"}, {"label": "2", "text": "柱には、原則として、配管等の埋設を行わない。"}, {"label": "3", "text": "梁貫通孔は、せん断力の大きい部位を避けて設け、必要な補強を行う。"}, {"label": "4", "text": "構造体に作用する荷重及び外力は、固定荷重、積載荷重及び地震力とし、風圧力は考慮しない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["構造体に作用する荷重及び外力は、固定荷重、積載荷重及び地震力とし、風圧力は考慮しない。"], "answerHints": [["風圧力は考慮しない"]], "mnemonic": "正しくは：固定荷重・積載荷重・積雪荷重・風圧力・地震力などを考慮する。", "block": 6, "group": 2}, {"id": "R01_kouki_03", "source": "R1後 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "流体の粘性の影響は、流体に接する壁面近くでは無視できる。"}, {"label": "2", "text": "水中における水の圧力は、静止した水面からの深さに比例して高くなる。"}, {"label": "3", "text": "圧力計が示すゲージ圧は、絶対圧から大気圧を差し引いた圧力である。"}, {"label": "4", "text": "ベルヌーイの定理は、流線上にエネルギー保存の法則を適用したものである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["流体の粘性の影響は、流体に接する壁面近くでは無視できる。"], "answerHints": [["無視できる"]], "mnemonic": "正しくは：壁面近くでは流体の粘性の影響が大きい。", "block": 6, "group": 2}, {"id": "R01_kouki_06", "source": "R1後 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート造の建築物の鉄筋に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ジャンカ、コールドジョイントは、鉄筋の腐食の原因になりやすい。"}, {"label": "2", "text": "鉄筋のかぶり厚さは、外壁、柱、梁及び基礎で同じ厚さとしなければならない。"}, {"label": "3", "text": "あばら筋は、梁のせん断破壊を防止する補強筋である。"}, {"label": "4", "text": "コンクリートの引張強度は小さく、鉄筋の引張強度は大きい。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鉄筋のかぶり厚さは、外壁、柱、梁及び基礎で同じ厚さとしなければならない。"], "answerHints": [["同じ厚さとしなければならない"]], "mnemonic": "正しくは：かぶり厚さは部位ごとに定められ、同じではない（基礎は大きくする等）。", "block": 6, "group": 2}, {"id": "H30_kouki_09", "source": "H30後 No.9", "category": "空調・衛生", "type": "single", "question": "熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "二重サッシ窓では、ブラインドを室内に設置するより、二重サッシ内に設置する方が、日射負荷は小さくなる。"}, {"label": "2", "text": "構造体の構成材質が同じであれば、厚さの厚い方が熱通過率は小さくなる。"}, {"label": "3", "text": "顕熱比(SHF)とは、潜熱負荷に対する顕熱負荷の割合をいう。"}, {"label": "4", "text": "暖房負荷計算では、一般的に、日射負荷は考慮しない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["顕熱比(SHF)とは、潜熱負荷に対する顕熱負荷の割合をいう。"], "answerHints": [["潜熱負荷に対する"]], "mnemonic": "正しくは：SHFは全熱負荷のうち顕熱負荷が占める割合。", "block": 6, "group": 2}, {"id": "H30_kouki_12", "source": "H30後 No.12", "category": "空調・衛生", "type": "single", "question": "放射冷暖房に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "放射暖房は、対流暖房に比べて、室内温度の上下むらが少ない。"}, {"label": "2", "text": "放射暖房は、天井の高い工場などでは効果が得られにくい。"}, {"label": "3", "text": "放射冷房の場合、放熱面温度を下げすぎると、放熱面で結露が生じる。"}, {"label": "4", "text": "冷温水パネルの場合、天井などに水配管を必要とし、水損事故のリスクがある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["放射暖房は、天井の高い工場などでは効果が得られにくい。"], "answerHints": [["効果が得られにくい"]], "mnemonic": "正しくは：放射暖房は天井の高い工場などでも効果が得られやすい。", "block": 6, "group": 2}, {"id": "H30_kouki_15", "source": "H30後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道の浄水施設における消毒に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "原水が清浄であっても、浄水施設には必ず消毒設備を設ける。"}, {"label": "2", "text": "水の消毒には、塩素剤のみが認められている。"}, {"label": "3", "text": "遊離残留塩素より結合残留塩素の方が、殺菌力が高い。"}, {"label": "4", "text": "一般細菌は、塩素消毒によりほとんど検出されなくなる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["遊離残留塩素より結合残留塩素の方が、殺菌力が高い。"], "answerHints": [["結合残留塩素の方が"]], "mnemonic": "正しくは：結合残留塩素より遊離残留塩素の方が殺菌力が高い。", "block": 6, "group": 2}, {"id": "H30_kouki_18", "source": "H29後 No.18 / H30後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "逃がし管は、貯湯タンクなどから単独で立ち上げ、保守用の仕切弁を設ける。"}, {"label": "2", "text": "ヒートポンプ給湯機は、大気中の熱エネルギーを給湯の加熱に利用するものである。"}, {"label": "3", "text": "中央給湯方式に設ける循環ポンプは、一般的に、貯湯タンクへの返湯管に設置する。"}, {"label": "4", "text": "密閉式膨張タンクは、設置位置や高さの制限を受けずに設置することができる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["逃がし管は、貯湯タンクなどから単独で立ち上げ、保守用の仕切弁を設ける。"], "answerHints": [["仕切弁を設ける"]], "mnemonic": "正しくは：逃がし管には弁を設けてはならない。", "block": 6, "group": 2}, {"id": "H30_kouki_22", "source": "H30後 No.22", "category": "空調・衛生", "type": "single", "question": "液化石油ガス(LPG)設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "LPG の充てん容器の設置の際は、容器が常に50 °C以下に保たれる措置を講じる。"}, {"label": "2", "text": "LPG のガス漏れ警報器には検査合格表示が付され、その有効期間は5年である。"}, {"label": "3", "text": "LPG は、本来、無色・無臭のガスであるが、ガス漏れを感知できるように臭いがつけられている。"}, {"label": "4", "text": "「液化石油ガスの保安の確保及び取引の適正化に関する法律」による特定液化石油ガス器具等には、技術上の基準に適合しているとして PS マークが付されている。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["LPG の充てん容器の設置の際は、容器が常に50 °C以下に保たれる措置を講じる。"], "answerHints": [["50 °C以下"]], "mnemonic": "正しくは：LPGの充填容器は常に40℃以下に保つ。", "block": 6, "group": 2}, {"id": "R01_zenki_10", "source": "R1前 No.10", "category": "空調・衛生", "type": "single", "question": "空気調和設備に関する用語の組合せのうち、関係のないものはどれか。", "choices": [{"label": "1", "text": "冷却水の水質 ――――――――― ブローダウン"}, {"label": "2", "text": "吸収冷温水機 ――――――――― 特定フロン"}, {"label": "3", "text": "変風量(VAV)ユニット ――― 温度検出器"}, {"label": "4", "text": "空調ゾーニング ―――――――― ペリメータ"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["吸収冷温水機 ――――――――― 特定フロン"], "answerHints": [["特定フロン"]], "mnemonic": "吸収冷温水機の冷媒は水（フロンは使わない）。", "block": 6, "group": 2}, {"id": "R01_zenki_13", "source": "R1前 No.13", "category": "空調・衛生", "type": "single", "question": "床面積の合計が100m2を超える住宅の調理室に設置するガスコンロ(開放式燃焼器具)の廃ガス等を、換気扇により排気する場合の必要換気量として、「建築基準法」上、正しいものはどれか。ただし、排気フードは設けないものとする。ここで、K:燃料の単位燃焼量当たりの理論廃ガス量〔m3/(kW・h)〕Q:火を使用する器具の実況に応じた燃料消費量〔kW〕とする。", "choices": [{"label": "1", "text": "2KQ[m3/h]"}, {"label": "2", "text": "20KQ[m3/h]"}, {"label": "3", "text": "30KQ[m3/h]"}, {"label": "4", "text": "40KQ[m3/h]"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["40KQ[m3/h]"], "answerHints": [["40KQ"]], "mnemonic": "排気フードなしは40KQ（フードⅡ型20KQ、Ⅰ型30KQ、煙突2KQ）。", "block": 6, "group": 2}, {"id": "R01_zenki_16", "source": "R1前 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "下水とは、生活若しくは事業(耕作の事業を除く。)に起因し、若しくは付随する廃水又は雨水をいう。"}, {"label": "2", "text": "下水道の流速は、一般的に、下流に行くに従い漸増させ、勾配は下流に行くに従い緩やかにする。"}, {"label": "3", "text": "下水道本管への取付管の接続は、管底接続とする。"}, {"label": "4", "text": "分流式では、降雨初期において、汚濁された路面排水が雨水管きょを経て直接公共用水域に放流される。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["下水道本管への取付管の接続は、管底接続とする。"], "answerHints": [["管底接続"]], "mnemonic": "正しくは：取付管は本管の中心線より上方に接続する。", "block": 6, "group": 2}, {"id": "R01_zenki_19", "source": "H30前 No.19 / R1前 No.19", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "各個通気方式は、自己サイホン作用の防止に有効である。"}, {"label": "2", "text": "通気立て管の下部は、最低位の排水横枝管より下部で排水立て管に接続するか、又は排水横主管に接続する。"}, {"label": "3", "text": "排水立て管の管径は、下階になるに従い排水負荷に応じて大きくする。"}, {"label": "4", "text": "各個通気管は、器具のトラップ下流側の排水管より取り出す。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水立て管の管径は、下階になるに従い排水負荷に応じて大きくする。"], "answerHints": [["大きくする"]], "mnemonic": "正しくは：排水立て管は最下部の最大負荷で決めた管径とし、上部まで同一管径とする。", "block": 6, "group": 2}, {"id": "R01_zenki_22", "source": "R1前 No.22", "category": "空調・衛生", "type": "single", "question": "ガス漏れ警報器に関する文中、 内に当てはまる数値及び語句の組合せとして、適当なものはどれか。\n液化石油ガスのガス漏れ警報器の検知部は、ガス機器からの水平距離が A m以内で、かつ、 B から30cm以内の位置に設置しなければならない。", "choices": [{"label": "1", "text": "4 ――― 床面"}, {"label": "2", "text": "8 ――― 床面"}, {"label": "3", "text": "4 ――― 天井面"}, {"label": "4", "text": "8 ――― 天井面"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["4 ――― 床面"], "answerHints": [["4", "床面"]], "mnemonic": "LPG（空気より重い）は水平距離4m以内・床面から30cm以内。都市ガス（軽い）は8m以内・天井面から30cm以内。", "block": 6, "group": 2}, {"id": "R01_kouki_11", "source": "R1後 No.11", "category": "空調・衛生", "type": "single", "question": "暖房に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "蒸気暖房には、一般的に、蒸気圧力100kPa以下の低圧蒸気が使用される。"}, {"label": "2", "text": "温水暖房は、一般的に、50~80°Cの温水が使われる。"}, {"label": "3", "text": "鋳鉄製放熱器での暖房の場合、蒸気より温水の方が負荷変動に応じた制御が容易である。"}, {"label": "4", "text": "鋳鉄製温水ボイラーの温水温度は、ボイラー構造規格により、最高100°Cまでに制限されている。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鋳鉄製温水ボイラーの温水温度は、ボイラー構造規格により、最高100°Cまでに制限されている。"], "answerHints": [["最高100°C"]], "mnemonic": "正しくは：鋳鉄製温水ボイラーの温水温度は最高120℃まで。", "block": 6, "group": 2}, {"id": "R01_kouki_14", "source": "R1後 No.14", "category": "空調・衛生", "type": "single", "question": "特殊建築物の居室に機械換気設備を設ける場合、有効換気量の必要最小値を算定する式として、「建築基準法」上、正しいものはどれか。ただし、V:有効換気量[m3/h]、Af:居室の床面積[m2]、N:実況に応じた1人当たりの占有面積(3を超えるときは3とする。)[m2]とする。", "choices": [{"label": "1", "text": "V = 10Af / N"}, {"label": "2", "text": "V = 20Af / N"}, {"label": "3", "text": "V = Af / 10N"}, {"label": "4", "text": "V = Af / 20N"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["V = 20Af / N"], "answerHints": [["20Af / N"]], "mnemonic": "V＝20Af／N（1人当たり20m3/h）。", "block": 6, "group": 2}, {"id": "R01_kouki_17", "source": "R1後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給水配管には、ライニング鋼管、ステンレス鋼管、樹脂管等が用いられる。"}, {"label": "2", "text": "給水量の算定にあたっては、建物の用途、使用時間及び使用人員を把握するほか、空調用水等も考慮する。"}, {"label": "3", "text": "高置タンク方式で重力により給水する場合、高置タンクの高さは、最上階の器具等の必要給水圧力が確保できるように決定する。"}, {"label": "4", "text": "飲料用給水タンクのオーバーフロー管には、防虫対策として排水トラップを設ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用給水タンクのオーバーフロー管には、防虫対策として排水トラップを設ける。"], "answerHints": [["排水トラップを設ける"]], "mnemonic": "正しくは：オーバーフロー管には排水トラップを設けてはならない（防虫網を設け間接排水）。", "block": 6, "group": 2}, {"id": "R01_kouki_20", "source": "H30後 No.20 / R1後 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ループ通気管の管径は、当該ループ通気管を接続する排水横枝管と通気立て管の管径のうち、いずれか小さい方の1/2以上とする。"}, {"label": "2", "text": "伸頂通気管の管径は、排水立て管の管径の1/2以上とする。"}, {"label": "3", "text": "水封式トラップの機能は、封水を常時保持することで維持される。"}, {"label": "4", "text": "Uトラップは、排水配管の途中に設置するトラップである。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["伸頂通気管の管径は、排水立て管の管径の1/2以上とする。"], "answerHints": [["1/2以上"]], "mnemonic": "正しくは：伸頂通気管の管径は、排水立て管の管径より小さくしない。", "block": 6, "group": 2}, {"id": "H30_kouki_24", "source": "H30後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "給湯機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "元止め式のガス瞬間湯沸器は、湯沸器の操作で給湯するもので、給湯配管ができないものである。"}, {"label": "2", "text": "貯湯式電気温水器の先止め式には、逃し弁及び給水供給側に減圧逆止弁が必要である。"}, {"label": "3", "text": "密閉式ガス湯沸器は、燃焼空気を室内からとり、燃焼ガスを屋外に排出する機器である。"}, {"label": "4", "text": "潜熱回収型ガス給湯器には、潜熱回収時の凝縮水を中和処理する装置が組み込まれている。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["密閉式ガス湯沸器は、燃焼空気を室内からとり、燃焼ガスを屋外に排出する機器である。"], "answerHints": [["室内からとり"]], "mnemonic": "正しくは：密閉式は燃焼空気を屋外から取り入れ屋外に排出。室内から取るのは半密閉式。", "block": 6, "group": 2}, {"id": "H30_kouki_27", "source": "H30後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "吹出口に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "線状吹出口は、サイズの大きいものは到達距離が長くとれ、高所用吹出口としても適している。"}, {"label": "2", "text": "床吹出口には、ダンパーを内蔵したものや小型ファンを内蔵したものがある。"}, {"label": "3", "text": "ユニバーサル型吹出口には、羽根が垂直のV型、水平のH型、羽根が二重に配置された VH型などがある。"}, {"label": "4", "text": "ノズル型吹出口からの吹出し空気は、誘引空気と混合して放射状に吹き出される。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ノズル型吹出口からの吹出し空気は、誘引空気と混合して放射状に吹き出される。"], "answerHints": [["放射状"]], "mnemonic": "正しくは：誘引空気と混合して放射状に吹き出すのはふく流（アネモ）型。ノズル型は到達距離が長く大空間向け。", "block": 6, "group": 2}, {"id": "R01_zenki_26", "source": "R1前 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "弁の構造及び特徴に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "仕切弁は、弁体が上下に作動し流体を仕切るもので、開閉に時間を要する。"}, {"label": "2", "text": "玉形弁は、圧力損失が仕切弁よりも大きいが、流量を調整するのに適している。"}, {"label": "3", "text": "バタフライ弁は、コンパクトであり、重量が軽いことから取り付けが容易である。"}, {"label": "4", "text": "ボール弁は、流体の流れ方向を一定に保ち、逆流を防止する弁である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボール弁は、流体の流れ方向を一定に保ち、逆流を防止する弁である。"], "answerHints": [["逆流を防止する弁"]], "mnemonic": "正しくは：逆流防止は逆止弁。ボール弁は球状の弁体を90°回転させて開閉する。", "block": 6, "group": 2}, {"id": "R01_kouki_25", "source": "R1後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "送風機及びポンプに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "遠心送風機は、羽根車の中に軸方向から空気が入り、半径方向に通り抜ける構造である。"}, {"label": "2", "text": "遠心ポンプの軸動力は、吐出量の増加とともに減少する。"}, {"label": "3", "text": "斜流送風機は、風量・静圧とも遠心式と軸流式の中間に位置し、小形の割には取り扱う風量が大きい。"}, {"label": "4", "text": "遠心ポンプの吐出量の調整弁は、ポンプの吐出側に設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["遠心ポンプの軸動力は、吐出量の増加とともに減少する。"], "answerHints": [["減少する"]], "mnemonic": "正しくは：遠心ポンプの軸動力は、吐出量の増加とともに増加する。", "block": 6, "group": 2}, {"id": "H30_kouki_29", "source": "H30後 No.29", "category": "施工管理法", "type": "single", "question": "施工計画に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "施工図を作成する際は、施工上の納まりのほか、他工事との取り合いについても調整する。"}, {"label": "2", "text": "仮設に使用する機材は、設計図書に定める品質及び性能を有するもので、かつ、新品とする必要がある。"}, {"label": "3", "text": "機器を選定する際は、コスト、品質及び性能のほか、納期についても考慮する必要がある。"}, {"label": "4", "text": "施工図は、工事工程に支障のないように、作成順序、作成予定日等をあらかじめ定めて作成する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["仮設に使用する機材は、設計図書に定める品質及び性能を有するもので、かつ、新品とする必要がある。"], "answerHints": [["新品とする必要がある"]], "mnemonic": "正しくは：仮設に使用する機材は、新品でなくてもよい。", "block": 6, "group": 2}, {"id": "H30_kouki_34", "source": "H29後 No.34 / H30後 No.34", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "送風機は、レベルを水準器で検査し、水平となるように基礎と共通架台の間にライナーを入れて調整する。"}, {"label": "2", "text": "パッケージ形空気調和機は、コンクリート基礎上に防振ゴムパッドを敷いて水平に据え付ける。"}, {"label": "3", "text": "冷却塔は、補給水口の高さが高置タンクの低水位から1m未満となるように据え付ける。"}, {"label": "4", "text": "吸収冷温水機は、据付け後に工場出荷時の気密が保持されているか確認する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["冷却塔は、補給水口の高さが高置タンクの低水位から1m未満となるように据え付ける。"], "answerHints": [["1m未満"]], "mnemonic": "正しくは：冷却塔の補給水口は、補給水タンクの低水位から3m以上低くなるように据え付ける。", "block": 6, "group": 2}, {"id": "H30_kouki_37", "source": "H30後 No.37", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "臭気を防止するためには、器具トラップの他に、排水管にも配管トラップを設けることが望ましい。"}, {"label": "2", "text": "ループ通気管は、当該通気管を排水横枝管から取り出した階の床下で通気立て管に接続してはならない。"}, {"label": "3", "text": "鋼管の溶接方法には、被覆アーク溶接等がある。"}, {"label": "4", "text": "汚水槽の通気管は、他の排水系統の通気管に接続してはならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["臭気を防止するためには、器具トラップの他に、排水管にも配管トラップを設けることが望ましい。"], "answerHints": [["配管トラップを設けることが望ましい"]], "mnemonic": "正しくは：器具トラップがあるのに配管トラップを設けると二重トラップになるので設けない。", "block": 6, "group": 2}, {"id": "H30_kouki_40", "source": "H30後 No.40", "category": "施工管理法", "type": "single", "question": "保温・防Ç・塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ロックウール保温材は、グラスウール保温材に比べて、使用できる最高温度が低い。"}, {"label": "2", "text": "塗装は塗料の乾燥に適した環境で行い、溶剤による中毒を起こさないように換気を行う。"}, {"label": "3", "text": "鋼管のねじ接合における余ねじ部及びパイプレンチ跡には、防Ç塗料を塗布する。"}, {"label": "4", "text": "防火区画を貫通する不燃材料の配管に保温が必要な場合、当該貫通部の保温にはロックウール保温材を使用する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ロックウール保温材は、グラスウール保温材に比べて、使用できる最高温度が低い。"], "answerHints": [["最高温度が低い"]], "mnemonic": "正しくは：ロックウール保温材は、グラスウールより使用できる最高温度が高い。", "block": 6, "group": 2}, {"id": "R01_zenki_32", "source": "H30前 No.32 / R1前 No.32", "category": "施工管理法", "type": "single", "question": "抜取検査を行う場合の必要条件として、適当でないものはどれか。", "choices": [{"label": "1", "text": "合格したロットの中に、不良品の混入が許されないこと。"}, {"label": "2", "text": "ロットの中からサンプルの抜取りがランダムにできること。"}, {"label": "3", "text": "品質基準が明確であり、再現性が確保されること。"}, {"label": "4", "text": "検査対象がロットとして処理できること。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["合格したロットの中に、不良品の混入が許されないこと。"], "answerHints": [["混入が許されない"]], "mnemonic": "正しくは：抜取検査では、合格ロットにある程度の不良品の混入が許されること。", "block": 6, "group": 2}, {"id": "R01_zenki_35", "source": "R1前 No.35", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飲料用給水タンクを設置する場合、タンク底部は、設置床から60cm以上離す。"}, {"label": "2", "text": "飲料用給水タンクを設置する場合、タンク上部は、天井から100cm以上離す。"}, {"label": "3", "text": "排水用水中ポンプを設置する場合、ポンプは、吸い込みピットの壁から20cm以上離す。"}, {"label": "4", "text": "排水用水中ポンプを設置する場合、ポンプは、排水槽への排水流入部に近接した位置に据え付ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水用水中ポンプを設置する場合、ポンプは、排水槽への排水流入部に近接した位置に据え付ける。"], "answerHints": [["近接した位置"]], "mnemonic": "正しくは：排水用水中ポンプは、排水流入部から離れた位置に据え付ける。", "block": 6, "group": 2}, {"id": "R01_zenki_38", "source": "R1前 No.38", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "変風量(VAV)ユニットは、厨房の排気ダクト系統には使用しない。"}, {"label": "2", "text": "防火区画を貫通するダクトと当該防火区画の壁又は床とのすき間には、グラスウール保温材を充てんする。"}, {"label": "3", "text": "厨房の排気ダクトには、ダクト内の点検が定期的にできるように点検口を設ける。"}, {"label": "4", "text": "排気フードの吊りは、四隅のほか最大1,500mm間隔で行う。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火区画を貫通するダクトと当該防火区画の壁又は床とのすき間には、グラスウール保温材を充てんする。"], "answerHints": [["グラスウール保温材"]], "mnemonic": "正しくは：防火区画貫通部のすき間は、ロックウール保温材などの不燃材料で充填する。", "block": 6, "group": 2}, {"id": "R01_kouki_29", "source": "R1後 No.29", "category": "施工管理法", "type": "single", "question": "公共工事における施工計画に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "設計図書及び工事関係図書は、監督員の承諾を受けた場合を除き、工事の施工のために使用する以外の目的で第三者に使用させない。"}, {"label": "2", "text": "現場代理人は、主任技術者を兼ねることができる。"}, {"label": "3", "text": "施工計画書に記載された品質計画は、その妥当性について監督員の承諾を得る。"}, {"label": "4", "text": "設計図書の中にくい違いがある場合、現場代理人の責任で対応方法を決定し、その結果を記録に残す。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["設計図書の中にくい違いがある場合、現場代理人の責任で対応方法を決定し、その結果を記録に残す。"], "answerHints": [["現場代理人の責任で対応方法を決定"]], "mnemonic": "正しくは：設計図書にくい違いがある場合は、監督員に通知して確認・指示を受ける。", "block": 6, "group": 2}, {"id": "R01_kouki_34", "source": "R1後 No.34", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "汚物用水中モーターポンプは、点検や引上げに支障がないように、点検用マンホールの真下近くに設置する。"}, {"label": "2", "text": "送風機やポンプの防振基礎に取り付ける防振材は、機器の固有振動数、回転数、荷重等を考慮して選定する。"}, {"label": "3", "text": "壁掛け小便器を軽量鉄骨ボード壁に取り付ける場合、小便器のバックハンガーは、下地材を避けて仕上げボードにビス止めする。"}, {"label": "4", "text": "冷却塔を屋上に設置する場合の設置位置は、煙突からの煙を吸い込まないように、煙突頂部から離れた位置とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["壁掛け小便器を軽量鉄骨ボード壁に取り付ける場合、小便器のバックハンガーは、下地材を避けて仕上げボードにビス止めする。"], "answerHints": [["下地材を避けて"]], "mnemonic": "正しくは：バックハンガーは、補強した下地材に堅固に取り付ける。", "block": 6, "group": 2}, {"id": "R01_kouki_37", "source": "R1後 No.37", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飲料用の受水タンクの水抜管は、雑排水系統の排水管に直接接続する。"}, {"label": "2", "text": "排水横枝管から取り出した通気管は、その排水系統の最も高い位置にある衛生器具のあふれ縁から150mm以上上方で横走りさせ、通気立て管に接続する。"}, {"label": "3", "text": "各階で排水が合流する排水立て管において、排水立て管の各階の管径は、排水立て管最下部の管径と同一とする。"}, {"label": "4", "text": "敷地内(車両通行部を除く。)に給水管を埋設する場合、埋設深さ(土かぶり)は、一般的に、300mm以上とする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用の受水タンクの水抜管は、雑排水系統の排水管に直接接続する。"], "answerHints": [["直接接続する"]], "mnemonic": "正しくは：飲料用受水タンクの水抜管は間接排水とする。", "block": 6, "group": 2}, {"id": "R01_kouki_40", "source": "R1後 No.40", "category": "施工管理法", "type": "single", "question": "保温、防錆及び塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ロックウール保温材は、グラスウール保温材に比べて、使用できる最高温度が低い。"}, {"label": "2", "text": "防火区画を貫通する不燃材料の配管に保温が必要な場合、当該貫通部の保温にはロックウール保温材を使用する。"}, {"label": "3", "text": "鋼管のねじ接合における余ねじ部及びパイプレンチ跡には、防錆塗料を塗布する。"}, {"label": "4", "text": "塗装は塗料の乾燥に適した環境で行い、溶剤による中毒を起こさないように換気を行う。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ロックウール保温材は、グラスウール保温材に比べて、使用できる最高温度が低い。"], "answerHints": [["最高温度が低い"]], "mnemonic": "正しくは：ロックウール保温材は、グラスウールより使用できる最高温度が高い。", "block": 6, "group": 2}, {"id": "H30_kouki_43", "source": "H30後 No.43", "category": "法規", "type": "single", "question": "建設現場における安全衛生管理体制に関する文中、 内に当てはまる「労働安全衛生法」上に定められた数値の組合せとして、正しいものはどれか。\n事業者は、労働者の数が常時 A 人以上 B 人未満の事業場においては、安\n全衛生推進者を選任しなければならない。\n---(A)-----(B)", "choices": [{"label": "1", "text": "5-------50"}, {"label": "2", "text": "5-------60"}, {"label": "3", "text": "10-------50"}, {"label": "4", "text": "10-------60"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["10-------50"], "answerHints": [["10", "50"]], "mnemonic": "安全衛生推進者は常時10人以上50人未満の事業場で選任。", "block": 6, "group": 2}, {"id": "H30_kouki_46", "source": "H30後 No.46", "category": "法規", "type": "single", "question": "次の空気環境項目のうち、「建築基準法」上、建築物の居室に設ける中央管理方式の空気調和設備の性能として、規定されていないものはどれか。", "choices": [{"label": "1", "text": "浮遊粉じんの量"}, {"label": "2", "text": "二酸化炭素の含有率"}, {"label": "3", "text": "酸素の含有率"}, {"label": "4", "text": "気流"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["規定されていないもの"], "answerTexts": ["酸素の含有率"], "answerHints": [["酸素の含有率"]], "mnemonic": "中央管理方式の基準は浮遊粉じん・CO・CO2・温度・相対湿度・気流（＋ホルムアルデヒド）。酸素は規定なし。", "block": 6, "group": 2}, {"id": "H30_kouki_49", "source": "H30後 No.49", "category": "法規", "type": "single", "question": "地上3階建ての耐火構造で内装制限した事務庁舎において、「消防法」上に定められた屋内消火栓設備の設置を要する建物規模(延べ面積)として、正しいものはどれか。", "choices": [{"label": "1", "text": "600 m2以上"}, {"label": "2", "text": "1,000 m2以上"}, {"label": "3", "text": "2,000 m2以上"}, {"label": "4", "text": "3,000 m2以上"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["3,000 m2以上"], "answerHints": [["3,000 m2以上"]], "mnemonic": "事務所の屋内消火栓は延べ1,000m2以上。耐火構造＋内装制限で3倍の3,000m2以上。", "block": 6, "group": 2}, {"id": "H30_kouki_52", "source": "H30後 No.52", "category": "法規", "type": "single", "question": "廃棄物の処分に関する文中、 内に当てはまる用語の組合せとして、「廃棄物の処理及び清掃に関する法律」上、正しいものはどれか。\n建設工事に伴って伐採した樹木を A として処分する。建設工事に使用する資材の梱包に使用された段ボールを B として処分する。\n---(A)-------(B)", "choices": [{"label": "1", "text": "産業廃棄物---- 産業廃棄物"}, {"label": "2", "text": "一般廃棄物---- 一般廃棄物"}, {"label": "3", "text": "一般廃棄物---- 産業廃棄物"}, {"label": "4", "text": "産業廃棄物---- 一般廃棄物"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["産業廃棄物---- 産業廃棄物"], "answerHints": [["産業廃棄物"]], "mnemonic": "建設工事で出る伐採木（木くず）も梱包の段ボール（紙くず）も産業廃棄物。", "block": 6, "group": 2}, {"id": "R01_zenki_45", "source": "R1前 No.45", "category": "法規", "type": "single", "question": "建築物の階数、高さについての記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建築物の地階部分は、その部分の用途と面積にかかわらず建築物の階数に算入する。"}, {"label": "2", "text": "建築物のエレベーター機械室、装飾塔その他これらに類する屋上部分は、その部分の面積の合計が所定の条件を満たせば、建築物の階数に算入しない。"}, {"label": "3", "text": "建築物の階段室、エレベーター機械室その他これらに類する屋上部分は、その部分の面積の合計が所定の条件を満たせば、建築物の高さに算入しない場合がある。"}, {"label": "4", "text": "屋根の棟飾りは、建築物の高さに算入しない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建築物の地階部分は、その部分の用途と面積にかかわらず建築物の階数に算入する。"], "answerHints": [["用途と面積にかかわらず"]], "mnemonic": "正しくは：地階の機械室・倉庫等で水平投影面積が建築面積の1/8以下なら、階数に算入しない。", "block": 6, "group": 2}, {"id": "R01_zenki_48", "source": "R1前 No.48", "category": "法規", "type": "single", "question": "建設業の許可に関する記述のうち、「建設業法」上、正しいものはどれか。ただし、軽微な建設工事のみを請け負うことを営業とする者は除く。", "choices": [{"label": "1", "text": "「国土交通大臣の許可」は、「都道府県知事の許可」よりも、受注可能な請負金額が大きい。"}, {"label": "2", "text": "2以上の都道府県の区域内に営業所を設ける場合は、営業所を設けるそれぞれの「都道府県知事の許可」が必要である。"}, {"label": "3", "text": "「国土交通大臣の許可」は、「都道府県知事の許可」よりも、下請契約できる代金額の総額が大きい。"}, {"label": "4", "text": "「国土交通大臣の許可」と「都道府県知事の許可」では、どちらも工事可能な区域に制限はない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["「国土交通大臣の許可」と「都道府県知事の許可」では、どちらも工事可能な区域に制限はない。"], "answerHints": [["工事可能な区域に制限はない"]], "mnemonic": "大臣許可と知事許可の違いは営業所の所在のみ。施工区域・請負金額・下請代金額に差はない。", "block": 6, "group": 2}, {"id": "R01_zenki_52", "source": "R1前 No.52", "category": "法規", "type": "single", "question": "産業廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業活動に伴って生じた産業廃棄物は、事業者が自ら処理しなければならない。"}, {"label": "2", "text": "産業廃棄物の運搬、処分に係る委託契約書は、契約の終了の日から年間保管する必要がある。"}, {"label": "3", "text": "事業者は、その事業活動に伴って生じた産業廃棄物の運搬先が2以上ある場合、運搬先ごとに産業廃棄物管理票を交付しなければならない。"}, {"label": "4", "text": "事務所ビルの改築に伴って生じた衛生陶器の破片は、産業廃棄物として処分する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["産業廃棄物の運搬、処分に係る委託契約書は、契約の終了の日から年間保管する必要がある。"], "answerHints": [["年間保管"]], "mnemonic": "正しくは：委託契約書は、契約の終了の日から5年間保存する。", "block": 6, "group": 2}, {"id": "R01_kouki_45", "source": "R1後 No.45", "category": "法規", "type": "single", "question": "建築の用語に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建築物とは、土地に定着する工作物のうち屋根及び柱若しくは壁を有するものなどをいい、建築設備は含まない。"}, {"label": "2", "text": "継続的に使用される会議室は、居室である。"}, {"label": "3", "text": "主要構造部とは、壁、柱、床、はり、屋根又は階段をいい、構造耐力上主要な部分とは必ずしも一致しない。"}, {"label": "4", "text": "アルミニウムとガラスはどちらも不燃材料である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建築物とは、土地に定着する工作物のうち屋根及び柱若しくは壁を有するものなどをいい、建築設備は含まない。"], "answerHints": [["建築設備は含まない"]], "mnemonic": "正しくは：建築物には建築設備を含む。", "block": 6, "group": 2}, {"id": "R01_kouki_48", "source": "R1後 No.48", "category": "法規", "type": "single", "question": "建設業を営もうとする者のうち、「建設業法」上、必要となる建設業の許可が国土交通大臣の許可に限られるものはどれか。ただし、軽微な建設工事のみを請け負うことを営業とする者は除く。", "choices": [{"label": "1", "text": "2以上の都道府県の区域内に営業所を設けて営業しようとする者"}, {"label": "2", "text": "2以上の都道府県の区域にまたがる建設工事を施工しようとする者"}, {"label": "3", "text": "請負金額が500万円以上の管工事を発注者から直接請け負い施工する者"}, {"label": "4", "text": "4,500万円以上の下請契約を締結して管工事を施工しようとする者"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["国土交通大臣の許可に限られるもの"], "answerTexts": ["2以上の都道府県の区域内に営業所を設けて営業しようとする者"], "answerHints": [["2以上の都道府県の区域内に営業所"]], "mnemonic": "2以上の都道府県に営業所を設ける場合は大臣許可。工事の施工区域や金額は関係しない。", "block": 6, "group": 2}, {"id": "R01_kouki_51", "source": "R1後 No.51", "category": "法規", "type": "single", "question": "冷媒としてフロン類が充塡されている以下の機器のうち、「フロン類の使用の合理化及び管理の適正化に関する法律」の対象でないものはどれか。", "choices": [{"label": "1", "text": "業務用のエアコンディショナー"}, {"label": "2", "text": "家庭用のエアコンディショナー"}, {"label": "3", "text": "業務用の冷蔵庫"}, {"label": "4", "text": "冷蔵の機能を有する自動販売機"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["の対象でないもの"], "answerTexts": ["家庭用のエアコンディショナー"], "answerHints": [["家庭用"]], "mnemonic": "フロン排出抑制法の対象は業務用（第一種特定製品）。家庭用エアコンは家電リサイクル法の対象。", "block": 6, "group": 2}, {"id": "R02_kouki_01", "source": "R2後 No.1", "category": "一般基礎", "type": "single", "question": "公共用水域の水質汚濁に係る環境基準において、「生活環境の保全に関する環境基準」に基準値が定められていないものはどれか。", "choices": [{"label": "1", "text": "塩化物イオン濃度"}, {"label": "2", "text": "水素イオン濃度(pH)"}, {"label": "3", "text": "生物化学的酸素要求量(BOD)"}, {"label": "4", "text": "浮遊物質量(SS)"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["塩化物イオン濃度"], "answerHints": [["塩化物イオン濃度"]], "mnemonic": "生活環境項目はpH・BOD（COD）・SS・DO・大腸菌数等。塩化物イオンは基準値がない。", "block": 7, "group": 3}, {"id": "R02_kouki_04", "source": "R2後 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "熱容量の大きい物質は、温まりにくく冷えにくい。"}, {"label": "2", "text": "熱伝導とは、物質の内部において、温度の高い方から低い方に熱エネルギーが移動する現象をいう。"}, {"label": "3", "text": "熱放射による熱エネルギーの移動には、熱エネルギーを伝達する媒体が必要である。"}, {"label": "4", "text": "固体、液体及び気体のような状態を相といい、相が変化することを相変化という。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["熱放射による熱エネルギーの移動には、熱エネルギーを伝達する媒体が必要である。"], "answerHints": [["媒体が必要である"]], "mnemonic": "正しくは：熱放射は媒体（物質）を必要とせず、真空中でも熱エネルギーが移動する。", "block": 7, "group": 3}, {"id": "R03_zenki_01", "source": "R3前 No.1", "category": "一般基礎", "type": "single", "question": "次の指標のうち、室内空気環境と関係のないものはどれか。", "choices": [{"label": "1", "text": "浮遊物質量(SS)"}, {"label": "2", "text": "予想平均申告(PMV)"}, {"label": "3", "text": "揮発性有機化合物(VOCs)濃度"}, {"label": "4", "text": "気流"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["浮遊物質量(SS)"], "answerHints": [["浮遊物質量(SS)"]], "mnemonic": "SSは水質の指標。PMV・VOCs・気流は室内空気環境の指標。", "block": 7, "group": 3}, {"id": "R03_zenki_04", "source": "R3前 No.4", "category": "一般基礎", "type": "single", "question": "伝熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "固体壁における熱通過とは、固体壁を挟んだ流体の間の伝熱をいう。"}, {"label": "2", "text": "固体壁における熱伝達とは、固体壁表面とこれに接する流体との間で熱が移動する現象をいう。"}, {"label": "3", "text": "気体は、一般的に、液体や固体と比較して熱伝導率が大きい。"}, {"label": "4", "text": "自然対流とは、流体内のある部分が温められ上昇し、周囲の低温の流体がこれに代わって流入する熱移動現象等をいう。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["気体は、一般的に、液体や固体と比較して熱伝導率が大きい。"], "answerHints": [["熱伝導率が大きい"]], "mnemonic": "正しくは：気体の熱伝導率は液体や固体より小さい。", "block": 7, "group": 3}, {"id": "R03_kouki_01", "source": "R3後 No.1", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "湿り空気を加熱すると、その絶対湿度は低下する。"}, {"label": "2", "text": "不飽和湿り空気の湿球温度は、その乾球温度より低くなる。"}, {"label": "3", "text": "露点温度とは、その空気と同じ絶対湿度をもつ飽和湿り空気の温度をいう。"}, {"label": "4", "text": "相対湿度とは、ある湿り空気の水蒸気分圧と、その温度と同じ温度の飽和湿り空気の水蒸気分圧との比をいう。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["湿り空気を加熱すると、その絶対湿度は低下する。"], "answerHints": [["絶対湿度は低下する"]], "mnemonic": "正しくは：湿り空気を加熱しても絶対湿度は変化しない（相対湿度が低下する）。", "block": 7, "group": 3}, {"id": "R03_kouki_04", "source": "R3後 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "体積を一定に保ったまま気体を冷却すると、圧力は低くなる。"}, {"label": "2", "text": "気体では、定容比熱より定圧比熱のほうが大きい。"}, {"label": "3", "text": "潜熱とは、物体の相変化を伴わず、温度変化のみに費やされる熱をいう。"}, {"label": "4", "text": "熱は、低温の物体から高温の物体へ自然に移ることはない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["潜熱とは、物体の相変化を伴わず、温度変化のみに費やされる熱をいう。"], "answerHints": [["相変化を伴わず、温度変化のみ"]], "mnemonic": "正しくは：潜熱は温度変化を伴わず相変化のみに費やされる熱（設問は顕熱の説明）。", "block": 7, "group": 3}, {"id": "R02_kouki_07", "source": "R2後 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "変風量単一ダクト方式は、VAVユニットの発生騒音に注意が必要である。"}, {"label": "2", "text": "ファンコイルユニット・ダクト併用方式を事務所ビルに採用する場合、一般的に、ファンコイルユニットで外気負荷を含む熱負荷全体を処理する。"}, {"label": "3", "text": "定風量単一ダクト方式は、変風量単一ダクト方式に比べて、室内の良好な気流分布を確保しやすい。"}, {"label": "4", "text": "変風量単一ダクト方式は、給気温度を一定にして各室の送風量を変化させることで室温を制御する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ファンコイルユニット・ダクト併用方式を事務所ビルに採用する場合、一般的に、ファンコイルユニットで外気負荷を含む熱負荷全体を処理する。"], "answerHints": [["外気負荷を含む熱負荷全体"]], "mnemonic": "正しくは：外気負荷は空調機（ダクト側）で処理し、ファンコイルユニットは主に室内負荷を処理する。", "block": 7, "group": 3}, {"id": "R02_kouki_11", "source": "R2後 No.11", "category": "空調・衛生", "type": "single", "question": "コールドドラフトの防止に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "暖房負荷となる外壁面からの熱損失をできるだけ減少させる。"}, {"label": "2", "text": "自然対流形の放熱器では、放熱器をできるだけ外壁の窓下全体に設置する。"}, {"label": "3", "text": "屋外から侵入する隙間風を減らすため、外気に面する建具廻りの気密性を高める。"}, {"label": "4", "text": "強制対流形の放熱器では、放熱器を暖房負荷の小さい内壁側に設置する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["強制対流形の放熱器では、放熱器を暖房負荷の小さい内壁側に設置する。"], "answerHints": [["暖房負荷の小さい内壁側"]], "mnemonic": "正しくは：放熱器は窓下など外壁側の暖房負荷の大きい位置に設置する。", "block": 7, "group": 3}, {"id": "R02_kouki_15", "source": "R2後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道における水道水の消毒に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "浄水施設には、必ず消毒設備を設けなければならない。"}, {"label": "2", "text": "水道水の消毒薬には、液化塩素、次亜塩素酸ナトリウム等が使用される。"}, {"label": "3", "text": "遊離残留塩素より結合残留塩素の方が、殺菌力が高い。"}, {"label": "4", "text": "一般細菌には、塩素消毒が有効である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["遊離残留塩素より結合残留塩素の方が、殺菌力が高い。"], "answerHints": [["結合残留塩素の方が"]], "mnemonic": "正しくは：結合残留塩素より遊離残留塩素の方が殺菌力が高い。", "block": 7, "group": 3}, {"id": "R02_kouki_18", "source": "R2後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "シャワー用水栓は、熱傷の危険を避けるため、一般的に、サーモスタット湯水混合水栓を使用する。"}, {"label": "2", "text": "給湯循環ポンプは、給湯管からの放熱により給湯温度が低下することを防止するために設ける。"}, {"label": "3", "text": "給湯配管に、水道用硬質塩化ビニルライニング鋼管を使用する。"}, {"label": "4", "text": "中央給湯方式の膨張タンクは、装置内の圧力が水の膨張により異常に上昇しないように設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給湯配管に、水道用硬質塩化ビニルライニング鋼管を使用する。"], "answerHints": [["水道用硬質塩化ビニルライニング鋼管"]], "mnemonic": "正しくは：給湯配管には水道用耐熱性硬質塩化ビニルライニング鋼管等を使用する。", "block": 7, "group": 3}, {"id": "R02_kouki_22", "source": "R2後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液化天然ガスは、メタンを主成分とした天然ガスを冷却して液化したものである。"}, {"label": "2", "text": "都市ガスのガス漏れ警報器は、天井付近に排気口がある室内では、燃焼器等から最も近い排気口付近に設置する。"}, {"label": "3", "text": "液化石油ガス用のガス漏れ警報器の有効期間は、8年である。"}, {"label": "4", "text": "半密閉式ガス機器は、燃焼用の空気を屋内から取り入れ、燃焼ガスを屋外に排出するものである。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化石油ガス用のガス漏れ警報器の有効期間は、8年である。"], "answerHints": [["8年"]], "mnemonic": "正しくは：液化石油ガス（LPG）用ガス漏れ警報器の有効期間は5年。", "block": 7, "group": 3}, {"id": "R03_zenki_09", "source": "R3前 No.9", "category": "空調・衛生", "type": "single", "question": "熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "構造体の熱通過率の値が小さいほど、通過熱負荷は小さくなる。"}, {"label": "2", "text": "冷房負荷計算では、OA機器から発生する顕熱及び潜熱を考慮する必要がある。"}, {"label": "3", "text": "二重サッシ内にブラインドを設置した場合は、室内に設置した場合より日射負荷は小さくなる。"}, {"label": "4", "text": "冷房負荷計算では、ダクト通過熱損失と送風機による熱負荷を考慮する必要がある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["冷房負荷計算では、OA機器から発生する顕熱及び潜熱を考慮する必要がある。"], "answerHints": [["顕熱及び潜熱"]], "mnemonic": "正しくは：OA機器からの発熱は顕熱のみを考慮する。", "block": 7, "group": 3}, {"id": "R03_zenki_12", "source": "R3前 No.12", "category": "空調・衛生", "type": "single", "question": "吸収冷温水機の特徴に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "木質バイオマス燃料の木質ペレットを燃料として使用する機種もある。"}, {"label": "2", "text": "立ち上がり時間は、一般的に、圧縮式冷凍機に比べて短い。"}, {"label": "3", "text": "運転時、冷水と温水を同時に取り出すことができる機種もある。"}, {"label": "4", "text": "二重効用吸収冷温水機は、一般的に、取扱いにボイラー技士を必要としない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["立ち上がり時間は、一般的に、圧縮式冷凍機に比べて短い。"], "answerHints": [["比べて短い"]], "mnemonic": "正しくは：吸収冷温水機の立ち上がり時間は、圧縮式冷凍機に比べて長い。", "block": 7, "group": 3}, {"id": "R03_zenki_15", "source": "R3前 No.15", "category": "空調・衛生", "type": "single", "question": "給水装置(最終の止水機構の流出側に設置されている給水用具を除く。)の耐圧性能試験の「静水圧」と「保持時間」の組合せのうち、適当なものはどれか。", "choices": [{"label": "1", "text": "1.75MPa ――― 30秒間"}, {"label": "2", "text": "1.75MPa ――― 1分間"}, {"label": "3", "text": "0.75MPa ――― 1分間"}, {"label": "4", "text": "0.75MPa ――― 5分間"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["1.75MPa ――― 1分間"], "answerHints": [["1.75MPa", "1分間"]], "mnemonic": "給水装置の耐圧性能試験は静水圧1.75MPaを1分間保持。", "block": 7, "group": 3}, {"id": "R03_zenki_18", "source": "R3前 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給湯管に使用される架橋ポリエチレン管の線膨張係数は、銅管の線膨張係数に比べて小さい。"}, {"label": "2", "text": "湯沸室の給茶用の給湯には、一般的に、局所式給湯設備が採用される。"}, {"label": "3", "text": "ホテル、病院等の給湯使用量の大きな建物には、中央式給湯設備が採用されることが多い。"}, {"label": "4", "text": "給湯配管で上向き供給方式の場合、給湯管は先上がり、返湯管は先下がりとする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給湯管に使用される架橋ポリエチレン管の線膨張係数は、銅管の線膨張係数に比べて小さい。"], "answerHints": [["比べて小さい"]], "mnemonic": "正しくは：架橋ポリエチレン管の線膨張係数は銅管より大きい。", "block": 7, "group": 3}, {"id": "R03_zenki_21", "source": "R1後 No.21 / R3前 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備において、ポンプの仕様の決定に関係のないものはどれか。", "choices": [{"label": "1", "text": "実揚程"}, {"label": "2", "text": "消防用ホースの摩擦損失水頭"}, {"label": "3", "text": "屋内消火栓の同時開口数"}, {"label": "4", "text": "水源の容量"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["水源の容量"], "answerHints": [["水源の容量"]], "mnemonic": "ポンプ仕様は吐出量（同時開口数）と全揚程（実揚程・ホース・配管の摩擦損失）で決まる。水源容量は無関係。", "block": 7, "group": 3}, {"id": "R03_kouki_07", "source": "R3後 No.7", "category": "空調・衛生", "type": "single", "question": "変風量単一ダクト方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "負荷変動が異なる室が複数ある場合には、代表室に設置したサーモスタットにより給気温度の制御を行う。"}, {"label": "2", "text": "送風量の制御は、一般的に、インバーターにより空気調和機の送風機を回転数制御する。"}, {"label": "3", "text": "定風量単一ダクト方式に比べ、間仕切り変更や負荷の変動にも容易に対応しやすい。"}, {"label": "4", "text": "使用しない室や使用しない時間帯に対応するために、VAVユニットは全閉機能付きのものを使用する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["負荷変動が異なる室が複数ある場合には、代表室に設置したサーモスタットにより給気温度の制御を行う。"], "answerHints": [["代表室に設置したサーモスタット"]], "mnemonic": "正しくは：負荷変動の異なる室は、各室のサーモスタットでVAVユニットの風量を個別に制御する。", "block": 7, "group": 3}, {"id": "R03_kouki_11", "source": "R3後 No.11", "category": "空調・衛生", "type": "single", "question": "温水暖房における膨張タンクに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "開放式膨張タンクの容量は、装置全水量の膨張量から求める。"}, {"label": "2", "text": "開放式膨張タンクにボイラーの逃がし管を接続する場合は、メンテナンス用バルブを設ける。"}, {"label": "3", "text": "密閉式膨張タンクは、一般的に、ダイヤフラム式やプラダー式が用いられる。"}, {"label": "4", "text": "密閉式膨張タンク内の最低圧力は、装置内が大気圧以下とならないように設定する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["開放式膨張タンクにボイラーの逃がし管を接続する場合は、メンテナンス用バルブを設ける。"], "answerHints": [["メンテナンス用バルブを設ける"]], "mnemonic": "正しくは：ボイラーの逃がし管には弁を設けてはならない。", "block": 7, "group": 3}, {"id": "R03_kouki_14", "source": "R3後 No.14", "category": "空調・衛生", "type": "single", "question": "機械換気を行う室のうち、第三種換気方式を用いることが適当でないものはどれか。", "choices": [{"label": "1", "text": "シャワー室"}, {"label": "2", "text": "書庫・倉庫"}, {"label": "3", "text": "エレベーター機械室"}, {"label": "4", "text": "ボイラー室"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボイラー室"], "answerHints": [["ボイラー室"]], "mnemonic": "ボイラー室は燃焼用空気の供給が必要なので第一種（給気機あり）。第三種（排気のみ・負圧）は不適。", "block": 7, "group": 3}, {"id": "R03_kouki_18", "source": "R3後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "潜熱回収型給湯器は、燃焼排ガス中の水蒸気の凝縮潜熱を回収することで、熱効率を向上させている。"}, {"label": "2", "text": "先止め式ガス瞬間湯沸器の能力は、それに接続する器具の必要給湯量を基準として算定する。"}, {"label": "3", "text": "Q機能付き給湯器は、出湯温度を短い時間で設定温度にする構造のものである。"}, {"label": "4", "text": "シャワーに用いるガス瞬間湯沸器は、湯沸器の湯栓で出湯を操作する元止め式とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["シャワーに用いるガス瞬間湯沸器は、湯沸器の湯栓で出湯を操作する元止め式とする。"], "answerHints": [["元止め式"]], "mnemonic": "正しくは：シャワー用のガス瞬間湯沸器は、器具側の水栓で操作する先止め式とする。", "block": 7, "group": 3}, {"id": "R03_kouki_21", "source": "R3後 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓ポンプ回りの配管に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吸水管には、ろ過装置(フート弁に附属するものを含む。)を設ける。"}, {"label": "2", "text": "水源の水位がポンプより高い位置にある場合、吸水管には逆止め弁を設ける。"}, {"label": "3", "text": "吸水管は、ポンプごとに専用とする。"}, {"label": "4", "text": "締切運転時における水温上昇防止のため、逃し配管を設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水源の水位がポンプより高い位置にある場合、吸水管には逆止め弁を設ける。"], "answerHints": [["逆止め弁"]], "mnemonic": "正しくは：水源の水位がポンプより高い場合、吸水管には止水弁（仕切弁）を設ける。", "block": 7, "group": 3}, {"id": "R02_kouki_24", "source": "R2後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "保温材に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "グラスウール保温材は、ポリスチレンフォーム保温材に比べて吸水性や透湿性が小さい。"}, {"label": "2", "text": "ポリスチレンフォーム保温材は、主に保冷用として使用される。"}, {"label": "3", "text": "人造鉱物繊維保温材には、保温筒、保温板、保温帯等の形状のものがある。"}, {"label": "4", "text": "ロックウール保温材は、耐火性に優れ、防火区画の貫通部等に使用される。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["グラスウール保温材は、ポリスチレンフォーム保温材に比べて吸水性や透湿性が小さい。"], "answerHints": [["吸水性や透湿性が小さい"]], "mnemonic": "正しくは：グラスウール保温材は、ポリスチレンフォーム保温材に比べて吸水性・透湿性が大きい。", "block": 7, "group": 3}, {"id": "R02_kouki_27", "source": "R2後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "防火ダンパに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "防火ダンパのケーシング及び可動羽根は、厚さ1.2mm以上の鋼板製とする。"}, {"label": "2", "text": "防火ダンパには、温度ヒューズ型ダンパ、熱感知器連動型ダンパ等がある。"}, {"label": "3", "text": "空気調和設備のダクトに設置する防火ダンパの温度ヒューズは、公称作動温度72°Cのものとする。"}, {"label": "4", "text": "厨房排気のダクトに設置する防火ダンパの温度ヒューズは、公称作動温度120°Cのものとする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火ダンパのケーシング及び可動羽根は、厚さ1.2mm以上の鋼板製とする。"], "answerHints": [["1.2mm以上"]], "mnemonic": "正しくは：防火ダンパーのケーシングは厚さ1.5mm以上の鋼板製。", "block": 7, "group": 3}, {"id": "R03_zenki_26", "source": "R3前 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水・通気用耐火二層管は、防火区画貫通部1時間遮炎性能の規定に適合する。"}, {"label": "2", "text": "水道用硬質ポリ塩化ビニル管の種類には、VPとHIVP(耐衝撃性)がある。"}, {"label": "3", "text": "水道用ポリエチレン二層管の種類には、1種、2種、3種がある。"}, {"label": "4", "text": "排水用リサイクル硬質ポリ塩化ビニル管(REP-VU)は、屋内排水用の塩化ビニル管である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水用リサイクル硬質ポリ塩化ビニル管(REP-VU)は、屋内排水用の塩化ビニル管である。"], "answerHints": [["屋内排水用"]], "mnemonic": "正しくは：REP-VUは、一般的に、屋外排水配管に用いられる。", "block": 7, "group": 3}, {"id": "R03_kouki_25", "source": "R3後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "送風機及びポンプに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "斜流送風機は、ケーシングが軸流式の形状のものと、遠心式の形状のものがある。"}, {"label": "2", "text": "遠心送風機のうち、多翼送風機は、羽根車の出口の羽根形状が回転方向に対して前に湾曲している。"}, {"label": "3", "text": "水中モーターポンプは、耐水構造の電動機を水中に潜没させて使用できるポンプである。"}, {"label": "4", "text": "給水ポンプユニットの末端圧力一定方式は、ポンプ吐出側の圧力を検知し水量の増減に関係なく圧力が一定になるように制御する方式である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給水ポンプユニットの末端圧力一定方式は、ポンプ吐出側の圧力を検知し水量の増減に関係なく圧力が一定になるように制御する方式である。"], "answerHints": [["水量の増減に関係なく"]], "mnemonic": "正しくは：末端圧力一定方式は、水量の増減に応じて吐出圧力を変え末端の圧力を一定にする（設問は吐出圧力一定方式）。", "block": 7, "group": 3}, {"id": "R02_kouki_30", "source": "R2後 No.30", "category": "施工管理法", "type": "single", "question": "設備工事における工程管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "設備工事の総合工程表は、建築工事の工程との調整を図るため、建築工事の工程表を十分に検討した上で作成する。"}, {"label": "2", "text": "機器類の搬入時期は、搬入口、搬入経路等の工事の工程や機器類搬入後の関係工事の工程を考慮して決定する。"}, {"label": "3", "text": "工程計画を立案する際は、工事着工前の官公署への届出や工事施工完了後の後片付けも工程に組み入れる。"}, {"label": "4", "text": "試運転調整は、給排水本管接続工事や受電の前に完了できるように、開始時期を決定する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["試運転調整は、給排水本管接続工事や受電の前に完了できるように、開始時期を決定する。"], "answerHints": [["受電の前に完了"]], "mnemonic": "正しくは：試運転調整は給排水本管接続や受電の後に行うので、それらの時期を考慮して開始時期を決める。", "block": 7, "group": 3}, {"id": "R02_kouki_34", "source": "R2後 No.34", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "高置タンクの架台の高さが2mを超える場合、架台の昇降タラップには転落防止用の防護柵を設置する。"}, {"label": "2", "text": "飲料用受水タンクの上部には、排水再利用設備や空気調和設備の配管等、飲料水以外の配管は通さないようにする。"}, {"label": "3", "text": "空調用遠心ポンプを設置する場合、カップリング外周の段違いや面間寸法の誤差がないことを確認する。"}, {"label": "4", "text": "ファンコイルユニットを天井内に設置する場合の設置高さは、ドレンアップポンプを設けない場合、ドレン管の勾配が1/250程度とれる高さとする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ファンコイルユニットを天井内に設置する場合の設置高さは、ドレンアップポンプを設けない場合、ドレン管の勾配が1/250程度とれる高さとする。"], "answerHints": [["1/250程度"]], "mnemonic": "正しくは：ファンコイルユニットのドレン管の勾配は1/100程度以上とれる高さとする。", "block": 7, "group": 3}, {"id": "R02_kouki_37", "source": "R2後 No.37", "category": "施工管理法", "type": "single", "question": "配管及び配管付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "FRP製受水タンクに給水管を接続する場合、変位吸収管継手を用いて接続する。"}, {"label": "2", "text": "ねじ込み式鋼管製管継手(白)は、水道用硬質塩化ビニルライニング鋼管の接合に使用される。"}, {"label": "3", "text": "単式伸縮管継手を取り付ける場合、伸縮管継手の本体は固定しない。"}, {"label": "4", "text": "冷媒用フレア及びろう付け管継手は、冷媒用の銅管の接合に使用される。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ねじ込み式鋼管製管継手(白)は、水道用硬質塩化ビニルライニング鋼管の接合に使用される。"], "answerHints": [["ねじ込み式鋼管製管継手(白)"]], "mnemonic": "正しくは：硬質塩化ビニルライニング鋼管のねじ接合には管端防食管継手を使用する。", "block": 7, "group": 3}, {"id": "R02_kouki_40", "source": "R2後 No.40", "category": "施工管理法", "type": "single", "question": "塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "塗装場所の気温が5°C以下の場合、原則として、塗装は行わない。"}, {"label": "2", "text": "下塗り塗料としては、一般的に、さび止めペイントが使用される。"}, {"label": "3", "text": "塗料の調合は、原則として、工事現場で行う。"}, {"label": "4", "text": "製作工場でさび止め塗装された機材の現場でのさび止め補修は、塗装のはく離した部分のみとしてよい。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["塗料の調合は、原則として、工事現場で行う。"], "answerHints": [["工事現場で行う"]], "mnemonic": "正しくは：塗料の調合は、原則として製造所で行う（調合済み塗料を使用する）。", "block": 7, "group": 3}, {"id": "R03_zenki_32", "source": "R1後 No.33 / R3前 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ツールボックスミーティングは、作業開始前だけでなく、必要に応じて、昼食後の作業再開時や作業切替え時に行われることもある。"}, {"label": "2", "text": "ツールボックスミーティングでは、当該作業における安全等について、短時間の話し合いが行われる。"}, {"label": "3", "text": "既設汚水ピット内で作業を行う際は、酸素濃度のほか、硫化水素濃度も確認する。"}, {"label": "4", "text": "既設汚水ピット内で作業を行う際は、酸素濃度が15%以上であることを確認する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["既設汚水ピット内で作業を行う際は、酸素濃度が15%以上であることを確認する。"], "answerHints": [["15%以上"]], "mnemonic": "正しくは：酸素濃度は18%以上であることを確認する。", "block": 7, "group": 3}, {"id": "R03_zenki_35", "source": "R3前 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "保温するダクトが防火区画を貫通する場合、貫通部の保温材はロックウール保温材とする。"}, {"label": "2", "text": "送風機の接続ダクトに取り付ける風量測定口は、送風機の吐出し口の直近に取り付ける。"}, {"label": "3", "text": "フレキシブルダクトは、吹出口ボックス及び吸込口ボックスの接続用に使用してもよい。"}, {"label": "4", "text": "共板フランジ工法ダクトの施工において、クリップ等のフランジ押え金具は再使用しない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送風機の接続ダクトに取り付ける風量測定口は、送風機の吐出し口の直近に取り付ける。"], "answerHints": [["吐出し口の直近"]], "mnemonic": "正しくは：風量測定口は気流が安定した位置に設け、送風機の吐出し口直近は避ける。", "block": 7, "group": 3}, {"id": "R03_kouki_31", "source": "R3後 No.31", "category": "施工管理法", "type": "single", "question": "施工の品質を確認するための試験又は検査に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "高置タンク以降の給水配管の水圧試験において、静水頭に相当する圧力の2倍の圧力が0.75MPa未満の場合、0.75MPaの圧力で試験を行う。"}, {"label": "2", "text": "準耐火構造の防火区画を水道用硬質塩化ビニルライニング鋼管の給水管が貫通する箇所において、貫通部の隙間が難燃材料で埋め戻されていることを確認する。"}, {"label": "3", "text": "洗面器の取付けにおいて、がたつきがないこと、及び、附属の給排水金具等から漏水がないことを確認する。"}, {"label": "4", "text": "排水用水中モーターポンプの試験において、レベルスイッチからの信号による発停を確認する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["準耐火構造の防火区画を水道用硬質塩化ビニルライニング鋼管の給水管が貫通する箇所において、貫通部の隙間が難燃材料で埋め戻されていることを確認する。"], "answerHints": [["難燃材料"]], "mnemonic": "正しくは：防火区画貫通部の隙間はモルタルその他の不燃材料で埋め戻す。", "block": 7, "group": 3}, {"id": "R03_kouki_34", "source": "R3後 No.34", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "汚水槽の通気管は、その他の排水系統の通気立て管を介して大気に開放する。"}, {"label": "2", "text": "給水管の分岐は、チーズによる枝分かれ分岐とし、クロス形の継手は使用しない。"}, {"label": "3", "text": "飲料用の受水タンクのオーバーフロー管は、排水口空間を設け、間接排水とする。"}, {"label": "4", "text": "給水横走り管から上方へ給水する場合は、配管の上部から枝管を取り出す。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["汚水槽の通気管は、その他の排水系統の通気立て管を介して大気に開放する。"], "answerHints": [["その他の排水系統の通気立て管を介して"]], "mnemonic": "正しくは：汚水槽の通気管は他の通気系統に接続せず、単独で大気に開放する。", "block": 7, "group": 3}, {"id": "R03_zenki_49", "source": "R3前 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程表に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ネットワーク工程表は、各作業の現時点における進行状態が達成度により把握できる。"}, {"label": "2", "text": "バーチャート工程表は、ネットワーク工程表に比べて、各作業の遅れへの対策が立てにくい。"}, {"label": "3", "text": "毎日の予定出来高が一定の場合、バーチャート工程表上の予定進度曲線はS字形となる。"}, {"label": "4", "text": "ガントチャート工程表は、各作業の変更が他の作業に及ぼす影響が不明という欠点がある。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ネットワーク工程表は、各作業の現時点における進行状態が達成度により把握できる。", "毎日の予定出来高が一定の場合、バーチャート工程表上の予定進度曲線はS字形となる。"], "answerHints": [["ネットワーク工程表"], ["S字形"]], "mnemonic": "達成度で現時点の進行状態が把握できるのはガントチャート。毎日の出来高が一定なら予定進度曲線は直線になる。", "block": 7, "group": 3}, {"id": "R03_zenki_52", "source": "R3前 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "厨房排気ダクトの防火ダンパーでは、温度ヒューズの作動温度は72°Cとする。"}, {"label": "2", "text": "ダクトからの振動伝播を防ぐ必要がある場合は、ダクトの吊りは防振吊りとする。"}, {"label": "3", "text": "長方形ダクトの断面のアスペクト比(長辺と短辺の比)は、原則として、4以下とする。"}, {"label": "4", "text": "アングルフランジ工法ダクトのフランジは、ダクト本体を成型加工したものである。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["厨房排気ダクトの防火ダンパーでは、温度ヒューズの作動温度は72°Cとする。", "アングルフランジ工法ダクトのフランジは、ダクト本体を成型加工したものである。"], "answerHints": [["72°C"], ["ダクト本体を成型加工"]], "mnemonic": "厨房排気の防火ダンパーの温度ヒューズは120℃。ダクト本体を成型加工してフランジにするのは共板フランジ工法（アングルフランジは山形鋼）。", "block": 7, "group": 3}, {"id": "R03_kouki_51", "source": "R3後 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "飲料用の冷水器の排水管は、その他の排水管に直接連結しない。"}, {"label": "2", "text": "飲料用の受水タンクに給水管を接続する場合は、フレキシブルジョイントを介して接続する。"}, {"label": "3", "text": "ループ通気管の排水横枝管からの取出しの向きは、水平又は水平から45°以内とする。"}, {"label": "4", "text": "ループ通気管の排水横枝管からの取出し位置は、排水横枝管に最上流の器具排水管が接続された箇所の上流側とする。"}], "answer": ["3", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ループ通気管の排水横枝管からの取出しの向きは、水平又は水平から45°以内とする。", "ループ通気管の排水横枝管からの取出し位置は、排水横枝管に最上流の器具排水管が接続された箇所の上流側とする。"], "answerHints": [["水平又は水平から45°以内"], ["上流側"]], "mnemonic": "ループ通気管は排水横枝管の垂直上方〜45°以内で、最上流の器具排水管接続箇所の下流側から取り出す。", "block": 7, "group": 3}, {"id": "R02_kouki_44", "source": "R2後 No.44", "category": "法規", "type": "single", "question": "労働契約の締結に際し、「労働基準法」上、使用者が労働者に対して明示しなければならない労働条件として、定められていないものはどれか。", "choices": [{"label": "1", "text": "就業の場所及び従事すべき業務に関する事項"}, {"label": "2", "text": "所定労働時間を超える労働の有無に関する事項"}, {"label": "3", "text": "賃金の決定及び支払の時期に関する事項"}, {"label": "4", "text": "福利厚生施設の利用に関する事項"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["福利厚生施設の利用に関する事項"], "answerHints": [["福利厚生施設の利用に関する事項"]], "mnemonic": "明示義務は就業場所・業務、労働時間・時間外労働の有無、賃金の決定・支払時期等。福利厚生施設の利用は該当しない。", "block": 7, "group": 3}, {"id": "R02_kouki_47", "source": "R2後 No.47", "category": "法規", "type": "single", "question": "建設業の許可に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "管工事業の許可を受けた者が管工事を請け負う場合においては、当該管工事に附帯する電気工事を請け負うことができる。"}, {"label": "2", "text": "2級管工事施工管理技士は、管工事業に係る一般建設業の許可を受ける建設業者が営業所ごとに専任で置く技術者としての要件を満たしている。"}, {"label": "3", "text": "建設工事を下請負人としてのみ請け負い施工する者においても、請負金額が500万円以上の管工事を請け負う場合は、当該建設業の許可を受けなくてはならない。"}, {"label": "4", "text": "建設業の許可は、10年ごとにその更新を受けなければ、その期間の経過によって、その効力を失う。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設業の許可は、10年ごとにその更新を受けなければ、その期間の経過によって、その効力を失う。"], "answerHints": [["10年"]], "mnemonic": "正しくは：建設業の許可は5年ごとに更新を受けなければ効力を失う。", "block": 7, "group": 3}, {"id": "R02_kouki_50", "source": "R2後 No.50", "category": "法規", "type": "single", "question": "次の建築物に係る建設工事のうち、「建設工事に係る資材の再資源化等に関する法律」上、特定建設資材廃棄物をその種類ごとに分別しつつ施工しなければならない工事に該当するものはどれか。ただし、都道府県条例で、適用すべき建設工事の規模に関する基準を定めた区域における建設工事を除く。", "choices": [{"label": "1", "text": "解体工事で当該解体工事に係る床面積の合計が50m2であるもの"}, {"label": "2", "text": "新築工事で床面積の合計が300m2であるもの"}, {"label": "3", "text": "建築設備の改修工事で請負代金の額が3,000万円であるもの"}, {"label": "4", "text": "模様替工事で請負代金の額が1億円であるもの"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["特定建設資材廃棄物をその種類ごとに分別しつつ施工しなければならない工事に該当するもの"], "answerTexts": ["模様替工事で請負代金の額が1億円であるもの"], "answerHints": [["模様替工事で請負代金の額が1億円"]], "mnemonic": "分別解体の対象：解体80m²以上、新築・増築500m²以上、修繕・模様替等1億円以上、建築物以外500万円以上。", "block": 7, "group": 3}, {"id": "R03_zenki_39", "source": "R3前 No.39", "category": "法規", "type": "single", "question": "建設業における安全衛生管理に関する記述のうち、「労働安全衛生法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、常時5人以上60人未満の労働者を使用する事業場ごとに、安全衛生推進者を選任しなければならない。"}, {"label": "2", "text": "事業者は、労働者を雇い入れたときは、当該労働者に対し、その従事する業務に関する安全又は衛生のための教育を行わなければならない。"}, {"label": "3", "text": "事業者は、移動はしごを使用する場合、はしごの幅は30cm以上のものでなければ使用してはならない。"}, {"label": "4", "text": "事業者は、移動はしごを使用する場合、すべり止め装置の取付けその他転位を防止するため必要な措置を講じたものでなければ使用してはならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、常時5人以上60人未満の労働者を使用する事業場ごとに、安全衛生推進者を選任しなければならない。"], "answerHints": [["5人以上60人未満"]], "mnemonic": "正しくは：安全衛生推進者は常時10人以上50人未満の事業場ごとに選任する。", "block": 7, "group": 3}, {"id": "R03_zenki_42", "source": "R3前 No.42", "category": "法規", "type": "single", "question": "建築設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "排水のための配管設備の末端は、公共下水道、都市下水路その他の排水施設に排水上有効に連結しなければならない。"}, {"label": "2", "text": "排水管を構造耐力上主要な部分を貫通して配管する場合、建築物の構造耐力上支障を生じないようにしなければならない。"}, {"label": "3", "text": "給水管をコンクリートに埋設する場合、腐食するおそれのある部分には、その材質に応じ有効な腐食防止のための措置を講じなければならない。"}, {"label": "4", "text": "雨水排水立て管は、通気管と兼用し、又は通気管に連結することができる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["雨水排水立て管は、通気管と兼用し、又は通気管に連結することができる。"], "answerHints": [["通気管と兼用し"]], "mnemonic": "正しくは：雨水排水立て管は、汚水排水管若しくは通気管と兼用し、又はこれらに連結してはならない。", "block": 7, "group": 3}, {"id": "R03_zenki_45", "source": "R3前 No.45", "category": "法規", "type": "single", "question": "屋内消火栓設備を設置しなければならない防火対象物に、「消防法」上、該当するものはどれか。ただし、主要構造部は耐火構造とし、かつ、壁及び天井の室内に面する部分の仕上げは難燃材料でした防火対象物とする。また、地階、無窓階及び指定可燃物の貯蔵、取扱いはないものとする。", "choices": [{"label": "1", "text": "事務所 ――― 地上3階、延べ面積2,000m2"}, {"label": "2", "text": "共同住宅 ―― 地上3階、延べ面積2,000m2"}, {"label": "3", "text": "集会場 ――― 地上2階、延べ面積2,000m2"}, {"label": "4", "text": "学校 ―――― 地上2階、延べ面積2,000m2"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["該当するもの"], "answerTexts": ["集会場 ――― 地上2階、延べ面積2,000m2"], "answerHints": [["集会場"]], "mnemonic": "屋内消火栓は集会場500m²・事務所1,000m²・共同住宅/学校700m²以上で、耐火構造＋難燃仕上げは3倍。集会場のみ1,500m²≦2,000m²で該当。", "block": 7, "group": 3}, {"id": "R03_zenki_48", "source": "R3前 No.48", "category": "法規", "type": "single", "question": "廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建設工事の現場事務所から排出される生ゴミ、新聞、雑誌等は、産業廃棄物として処理しなければならない。"}, {"label": "2", "text": "一般廃棄物の処理は市町村が行い、産業廃棄物の処理は事業者が自ら行わなければならない。"}, {"label": "3", "text": "事業者は、処分受託者から、最終処分が終了した旨を記載した産業廃棄物管理票の写しの送付を受けたときは、当該管理票の写しを、送付を受けた日から5年間保存しなければならない。"}, {"label": "4", "text": "建築物の改築に伴い廃棄する蛍光灯の安定器にポリ塩化ビフェニルが含まれている場合、特別管理産業廃棄物として処理しなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設工事の現場事務所から排出される生ゴミ、新聞、雑誌等は、産業廃棄物として処理しなければならない。"], "answerHints": [["産業廃棄物として処理"]], "mnemonic": "正しくは：現場事務所の生ゴミ・新聞・雑誌等は一般廃棄物として処理する。", "block": 7, "group": 3}, {"id": "R03_kouki_41", "source": "R3後 No.41", "category": "法規", "type": "single", "question": "建築物の用語に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "病院は、特殊建築物である。"}, {"label": "2", "text": "基礎ぐいは、主要構造部である。"}, {"label": "3", "text": "集会のために継続的に使用する室は、居室である。"}, {"label": "4", "text": "金属板とガラスは、いずれも不燃材料である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["基礎ぐいは、主要構造部である。"], "answerHints": [["基礎ぐい"]], "mnemonic": "正しくは：主要構造部は壁・柱・床・はり・屋根・階段。基礎ぐいは含まれない（構造耐力上主要な部分には該当）。", "block": 7, "group": 3}, {"id": "R03_kouki_44", "source": "R3後 No.44", "category": "法規", "type": "single", "question": "建設工事における請負契約に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建設工事の注文者は、工事1件の予定価格が500万円に満たない場合、当該契約の締結又は入札までに、建設業者が当該建設工事の見積りに必要な期間を1日以上設けなければならない。"}, {"label": "2", "text": "建設工事の請負契約の当事者は、契約の締結に際して、工事内容、請負代金の額、工事着手の時期及び工事完成の時期等を書面に記載し、相互に交付しなければならない。"}, {"label": "3", "text": "元請負人は、下請負人からその請け負った建設工事が完成した旨の通知を受けたときは、当該通知を受けた日から10日以内に、その完成を確認するための検査を完了しなければならない。"}, {"label": "4", "text": "元請負人は、請負代金の工事完成後の支払を受けたときは、下請負人に対して、当該下請負人が施工した部分に相応する下請代金を、当該支払を受けた日から1月以内に支払わなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["元請負人は、下請負人からその請け負った建設工事が完成した旨の通知を受けたときは、当該通知を受けた日から10日以内に、その完成を確認するための検査を完了しなければならない。"], "answerHints": [["10日以内"]], "mnemonic": "正しくは：完成通知を受けた日から20日以内に検査を完了しなければならない。", "block": 7, "group": 3}, {"id": "R03_kouki_47", "source": "R3後 No.47", "category": "法規", "type": "single", "question": "業務用冷凍空調機器(カーエアコンを除く。)の冷媒管理に関する記述のうち、「フロン類の使用の合理化及び管理の適正化に関する法律」上、第一種特定製品の管理者が当該機器の使用時又は廃棄時に行うべき事項として定められていないものはどれか。", "choices": [{"label": "1", "text": "簡易点検の実施"}, {"label": "2", "text": "フロン類の漏えいを確認した場合の当該漏えいに係る点検及び漏えい箇所の修理"}, {"label": "3", "text": "点検及び整備に係る記録簿の保存"}, {"label": "4", "text": "フロン類の再生の実施及び再生証明書の交付"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["フロン類の再生の実施及び再生証明書の交付"], "answerHints": [["再生の実施及び再生証明書の交付"]], "mnemonic": "管理者の義務は簡易点検・定期点検、漏えい時の点検・修理、記録簿の保存等。フロン類の再生は第一種フロン類再生業者が行う。", "block": 7, "group": 3}, {"id": "R02_kouki_02", "source": "R2後 No.2", "category": "一般基礎", "type": "single", "question": "空気環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "浮遊粉じん量は、室内空気の汚染度を示す指標の一つである。"}, {"label": "2", "text": "二酸化炭素の濃度は、室内空気の汚染度を示す指標の一つである。"}, {"label": "3", "text": "居室の必要換気量は、一般的に、一酸化炭素濃度の許容値に基づき算出する。"}, {"label": "4", "text": "ホルムアルデヒドの室内濃度が高くなると、眼や呼吸器系を刺激し、アレルギーを引き起こすおそれがある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["居室の必要換気量は、一般的に、一酸化炭素濃度の許容値に基づき算出する。"], "answerHints": [["一酸化炭素濃度"]], "mnemonic": "正しくは：居室の必要換気量は、一般的に、二酸化炭素濃度の許容値に基づき算出する。", "block": 8, "group": 3}, {"id": "R02_kouki_05", "source": "R2後 No.5", "category": "一般基礎", "type": "single", "question": "電気設備における「保護装置等」と「主な目的」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "接地工事――――感電防止"}, {"label": "2", "text": "配線用遮断器――短絡保護"}, {"label": "3", "text": "漏電遮断器―――地絡保護"}, {"label": "4", "text": "サーマルリレ――力率改善"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["サーマルリレ――力率改善"], "answerHints": [["力率改善"]], "mnemonic": "正しくは：サーマルリレーは電動機の過負荷保護。力率改善は進相コンデンサ。", "block": 8, "group": 3}, {"id": "R03_zenki_02", "source": "R3前 No.2", "category": "一般基礎", "type": "single", "question": "室内空気環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "石綿は、天然の繊維状の鉱物で、その粉じんを吸入すると、中皮腫などの重篤な健康障害を引き起こすおそれがある。"}, {"label": "2", "text": "空気齢とは、室内のある地点における空気の新鮮さの度合いを示すもので、空気齢が大きいほど、その地点での換気効率がよく空気は新鮮である。"}, {"label": "3", "text": "臭気は、空気汚染を示す指標の一つであり、臭気強度や臭気指数で表す。"}, {"label": "4", "text": "二酸化炭素は無色無臭の気体で、「建築物における衛生的環境の確保に関する法律」における建築物環境衛生管理基準では、室内における許容濃度は0.1%以下とされている。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["空気齢とは、室内のある地点における空気の新鮮さの度合いを示すもので、空気齢が大きいほど、その地点での換気効率がよく空気は新鮮である。"], "answerHints": [["大きいほど"]], "mnemonic": "正しくは：空気齢が小さいほど、その地点の換気効率がよく空気は新鮮である。", "block": 8, "group": 3}, {"id": "R03_zenki_05", "source": "R3前 No.5", "category": "一般基礎", "type": "single", "question": "一般用電気工作物において、「電気工事士法」上、電気工事士資格を有しない者でも従事することができるものはどれか。", "choices": [{"label": "1", "text": "電線管に電線を収める作業"}, {"label": "2", "text": "電線管とボックスを接続する作業"}, {"label": "3", "text": "露出型コンセントを取り換える作業"}, {"label": "4", "text": "接地極を地面に埋設する作業"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["できるもの"], "answerTexts": ["露出型コンセントを取り換える作業"], "answerHints": [["露出型コンセントを取り換える作業"]], "mnemonic": "露出型コンセント・スイッチの取換え等は軽微な作業で資格不要。電線管への入線・接続、接地極の埋設は電気工事士の作業。", "block": 8, "group": 3}, {"id": "R03_kouki_02", "source": "R3後 No.2", "category": "一般基礎", "type": "single", "question": "水に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "大気圧において、1kgの水の温度を1°C上昇させるために必要な熱量は、約4.2kJである。"}, {"label": "2", "text": "0°Cの水が氷になると、その容積は約10%増加する。"}, {"label": "3", "text": "硬水は、カルシウム塩、マグネシウム塩を多く含む水である。"}, {"label": "4", "text": "大気圧において、空気の水に対する溶解度は、温度の上昇とともに増加する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["大気圧において、空気の水に対する溶解度は、温度の上昇とともに増加する。"], "answerHints": [["増加する"]], "mnemonic": "正しくは：空気の水に対する溶解度は、温度の上昇とともに減少する。", "block": 8, "group": 3}, {"id": "R03_kouki_05", "source": "R3後 No.5", "category": "一般基礎", "type": "single", "question": "電気設備に関する用語の組合せのうち、関係のないものはどれか。", "choices": [{"label": "1", "text": "漏電遮断器 ―――― 地絡保護"}, {"label": "2", "text": "配線用遮断器 ――― 短絡保護"}, {"label": "3", "text": "接地工事 ――――― 感電防止"}, {"label": "4", "text": "サーマルリレー ―― 力率改善"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["サーマルリレー ―― 力率改善"], "answerHints": [["力率改善"]], "mnemonic": "正しくは：サーマルリレーは電動機の過負荷保護。力率改善は進相コンデンサ。", "block": 8, "group": 3}, {"id": "R02_kouki_09", "source": "R2後 No.9", "category": "空調・衛生", "type": "single", "question": "冷房時の熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "日射負荷には、顕熱と潜熱がある。"}, {"label": "2", "text": "外気負荷には、顕熱と潜熱がある。"}, {"label": "3", "text": "照明器具による熱負荷は、顕熱のみである。"}, {"label": "4", "text": "窓ガラス面の通過熱負荷計算では、一般的に、内外温度差を使用する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["日射負荷には、顕熱と潜熱がある。"], "answerHints": [["日射負荷"]], "mnemonic": "正しくは：日射負荷は顕熱のみ。顕熱と潜熱があるのは外気負荷・人体・すきま風。", "block": 8, "group": 3}, {"id": "R02_kouki_12", "source": "R2後 No.12", "category": "空調・衛生", "type": "single", "question": "ルームエアコンに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "セパレート型の場合、冷媒配管の高低差には制限があるが、長さには制限がない。"}, {"label": "2", "text": "ルームエアコンを廃棄する場合、特定家庭用機器再商品化法(家電リサイクル法)に基づき処理する必要がある。"}, {"label": "3", "text": "圧縮機には、全密閉形のロータリー形、スクロール形等が使用されている。"}, {"label": "4", "text": "外気温度が低い時に暖房運転を行うと、屋外機の熱交換器に霜が付着することがある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["セパレート型の場合、冷媒配管の高低差には制限があるが、長さには制限がない。"], "answerHints": [["長さには制限がない"]], "mnemonic": "正しくは：セパレート型の冷媒配管は、高低差・長さともに制限がある。", "block": 8, "group": 3}, {"id": "R02_kouki_16", "source": "R2後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "汚水管きょにあっては、計画下水量は、計画時間最大汚水量とする。"}, {"label": "2", "text": "下水道は、公共下水道、流域下水道及び都市下水路に分けられる。"}, {"label": "3", "text": "公共下水道は、汚水を排除すべき排水施設の相当部分が暗きょ構造となっている。"}, {"label": "4", "text": "下水道本管に接続する取付管の勾配は、1/200以上とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["下水道本管に接続する取付管の勾配は、1/200以上とする。"], "answerHints": [["1/200以上"]], "mnemonic": "正しくは：取付管の勾配は1/100以上とする。", "block": 8, "group": 3}, {"id": "R02_kouki_19", "source": "R2後 No.19", "category": "空調・衛生", "type": "single", "question": "排水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "トラップは、下水ガス等の排水管から室内への侵入を封水により防止する。"}, {"label": "2", "text": "トラップの封水は、誘導サイホン作用、自己サイホン作用、蒸発、毛管現象等により損失する場合がある。"}, {"label": "3", "text": "わんトラップは、サイホン式トラップの一種である。"}, {"label": "4", "text": "大便器のトラップは、本体と一体になっているため、作り付けトラップと呼ばれる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["わんトラップは、サイホン式トラップの一種である。"], "answerHints": [["サイホン式トラップ"]], "mnemonic": "正しくは：わんトラップ（ベルトラップ）・ドラムトラップは非サイホン式トラップ。", "block": 8, "group": 3}, {"id": "R02_kouki_23", "source": "R2後 No.23", "category": "空調・衛生", "type": "single", "question": "FRP製浄化槽に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "埋戻しは、良質土で行うものとし、周囲を数回に分け均等に突き固め、水締めを行う。"}, {"label": "2", "text": "槽本体は、満水状態にして12時間以上放置し、漏水のないことを確認する。"}, {"label": "3", "text": "国土交通大臣型式認定の表示シールにより、認定番号、処理能力等を確認する。"}, {"label": "4", "text": "槽本体のマンホールのかさ上げは、最大300mmまでの高さとする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["槽本体は、満水状態にして12時間以上放置し、漏水のないことを確認する。"], "answerHints": [["12時間以上"]], "mnemonic": "正しくは：浄化槽は満水状態にして24時間放置し、漏水のないことを確認する。", "block": 8, "group": 3}, {"id": "R03_zenki_10", "source": "R3前 No.10", "category": "空調・衛生", "type": "single", "question": "空気清浄装置の記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ろ材の特性の一つとして、粉じん保持容量が小さいことが求められる。"}, {"label": "2", "text": "自動巻取形は、タイマー又は前後の差圧スイッチにより自動的に巻取りが行われる。"}, {"label": "3", "text": "静電式は、比較的微細な粉じん用に使用される。"}, {"label": "4", "text": "圧力損失は、上流側と下流側の圧力差で、初期値と最終値がある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ろ材の特性の一つとして、粉じん保持容量が小さいことが求められる。"], "answerHints": [["粉じん保持容量が小さい"]], "mnemonic": "正しくは：ろ材は粉じん保持容量が大きく、空気抵抗が小さいことが求められる。", "block": 8, "group": 3}, {"id": "R03_zenki_13", "source": "R3前 No.13", "category": "空調・衛生", "type": "single", "question": "換気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "発電機室の換気は、第1種機械換気方式とする。"}, {"label": "2", "text": "無窓の居室の換気は、第1種機械換気方式とする。"}, {"label": "3", "text": "便所の換気は、居室の換気系統にまとめる。"}, {"label": "4", "text": "駐車場の換気は、誘引誘導換気方式とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["便所の換気は、居室の換気系統にまとめる。"], "answerHints": [["居室の換気系統にまとめる"]], "mnemonic": "正しくは：便所の換気は臭気が他室へ流れないよう、居室とは別の単独系統（第3種）とする。", "block": 8, "group": 3}, {"id": "R03_zenki_16", "source": "R3前 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "管きょの断面は、円形又は矩形を標準とし、小規模下水道では円形又は卵形を標準とする。"}, {"label": "2", "text": "分流式の汚水だけを流す場合は、必ず暗きょとする。"}, {"label": "3", "text": "管きょの流速が小さければ、管きょ底部に汚物が沈殿しにくくなる。"}, {"label": "4", "text": "公共下水道の排除方式は、原則として、分流式とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["管きょの流速が小さければ、管きょ底部に汚物が沈殿しにくくなる。"], "answerHints": [["沈殿しにくくなる"]], "mnemonic": "正しくは：管きょの流速が小さいと、底部に汚物が沈殿しやすくなる。", "block": 8, "group": 3}, {"id": "R03_zenki_19", "source": "R3前 No.19", "category": "空調・衛生", "type": "single", "question": "通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水横枝管から立ち上げたループ通気管は、通気立て管又は伸頂通気管に接続する。"}, {"label": "2", "text": "大便器の器具排水管は、湿り通気管として利用してよい。"}, {"label": "3", "text": "通気立て管の上端は、単独で大気中に開口してよい。"}, {"label": "4", "text": "通気管は、排水系統内の空気の流れを円滑にするために設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["大便器の器具排水管は、湿り通気管として利用してよい。"], "answerHints": [["湿り通気管として利用してよい"]], "mnemonic": "正しくは：大便器の器具排水管は湿り通気管として利用してはならない。", "block": 8, "group": 3}, {"id": "R03_zenki_22", "source": "R3前 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液化石油ガスは、空気中に漏えいすると低いところに滞留しやすい。"}, {"label": "2", "text": "液化石油ガスは、主成分である炭化水素由来の臭気により、ガス漏れを感知できる。"}, {"label": "3", "text": "一般家庭用のガスメーターは、原則として、マイコンメーターとする。"}, {"label": "4", "text": "液化天然ガスは、石炭や石油に比べ、燃焼時の二酸化炭素の発生量が少ない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化石油ガスは、主成分である炭化水素由来の臭気により、ガス漏れを感知できる。"], "answerHints": [["炭化水素由来の臭気により"]], "mnemonic": "正しくは：液化石油ガスはほぼ無臭なので、付臭剤の臭気によりガス漏れを感知できるようにしている。", "block": 8, "group": 3}, {"id": "R03_kouki_09", "source": "R3後 No.9", "category": "空調・衛生", "type": "single", "question": "熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "構造体の空気層は、熱通過率には影響を与えない。"}, {"label": "2", "text": "非空調室と接する内壁の単位面積当たりの熱負荷は、空調対象室と非空調室の温度差と熱通過率より求める。"}, {"label": "3", "text": "冷房負荷計算では、人体や事務機器からの負荷を室内負荷として考慮する。"}, {"label": "4", "text": "暖房負荷計算では、一般的に、外壁、屋根、ピロティの熱負荷には方位係数を乗じる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["構造体の空気層は、熱通過率には影響を与えない。"], "answerHints": [["影響を与えない"]], "mnemonic": "正しくは：構造体の空気層は熱抵抗となり、熱通過率に影響を与える。", "block": 8, "group": 3}, {"id": "R03_kouki_12", "source": "R3後 No.12", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ガスエンジンヒートポンプ方式は、一般的に、デフロスト運転は不要である。"}, {"label": "2", "text": "インバーター制御のものは、高調波対策を考慮する必要がある。"}, {"label": "3", "text": "冷暖房能力は、外気温度、冷媒管長、屋外機と屋内機の設置高低差等により変化しない。"}, {"label": "4", "text": "省エネルギー性能の評価指標には、APF(通年エネルギー消費効率)がある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["冷暖房能力は、外気温度、冷媒管長、屋外機と屋内機の設置高低差等により変化しない。"], "answerHints": [["変化しない"]], "mnemonic": "正しくは：冷暖房能力は、外気温度・冷媒管長・屋外機と屋内機の高低差等により変化する。", "block": 8, "group": 3}, {"id": "R03_kouki_16", "source": "R3後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "公共下水道と敷地内排水系統の排水方式において、分流式と合流式の定義は同じである。"}, {"label": "2", "text": "管きょの接合方法には、水面接合、管頂接合、管中心接合及び管底接合がある。"}, {"label": "3", "text": "公共下水道の設置、改築、修繕、維持その他の管理は、市町村が行う。"}, {"label": "4", "text": "取付管は、本管の中心線から上方に取り付ける。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["公共下水道と敷地内排水系統の排水方式において、分流式と合流式の定義は同じである。"], "answerHints": [["定義は同じである"]], "mnemonic": "正しくは：分流式・合流式の定義は異なる（下水道は汚水と雨水、敷地内は汚水と雑排水の合流・分流）。", "block": 8, "group": 3}, {"id": "R03_kouki_19", "source": "R3後 No.19", "category": "空調・衛生", "type": "single", "question": "衛生器具の「名称」と当該器具の「トラップの最小口径」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "掃除流し ―――――― 50mm"}, {"label": "2", "text": "壁掛け小型小便器 ―― 40mm"}, {"label": "3", "text": "汚物流し ―――――― 75mm"}, {"label": "4", "text": "大便器 ――――――― 75mm"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["掃除流し ―――――― 50mm"], "answerHints": [["50mm"]], "mnemonic": "正しくは：掃除流しのトラップ最小口径は65mm（汚物流し・大便器75mm、壁掛け小型小便器40mm）。", "block": 8, "group": 3}, {"id": "R03_kouki_22", "source": "R3後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "都市ガスの引込みで、本支管分岐個所から敷地境界線までの導管を供給管という。"}, {"label": "2", "text": "液化天然ガス(LNG)には、一酸化炭素が含まれている。"}, {"label": "3", "text": "液化石油ガス(LPG)の一般家庭向け供給方式には、戸別供給方式と集団供給方式がある。"}, {"label": "4", "text": "液化石油ガス(LPG)の充填容器の設置においては、容器が常に40°C以下に保たれる措置を講じる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化天然ガス(LNG)には、一酸化炭素が含まれている。"], "answerHints": [["一酸化炭素が含まれている"]], "mnemonic": "正しくは：液化天然ガス（LNG）には一酸化炭素は含まれていない。", "block": 8, "group": 3}, {"id": "R02_kouki_25", "source": "R2後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "飲料用給水タンクの構造に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "2槽式タンクの中仕切り板は、一方のタンクを空にした場合にあっても、地震等により損傷しない構造のものとする。"}, {"label": "2", "text": "屋外に設置するFRP製タンクは、藻類の増殖防止に有効な遮光性を有するものとする。"}, {"label": "3", "text": "タンク底部には、水の滞留防止のため、吸込みピットを設けてはならない。"}, {"label": "4", "text": "通気口は、衛生上有害なものが入らない構造とし、防虫網を設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["タンク底部には、水の滞留防止のため、吸込みピットを設けてはならない。"], "answerHints": [["吸込みピットを設けてはならない"]], "mnemonic": "正しくは：タンク底部には勾配を付け、吸込みピットを設ける（水抜き・清掃用）。", "block": 8, "group": 3}, {"id": "R03_zenki_24", "source": "R3前 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "給湯設備の機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "小型貫流ボイラーは、保有水量が少ないため、起動時間が短く、負荷変動への追従性がよい。"}, {"label": "2", "text": "空気熱源ヒートポンプ給湯機は、大気中の熱エネルギーを給湯の加熱に利用するものである。"}, {"label": "3", "text": "真空式温水発生機は、本体に封入されている熱媒水の補給を必要としない。"}, {"label": "4", "text": "密閉式ガス湯沸器は、燃焼空気を室内から取り入れ、燃焼ガスを直接屋外に排出するものである。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["密閉式ガス湯沸器は、燃焼空気を室内から取り入れ、燃焼ガスを直接屋外に排出するものである。"], "answerHints": [["室内から取り入れ"]], "mnemonic": "正しくは：密閉式は燃焼用空気を屋外から取り入れ、燃焼ガスを屋外に排出する（設問は半密閉式）。", "block": 8, "group": 3}, {"id": "R03_zenki_27", "source": "R3前 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "案内羽根(ガイドベーン)は、直角エルボ等に設け、圧力損失を低減する。"}, {"label": "2", "text": "軸流吹出口の種類には、ノズル形、パンカルーバー形、グリル形等がある。"}, {"label": "3", "text": "吸込口が居住区域内の座席に近い位置にある場合は、有効開口面風速を2.0~3.0m/sとする。"}, {"label": "4", "text": "シーリングディフューザー形吹出口は、室内空気を誘引する効果が小さく、拡散半径が小さい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["シーリングディフューザー形吹出口は、室内空気を誘引する効果が小さく、拡散半径が小さい。"], "answerHints": [["効果が小さく", "拡散半径が小さい"]], "mnemonic": "正しくは：シーリングディフューザー形吹出口は、誘引効果が大きく拡散半径が大きい。", "block": 8, "group": 3}, {"id": "R03_kouki_26", "source": "R3後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ボールタップは、比較的小さなタンクの水位を一定に保つために用いる。"}, {"label": "2", "text": "架橋ポリエチレン管は、構造により単層管と二層管に分類される。"}, {"label": "3", "text": "スイング逆止め弁を垂直配管に取り付ける場合は、下向きの流れとする。"}, {"label": "4", "text": "配管用炭素鋼鋼管には黒管と白管があり、白管は、黒管に溶融亜鉛めっきを施したものである。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["スイング逆止め弁を垂直配管に取り付ける場合は、下向きの流れとする。"], "answerHints": [["下向きの流れ"]], "mnemonic": "正しくは：スイング逆止め弁を垂直配管に取り付ける場合は、上向きの流れとする。", "block": 8, "group": 3}, {"id": "R02_kouki_32", "source": "R2後 No.32", "category": "施工管理法", "type": "single", "question": "施工の品質を確認するための試験又は検査に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水用水中モーターポンプの試験において、レベルスイッチからの信号による発停を確認する。"}, {"label": "2", "text": "防火区画を給水管が貫通する箇所において、貫通部の隙間が難燃材料で埋め戻されていることを確認する。"}, {"label": "3", "text": "洗面器の取付けにおいて、がたつきがないこと、及び、付属の給排水金具等から漏水がないことを確認する。"}, {"label": "4", "text": "高置タンク以降の給水配管の水圧試験において、静水頭に相当する圧力の2倍の圧力が0.75MPa未満の場合、0.75MPaの圧力で試験を行う。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火区画を給水管が貫通する箇所において、貫通部の隙間が難燃材料で埋め戻されていることを確認する。"], "answerHints": [["難燃材料"]], "mnemonic": "正しくは：防火区画貫通部の隙間はモルタルその他の不燃材料で埋め戻す。", "block": 8, "group": 3}, {"id": "R02_kouki_35", "source": "R2後 No.35", "category": "施工管理法", "type": "single", "question": "機器の据付けに使用するアンカーボルトに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "アンカーボルトを選定する場合、常時荷重に対する許容引抜き荷重は、長期許容引抜き荷重とする。"}, {"label": "2", "text": "ボルト径がM12以下のL型アンカーボルトの短期許容引抜き荷重は、一般的に、同径のJ型アンカーボルトの短期許容引抜き荷重より大きい。"}, {"label": "3", "text": "アンカーボルトは、機器の据付け後、ボルト頂部のねじ山がナットから3山程度出る長さとする。"}, {"label": "4", "text": "アンカーボルトの径は、アンカーボルトに加わる引抜き力、せん断力、アンカーボルトの本数等から決定する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボルト径がM12以下のL型アンカーボルトの短期許容引抜き荷重は、一般的に、同径のJ型アンカーボルトの短期許容引抜き荷重より大きい。"], "answerHints": [["より大きい"]], "mnemonic": "正しくは：L型アンカーボルトの短期許容引抜き荷重は、同径のJ型より小さい。", "block": 8, "group": 3}, {"id": "R02_kouki_38", "source": "R2後 No.38", "category": "施工管理法", "type": "single", "question": "ダクトの施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクトの吊りボルトが長い場合には、振れ止めを設ける。"}, {"label": "2", "text": "浴室等の多湿箇所からの排気ダクトには、継手及び継目(はぜ)の外側からシールを施す。"}, {"label": "3", "text": "保温を施すダクトには、ダクトの寸法にかかわらず、形鋼による補強は不要である。"}, {"label": "4", "text": "アングルフランジ工法ダクトのガスケットには、フランジ幅と同一幅のものを用いる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["保温を施すダクトには、ダクトの寸法にかかわらず、形鋼による補強は不要である。"], "answerHints": [["形鋼による補強は不要"]], "mnemonic": "正しくは：保温を施すダクトでも、ダクトの寸法に応じて形鋼による補強が必要。", "block": 8, "group": 3}, {"id": "R02_kouki_42", "source": "R1前 No.42 / R2後 No.42", "category": "施工管理法", "type": "single", "question": "JISに規定されている配管系の識別表示について、管内の「物質等の種類」とその「識別色」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水――――青"}, {"label": "2", "text": "油――――白"}, {"label": "3", "text": "電気―――うすい黄赤"}, {"label": "4", "text": "ガス―――うすい黄"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["油――――白"], "answerHints": [["白"]], "mnemonic": "正しくは：油の識別色は茶色（水＝青、ガス＝うすい黄、電気＝うすい黄赤）。", "block": 8, "group": 3}, {"id": "R03_zenki_33", "source": "R3前 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "パッケージ形空気調和機の屋外機の騒音対策には、防音壁の設置等がある。"}, {"label": "2", "text": "遠心送風機の心出し調整は、製造者が出荷前に行うこととし、据付け時には行わない。"}, {"label": "3", "text": "床置き形のパッケージ形空気調和機の基礎の高さは、150mm程度とする。"}, {"label": "4", "text": "縦横比の大きい自立機器への頂部支持材の取付けは、原則として、2箇所以上とする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["遠心送風機の心出し調整は、製造者が出荷前に行うこととし、据付け時には行わない。"], "answerHints": [["据付け時には行わない"]], "mnemonic": "正しくは：遠心送風機の心出し調整は、据付け時にも現場で行う。", "block": 8, "group": 3}, {"id": "R03_zenki_37", "source": "R3前 No.37", "category": "施工管理法", "type": "single", "question": "「機器又は配管」とその「試験方法」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "建物内排水管 ――――― 通水試験"}, {"label": "2", "text": "敷地排水管 ―――――― 通水試験"}, {"label": "3", "text": "浄化槽 ―――――――― 満水試験"}, {"label": "4", "text": "排水ポンプ吐出し管 ―― 満水試験"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水ポンプ吐出し管 ―― 満水試験"], "answerHints": [["満水試験"]], "mnemonic": "正しくは：排水ポンプ吐出し管は水圧試験（圧送されるため）。", "block": 8, "group": 3}, {"id": "R03_kouki_32", "source": "R3後 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "わく組足場における高さ2m以上の作業場所に設ける作業床の幅は、30cm以上とする。"}, {"label": "2", "text": "わく組足場における高さ2m以上の作業場所に設ける作業床の床材間の隙間は、3cm以下とする。"}, {"label": "3", "text": "脚立の脚と水平面との角度は、75度以下とする。"}, {"label": "4", "text": "折りたたみ式の脚立は、脚と水平面との角度を確実に保つための金具等を備えたものとする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["わく組足場における高さ2m以上の作業場所に設ける作業床の幅は、30cm以上とする。"], "answerHints": [["30cm以上"]], "mnemonic": "正しくは：高さ2m以上の作業床の幅は40cm以上、床材間の隙間は3cm以下。", "block": 8, "group": 3}, {"id": "R03_kouki_35", "source": "R3後 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "送風機とダクトを接続するたわみ継手の両端のフランジ間隔は、150mm以上とする。"}, {"label": "2", "text": "共板フランジ工法ダクトとアングルフランジ工法ダクトでは、横走りダクトの許容最大吊り間隔は同じである。"}, {"label": "3", "text": "風量調整ダンパーは、原則として、気流の整流されたところに取り付ける。"}, {"label": "4", "text": "長方形ダクトのかどの継目(はぜ)は、ダクトの強度を保つため、原則として、2箇所以上とする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["共板フランジ工法ダクトとアングルフランジ工法ダクトでは、横走りダクトの許容最大吊り間隔は同じである。"], "answerHints": [["許容最大吊り間隔は同じ"]], "mnemonic": "正しくは：共板フランジ工法ダクトの吊り間隔はアングルフランジ工法より小さい（共板2m、アングル3m）。", "block": 8, "group": 3}, {"id": "R03_zenki_50", "source": "R3前 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "遠心送風機の据付け時の調整において、Vベルトの張りが強すぎると、軸受の過熱の原因になる。"}, {"label": "2", "text": "呼び番号3の天吊りの遠心送風機は、形鋼製の架台上に据え付け、架台はスラブから吊りボルトで吊る。"}, {"label": "3", "text": "冷却塔は、補給水口の高さが補給水タンクの低水位から2m以内となるように据え付ける。"}, {"label": "4", "text": "埋込式アンカーボルトの中心とコンクリート基礎の端部の間隔は、一般的に、150mm以上を目安としてよい。"}], "answer": ["2", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["呼び番号3の天吊りの遠心送風機は、形鋼製の架台上に据え付け、架台はスラブから吊りボルトで吊る。", "冷却塔は、補給水口の高さが補給水タンクの低水位から2m以内となるように据え付ける。"], "answerHints": [["吊りボルトで吊る"], ["2m以内"]], "mnemonic": "呼び番号2以上の天吊り送風機は吊りボルトではなく形鋼で吊る。冷却塔の補給水口は補給水タンクの低水位から3m以上低くする。", "block": 8, "group": 3}, {"id": "R03_kouki_49", "source": "R3後 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程表に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ガントチャート工程表は、各作業を合わせた工事全体の進行状態が不明という欠点がある。"}, {"label": "2", "text": "ガントチャート工程表は、各作業の所要日数が容易に把握できる。"}, {"label": "3", "text": "バーチャート工程表に記入される予定進度曲線は、バナナ曲線とも呼ばれている。"}, {"label": "4", "text": "バーチャート工程表は、各作業の施工日程が容易に把握できる。"}], "answer": ["2", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ガントチャート工程表は、各作業の所要日数が容易に把握できる。", "バーチャート工程表に記入される予定進度曲線は、バナナ曲線とも呼ばれている。"], "answerHints": [["所要日数"], ["バナナ曲線"]], "mnemonic": "ガントチャートは現時点の進捗状況が分かるが所要日数は不明。バナナ曲線は進捗の許容範囲を示す工程管理曲線で、予定進度曲線（S字）とは別。", "block": 8, "group": 3}, {"id": "R03_kouki_52", "source": "R3後 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ダクト接合用のフランジの許容最大取付け間隔は、ダクトの寸法が小さいほど小さくなる。"}, {"label": "2", "text": "シーリングディフューザーの外コーンには、落下防止用のワイヤー等を取り付ける。"}, {"label": "3", "text": "防火ダンパーは、火災による脱落がないように、原則として、4本吊りとする。"}, {"label": "4", "text": "小口径のスパイラルダクトの接続には、一般的に、差込継手が使用される。"}], "answer": ["1", "2"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクト接合用のフランジの許容最大取付け間隔は、ダクトの寸法が小さいほど小さくなる。", "シーリングディフューザーの外コーンには、落下防止用のワイヤー等を取り付ける。"], "answerHints": [["小さいほど小さくなる"], ["外コーン"]], "mnemonic": "フランジの最大取付け間隔はダクト寸法が大きいほど小さい。落下防止ワイヤーはシーリングディフューザーの内コーンに付ける。", "block": 8, "group": 3}, {"id": "R02_kouki_45", "source": "R2後 No.45", "category": "法規", "type": "single", "question": "建築物の階数又は高さに関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建築物の地階部分は、その部分の用途と面積にかかわらず建築物の階数に算入する。"}, {"label": "2", "text": "屋根の棟飾りは、建築物の高さに算入しない。"}, {"label": "3", "text": "建築物のエレベーター機械室、装飾塔その他これらに類する屋上部分は、その部分の面積の合計が所定の条件を満たせば、建築物の階数に算入しない。"}, {"label": "4", "text": "建築物の階段室、エレベーター機械室その他これらに類する屋上部分は、その部分の面積の合計が所定の条件を満たせば、建築物の高さに算入しない場合がある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建築物の地階部分は、その部分の用途と面積にかかわらず建築物の階数に算入する。"], "answerHints": [["用途と面積にかかわらず"]], "mnemonic": "正しくは：地階の機械室・倉庫等で水平投影面積が建築面積の1/8以下のものは階数に算入しない。", "block": 8, "group": 3}, {"id": "R02_kouki_48", "source": "R2後 No.48", "category": "法規", "type": "single", "question": "建設業の許可を受けた建設業者が、現場に置く主任技術者等に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "発注者から直接請け負った建設工事を、下請契約を行わずに自ら施工する場合は、主任技術者が当該工事の施工の技術上の管理をつかさどることができる。"}, {"label": "2", "text": "一定金額以上で請け負った共同住宅の建設工事に置く主任技術者は、工事現場ごとに、専任の者でなければならない。"}, {"label": "3", "text": "発注者から直接請け負った建設工事を施工するために他の建設業者と下請契約を締結する場合は、下請契約の請負代金の額にかかわらず監理技術者を置かなければならない。"}, {"label": "4", "text": "主任技術者は、当該建設工事の施工計画の作成、工程管理、品質管理その他の技術上の管理及び当該建設工事の施工に従事する者の技術上の指導監督の職務を誠実に行わなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["発注者から直接請け負った建設工事を施工するために他の建設業者と下請契約を締結する場合は、下請契約の請負代金の額にかかわらず監理技術者を置かなければならない。"], "answerHints": [["下請契約の請負代金の額にかかわらず"]], "mnemonic": "正しくは：監理技術者が必要なのは、元請の下請契約の総額が一定額以上（現行4,500万円以上、建築一式7,000万円以上）の場合。", "block": 8, "group": 3}, {"id": "R02_kouki_51", "source": "R2後 No.51", "category": "法規", "type": "single", "question": "特定建設作業に伴って発生する騒音について規制する指定地域において、災害その他非常の事態の発生により当該特定建設作業を緊急に行う必要がある場合にあっても、当該騒音について「騒音規制法」上の規制が適用されるものはどれか。", "choices": [{"label": "1", "text": "連続して6日間を超えて行われる作業に伴って発生する騒音"}, {"label": "2", "text": "作業の場所の敷地の境界線において、85デシベルを超える大きさの騒音"}, {"label": "3", "text": "日曜日に行われる作業に伴って発生する騒音"}, {"label": "4", "text": "1日14時間を超えて行われる作業に伴って発生する騒音"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["上の規制が適用されるもの"], "answerTexts": ["作業の場所の敷地の境界線において、85デシベルを超える大きさの騒音"], "answerHints": [["85デシベルを超える"]], "mnemonic": "災害等の緊急時でも適用されるのは敷地境界85dBの騒音基準。作業時間・連続日数・日曜休日の制限は適用除外。", "block": 8, "group": 3}, {"id": "R03_zenki_40", "source": "R3前 No.40", "category": "法規", "type": "single", "question": "未成年者の労働契約に関する記述のうち、「労働基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "親権者又は後見人は、未成年者に代って労働契約を締結してはならない。"}, {"label": "2", "text": "未成年者は、独立して賃金を請求することができる。"}, {"label": "3", "text": "親権者又は後見人は、未成年者の同意を得れば、未成年者の賃金を代って受け取ることができる。"}, {"label": "4", "text": "使用者は、原則として、満18才に満たない者を午後10時から午前5時までの間において使用してはならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["親権者又は後見人は、未成年者の同意を得れば、未成年者の賃金を代って受け取ることができる。"], "answerHints": [["未成年者の同意を得れば"]], "mnemonic": "正しくは：親権者・後見人は、未成年者の賃金を代わって受け取ってはならない（同意があっても不可）。", "block": 8, "group": 3}, {"id": "R03_zenki_43", "source": "R3前 No.43", "category": "法規", "type": "single", "question": "建設業の許可を受けた建設業者が、発注者から直接請け負った建設工事の現場に掲げる標識の記載事項として、「建設業法」上、定められていないものはどれか。", "choices": [{"label": "1", "text": "商号又は名称"}, {"label": "2", "text": "現場代理人の氏名"}, {"label": "3", "text": "主任技術者又は監理技術者の氏名"}, {"label": "4", "text": "一般建設業又は特定建設業の別"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["現場代理人の氏名"], "answerHints": [["現場代理人の氏名"]], "mnemonic": "標識の記載事項は商号・名称、代表者氏名、一般/特定の別、許可番号・許可年月日、主任技術者/監理技術者の氏名等。現場代理人は含まない。", "block": 8, "group": 3}, {"id": "R03_zenki_46", "source": "R3前 No.46", "category": "法規", "type": "single", "question": "次の建設資材のうち、「建設工事に係る資材の再資源化等に関する法律」上、再資源化が特に必要とされる特定建設資材に該当しないものはどれか。", "choices": [{"label": "1", "text": "木材"}, {"label": "2", "text": "アスファルト・コンクリート"}, {"label": "3", "text": "コンクリート"}, {"label": "4", "text": "アルミニウム"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["アルミニウム"], "answerHints": [["アルミニウム"]], "mnemonic": "特定建設資材はコンクリート、コンクリート及び鉄から成る資材、木材、アスファルト・コンクリートの4つ。", "block": 8, "group": 3}, {"id": "R03_kouki_39", "source": "R3後 No.39", "category": "法規", "type": "single", "question": "建設工事現場における作業のうち、「労働安全衛生法」上、作業主任者を選任すべき作業に該当しないものはどれか。", "choices": [{"label": "1", "text": "既設汚水ピット内での配管の作業"}, {"label": "2", "text": "型枠支保工の組立ての作業"}, {"label": "3", "text": "つり上げ荷重が1トン未満の移動式クレーンの玉掛けの作業"}, {"label": "4", "text": "第一種圧力容器(小型圧力容器等を除く。)の取扱いの作業"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["つり上げ荷重が1トン未満の移動式クレーンの玉掛けの作業"], "answerHints": [["つり上げ荷重が1トン未満"]], "mnemonic": "玉掛け作業は作業主任者の選任対象ではない（1t未満は特別教育）。汚水ピット内は酸素欠乏危険作業主任者、型枠支保工・第一種圧力容器も作業主任者が必要。", "block": 8, "group": 3}, {"id": "R03_kouki_42", "source": "R3後 No.42", "category": "法規", "type": "single", "question": "建築設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "飲料水の配管設備とその他の配管設備とは、直接連結させてはならない。"}, {"label": "2", "text": "合併処理浄化槽は、放流水に含まれる大腸菌群数が、3,000〔個/cm3〕以下とする性能を有するものでなければならない。"}, {"label": "3", "text": "調理室で、火を使用する器具の近くに排気フードを有する排気筒を設ける場合、排気フードは、不燃材料で造らなければならない。"}, {"label": "4", "text": "排水再利用配管設備は、塩素消毒その他これに類する措置を講ずれば、手洗器に連結させてもよい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["排水再利用配管設備は、塩素消毒その他これに類する措置を講ずれば、手洗器に連結させてもよい。"], "answerHints": [["手洗器に連結させてもよい"]], "mnemonic": "正しくは：排水再利用配管設備は、洗面器・手洗器等に連結してはならない。", "block": 8, "group": 3}, {"id": "R03_kouki_45", "source": "R3後 No.45", "category": "法規", "type": "single", "question": "同一の場所で複数の危険物を取り扱う場合において、指定数量未満となる組合せとして、「消防法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "灯油 100L、重油 200L"}, {"label": "2", "text": "ガソリン 100L、灯油 200L"}, {"label": "3", "text": "軽油 500L、重油 1,000L"}, {"label": "4", "text": "灯油 200L、軽油 500L"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["軽油 500L、重油 1,000L"], "answerHints": [["軽油 500L", "重油 1,000L"]], "mnemonic": "指定数量はガソリン200L、灯油・軽油1,000L、重油2,000L。倍数の合計は0.5＋0.5＝1.0で指定数量以上となる。", "block": 8, "group": 3}, {"id": "R02_kouki_03", "source": "R2後 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "流体が直管路を満流で流れる場合、圧力損失の大きさは、平均流速と関係しない。"}, {"label": "2", "text": "ウォーターハンマーによる圧力波の伝わる速度は、管の内径や肉厚と関係している。"}, {"label": "3", "text": "毛管現象は、液柱に作用する重力と表面張力の鉛直成分とのつり合いによるものである。"}, {"label": "4", "text": "ピトー管は、流速の測定に用いられる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["流体が直管路を満流で流れる場合、圧力損失の大きさは、平均流速と関係しない。"], "answerHints": [["平均流速と関係しない"]], "mnemonic": "正しくは：直管路の圧力損失は平均流速の2乗に比例する。", "block": 9, "group": 3}, {"id": "R02_kouki_06", "source": "R2後 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート造の建築物の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "夏期の打込み後のコンクリートは、急激な乾燥を防ぐために散水による湿潤養生を行う。"}, {"label": "2", "text": "型枠の存置期間は、セメントの種類や平均気温によって変わる。"}, {"label": "3", "text": "スランプ値が小さいほど、コンクリートの流動性が高くなる。"}, {"label": "4", "text": "水セメント比が大きくなると、コンクリートの圧縮強度が小さくなる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["スランプ値が小さいほど、コンクリートの流動性が高くなる。"], "answerHints": [["小さいほど"]], "mnemonic": "正しくは：スランプ値が大きいほど、コンクリートの流動性が高い。", "block": 9, "group": 3}, {"id": "R03_zenki_03", "source": "R3前 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する用語の組合せのうち、関係のないものはどれか。", "choices": [{"label": "1", "text": "粘性係数 ――――― 摩擦応力"}, {"label": "2", "text": "パスカルの原理 ―― 水圧"}, {"label": "3", "text": "体積弾性係数 ――― 圧縮率"}, {"label": "4", "text": "レイノルズ数 ――― 表面張力"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["レイノルズ数 ――― 表面張力"], "answerHints": [["表面張力"]], "mnemonic": "レイノルズ数は慣性力と粘性力の比で、層流・乱流の判定に使う。表面張力は毛管現象と関係。", "block": 9, "group": 3}, {"id": "R03_zenki_06", "source": "R3前 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート造の建築物の鉄筋に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ジャンカ、コールドジョイントは、鉄筋の腐食の原因になりやすい。"}, {"label": "2", "text": "コンクリートの引張り強度は小さく、鉄筋の引張り強度は大きい。"}, {"label": "3", "text": "あばら筋は、梁のせん断破壊を防止する補強筋である。"}, {"label": "4", "text": "鉄筋のかぶり厚さは、外壁、柱、梁及び基礎で同じ厚さとしなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鉄筋のかぶり厚さは、外壁、柱、梁及び基礎で同じ厚さとしなければならない。"], "answerHints": [["同じ厚さとしなければならない"]], "mnemonic": "正しくは：かぶり厚さは部位ごとに異なる（土に接する基礎などは厚くする）。", "block": 9, "group": 3}, {"id": "R03_kouki_03", "source": "R3後 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液体は、気体に比べて圧縮しにくい。"}, {"label": "2", "text": "大気圧において、水の粘性係数は空気の粘性係数より小さい。"}, {"label": "3", "text": "管路を流れる水は、レイノルズ数が大きくなると層流から乱流に変化する。"}, {"label": "4", "text": "流水管路において、弁の急閉はウォーターハンマーが発生する要因となる"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["大気圧において、水の粘性係数は空気の粘性係数より小さい。"], "answerHints": [["より小さい"]], "mnemonic": "正しくは：水の粘性係数は空気の粘性係数より大きい。", "block": 9, "group": 3}, {"id": "R03_kouki_06", "source": "R3後 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリートの特性に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "コンクリートと鉄筋の線膨張係数は、ほぼ等しい。"}, {"label": "2", "text": "異形棒鋼は、丸鋼と比べてコンクリートとの付着力が大きい。"}, {"label": "3", "text": "コンクリートはアルカリ性のため、コンクリート中の鉄筋はさびにくい。"}, {"label": "4", "text": "鉄筋コンクリート造は、剛性が低く振動による影響を受けやすい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鉄筋コンクリート造は、剛性が低く振動による影響を受けやすい。"], "answerHints": [["剛性が低く"]], "mnemonic": "正しくは：鉄筋コンクリート造は剛性が高く、振動による影響を受けにくい。", "block": 9, "group": 3}, {"id": "R02_kouki_10", "source": "R2後 No.10", "category": "空調・衛生", "type": "single", "question": "エアフィルターの「種類」と「主な用途」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "活性炭フィルタ―――屋外粉じんの除去"}, {"label": "2", "text": "電気集じん器――――屋内粉じんの除去"}, {"label": "3", "text": "HEPAフィルター――クリーンルーム用"}, {"label": "4", "text": "自動巻取形―――――般空調用"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["活性炭フィルタ―――屋外粉じんの除去"], "answerHints": [["屋外粉じんの除去"]], "mnemonic": "正しくは：活性炭フィルターは有害ガス・臭気の除去用。", "block": 9, "group": 3}, {"id": "R02_kouki_13", "source": "R2後 No.13", "category": "空調・衛生", "type": "single", "question": "換気の「対象となる室」と「主な目的」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "居室―――――室内空気の浄化"}, {"label": "2", "text": "更衣室――――熱の排除"}, {"label": "3", "text": "ボイラー室――酸素の供給"}, {"label": "4", "text": "浴室―――――水蒸気の排除"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["更衣室――――熱の排除"], "answerHints": [["熱の排除"]], "mnemonic": "正しくは：更衣室の換気の主目的は臭気の除去（熱の排除は電気室・機械室など）。", "block": 9, "group": 3}, {"id": "R02_kouki_17", "source": "R2後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給水管への逆サイホン作用による汚染の防止には、排水口空間の確保が基本となる。"}, {"label": "2", "text": "飲料用給水タンクには、内径60cm以上のマンホールを設ける。"}, {"label": "3", "text": "給水管に設置するエアチャンバーは、ウォーターハンマーの防止に有効である。"}, {"label": "4", "text": "大気圧式バキュームブレーカーは、大便器洗浄弁等と組み合わせて使用される。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給水管への逆サイホン作用による汚染の防止には、排水口空間の確保が基本となる。"], "answerHints": [["排水口空間"]], "mnemonic": "正しくは：逆サイホン作用による汚染防止は吐水口空間の確保が基本。", "block": 9, "group": 3}, {"id": "R02_kouki_21", "source": "R2後 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋内消火栓設備には、非常電源を附置する。"}, {"label": "2", "text": "屋内消火栓箱の上部には、設置の表示のための緑色の灯火を設ける。"}, {"label": "3", "text": "屋内消火栓の開閉弁は、自動式のものでない場合、床面からの高さが1.5m以下の位置に設ける。"}, {"label": "4", "text": "加圧送水装置には、高架水槽、圧力水槽又はポンプを用いるものがある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["屋内消火栓箱の上部には、設置の表示のための緑色の灯火を設ける。"], "answerHints": [["緑色の灯火"]], "mnemonic": "正しくは：屋内消火栓箱の上部には、設置の標示のため赤色の灯火を設ける。", "block": 9, "group": 3}, {"id": "R03_zenki_07", "source": "R1後 No.7 / R3前 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和設備の計画に関する記述のうち、省エネルギーの観点から、適当でないものはどれか。", "choices": [{"label": "1", "text": "湿度制御のため、冷房に冷却減湿・再熱方式を採用する。"}, {"label": "2", "text": "予冷・予熱時に外気を取り入れないように制御する。"}, {"label": "3", "text": "ユニット形空気調和機に全熱交換器を組み込む。"}, {"label": "4", "text": "成績係数が高い機器を採用する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["湿度制御のため、冷房に冷却減湿・再熱方式を採用する。"], "answerHints": [["冷却減湿・再熱方式"]], "mnemonic": "冷却減湿・再熱方式は冷却と加熱を同時に行うため、エネルギーの無駄が大きく省エネに反する。", "block": 9, "group": 3}, {"id": "R03_zenki_11", "source": "R3前 No.11", "category": "空調・衛生", "type": "single", "question": "放熱器を室内に設置する直接暖房方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "暖房用自然対流・放射形放熱器には、コンベクタ類とラジエータ類がある。"}, {"label": "2", "text": "温水暖房のウォーミングアップにかかる時間は、蒸気暖房に比べて長くなる。"}, {"label": "3", "text": "温水暖房の放熱面積は、蒸気暖房に比べて小さくなる。"}, {"label": "4", "text": "暖房用強制対流形放熱器のファンコンベクタには、ドレンパンは不要である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["温水暖房の放熱面積は、蒸気暖房に比べて小さくなる。"], "answerHints": [["小さくなる"]], "mnemonic": "正しくは：温水暖房は放熱器の表面温度が低いため、放熱面積は蒸気暖房より大きくなる。", "block": 9, "group": 3}, {"id": "R03_zenki_14", "source": "R3前 No.14", "category": "空調・衛生", "type": "single", "question": "換気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "汚染度の高い室を換気する場合の室圧は、周囲の室より高くする。"}, {"label": "2", "text": "汚染源が固定していない室は、全体空気の入替えを行う全般換気とする。"}, {"label": "3", "text": "排気フードは、できるだけ汚染源に近接し、汚染源を囲むように設ける。"}, {"label": "4", "text": "排風機は、できるだけダクト系の末端に設け、ダクト内を負圧にする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["汚染度の高い室を換気する場合の室圧は、周囲の室より高くする。"], "answerHints": [["周囲の室より高くする"]], "mnemonic": "正しくは：汚染度の高い室の室圧は周囲より低く（負圧に）し、汚染空気を漏らさない。", "block": 9, "group": 3}, {"id": "R03_zenki_17", "source": "R3前 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "節水こま組込みの節水型給水栓は、流し洗いの場合、無意識に節水することができる。"}, {"label": "2", "text": "給水管の分岐は、上向き給水の場合は上取出し、下向き給水の場合は下取出しとする。"}, {"label": "3", "text": "飲料用給水タンクのオーバーフロー管には、排水トラップを設けてはならない。"}, {"label": "4", "text": "高置タンク方式は、他の給水方式に比べ、給水圧力の変動が大きい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["高置タンク方式は、他の給水方式に比べ、給水圧力の変動が大きい。"], "answerHints": [["給水圧力の変動が大きい"]], "mnemonic": "正しくは：高置タンク方式は、他の方式に比べて給水圧力の変動が小さい。", "block": 9, "group": 3}, {"id": "R03_zenki_20", "source": "R3前 No.20", "category": "空調・衛生", "type": "single", "question": "器具排水負荷単位法による排水管の管径の算定に関係のないものはどれか。", "choices": [{"label": "1", "text": "器具排水負荷単位数"}, {"label": "2", "text": "ブランチ間隔"}, {"label": "3", "text": "配管材質"}, {"label": "4", "text": "勾配"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["配管材質"], "answerHints": [["配管材質"]], "mnemonic": "器具排水負荷単位法では、器具排水負荷単位数・ブランチ間隔・勾配から管径を求める。配管材質は関係ない。", "block": 9, "group": 3}, {"id": "R03_zenki_23", "source": "R3前 No.23", "category": "空調・衛生", "type": "single", "question": "FRP製浄化槽の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "槽が2槽に分かれる場合においても、基礎は一体の共通基礎とする。"}, {"label": "2", "text": "ブロワーは、隣家や寝室等から離れた場所に設置する。"}, {"label": "3", "text": "通気管を設ける場合は、先下り勾配とする。"}, {"label": "4", "text": "腐食が激しい箇所のマンホールふたは、プラスチック製等としてよい。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["通気管を設ける場合は、先下り勾配とする。"], "answerHints": [["先下り勾配"]], "mnemonic": "正しくは：浄化槽の通気管は先上り勾配とする。", "block": 9, "group": 3}, {"id": "R03_kouki_10", "source": "R3後 No.10", "category": "空調・衛生", "type": "single", "question": "空気清浄装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ろ過式には、粗じん用、中性能、HEPA等がある。"}, {"label": "2", "text": "ろ過式の構造には、自動更新型、ユニット交換型等がある。"}, {"label": "3", "text": "ろ過式のろ材には、粉じん保持容量が大きく、空気抵抗が大きいことが求められる。"}, {"label": "4", "text": "静電式は、高電圧を使って粉じんを帯電させて除去する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ろ過式のろ材には、粉じん保持容量が大きく、空気抵抗が大きいことが求められる。"], "answerHints": [["空気抵抗が大きい"]], "mnemonic": "正しくは：ろ材は粉じん保持容量が大きく、空気抵抗が小さいことが求められる。", "block": 9, "group": 3}, {"id": "R03_kouki_13", "source": "R3後 No.13", "category": "空調・衛生", "type": "single", "question": "換気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "換気回数とは、換気量を室容積で除したものである。"}, {"label": "2", "text": "必要換気量とは、室内の汚染質濃度を許容値以下に保つために循環する空気量をいう。"}, {"label": "3", "text": "自然換気には、風力によるものと温度差によるものがある。"}, {"label": "4", "text": "シックハウスを防ぐには、室内中のTVOC(総揮発性有機化合物の濃度)を低く保つ必要がある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["必要換気量とは、室内の汚染質濃度を許容値以下に保つために循環する空気量をいう。"], "answerHints": [["循環する空気量"]], "mnemonic": "正しくは：必要換気量は、汚染質濃度を許容値以下に保つために取り入れる外気量。", "block": 9, "group": 3}, {"id": "R03_kouki_17", "source": "R3後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水道直結直圧方式を採用する場合は、夏季等の水圧が低くなる時期の本管水圧で決定する。"}, {"label": "2", "text": "飲料用給水タンクは、保守点検及び清掃を考慮し、容量に応じて2槽分割等にする。"}, {"label": "3", "text": "飲料用給水タンクの上部には、原則として、飲料水以外の配管を設けてはならない。"}, {"label": "4", "text": "飲料用給水タンクのオーバーフロー管には、トラップを設け、虫の侵入を防止する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用給水タンクのオーバーフロー管には、トラップを設け、虫の侵入を防止する。"], "answerHints": [["トラップを設け"]], "mnemonic": "正しくは：オーバーフロー管には排水トラップを設けてはならない（間接排水とし、管端に防虫網を設ける）。", "block": 9, "group": 3}, {"id": "R03_kouki_20", "source": "R2後 No.20 / R3後 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "通気管は、管内の水滴が自然流下によって排水管に流れるように勾配をとる。"}, {"label": "2", "text": "通気管を設ける主な目的は、トラップが破封しないようにすることである。"}, {"label": "3", "text": "排水槽に設ける通気管の最小管径は、50mmとする。"}, {"label": "4", "text": "ループ通気方式は、自己サイホン作用の防止に有効である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ループ通気方式は、自己サイホン作用の防止に有効である。"], "answerHints": [["ループ通気方式"]], "mnemonic": "正しくは：自己サイホン作用の防止に有効なのは各個通気方式。", "block": 9, "group": 3}, {"id": "R02_kouki_26", "source": "R2後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "逆止め弁は、チャッキ弁とも呼ばれ、スイング式やリフト式がある。"}, {"label": "2", "text": "自動空気抜き弁は、配管に混入した空気を自動的に排出する目的で使用する。"}, {"label": "3", "text": "ストレーナーは、配管中のゴミ等を取り除き、弁類や機器類の損傷を防ぐ目的で使用する。"}, {"label": "4", "text": "定水位調整弁は、汚水槽や雑排水槽の水位を一定に保つ目的で使用する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["定水位調整弁は、汚水槽や雑排水槽の水位を一定に保つ目的で使用する。"], "answerHints": [["汚水槽や雑排水槽"]], "mnemonic": "正しくは：定水位調整弁は受水タンク等の給水用タンクの水位を一定に保つために使用する。", "block": 9, "group": 3}, {"id": "R03_zenki_25", "source": "R3前 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "遠心ポンプでは、一般的に、吐出量が増加したときは全揚程も増加する。"}, {"label": "2", "text": "飲料用受水タンクには、鋼板製、ステンレス製、プラスチック製及び木製のものがある。"}, {"label": "3", "text": "軸流送風機は、構造的に小型で低圧力、大風量に適した送風機である。"}, {"label": "4", "text": "吸収冷温水機は、ボイラーと冷凍機の両方を設置する場合に比べ、設置面積が小さい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["遠心ポンプでは、一般的に、吐出量が増加したときは全揚程も増加する。"], "answerHints": [["全揚程も増加する"]], "mnemonic": "正しくは：遠心ポンプは吐出量が増加すると全揚程は減少する。", "block": 9, "group": 3}, {"id": "R03_kouki_24", "source": "R3後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ユニット形空気調和機は、冷却、加熱の熱源装置を持たず、ほかから供給される冷温水等を用いて空気を処理し送風する機器である。"}, {"label": "2", "text": "ファンコイルユニットは、冷温水を使用して室内空気を冷却除湿又は加熱する機器である。"}, {"label": "3", "text": "パッケージ形空気調和機は、空気熱源のものと水熱源のものがある。"}, {"label": "4", "text": "気化式加湿器は、通過する空気に水を噴霧気化させることで加湿を行う。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["気化式加湿器は、通過する空気に水を噴霧気化させることで加湿を行う。"], "answerHints": [["水を噴霧気化"]], "mnemonic": "正しくは：気化式加湿器は、水を含ませた加湿材に空気を通して気化させる（噴霧するのは水噴霧式）。", "block": 9, "group": 3}, {"id": "R03_kouki_27", "source": "R3後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ステンレス鋼板製ダクトは、厨房等の湿度の高い室の排気ダクトには使用しない。"}, {"label": "2", "text": "硬質塩化ビニル板製ダクトは、腐食性ガス等を含む排気ダクトに用いられる。"}, {"label": "3", "text": "グラスウール製ダクトは、吹出口及び吸込口のボックス等に用いられる。"}, {"label": "4", "text": "フランジ用ガスケットの材質は、繊維系、ゴム系、樹脂系がある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ステンレス鋼板製ダクトは、厨房等の湿度の高い室の排気ダクトには使用しない。"], "answerHints": [["排気ダクトには使用しない"]], "mnemonic": "正しくは：ステンレス鋼板製ダクトは、厨房等の湿度の高い室の排気ダクトに使用される。", "block": 9, "group": 3}, {"id": "R02_kouki_33", "source": "R2後 No.33", "category": "施工管理法", "type": "single", "question": "建設工事現場の安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "既設汚水ピット内の作業前における酸素濃度の測定は、酸素欠乏症等に関する特別の教育を受けた作業員が行う。"}, {"label": "2", "text": "高所作業には、高血圧症、低血圧症、心臓疾患等を有する作業員を配置しない。"}, {"label": "3", "text": "気温の高い日に作業を行う場合、熱中症予防のため、暑さ指数(WBGT)を確認する。"}, {"label": "4", "text": "軟弱地盤上にクレーンを設置する場合に、クレーンの下に強度のある鉄板を敷く。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["既設汚水ピット内の作業前における酸素濃度の測定は、酸素欠乏症等に関する特別の教育を受けた作業員が行う。"], "answerHints": [["特別の教育を受けた作業員"]], "mnemonic": "正しくは：作業前の酸素濃度測定は酸素欠乏危険作業主任者が行う。", "block": 9, "group": 3}, {"id": "R02_kouki_36", "source": "R2後 No.36", "category": "施工管理法", "type": "single", "question": "配管及び配管付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水道用硬質塩化ビニルライニング鋼管のねじ接合において、ライニング部の面取りを行う。"}, {"label": "2", "text": "硬質ポリ塩化ビニル管を横走り配管とする場合、管径の大きい鋼管から吊りボルトで吊ることができる。"}, {"label": "3", "text": "給水栓には、クロスコネクションが起きないように吐水口空間を設ける。"}, {"label": "4", "text": "給水用の仕切弁には、管端防食ねじ込み形弁等がある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["硬質ポリ塩化ビニル管を横走り配管とする場合、管径の大きい鋼管から吊りボルトで吊ることができる。"], "answerHints": [["管径の大きい鋼管から吊りボルトで吊る"]], "mnemonic": "正しくは：配管は他の配管から吊ってはならない（共吊り禁止）。", "block": 9, "group": 3}, {"id": "R02_kouki_39", "source": "R2後 No.39", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト付属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "亜鉛鉄板製長方形ダクトの剛性は、継目(はぜ)の箇所数が少ないほど高くなる。"}, {"label": "2", "text": "長方形ダクトのエルボの内側半径は、ダクト幅の1/2以上とする。"}, {"label": "3", "text": "遠心送風機の吐出し口の近くにダクトの曲がりを設ける場合、曲がり方向は送風機の回転方向と同じ方向とする。"}, {"label": "4", "text": "吹出口の配置は、吹き出し空気の拡散半径や到達距離を考慮して決定する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["亜鉛鉄板製長方形ダクトの剛性は、継目(はぜ)の箇所数が少ないほど高くなる。"], "answerHints": [["少ないほど"]], "mnemonic": "正しくは：長方形ダクトの剛性は、継目（はぜ）の箇所数が多いほど高くなる。", "block": 9, "group": 3}, {"id": "R03_zenki_29", "source": "R3前 No.29", "category": "施工管理法", "type": "single", "question": "公共工事における施工計画等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "受注者は、総合施工計画書及び工種別の施工計画書を監督員に提出する。"}, {"label": "2", "text": "発注者は、現場代理人の工事現場への常駐義務を一定の要件のもとに緩和できる。"}, {"label": "3", "text": "設計図面と標準仕様書の内容に相違がある場合は、標準仕様書の内容が優先される。"}, {"label": "4", "text": "受注者は、設計図書の内容や現場の納まりに疑義が生じた場合、監督員と協議する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["設計図面と標準仕様書の内容に相違がある場合は、標準仕様書の内容が優先される。"], "answerHints": [["標準仕様書の内容が優先される"]], "mnemonic": "正しくは：設計図面が標準仕様書より優先される（質問回答書＞現場説明書＞特記仕様書＞図面＞標準仕様書）。", "block": 9, "group": 3}, {"id": "R03_zenki_34", "source": "R3前 No.34", "category": "施工管理法", "type": "single", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給水立て管から各階への分岐管には、分岐点に近接した部分に止水弁を設ける。"}, {"label": "2", "text": "雑排水用に配管用炭素鋼鋼管を使用する場合は、ねじ込み式鋼管製管継手で接続する。"}, {"label": "3", "text": "パイプカッターは、管径が小さい銅管やステンレス鋼管の切断に使用される。"}, {"label": "4", "text": "地中で給水管と排水管を交差させる場合は、給水管を排水管より上方に埋設する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["雑排水用に配管用炭素鋼鋼管を使用する場合は、ねじ込み式鋼管製管継手で接続する。"], "answerHints": [["ねじ込み式鋼管製管継手"]], "mnemonic": "正しくは：排水用の鋼管のねじ接合には、ねじ込み式排水管継手（ドレネージ継手）を使用する。", "block": 9, "group": 3}, {"id": "R03_zenki_38", "source": "R3前 No.38", "category": "施工管理法", "type": "single", "question": "渦巻きポンプの試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "膨張タンク等から注水して、機器及び配管系の空気抜きを行う。"}, {"label": "2", "text": "吸込み側の弁を全閉から徐々に開いて吐水量を調整する。"}, {"label": "3", "text": "グランドパッキン部から一定量の水滴の滴下があることを確認する。"}, {"label": "4", "text": "軸受温度が周囲空気温度より過度に高くなっていないことを確認する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["吸込み側の弁を全閉から徐々に開いて吐水量を調整する。"], "answerHints": [["吸込み側の弁"]], "mnemonic": "正しくは：吸込み側の弁は全開とし、吐出し側の弁を全閉から徐々に開いて吐水量を調整する。", "block": 9, "group": 3}, {"id": "R03_kouki_33", "source": "R3後 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水用水中モーターポンプは、ピットの壁から200mm程度離して設置する。"}, {"label": "2", "text": "吸収冷温水機は、工場出荷時の気密が確保されていることを確認する。"}, {"label": "3", "text": "大型のボイラーの基礎は、床スラブ上に打設した無筋コンクリート基礎とする。"}, {"label": "4", "text": "防振装置付きの機器や地震力が大きくなる重量機器は、可能な限り低層階に設置する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["大型のボイラーの基礎は、床スラブ上に打設した無筋コンクリート基礎とする。"], "answerHints": [["無筋コンクリート基礎"]], "mnemonic": "正しくは：大型ボイラー等の重量機器の基礎は、床スラブと鉄筋で緊結した鉄筋コンクリート基礎とする。", "block": 9, "group": 3}, {"id": "R03_kouki_37", "source": "R2後 No.41 / R3後 No.37", "category": "施工管理法", "type": "single", "question": "試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "高置タンク方式の給水設備における残留塩素の測定は、高置タンクに最も近い水栓で行う。"}, {"label": "2", "text": "屋外騒音の測定は、冷却塔等の騒音の発生源となる機器を運転して、敷地境界線上で行う。"}, {"label": "3", "text": "マルチパッケージ形空気調和機の試運転では、運転前に、屋外機と屋内機の間の電気配線及び冷媒配管の接続について確認する。"}, {"label": "4", "text": "多翼形送風機の試運転では、軸受け温度を測定し、周囲の空気との温度差を確認する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["高置タンク方式の給水設備における残留塩素の測定は、高置タンクに最も近い水栓で行う。"], "answerHints": [["高置タンクに最も近い水栓"]], "mnemonic": "正しくは：残留塩素の測定は、高置タンクから最も遠い水栓で行う。", "block": 9, "group": 3}, {"id": "R03_zenki_51", "source": "R3前 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "給湯用の横引き配管には、勾配を設け、管内に発生した気泡を排出する。"}, {"label": "2", "text": "土中埋設の汚水排水管に雨水管を接続する場合は、ドロップ桝を介して接続する。"}, {"label": "3", "text": "銅管を鋼製金物で支持する場合は、ゴム等の絶縁材を介して支持する。"}, {"label": "4", "text": "揚水管のウォーターハンマーを防止するためには、ポンプ吐出側に防振継手を設ける。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["土中埋設の汚水排水管に雨水管を接続する場合は、ドロップ桝を介して接続する。", "揚水管のウォーターハンマーを防止するためには、ポンプ吐出側に防振継手を設ける。"], "answerHints": [["ドロップ桝"], ["防振継手"]], "mnemonic": "汚水排水管に雨水管を接続するときはトラップ桝を介す。ウォーターハンマー防止は衝撃吸収式逆止め弁や水撃防止器を設ける（防振継手は振動対策）。", "block": 9, "group": 3}, {"id": "R03_kouki_50", "source": "R3後 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "耐震ストッパーは、機器の4隅に設置し、それぞれアンカーボルト1本で基礎に固定する。"}, {"label": "2", "text": "飲料用の給水タンクは、タンクの上部が天井から100cm以上離れるように据え付ける。"}, {"label": "3", "text": "冷水ポンプのコンクリート基礎は、基礎表面に排水溝を設け、間接排水できるものとする。"}, {"label": "4", "text": "排水用水中モーターポンプは、排水槽への排水流入口に近接した位置に据え付ける。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["耐震ストッパーは、機器の4隅に設置し、それぞれアンカーボルト1本で基礎に固定する。", "排水用水中モーターポンプは、排水槽への排水流入口に近接した位置に据え付ける。"], "answerHints": [["アンカーボルト1本"], ["排水流入口に近接した"]], "mnemonic": "耐震ストッパーはアンカーボルト2本以上で基礎に固定する。排水用水中モーターポンプは排水流入口から離れた位置に据え付ける。", "block": 9, "group": 3}, {"id": "R02_kouki_43", "source": "R2後 No.43", "category": "法規", "type": "single", "question": "建設業の事業場における労働災害の防止等に関する記述のうち、「労働安全衛生法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "石綿をその重量の0.1%を超えて含有する保温材の撤去作業において、作業主任者を選任して労働者の指揮をさせる。"}, {"label": "2", "text": "ボール盤、面取り盤等を使用する作業において、手の滑りを防止するため、滑り止めを施した手袋を労働者に着用させる。"}, {"label": "3", "text": "明り掘削の作業において、運搬機械が転落するおそれがある場合、誘導者を配置して機械を誘導させる。"}, {"label": "4", "text": "明り掘削の作業において、物体の飛来又は落下による危険を防止するため、保護帽を労働者に着用させる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["ボール盤、面取り盤等を使用する作業において、手の滑りを防止するため、滑り止めを施した手袋を労働者に着用させる。"], "answerHints": [["手袋を労働者に着用させる"]], "mnemonic": "正しくは：ボール盤・面取り盤等の回転刃物の作業では、巻き込まれるおそれがあるので手袋を使用させてはならない。", "block": 9, "group": 3}, {"id": "R02_kouki_46", "source": "R2後 No.46", "category": "法規", "type": "single", "question": "建築物に設ける排水・通気設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "排水のための配管設備の汚水に接する部分は、不浸透質の耐水材料で造らなければならない。"}, {"label": "2", "text": "排水槽に設けるマンホールは、原則として、直径60cm以上の円が内接することができるものとする。"}, {"label": "3", "text": "排水管は、給水ポンプ、空気調和機その他これらに類する機器の排水管に直接連結してはならない。"}, {"label": "4", "text": "排水トラップの封水深は、阻集器を兼ねない場合、10cm以上15cm以下としなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["排水トラップの封水深は、阻集器を兼ねない場合、10cm以上15cm以下としなければならない。"], "answerHints": [["10cm以上15cm以下"]], "mnemonic": "正しくは：排水トラップの深さ（封水深）は5cm以上10cm以下。", "block": 9, "group": 3}, {"id": "R02_kouki_49", "source": "R1前 No.49 / R2後 No.49", "category": "法規", "type": "single", "question": "危険物の区分及び指定数量に関する記述のうち、「消防法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "重油は、第三石油類である。"}, {"label": "2", "text": "重油の指定数量は、2,000Lである。"}, {"label": "3", "text": "灯油は、第二石油類である。"}, {"label": "4", "text": "灯油の指定数量は、500Lである。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["灯油の指定数量は、500Lである。"], "answerHints": [["500L"]], "mnemonic": "正しくは：灯油（第二石油類）の指定数量は1,000L。重油（第三石油類）は2,000L、ガソリンは200L。", "block": 9, "group": 3}, {"id": "R02_kouki_52", "source": "R2後 No.52", "category": "法規", "type": "single", "question": "産業廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、産業廃棄物管理票(マニフェスト)を、産業廃棄物の種類にかかわらず、一括して交付することができる。"}, {"label": "2", "text": "産業廃棄物処理委託業者が収集運搬と処分の両方の業の許可を有する場合、産業廃棄物の収集運搬及び処分は、その業者に一括して委託することができる。"}, {"label": "3", "text": "事業者は、産業廃棄物管理票(マニフェスト)を、引渡しに係る産業廃棄物の運搬先が2以上である場合、運搬先ごとに交付しなければならない。"}, {"label": "4", "text": "建設工事の元請業者が、当該工事において発生させた産業廃棄物を自ら処理施設へ運搬する場合は、産業廃棄物収集運搬業の許可を必要としない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、産業廃棄物管理票(マニフェスト)を、産業廃棄物の種類にかかわらず、一括して交付することができる。"], "answerHints": [["種類にかかわらず、一括して"]], "mnemonic": "正しくは：マニフェストは産業廃棄物の種類ごと、運搬先ごとに交付する。", "block": 9, "group": 3}, {"id": "R03_zenki_41", "source": "R3前 No.41", "category": "法規", "type": "single", "question": "建築物に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "最下階の床は、主要構造部である。"}, {"label": "2", "text": "屋根は、主要構造部である。"}, {"label": "3", "text": "集会場は、特殊建築物である。"}, {"label": "4", "text": "共同住宅は、特殊建築物である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["最下階の床は、主要構造部である。"], "answerHints": [["最下階の床"]], "mnemonic": "正しくは：最下階の床は主要構造部に含まれない（主要構造部は壁・柱・床・はり・屋根・階段）。", "block": 9, "group": 3}, {"id": "R03_zenki_44", "source": "R3前 No.44", "category": "法規", "type": "single", "question": "建設業に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "元請負人は、その請け負った建設工事を施工するために必要な工程の細目、作業方法を定めようとするときは、あらかじめ、下請負人の意見をきかなければならない。"}, {"label": "2", "text": "建設業者は、建設工事の注文者から請求があったときは、請負契約の成立後、速やかに建設工事の見積書を交付しなければならない。"}, {"label": "3", "text": "工事現場における建設工事の施工に従事する者は、主任技術者又は監理技術者がその職務として行う指導に従わなければならない。"}, {"label": "4", "text": "建設業者は、共同住宅を新築する建設工事を請け負った場合、いかなる方法をもってするかを問わず、一括して他人に請け負わせてはならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設業者は、建設工事の注文者から請求があったときは、請負契約の成立後、速やかに建設工事の見積書を交付しなければならない。"], "answerHints": [["請負契約の成立後"]], "mnemonic": "正しくは：注文者から請求があったときは、請負契約が成立するまでの間に見積書を交付する。", "block": 9, "group": 3}, {"id": "R03_zenki_47", "source": "R3前 No.47", "category": "法規", "type": "single", "question": "次の「測定項目」と「法律」の組合せのうち、その法律に当該測定項目の規制値が定められていないものはどれか。", "choices": [{"label": "1", "text": "騒音値 ――――――――― 建築物における衛生的環境の確保に関する法律"}, {"label": "2", "text": "水素イオン濃度 ――――― 水質汚濁防止法"}, {"label": "3", "text": "生物化学的酸素要求量 ―― 浄化槽法"}, {"label": "4", "text": "いおう酸化物の量 ―――― 大気汚染防止法"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["騒音値 ――――――――― 建築物における衛生的環境の確保に関する法律"], "answerHints": [["騒音値"]], "mnemonic": "ビル管法の環境衛生管理基準は浮遊粉じん・CO・CO2・温度・湿度・気流・ホルムアルデヒド等で、騒音の規制値はない。", "block": 9, "group": 3}, {"id": "R03_kouki_40", "source": "R3後 No.40", "category": "法規", "type": "single", "question": "労働者に支払う賃金に関する記述のうち、「労働基準法」上、誤っているものはどれか。ただし、法令若しくは労働協約に別段の定めがある場合等、及び、労働組合等との書面による協定がある場合を除く。", "choices": [{"label": "1", "text": "賃金とは、賃金、給料、手当等、労働の対償として使用者が労働者に支払うものをいい、賞与はこれに含まれない。"}, {"label": "2", "text": "賃金は、通貨で、直接労働者に、その全額を支払わなければならない。"}, {"label": "3", "text": "賃金は、原則として、毎月1回以上一定の期日を定めて支払わなければならない。"}, {"label": "4", "text": "使用者は、労働者が疾病の費用に充てるために請求する場合においては、支払期日前であっても、既往の労働に対する賃金を支払わなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["賃金とは、賃金、給料、手当等、労働の対償として使用者が労働者に支払うものをいい、賞与はこれに含まれない。"], "answerHints": [["賞与はこれに含まれない"]], "mnemonic": "正しくは：賞与も労働の対償として支払われるものは賃金に含まれる。", "block": 9, "group": 3}, {"id": "R03_kouki_43", "source": "R3後 No.43", "category": "法規", "type": "single", "question": "建設業者が請け負った管工事について、「建設業法」上、当該工事の工事現場に置かなければならない主任技術者の要件に、該当しないものはどれか。", "choices": [{"label": "1", "text": "検定種目を管工事施工管理とする2級の技術検定に合格した者"}, {"label": "2", "text": "二級建築士免許の交付を受けた者"}, {"label": "3", "text": "建築設備士となった後、管工事に関し1年以上の実務の経験を有する者"}, {"label": "4", "text": "管工事に関し10年以上の実務の経験を有する者"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["二級建築士免許の交付を受けた者"], "answerHints": [["二級建築士免許"]], "mnemonic": "管工事の主任技術者は、2級管工事施工管理技士、建築設備士＋実務1年、実務10年以上等。二級建築士は該当しない。", "block": 9, "group": 3}, {"id": "R03_kouki_46", "source": "R3後 No.46", "category": "法規", "type": "single", "question": "次の建築設備のうち、「建築物のエネルギー消費性能の向上に関する法律」上、エネルギー消費性能が評価の対象に該当するものはどれか。", "choices": [{"label": "1", "text": "給水設備"}, {"label": "2", "text": "給湯設備"}, {"label": "3", "text": "ガス設備"}, {"label": "4", "text": "消火設備"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["評価の対象に該当するもの"], "answerTexts": ["給湯設備"], "answerHints": [["給湯設備"]], "mnemonic": "省エネ法（建築物省エネ法）の評価対象設備は空調・換気・照明・給湯・昇降機（＋太陽光発電等）。", "block": 9, "group": 3}, {"id": "R04_zenki_01", "source": "R4前 No.1", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "湿り空気の全圧が一定の場合、乾球温度と相対湿度が定まると、絶対湿度が定まる。"}, {"label": "2", "text": "絶対湿度は、湿り空気中に含まれている乾き空気1kgに対する水蒸気の質量で表す。"}, {"label": "3", "text": "飽和湿り空気の乾球温度と湿球温度は等しい。"}, {"label": "4", "text": "飽和湿り空気を冷却すると、相対湿度は上昇する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飽和湿り空気を冷却すると、相対湿度は上昇する。"], "answerHints": [["相対湿度は上昇する"]], "mnemonic": "正しくは：飽和湿り空気を冷却すると結露し、相対湿度は100%のまま（上昇しない）。", "block": 10, "group": 4}, {"id": "R04_zenki_04", "source": "R4前 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "単位質量の物体の温度を1°C上げるのに必要な熱量を比熱という。"}, {"label": "2", "text": "熱エネルギーが低温部から高温部に移動することを熱移動という。"}, {"label": "3", "text": "単一物質では、固体から液体への相変化における温度は変わらない。"}, {"label": "4", "text": "熱と仕事は、ともにエネルギーの一種であり、これらは相互に変換することができる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["熱エネルギーが低温部から高温部に移動することを熱移動という。"], "answerHints": [["低温部から高温部に"]], "mnemonic": "正しくは：熱は高温部から低温部へ移動する。", "block": 10, "group": 4}, {"id": "R04_kouki_01", "source": "R4後 No.1", "category": "一般基礎", "type": "single", "question": "空気環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "一酸化炭素は、炭素を含む物質の燃焼中に酸素が不足すると発生する気体である。"}, {"label": "2", "text": "二酸化炭素は、直接人体に有害とはならない気体で、空気より軽い。"}, {"label": "3", "text": "浮遊粉じん量は、室内空気の汚染度を示す指標の一つである。"}, {"label": "4", "text": "ホルムアルデヒドは、内装仕上げ材や家具等から放散され刺激臭を有する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["二酸化炭素は、直接人体に有害とはならない気体で、空気より軽い。"], "answerHints": [["空気より軽い"]], "mnemonic": "正しくは：二酸化炭素は空気より重い。", "block": 10, "group": 4}, {"id": "R04_kouki_04", "source": "R4後 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "熱容量の大きい物質は、温まりにくく冷えにくい。"}, {"label": "2", "text": "熱放射による熱エネルギーの伝達には、媒体が必要である。"}, {"label": "3", "text": "熱は、低温の物体から高温の物体へ自然に移ることはない。"}, {"label": "4", "text": "顕熱は、相変化を伴わない、物体の温度を変えるための熱である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["熱放射による熱エネルギーの伝達には、媒体が必要である。"], "answerHints": [["媒体が必要である"]], "mnemonic": "正しくは：熱放射は電磁波による伝達なので媒体は不要（真空中でも伝わる）。", "block": 10, "group": 4}, {"id": "R05_zenki_01", "source": "R5前 No.1", "category": "一般基礎", "type": "single", "question": "次の指標のうち、空気環境と関係のないものはどれか。", "choices": [{"label": "1", "text": "平均放射温度"}, {"label": "2", "text": "予想平均申告(PMV)"}, {"label": "3", "text": "浮遊物質(SS)"}, {"label": "4", "text": "不快指数"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["浮遊物質(SS)"], "answerHints": [["浮遊物質(SS)"]], "mnemonic": "SS（浮遊物質）は水質の指標。MRT・PMV・不快指数は温熱（空気）環境の指標。", "block": 10, "group": 4}, {"id": "R05_zenki_04", "source": "R5前 No.4", "category": "一般基礎", "type": "single", "question": "熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "気体を断熱圧縮すると温度は上がる。"}, {"label": "2", "text": "温度変化を伴わず、相変化するときに必要な熱は顕熱である。"}, {"label": "3", "text": "相変化には、融解、凝固、気化、液化、昇華等がある。"}, {"label": "4", "text": "熱伝導率は、一般的に、気体は小さく、金属は大きい。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["温度変化を伴わず、相変化するときに必要な熱は顕熱である。"], "answerHints": [["顕熱"]], "mnemonic": "正しくは：温度変化を伴わず相変化に使われる熱は潜熱。", "block": 10, "group": 4}, {"id": "R04_zenki_07", "source": "R4前 No.7", "category": "空調・衛生", "type": "single", "question": "定風量単一ダクト方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "送風量を一定にして送風温度を変化させる。"}, {"label": "2", "text": "各室ごとの温度制御が容易である。"}, {"label": "3", "text": "一般的に、空調機は機械室にあるため、維持管理が容易である。"}, {"label": "4", "text": "送風量が多いため、室内の清浄度を保ちやすい。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["各室ごとの温度制御が容易である。"], "answerHints": [["温度制御が容易"]], "mnemonic": "正しくは：定風量単一ダクト方式は各室ごとの温度制御が困難。", "block": 10, "group": 4}, {"id": "R04_zenki_11", "source": "R4前 No.11", "category": "空調・衛生", "type": "single", "question": "コールドドラフトの防止に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋外より侵入する隙間風を減らすため、外壁に面する建具の気密性を高める。"}, {"label": "2", "text": "外壁面からの熱損失を減らすため、外壁面の熱通過率を小さくする。"}, {"label": "3", "text": "窓面からの熱損失を減らすため、二重ガラスを使用する。"}, {"label": "4", "text": "自然対流形の放熱器は、できるだけ内壁側に設置する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["自然対流形の放熱器は、できるだけ内壁側に設置する。"], "answerHints": [["内壁側"]], "mnemonic": "正しくは：自然対流形の放熱器は外壁側の窓下に設置する。", "block": 10, "group": 4}, {"id": "R04_zenki_15", "source": "R4前 No.15", "category": "空調・衛生", "type": "single", "question": "上水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配水管から分水栓又はサドル付分水栓により給水管を取り出す場合、他の給水管の取り出し位置との間隔を15cm以上とする。"}, {"label": "2", "text": "簡易専用水道とは、水道事業の用に供する水道から供給を受ける水のみを水源とし、水の供給を受けるために設けられる水槽の有効容量の合計が10m3を超えるものをいう。"}, {"label": "3", "text": "浄水施設における緩速ろ過方式は、一般的に、原水水質が良好で濁度も低く安定している場合に採用される。"}, {"label": "4", "text": "給水装置とは、水道事業者の敷設した配水管から分岐して設けられた給水管及びこれに直結する給水用具をいう。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["配水管から分水栓又はサドル付分水栓により給水管を取り出す場合、他の給水管の取り出し位置との間隔を15cm以上とする。"], "answerHints": [["15cm以上"]], "mnemonic": "正しくは：給水管の取出し位置の間隔は30cm以上。", "block": 10, "group": 4}, {"id": "R04_zenki_18", "source": "R4前 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給湯配管には、水道用硬質塩化ビニルライニング鋼管を使用する。"}, {"label": "2", "text": "ヒートポンプ給湯機は、大気中の熱エネルギーを給湯の加熱に利用するものである。"}, {"label": "3", "text": "給湯配管をコンクリート内に敷設する場合は、保温材などをクッション材として機能させて、熱膨張の伸縮によって配管が破断しないように措置を行う。"}, {"label": "4", "text": "ガス瞬間湯沸器の先止め式とは、機器の出口側(給湯先)の湯栓の開閉でバーナーを着火・消火できる方式をいう。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給湯配管には、水道用硬質塩化ビニルライニング鋼管を使用する。"], "answerHints": [["水道用硬質塩化ビニルライニング鋼管"]], "mnemonic": "正しくは：給湯配管には水道用耐熱性硬質塩化ビニルライニング鋼管を使う。", "block": 10, "group": 4}, {"id": "R04_zenki_21", "source": "R4前 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "1号消火栓は、防火対象物の階ごとに、その階の各部からの水平距離が25m以下となるように設置する。"}, {"label": "2", "text": "屋内消火栓箱には、床面からの高さが1.2mの位置に、ポンプによる加圧送水装置の停止用押しボタンを設置する。"}, {"label": "3", "text": "2号消火栓(広範囲型を除く。)は、防火対象物の階ごとに、その階の各部からの水平距離が15m以下となるように設置する。"}, {"label": "4", "text": "屋内消火栓の開閉弁は、自動式のものでない場合、床面からの高さが1.5m以下の位置に設置する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["屋内消火栓箱には、床面からの高さが1.2mの位置に、ポンプによる加圧送水装置の停止用押しボタンを設置する。"], "answerHints": [["停止用押しボタン"]], "mnemonic": "正しくは：加圧送水装置は直接操作によってのみ停止できるもの（消火栓箱に停止ボタンは設けない）。", "block": 10, "group": 4}, {"id": "R04_kouki_07", "source": "R4後 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ファンコイルユニット・ダクト併用方式は、全空気方式に比べてダクトスペースが小さくなる。"}, {"label": "2", "text": "ファンコイルユニット・ダクト併用方式は、ファンコイルユニット毎の個別制御が困難である。"}, {"label": "3", "text": "パッケージ形空気調和機方式は、全熱交換ユニット等を使うなどして外気を取り入れる必要がある。"}, {"label": "4", "text": "パッケージ形空気調和機方式の冷媒配管は、長さが短く高低差が小さい方が運転効率が良い。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ファンコイルユニット・ダクト併用方式は、ファンコイルユニット毎の個別制御が困難である。"], "answerHints": [["困難"]], "mnemonic": "正しくは：FCU・ダクト併用方式はファンコイルユニット毎の個別制御が可能。", "block": 10, "group": 4}, {"id": "R04_kouki_11", "source": "R4後 No.11", "category": "空調・衛生", "type": "single", "question": "放射冷暖房方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "放射冷暖房方式は、室内における上下の温度差が少ない。"}, {"label": "2", "text": "放射暖房方式は、天井の高いホール等では良質な温熱環境を得られにくい。"}, {"label": "3", "text": "放射冷房方式は、放熱面温度を下げすぎると放熱面で結露を生じる場合がある。"}, {"label": "4", "text": "放射冷房方式は、室内空気温度を高めに設定しても温熱感的には快適な室内環境を得ることができる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["放射暖房方式は、天井の高いホール等では良質な温熱環境を得られにくい。"], "answerHints": [["得られにくい"]], "mnemonic": "正しくは：放射暖房は上下温度差が小さく、天井の高いホール等でも良質な温熱環境が得られる。", "block": 10, "group": 4}, {"id": "R04_kouki_14", "source": "R4後 No.14", "category": "空調・衛生", "type": "single", "question": "換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "第二種機械換気方式は、建具等からの室への空気の侵入を抑制できる。"}, {"label": "2", "text": "局所換気は、汚染物質を汚染源の近くで補そく・処理するため、周辺の室内環境を衛生的かつ安全に保つうえで有効である。"}, {"label": "3", "text": "温度差を利用する自然換気方式では、換気対象室のなるべく高い位置に給気口を設ける。"}, {"label": "4", "text": "外気を導入し居室の換気を行う場合は、外気の二酸化炭素濃度も考慮する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["温度差を利用する自然換気方式では、換気対象室のなるべく高い位置に給気口を設ける。"], "answerHints": [["高い位置に給気口"]], "mnemonic": "正しくは：温度差換気は低い位置に給気口、高い位置に排気口。", "block": 10, "group": 4}, {"id": "R04_kouki_17", "source": "R4後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "揚程が30mを超える給水ポンプの吐出し側に取り付ける逆止め弁は、衝撃吸収式とする。"}, {"label": "2", "text": "受水タンクのオーバーフローの取り出しは、給水吐水口端の高さより上方からとする。"}, {"label": "3", "text": "受水タンクへの給水には、ウォーターハンマーを起こりにくくするため、一般的に、定水位弁が用いられる。"}, {"label": "4", "text": "クロスコネクションとは、飲料用系統とその他の系統が、配管・装置により直接接続されることをいう。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["受水タンクのオーバーフローの取り出しは、給水吐水口端の高さより上方からとする。"], "answerHints": [["より上方から"]], "mnemonic": "正しくは：オーバーフローは給水吐水口端より下方から取り出す（吐水口空間を確保）。", "block": 10, "group": 4}, {"id": "R04_kouki_20", "source": "R4後 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "トラップの封水は、誘導サイホン作用、自己サイホン作用、蒸発、毛管現象等により損失する場合がある。"}, {"label": "2", "text": "建物内で用いられる代表的な排水通気方式には、ループ通気方式、各個通気方式、伸頂通気方式等がある。"}, {"label": "3", "text": "各個通気管は、器具のトラップ下流側の排水管より取り出す。"}, {"label": "4", "text": "管トラップの形式には、Sトラップ、Pトラップ、Uトラップ及びわんトラップがある。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["管トラップの形式には、Sトラップ、Pトラップ、Uトラップ及びわんトラップがある。"], "answerHints": [["わんトラップ"]], "mnemonic": "正しくは：管トラップはSトラップ・Pトラップ・Uトラップ。わんトラップは隔壁トラップ（非サイホン式）。", "block": 10, "group": 4}, {"id": "R05_zenki_08", "source": "R5前 No.8", "category": "空調・衛生", "type": "single", "question": "定風量単一ダクト方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "各室ごとの温度制御が容易である。"}, {"label": "2", "text": "送風量を一定にして送風温度を変化させる。"}, {"label": "3", "text": "空気調和機は、一般的に、機械室に設置されているため維持管理が容易である。"}, {"label": "4", "text": "送風量が多いため、室内の清浄度を保ちやすい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["各室ごとの温度制御が容易である。"], "answerHints": [["温度制御が容易"]], "mnemonic": "正しくは：定風量単一ダクト方式は各室ごとの温度制御が困難。", "block": 10, "group": 4}, {"id": "R05_zenki_11", "source": "R5前 No.11", "category": "空調・衛生", "type": "single", "question": "暖房設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "温水暖房は、温水の顕熱を利用している。"}, {"label": "2", "text": "蒸気暖房は、温水暖房に比べて制御性が良い。"}, {"label": "3", "text": "蒸気暖房のウォーミングアップにかかる時間は、温水暖房に比べて短い。"}, {"label": "4", "text": "温水暖房に使用する温水の温度は、一般的に、50〜60°Cとする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["蒸気暖房は、温水暖房に比べて制御性が良い。"], "answerHints": [["制御性が良い"]], "mnemonic": "正しくは：制御性が良いのは温水暖房。蒸気暖房は制御性が劣る。", "block": 10, "group": 4}, {"id": "R05_zenki_14", "source": "R5前 No.14", "category": "空調・衛生", "type": "single", "question": "換気の「対象となる室」と「換気の必要な主な要因」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "浴室 ―――――――――― 水蒸気"}, {"label": "2", "text": "車庫 ―――――――――― 有害ガス"}, {"label": "3", "text": "エレベーター機械室 ――― 熱"}, {"label": "4", "text": "ポンプ室 ―――――――― 酸素供給"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ポンプ室 ―――――――― 酸素供給"], "answerHints": [["酸素供給"]], "mnemonic": "酸素供給が主な要因となるのはボイラー室など燃焼器具のある室。浴室＝水蒸気、車庫＝有害ガス、EV機械室＝熱。", "block": 10, "group": 4}, {"id": "R05_zenki_17", "source": "R5前 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給水量の算定に用いられる器具給水負荷単位による方法では、給水管が受け持つ器具給水負荷単位の総和から、瞬時最大給水流量を求める。"}, {"label": "2", "text": "受水タンクの吐水側配管に取り付ける緊急遮断弁は、受水タンク内の残留塩素が規定値以下となる場合に給水を遮断する目的で設置される。"}, {"label": "3", "text": "大気圧式バキュームブレーカーは、大便器洗浄弁等と組み合わせて使用される。"}, {"label": "4", "text": "飲料用給水タンクには、直径60cm以上の円が内接するマンホールを設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["受水タンクの吐水側配管に取り付ける緊急遮断弁は、受水タンク内の残留塩素が規定値以下となる場合に給水を遮断する目的で設置される。"], "answerHints": [["残留塩素"]], "mnemonic": "正しくは：緊急遮断弁は地震時等に給水を遮断し、受水タンク内の水を確保する目的で設ける。", "block": 10, "group": 4}, {"id": "R05_zenki_21", "source": "R5前 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "2号消火栓(広範囲型を除く。)は、防火対象物の階ごとに、その階の各部分からホース接続口までの水平距離が20m以下となるようにする。"}, {"label": "2", "text": "屋内消火栓の加圧送水装置は、直接操作によってのみ停止できるものとする。"}, {"label": "3", "text": "1号消火栓は、防火対象物の階ごとに、その階の各部分からホース接続口までの水平距離が25m以下となるようにする。"}, {"label": "4", "text": "屋内消火栓の開閉弁の位置は、自動式のものでない場合、床面からの高さを1.5m以下とする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["2号消火栓(広範囲型を除く。)は、防火対象物の階ごとに、その階の各部分からホース接続口までの水平距離が20m以下となるようにする。"], "answerHints": [["20m以下"]], "mnemonic": "正しくは：2号消火栓（広範囲型を除く）は水平距離15m以下（1号は25m以下）。", "block": 10, "group": 4}, {"id": "R04_zenki_25", "source": "R4前 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "飲料用給水タンクに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "鋼板製タンク内の防錆処理は、エポキシ樹脂等の樹脂系塗料によるコーティングを施す。"}, {"label": "2", "text": "FRP製タンクは、軽量で施工性に富み、日光を遮断し紫外線にも強い等優れた特性を持つ。"}, {"label": "3", "text": "ステンレス鋼板製タンクを使用する場合、タンク内上部の気相部は塩素が滞留しやすいので耐食性に優れたステンレスを使用する。"}, {"label": "4", "text": "通気口は、衛生上有害なものが入らない構造とし、防虫網を設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["FRP製タンクは、軽量で施工性に富み、日光を遮断し紫外線にも強い等優れた特性を持つ。"], "answerHints": [["日光を遮断し", "紫外線にも強い"]], "mnemonic": "正しくは：FRP製タンクは光を透過しやすく藻が発生しやすい。紫外線にも弱い。", "block": 10, "group": 4}, {"id": "R04_kouki_24", "source": "R4後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "パッケージ形空気調和機は、圧縮機、熱源側熱交換器、利用側熱交換器、膨張弁、送風機、エアフィルター等が、屋外機や屋内機に収納される。"}, {"label": "2", "text": "ユニット形空気調和機の風量調節には、インバーター、スクロールダンパー及びインレットベーン方式があり、省エネルギー効果が最も高いのはインバーター方式である。"}, {"label": "3", "text": "ガスエンジンヒートポンプ式空気調和機は、エンジンの排ガスや冷却水の排熱の有効利用により高い冷房能力が得られる。"}, {"label": "4", "text": "ユニット形空気調和機は、冷却、加熱の熱源装置を持たず、ほかから供給される冷温水等を用いて空気を処理し送風する機器である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ガスエンジンヒートポンプ式空気調和機は、エンジンの排ガスや冷却水の排熱の有効利用により高い冷房能力が得られる。"], "answerHints": [["冷房能力"]], "mnemonic": "正しくは：GHPはエンジン排熱の有効利用により高い暖房能力が得られる。", "block": 10, "group": 4}, {"id": "R04_kouki_27", "source": "R4後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "長方形ダクトの板厚は、ダクトの周長により決定する。"}, {"label": "2", "text": "長方形ダクトのアスペクト比(長辺/短辺)は、原則として4以下とする。"}, {"label": "3", "text": "フレキシブルダクトは、一般的に、ダクトと吹出口等との接続用として用いられる。"}, {"label": "4", "text": "変風量ユニットは、室内の負荷変動に応じて風量を変化させるものである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["長方形ダクトの板厚は、ダクトの周長により決定する。"], "answerHints": [["周長"]], "mnemonic": "正しくは：長方形ダクトの板厚はダクトの長辺の長さで決まる。", "block": 10, "group": 4}, {"id": "R05_zenki_26", "source": "R5前 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水道用硬質塩化ビニルライニング鋼管のうちSGP−VDは、配管用炭素鋼鋼管(黒)の内面と外面に硬質ポリ塩化ビニルをライニングしたものである。"}, {"label": "2", "text": "ストレーナーは、配管中のゴミ等を取り除き、弁類や機器類の損傷を防ぐ目的で使用される。"}, {"label": "3", "text": "一般配管用ステンレス鋼鋼管は、給水、給湯、冷温水、冷却水等に使用される。"}, {"label": "4", "text": "ボール弁は、逆流を防止する弁であり、流体の流れ方向を一定に保つことができる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボール弁は、逆流を防止する弁であり、流体の流れ方向を一定に保つことができる。"], "answerHints": [["ボール弁"]], "mnemonic": "正しくは：逆流を防止し流れ方向を一定に保つのは逆止め弁（チャッキ弁）。", "block": 10, "group": 4}, {"id": "R04_zenki_31", "source": "R3前 No.31 / R4前 No.31", "category": "施工管理法", "type": "single", "question": "品質を確認するための検査に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "防火区画の穴埋めは、全数検査で確認する。"}, {"label": "2", "text": "給水配管の水圧試験は、全数検査で確認する。"}, {"label": "3", "text": "ボイラーの安全弁の作動は、全数検査で確認する。"}, {"label": "4", "text": "防火ダンパーの温度ヒューズの作動は、全数検査で確認する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火ダンパーの温度ヒューズの作動は、全数検査で確認する。"], "answerHints": [["全数検査"]], "mnemonic": "正しくは：防火ダンパーの温度ヒューズの作動確認は抜取検査（破壊を伴うため）。", "block": 10, "group": 4}, {"id": "R04_zenki_34", "source": "R4前 No.34", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷媒配管の銅管の接合には、差込接合(ろう付け)、フランジ接合、フレア接合がある。"}, {"label": "2", "text": "水道用硬質塩化ビニルライニング鋼管のねじ接合においては、配管切断後、ライニング部の面取りを行う。"}, {"label": "3", "text": "排水立て管は、下層階に行くに従い、途中で合流する排水量に応じて管径を大きくする。"}, {"label": "4", "text": "給水管の埋設深さは、私道内の車両通路(重車両通路部は除く。)では600mm以上とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水立て管は、下層階に行くに従い、途中で合流する排水量に応じて管径を大きくする。"], "answerHints": [["管径を大きくする"]], "mnemonic": "正しくは：排水立て管は最下部の最大管径で、上部から下部まで同一管径とする。", "block": 10, "group": 4}, {"id": "R04_zenki_37", "source": "R4前 No.37", "category": "施工管理法", "type": "single", "question": "吐出しダンパーにより風量を調整する多翼送風機の試運転調整における一般的な実施順序として適当なものはどれか。\nA:手元スイッチで瞬時運転し、回転方向を確認する。\nB:吐出しダンパーを全開にする。\nC:吐出しダンパーを全閉にする。\nD:送風機を運転する。\nE:軸受温度を点検する。\nF:吐出しダンパーを徐々に開いて規定風量に調節する。\nG:吐出しダンパーを徐々に閉じて規定風量に調節する。", "choices": [{"label": "1", "text": "A → B → D → G → E"}, {"label": "2", "text": "A → B → D → E → G"}, {"label": "3", "text": "B → A → D → G → E"}, {"label": "4", "text": "C → A → D → F → E"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["C → A → D → F → E"], "answerHints": [["C", "F"]], "mnemonic": "ダンパー全閉→瞬時運転で回転方向確認→運転→ダンパーを徐々に開いて規定風量→軸受温度点検。", "block": 10, "group": 4}, {"id": "R04_kouki_31", "source": "R4後 No.31", "category": "施工管理法", "type": "single", "question": "品質を確認するための検査に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "抜取検査には、計数抜取検査と計量抜取検査がある。"}, {"label": "2", "text": "品物を破壊しなければ検査の目的を達し得ない場合は、全数検査を行う。"}, {"label": "3", "text": "不良品を見逃すと人身事故のおそれがある場合は、全数検査を行う。"}, {"label": "4", "text": "抜取検査では、ロットとして、合格、不合格が判定される。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["品物を破壊しなければ検査の目的を達し得ない場合は、全数検査を行う。"], "answerHints": [["全数検査を行う"]], "mnemonic": "正しくは：破壊しなければ検査できないものは抜取検査とする。", "block": 10, "group": 4}, {"id": "R04_kouki_34", "source": "R4後 No.34", "category": "施工管理法", "type": "single", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "呼び径100の屋内横走り排水管の最小勾配は、1/200とする。"}, {"label": "2", "text": "排水トラップの封水深は、50mm以上100mm以下とする。"}, {"label": "3", "text": "便所の床下排水管は、一般的に、勾配を考慮して排水管を給水管より先に施工する。"}, {"label": "4", "text": "3階以上にわたる排水立て管には、各階ごとに満水試験継手を取り付ける。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["呼び径100の屋内横走り排水管の最小勾配は、1/200とする。"], "answerHints": [["1/200"]], "mnemonic": "正しくは：呼び径100の排水横管の最小勾配は1/100。", "block": 10, "group": 4}, {"id": "R04_kouki_37", "source": "R4後 No.37", "category": "施工管理法", "type": "single", "question": "異種管の接合に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "金属異種管の接合でイオン化傾向が大きく異なるものは、絶縁継手を介して接合する。"}, {"label": "2", "text": "配管用炭素鋼鋼管と銅管の接合は、絶縁フランジ接合とする。"}, {"label": "3", "text": "配管用炭素鋼鋼管とステンレス鋼管の接合は、防振継手を介して接合する。"}, {"label": "4", "text": "配管用炭素鋼鋼管と硬質塩化ビニル管の接合は、ユニオン又はソケットを用いて接合する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["配管用炭素鋼鋼管とステンレス鋼管の接合は、防振継手を介して接合する。"], "answerHints": [["防振継手"]], "mnemonic": "正しくは：鋼管とステンレス鋼管は絶縁継手（絶縁フランジ等）を介して接合する。", "block": 10, "group": 4}, {"id": "R05_zenki_32", "source": "R5前 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "脚立の脚と水平面との角度は、75度以下とする。"}, {"label": "2", "text": "天板高さ70cm以上の可搬式作業台には、手掛かり棒を設置することが望ましい。"}, {"label": "3", "text": "建設工事の死亡災害は、全産業の約1割を占め、墜落・転落による事故が多い。"}, {"label": "4", "text": "折りたたみ式の脚立は、脚と水平面との角度を確実に保つための金具等を備えたものとする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["建設工事の死亡災害は、全産業の約1割を占め、墜落・転落による事故が多い。"], "answerHints": [["約1割"]], "mnemonic": "正しくは：建設業の死亡災害は全産業の約3割を占め、墜落・転落が多い。", "block": 10, "group": 4}, {"id": "R05_zenki_35", "source": "R5前 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "変風量(VAV)ユニットを天井内に設ける場合は、制御部を点検できるようにする。"}, {"label": "2", "text": "フレキシブルダクトを使用する場合は、有効断面を損なわないよう施工する必要がある。"}, {"label": "3", "text": "厨房の排気は、油等が含まれるため、ダクトの継目及び継手にシールを施す。"}, {"label": "4", "text": "コーナーボルト工法は、フランジ押え金具で接合するので、ボルト・ナットを必要としない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["コーナーボルト工法は、フランジ押え金具で接合するので、ボルト・ナットを必要としない。"], "answerHints": [["ボルト・ナットを必要としない"]], "mnemonic": "正しくは：コーナーボルト工法は四隅をボルト・ナットで締め付け、フランジ押え金具を併用する。", "block": 10, "group": 4}, {"id": "R05_zenki_38", "source": "R5前 No.38", "category": "施工管理法", "type": "single", "question": "JISで規定されている配管系の識別表示について、管内の「物質の種類」とその「識別色」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "蒸気 ――― 青"}, {"label": "2", "text": "ガス ――― うすい黄"}, {"label": "3", "text": "油 ―――― 茶色"}, {"label": "4", "text": "電気 ――― うすい黄赤"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["蒸気 ――― 青"], "answerHints": [["青"]], "mnemonic": "正しくは：蒸気は暗い赤。青は水。ガス＝うすい黄、油＝茶色、電気＝うすい黄赤。", "block": 10, "group": 4}, {"id": "R04_zenki_51", "source": "R4前 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "飲料用タンクに設ける間接排水管の最小排水口空間は、100mmとする。"}, {"label": "2", "text": "フレキシブルジョイントは、温水配管の熱収縮を吸収するために使用する。"}, {"label": "3", "text": "給水栓には、クロスコネクションが起きないように吐水口空間を設ける。"}, {"label": "4", "text": "鋼管のねじ接合においては、余ねじ部に錆止めペイントを塗布する。"}], "answer": ["1", "2"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用タンクに設ける間接排水管の最小排水口空間は、100mmとする。", "フレキシブルジョイントは、温水配管の熱収縮を吸収するために使用する。"], "answerHints": [["100mm"], ["熱収縮"]], "mnemonic": "正しくは：飲料用タンクの間接排水の排水口空間は最小150mm。熱伸縮の吸収は伸縮管継手（フレキシブルジョイントは変位・振動吸収）。", "block": 10, "group": 4}, {"id": "R04_kouki_50", "source": "R4後 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ユニット形空気調和機の基礎の高さは、ドレンパンからの排水に空調機用トラップを設けるため150mm程度とする。"}, {"label": "2", "text": "冷却塔を建物の屋上に設置する場合は、防振装置を取り付けてはならない。"}, {"label": "3", "text": "冷凍機に接続する冷水、冷却水の配管は、荷重が直接本体にかからないようにする。"}, {"label": "4", "text": "排水用水中モーターポンプは、ピットの壁から50mm程度離して設置する。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["冷却塔を建物の屋上に設置する場合は、防振装置を取り付けてはならない。", "排水用水中モーターポンプは、ピットの壁から50mm程度離して設置する。"], "answerHints": [["取り付けてはならない"], ["50mm程度"]], "mnemonic": "正しくは：屋上の冷却塔には防振装置を取り付けてもよい（耐震ストッパー併用）。水中モーターポンプはピット壁から200mm程度離す。", "block": 10, "group": 4}, {"id": "R05_zenki_49", "source": "R5前 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程表に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ガントチャート工程表は、各作業の現時点での進行状態を棒グラフで示した図表である。"}, {"label": "2", "text": "バーチャート工程表は、工期に対する各作業の影響の度合いが正確に把握できる。"}, {"label": "3", "text": "ネットワーク工程表は、フロート(余裕時間)がわからないため、配員計画を立てにくい。"}, {"label": "4", "text": "タクト工程表は、同じ作業を繰り返し行う場合に用いられる。"}], "answer": ["2", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表は、工期に対する各作業の影響の度合いが正確に把握できる。", "ネットワーク工程表は、フロート(余裕時間)がわからないため、配員計画を立てにくい。"], "answerHints": [["正確に把握できる"], ["わからない", "立てにくい"]], "mnemonic": "正しくは：バーチャートは各作業の工期への影響度合いを把握しにくい。ネットワーク工程表はフロートがわかるので労務・材料計画を立てやすい。", "block": 10, "group": 4}, {"id": "R05_zenki_52", "source": "R5前 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "フレキシブルダクトは、吸込口ボックスの接続用に使用してはならない。"}, {"label": "2", "text": "変風量(VAV)ユニットの上流側が整流でなくても、風量制御特性に影響を及ぼすことはない。"}, {"label": "3", "text": "浴室の排気に長方形ダクトを使用する場合は、ダクトの角の継目が下面とならないように取り付ける。"}, {"label": "4", "text": "送風機に接続するたわみ継手のフランジ間隔は、たわみ量を考慮し決定する。"}], "answer": ["1", "2"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["フレキシブルダクトは、吸込口ボックスの接続用に使用してはならない。", "変風量(VAV)ユニットの上流側が整流でなくても、風量制御特性に影響を及ぼすことはない。"], "answerHints": [["使用してはならない"], ["影響を及ぼすことはない"]], "mnemonic": "正しくは：フレキシブルダクトは吹出口・吸込口ボックスの接続に使用してよい。VAVユニット上流側が整流でないと風量制御特性に影響する。", "block": 10, "group": 4}, {"id": "R04_zenki_41", "source": "R4前 No.41", "category": "法規", "type": "single", "question": "建築物に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建築基準法は、建築物の敷地、構造、設備及び用途に関する最低の基準を定めている。"}, {"label": "2", "text": "建築物に設ける避雷針は、建築設備である。"}, {"label": "3", "text": "熱源機器の過半を更新する工事は、大規模の修繕である。"}, {"label": "4", "text": "コンクリートとガラスは、いずれも耐水材料である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["熱源機器の過半を更新する工事は、大規模の修繕である。"], "answerHints": [["大規模の修繕である"]], "mnemonic": "正しくは：熱源機器（建築設備）の更新は大規模の修繕に当たらない。大規模の修繕は主要構造部の一種以上の過半の修繕。", "block": 10, "group": 4}, {"id": "R04_zenki_44", "source": "R4前 No.44", "category": "法規", "type": "single", "question": "建設業を営もうとする者のうち、「建設業法」上、必要となる建設業の許可が国土交通大臣の許可に限られるものはどれか。ただし、政令で定める軽微な建設工事のみを請け負うことを営業とする者は除く。", "choices": [{"label": "1", "text": "許可を受けた建設業の建設工事を請け負い、それに附帯する他の建設業の建設工事も請け負おうとする者"}, {"label": "2", "text": "二以上の都道府県の区域内に営業所を設けて営業しようとする者"}, {"label": "3", "text": "建設工事を発注者から直接請け負い、施工しようとする者"}, {"label": "4", "text": "4,500万円以上の下請契約を締結して管工事を施工しようとする者"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["国土交通大臣の許可に限られるもの"], "answerTexts": ["二以上の都道府県の区域内に営業所を設けて営業しようとする者"], "answerHints": [["二以上の都道府県"]], "mnemonic": "2以上の都道府県に営業所→国土交通大臣許可。1つの都道府県のみ→知事許可。", "block": 10, "group": 4}, {"id": "R04_zenki_47", "source": "R4前 No.47", "category": "法規", "type": "single", "question": "浄化槽に関する記述のうち、「浄化槽法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "終末処理下水道又はし尿処理施設で処理する場合を除き、浄化槽で処理した後でなければ、し尿を公共用水域等に放流してはならない。"}, {"label": "2", "text": "浄化槽工事を行うときは、浄化槽設備士の資格を有する者が自ら工事を行う場合を除き、浄化槽設備士に実地に監督させなければならない。"}, {"label": "3", "text": "浄化槽を設置した場合、使用を開始する前に、指定検査機関の水質検査を受けなければならない。"}, {"label": "4", "text": "浄化槽を工場で製造する場合、浄化槽の型式について、国土交通大臣の認定を受けなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["浄化槽を設置した場合、使用を開始する前に、指定検査機関の水質検査を受けなければならない。"], "answerHints": [["使用を開始する前に"]], "mnemonic": "正しくは：水質検査（7条検査）は使用開始後3月を経過した日から5月以内に受ける。", "block": 10, "group": 4}, {"id": "R04_kouki_41", "source": "R4後 No.41", "category": "法規", "type": "single", "question": "建築物の面積、高さ及び階数の算定方法に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建築物の外壁又はこれに代わる柱の中心線から水平距離1m突き出たひさしの水平投影面積は、当該建築物の建築面積に算入しない。"}, {"label": "2", "text": "建築物の塔屋部分は、その用途と面積にかかわらず建築物の階数に算入しない。"}, {"label": "3", "text": "延べ面積は、建築物の各階の床面積の合計である。"}, {"label": "4", "text": "屋根の棟飾りは、建築物の高さに算入しない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建築物の塔屋部分は、その用途と面積にかかわらず建築物の階数に算入しない。"], "answerHints": [["その用途と面積にかかわらず"]], "mnemonic": "正しくは：塔屋等は水平投影面積の合計が建築面積の1/8以下の場合に限り階数に算入しない。", "block": 10, "group": 4}, {"id": "R04_kouki_44", "source": "R4後 No.44", "category": "法規", "type": "single", "question": "建設業に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建設業者は、建設工事の注文者から請求があったときは、請負契約の成立後、速やかに建設工事の見積書を交付しなければならない。"}, {"label": "2", "text": "建設業者は、共同住宅を新築する建設工事を請け負った場合、いかなる方法をもってするかを問わず、一括して他人に請け負わせてはならない。"}, {"label": "3", "text": "請負人は、現場代理人を置く場合においては、当該現場代理人の権限に関する事項等を、書面により注文者に通知しなければならない。"}, {"label": "4", "text": "建設工事の請負契約の当事者は、契約の締結に際して、工事内容、請負代金の額、工事着手の時期及び工事完成の時期等を書面に記載し、相互に交付しなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設業者は、建設工事の注文者から請求があったときは、請負契約の成立後、速やかに建設工事の見積書を交付しなければならない。"], "answerHints": [["請負契約の成立後"]], "mnemonic": "正しくは：見積書は請負契約が成立するまでの間に交付する。", "block": 10, "group": 4}, {"id": "R04_kouki_47", "source": "R4後 No.47", "category": "法規", "type": "single", "question": "「騒音規制法」上、特定建設作業に伴って発生する騒音を規制する指定地域内において、災害その他非常の事態の発生により当該特定建設作業を緊急に行う必要がある場合にあっても、当該騒音について規制が適用されるものはどれか。", "choices": [{"label": "1", "text": "1日14時間を超えて行われる作業に伴って発生する騒音"}, {"label": "2", "text": "深夜に行われる作業に伴って発生する騒音"}, {"label": "3", "text": "連続して6日間を超えて行われる作業に伴って発生する騒音"}, {"label": "4", "text": "作業場所の敷地境界線において、85デシベルを超える大きさの騒音"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適用されるもの"], "answerTexts": ["作業場所の敷地境界線において、85デシベルを超える大きさの騒音"], "answerHints": [["85デシベル"]], "mnemonic": "災害等の緊急作業でも、敷地境界85dBの大きさ規制は適用。作業時間帯・1日の時間・連続日数の規制は適用除外。", "block": 10, "group": 4}, {"id": "R05_zenki_40", "source": "R5前 No.40", "category": "法規", "type": "single", "question": "労働時間に関する記述のうち、「労働基準法」上、誤っているものはどれか。ただし、労働組合等との協定等による別の定めがある場合を除く。", "choices": [{"label": "1", "text": "使用者は、その雇入れの日から起算して6箇月間継続勤務し全労働日の8割以上出勤した労働者に対して、10労働日の有給休暇を与えなければならない。"}, {"label": "2", "text": "使用者は、労働者に、休憩時間を除き1週間について38時間を超えて、労働させてはならない。"}, {"label": "3", "text": "使用者は、労働者に対して、毎週少なくとも1回の休日、又は4週間を通じ4日以上の休日を与えなければならない。"}, {"label": "4", "text": "使用者は、労働時間が8時間を超える場合においては少なくとも1時間の休憩時間を労働時間の途中に与えなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["使用者は、労働者に、休憩時間を除き1週間について38時間を超えて、労働させてはならない。"], "answerHints": [["38時間"]], "mnemonic": "正しくは：法定労働時間は1週40時間（1日8時間）。", "block": 10, "group": 4}, {"id": "R05_zenki_44", "source": "R5前 No.44", "category": "法規", "type": "single", "question": "管工事業に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "管工事業の許可を受けた者は、工事1件の請負代金の額が500万円未満の工事を施工する場合でも、主任技術者を置く必要がある。"}, {"label": "2", "text": "管工事を下請負人としてのみ施工する者は、請負代金の額に関わらず管工事業の許可を受けなくてもよい。"}, {"label": "3", "text": "2級管工事施工管理技士は、管工事業に係る一般建設業の許可を受ける際、営業所ごとに専任で置く技術者の要件を満たしている。"}, {"label": "4", "text": "管工事業の許可を受けた者が管工事を請け負う場合、当該工事に附帯する電気工事を請け負うことができる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["管工事を下請負人としてのみ施工する者は、請負代金の額に関わらず管工事業の許可を受けなくてもよい。"], "answerHints": [["請負代金の額に関わらず"]], "mnemonic": "正しくは：下請負人でも軽微な建設工事（500万円未満）以外を請け負うには管工事業の許可が必要。", "block": 10, "group": 4}, {"id": "R05_zenki_47", "source": "R5前 No.47", "category": "法規", "type": "single", "question": "「法律」と「測定項目」の組合せのうち、当該法律上、定められていないものはどれか。", "choices": [{"label": "1", "text": "大気汚染防止法 ――― いおう酸化物の量"}, {"label": "2", "text": "水質汚濁防止法 ――― 水素イオン濃度"}, {"label": "3", "text": "建築物における衛生的環境の確保に関する法律――――ばいじん量"}, {"label": "4", "text": "浄化槽法 ―――――― 溶存酸素量"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["建築物における衛生的環境の確保に関する法律――――ばいじん量"], "answerHints": [["ばいじん量"]], "mnemonic": "ビル管法で測定するのは浮遊粉じん量。ばいじんは大気汚染防止法の規制項目。", "block": 10, "group": 4}, {"id": "R04_zenki_02", "source": "R4前 No.2", "category": "一般基礎", "type": "single", "question": "水に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "濁度は水の濁りの程度を示し、色度は水の色の程度を示す度数である。"}, {"label": "2", "text": "CODは、汚濁水を酸化剤で化学的に酸化するときに消費される酸素量をいう。"}, {"label": "3", "text": "DOは、水に溶けない懸濁性の物質の量を示す指標である。"}, {"label": "4", "text": "硬度は、水中に溶存するカルシウムイオン及びマグネシウムイオンの量を示す指標である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["DOは、水に溶けない懸濁性の物質の量を示す指標である。"], "answerHints": [["水に溶けない懸濁性の物質"]], "mnemonic": "正しくは：DOは溶存酸素量。水に溶けない懸濁性物質の量はSS（浮遊物質）。", "block": 11, "group": 4}, {"id": "R04_zenki_05", "source": "R4前 No.5", "category": "一般基礎", "type": "single", "question": "電気設備に関する「機器又は方式」と「特徴」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "進相コンデンサ ―――――― 回路の力率を改善できる。"}, {"label": "2", "text": "3Eリレー(保護継電器) ―― 回路の逆相(反相)を保護できる。"}, {"label": "3", "text": "全電圧始動(直入始動) ―― 始動時のトルクを制御できる。"}, {"label": "4", "text": "スターデルタ始動 ――――― 始動時の電流を抑制できる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["全電圧始動(直入始動) ―― 始動時のトルクを制御できる。"], "answerHints": [["トルクを制御できる"]], "mnemonic": "正しくは：全電圧始動（直入始動）は始動時のトルクを制御できない（始動電流も大きい）。", "block": 11, "group": 4}, {"id": "R04_kouki_02", "source": "R4後 No.2", "category": "一般基礎", "type": "single", "question": "水に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "軟水は、カルシウム塩、マグネシウム塩を多く含む水である。"}, {"label": "2", "text": "BODは、水中に含まれる有機物質の量を示す指標である。"}, {"label": "3", "text": "0°Cの水が氷になると、体積は約10%増加する。"}, {"label": "4", "text": "pHは、水素イオン濃度の大小を示す指標である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["軟水は、カルシウム塩、マグネシウム塩を多く含む水である。"], "answerHints": [["軟水"]], "mnemonic": "正しくは：カルシウム塩・マグネシウム塩を多く含む水は硬水。", "block": 11, "group": 4}, {"id": "R04_kouki_05", "source": "R4後 No.5", "category": "一般基礎", "type": "single", "question": "電気設備において、「記号又は文字記号」とその「名称」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "EM−IE ―― 600V耐燃性ポリエチレン絶縁電線"}, {"label": "2", "text": "PF ―――― 合成樹脂製可とう電線管"}, {"label": "3", "text": "MC ―――― 電磁接触器"}, {"label": "4", "text": "ELCB ――― 配線用遮断器"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ELCB ――― 配線用遮断器"], "answerHints": [["ELCB"]], "mnemonic": "正しくは：配線用遮断器はMCCB。ELCBは漏電遮断器。", "block": 11, "group": 4}, {"id": "R05_zenki_02", "source": "R5前 No.2", "category": "一般基礎", "type": "single", "question": "水に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "1気圧のもとで水の密度は、0°Cのときに最大となる。"}, {"label": "2", "text": "1気圧のとき、水に対する空気の溶解度は、温度の上昇とともに減少する。"}, {"label": "3", "text": "1気圧のもとで1kgの水の温度を1°C上昇させるために必要な熱量は、約4.2kJである。"}, {"label": "4", "text": "1気圧のとき、沸点は約100°Cであるが、気圧が下がると沸点も下がる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["1気圧のもとで水の密度は、0°Cのときに最大となる。"], "answerHints": [["0°Cのとき"]], "mnemonic": "正しくは：水の密度は4°C付近で最大となる。", "block": 11, "group": 4}, {"id": "R05_zenki_05", "source": "R5前 No.5", "category": "一般基礎", "type": "single", "question": "電気設備に関する「機器又は方式」と「特徴」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "全電圧始動方式 ―――――― 始動時のトルクを制御できる"}, {"label": "2", "text": "3Eリレー ――――――――― 回路の反相を保護できる"}, {"label": "3", "text": "進相コンデンサ ―――――― 回路の力率を改善できる"}, {"label": "4", "text": "スターデルタ始動方式 ――― 始動時の電流を抑制できる"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["全電圧始動方式 ―――――― 始動時のトルクを制御できる"], "answerHints": [["トルクを制御できる"]], "mnemonic": "正しくは：全電圧始動方式は始動時のトルクを制御できない（始動電流も大きい）。", "block": 11, "group": 4}, {"id": "R04_zenki_09", "source": "R4前 No.9", "category": "空調・衛生", "type": "single", "question": "熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "顕熱比(SHF)とは、潜熱負荷に対する顕熱負荷の割合をいう。"}, {"label": "2", "text": "暖房負荷計算では、一般的に、日射負荷は考慮しない。"}, {"label": "3", "text": "外気負荷には、顕熱と潜熱がある。"}, {"label": "4", "text": "日射負荷は、顕熱のみである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["顕熱比(SHF)とは、潜熱負荷に対する顕熱負荷の割合をいう。"], "answerHints": [["潜熱負荷に対する"]], "mnemonic": "正しくは：顕熱比（SHF）は全熱負荷のうち顕熱負荷が占める割合。", "block": 11, "group": 4}, {"id": "R04_zenki_12", "source": "R4前 No.12", "category": "空調・衛生", "type": "single", "question": "吸収冷凍機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吸収冷凍機は、遠心冷凍機に比べて冷却塔の容量が大きくなる。"}, {"label": "2", "text": "吸収冷凍機の容量制御は、蒸発器にて行う。"}, {"label": "3", "text": "吸収冷凍機より遠心冷凍機の方が、低い温度の冷水を取り出すことができる。"}, {"label": "4", "text": "吸収冷凍機の冷媒は水である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["吸収冷凍機の容量制御は、蒸発器にて行う。"], "answerHints": [["蒸発器"]], "mnemonic": "正しくは：吸収冷凍機の容量制御は再生器の加熱量（蒸気・燃料量）で行う。", "block": 11, "group": 4}, {"id": "R04_zenki_16", "source": "R4前 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "建物からの排水が排除基準に適合していない場合には、除害施設等を設けなければならない。"}, {"label": "2", "text": "生活に起因する廃水(汚水)や雨水は、下水である。"}, {"label": "3", "text": "排水管の土被りは、建物の敷地内では、原則として20cm以上とする。"}, {"label": "4", "text": "排水設備の雨水ますの底には、深さ10cm以上の泥だまりを設ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水設備の雨水ますの底には、深さ10cm以上の泥だまりを設ける。"], "answerHints": [["10cm以上"]], "mnemonic": "正しくは：雨水ますの底には深さ15cm以上の泥だまりを設ける。", "block": 11, "group": 4}, {"id": "R04_zenki_19", "source": "R4前 No.19", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水トラップのディップとは、水底面頂部のことである。"}, {"label": "2", "text": "自己サイホン作用とは、トラップ内や器具排水管内を排水が満流状態で流れるためサイホン作用が生じ、封水が誘引されて損失する現象をいう。"}, {"label": "3", "text": "伸頂通気管は、排水立管の上部を通気管として延長し大気中に開口する。"}, {"label": "4", "text": "排水管の管径は、器具排水トラップの口径より小さくしてよい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水管の管径は、器具排水トラップの口径より小さくしてよい。"], "answerHints": [["小さくしてよい"]], "mnemonic": "正しくは：排水管の管径は器具排水トラップの口径以上とする。", "block": 11, "group": 4}, {"id": "R04_zenki_22", "source": "R4前 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液化石油ガス(LPG)のバルク供給方式は、工場や集合住宅等に用いられる。"}, {"label": "2", "text": "都市ガスの低圧供給方式は、一般的に、0.1MPa以上の圧力で供給される。"}, {"label": "3", "text": "液化石油ガス(LPG)の一般家庭用のガス容器には、一般的に、10kg、20kg、50kgのものがある。"}, {"label": "4", "text": "「ガス事業法」による特定ガス用品の基準に適合している器具には、PSマークが表示される。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["都市ガスの低圧供給方式は、一般的に、0.1MPa以上の圧力で供給される。"], "answerHints": [["0.1MPa以上"]], "mnemonic": "正しくは：都市ガスの低圧供給は0.1MPa未満の圧力。", "block": 11, "group": 4}, {"id": "R04_kouki_09", "source": "R4後 No.9", "category": "空調・衛生", "type": "single", "question": "熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "構造体の構成材質が同じであれば、厚さの薄い方が熱通過率は大きくなる。"}, {"label": "2", "text": "冷房負荷計算で、窓ガラス面からの熱負荷を算定する時はブラインドの有無を考慮する。"}, {"label": "3", "text": "暖房負荷計算では、一般的に、外気温度の時間的変化を考慮しない。"}, {"label": "4", "text": "照明器具による熱負荷は、顕熱と潜熱がある。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["照明器具による熱負荷は、顕熱と潜熱がある。"], "answerHints": [["顕熱と潜熱がある"]], "mnemonic": "正しくは：照明器具による熱負荷は顕熱のみ。", "block": 11, "group": 4}, {"id": "R04_kouki_12", "source": "R4後 No.12", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "マルチパッケージ形空気調和機には、1台の屋外機で冷房と暖房を屋内機ごとに選択できる機種もある。"}, {"label": "2", "text": "業務用パッケージ形空気調和機は、一般的に、代替フロン(HFC)が使用されており、「フロン類の使用の合理化及び管理の適正化に関する法律」の対象となっている。"}, {"label": "3", "text": "パッケージ形空気調和機には、空気熱源ヒートポンプ式と水熱源ヒートポンプ式がある。"}, {"label": "4", "text": "マルチパッケージ形空気調和機方式は、ユニット形空気調和機を用いた空気調和方式に比べて、機械室面積等が広く必要となる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["マルチパッケージ形空気調和機方式は、ユニット形空気調和機を用いた空気調和方式に比べて、機械室面積等が広く必要となる。"], "answerHints": [["広く必要となる"]], "mnemonic": "正しくは：マルチパッケージ方式はユニット形空調機方式に比べ機械室面積が小さくて済む。", "block": 11, "group": 4}, {"id": "R04_kouki_15", "source": "R4後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道施設に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "取水施設は、河川、湖沼又は地下の水源より原水を取り入れ、粗いごみや砂を取り除く施設である。"}, {"label": "2", "text": "送水施設は、取水施設にて取り入れた原水を浄水施設へ送る施設である。"}, {"label": "3", "text": "着水井には、流入する原水の水位変動を安定させ、その量を調整することで、浄水施設での浄化処理を安定させる役割がある。"}, {"label": "4", "text": "結合残留塩素は、遊離残留塩素より殺菌作用が低い。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送水施設は、取水施設にて取り入れた原水を浄水施設へ送る施設である。"], "answerHints": [["取水施設にて取り入れた原水"]], "mnemonic": "正しくは：原水を浄水施設へ送るのは導水施設。送水施設は浄水を配水施設へ送る。", "block": 11, "group": 4}, {"id": "R04_kouki_18", "source": "R4後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "FF方式のガス給湯器とは、燃焼用の外気導入と燃焼排ガスの屋外への排出を送風機を用いて強制的に行う方式である。"}, {"label": "2", "text": "60°Cの湯60リットルと、10°Cの水40リットルを混合した時、混合時に熱損失がないと仮定すると、混合水100リットルの温度は40°Cとなる。"}, {"label": "3", "text": "逃し管は、加熱による水の膨張で装置内の圧力が異常に上昇しないように設ける。"}, {"label": "4", "text": "湯の使用温度は、一般的に、給茶用、洗面用ともに50°C程度である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["湯の使用温度は、一般的に、給茶用、洗面用ともに50°C程度である。"], "answerHints": [["給茶用、洗面用ともに50°C程度"]], "mnemonic": "正しくは：使用温度は給茶用90°C程度、洗面用40°C程度。", "block": 11, "group": 4}, {"id": "R04_kouki_22", "source": "R4後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "貯蔵能力1,000kg未満のバルク貯槽は、その外面から2m以内にある火気をさえぎる措置を講じ、かつ、屋外に設置する。"}, {"label": "2", "text": "液化石油ガス(LPG)用のガス漏れ警報器の有効期間は、5年である。"}, {"label": "3", "text": "ガスの比重が1未満の場合、ガス漏れ警報設備の検知器は燃焼器等から水平距離10m以内に設ける。"}, {"label": "4", "text": "パイプシャフト内に密閉式ガス湯沸器を設置する場合、シャフト点検扉等に換気口を設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ガスの比重が1未満の場合、ガス漏れ警報設備の検知器は燃焼器等から水平距離10m以内に設ける。"], "answerHints": [["10m以内"]], "mnemonic": "正しくは：比重1未満（空気より軽い）ガスの検知器は燃焼器等から水平距離8m以内（天井付近）。", "block": 11, "group": 4}, {"id": "R05_zenki_09", "source": "R5前 No.9", "category": "空調・衛生", "type": "single", "question": "冷房負荷計算に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "OA機器による熱負荷は、顕熱のみである。"}, {"label": "2", "text": "ガラス面からの熱負荷は、ガラス面を透過した日射による負荷のみとする。"}, {"label": "3", "text": "人体による熱負荷は、顕熱と潜熱である。"}, {"label": "4", "text": "一般的に、9時、12時、14時及び16時における熱負荷を計算する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ガラス面からの熱負荷は、ガラス面を透過した日射による負荷のみとする。"], "answerHints": [["日射による負荷のみ"]], "mnemonic": "正しくは：ガラス面の熱負荷は透過日射負荷と、室内外温度差による通過熱負荷の両方。", "block": 11, "group": 4}, {"id": "R05_zenki_12", "source": "R5前 No.12", "category": "空調・衛生", "type": "single", "question": "吸収冷温水機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷房時にもガスや油をバーナーで燃焼させる必要がある。"}, {"label": "2", "text": "圧縮式冷凍機に比べて機器の立上がり時間が短い。"}, {"label": "3", "text": "機内を大気圧以下に保つ必要がある。"}, {"label": "4", "text": "吸収液には臭化リチウムが用いられる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["圧縮式冷凍機に比べて機器の立上がり時間が短い。"], "answerHints": [["立上がり時間が短い"]], "mnemonic": "正しくは：吸収冷温水機は圧縮式冷凍機に比べて立上がり時間が長い。", "block": 11, "group": 4}, {"id": "R05_zenki_15", "source": "R5前 No.15", "category": "空調・衛生", "type": "single", "question": "上水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "硬質ポリ塩化ビニル管に分水栓を取り付ける場合は、管の折損防止のため、サドル付を使用する。"}, {"label": "2", "text": "水道水の水質基準では、色度は5度以下と定められている。"}, {"label": "3", "text": "簡易専用水道とは、水道事業者から供給を受ける水のみを水源とし、水の供給を受ける水槽の有効容量の合計が5m3を超えるものをいう。"}, {"label": "4", "text": "配水管の試験は、原則として空気圧による試験は行わない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["簡易専用水道とは、水道事業者から供給を受ける水のみを水源とし、水の供給を受ける水槽の有効容量の合計が5m3を超えるものをいう。"], "answerHints": [["5m3"]], "mnemonic": "正しくは：簡易専用水道は水槽の有効容量の合計が10m3を超えるもの。", "block": 11, "group": 4}, {"id": "R05_zenki_18", "source": "R5前 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給湯配管には、水道用硬質塩化ビニルライニング鋼管を使用する。"}, {"label": "2", "text": "給湯配管をコンクリート内に敷設する場合は、熱による伸縮で配管が破断しないように保温材等をクッション材として機能させる。"}, {"label": "3", "text": "ヒートポンプ給湯機は、大気中の熱エネルギーを給湯の加熱に利用するものである。"}, {"label": "4", "text": "ガス瞬間湯沸器の先止め式とは、給湯先の湯栓の開閉により、バーナーが着火・消火する方式をいう。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給湯配管には、水道用硬質塩化ビニルライニング鋼管を使用する。"], "answerHints": [["水道用硬質塩化ビニルライニング鋼管"]], "mnemonic": "正しくは：給湯配管には水道用耐熱性硬質塩化ビニルライニング鋼管を使う。", "block": 11, "group": 4}, {"id": "R05_zenki_23", "source": "R5前 No.23", "category": "空調・衛生", "type": "single", "question": "FRP製浄化槽の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "槽が複数に分かれている場合、基礎は一体の共通基礎とする。"}, {"label": "2", "text": "槽本体のマンホールのかさ上げ高さは、最大300mmまでとする。"}, {"label": "3", "text": "槽は、満水状態にして24時間放置し、漏水のないことを確認する。"}, {"label": "4", "text": "埋戻しは、槽内に水を張る前に、良質土を用い均等に突き固める。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["埋戻しは、槽内に水を張る前に、良質土を用い均等に突き固める。"], "answerHints": [["槽内に水を張る前に"]], "mnemonic": "正しくは：埋戻しは槽内に水を張った状態で行う（槽の浮上・変形防止）。", "block": 11, "group": 4}, {"id": "R04_zenki_26", "source": "R4前 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "Y形ストレーナーは、円筒形のスクリーンを流路に対して45度傾けた構造で、横引きの配管では、上部にスクリーンを引き抜く。"}, {"label": "2", "text": "U形ストレーナーは、上部のカバーを外し上方にスクリーンを引き抜く。"}, {"label": "3", "text": "ストレート形ストレーナーは、流体がストレートに流れる構造でY形及びU形のストレーナーに比べ圧力損失が小さい。"}, {"label": "4", "text": "複式バケット形のオイルストレーナーは、ストレーナーの点検が容易な構造である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["Y形ストレーナーは、円筒形のスクリーンを流路に対して45度傾けた構造で、横引きの配管では、上部にスクリーンを引き抜く。"], "answerHints": [["上部にスクリーンを引き抜く"]], "mnemonic": "正しくは：Y形ストレーナーは横引き配管では下部にスクリーンを引き抜く。", "block": 11, "group": 4}, {"id": "R04_kouki_25", "source": "R4後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷却塔は、冷凍機等で作る冷水を利用して冷却水の水温を下げる装置である。"}, {"label": "2", "text": "遠心ポンプでは、吐出し量は羽根車の回転速度に比例して変化し、揚程は回転速度の2乗に比例して変化する。"}, {"label": "3", "text": "軸流送風機は、軸方向から空気が入り、軸方向に抜けるものである。"}, {"label": "4", "text": "パン形加湿器は、水槽内の水を電気ヒーター等により加熱し蒸気を発生させて加湿する装置である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["冷却塔は、冷凍機等で作る冷水を利用して冷却水の水温を下げる装置である。"], "answerHints": [["冷凍機等で作る冷水を利用して"]], "mnemonic": "正しくは：冷却塔は冷却水を外気と接触させ、水の蒸発潜熱で水温を下げる装置。", "block": 11, "group": 4}, {"id": "R05_zenki_24", "source": "R5前 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "大便器、小便器、洗面器等の衛生器具には、陶器以外にも、ほうろう、ステンレス、プラスチック等のものがある。"}, {"label": "2", "text": "インバータ方式のパッケージ形空気調和機は、電源の周波数を変えることで電動機の回転数を変化させ、冷暖房能力を制御する。"}, {"label": "3", "text": "温水ボイラーの容量は、定格出力〔W〕で表す。"}, {"label": "4", "text": "遠心ポンプの特性曲線では、吐出し量の増加に伴い全揚程も増加する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["遠心ポンプの特性曲線では、吐出し量の増加に伴い全揚程も増加する。"], "answerHints": [["全揚程も増加する"]], "mnemonic": "正しくは：遠心ポンプは吐出し量が増加すると全揚程は減少する。", "block": 11, "group": 4}, {"id": "R05_zenki_27", "source": "R5前 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "シーリングディフューザーは、誘引作用が大きく、気流拡散に優れている。"}, {"label": "2", "text": "ユニバーサル形吹出口は、羽根が垂直のV形、水平のH形、垂直・水平のVH形等がある。"}, {"label": "3", "text": "ノズル形吹出口は気流の到達距離が長く、大空間の壁面吹出口や天井面吹出口として使用される。"}, {"label": "4", "text": "吹出口とダクトの接続には、たわみ継手を使用する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["吹出口とダクトの接続には、たわみ継手を使用する。"], "answerHints": [["たわみ継手"]], "mnemonic": "正しくは：吹出口とダクトの接続にはフレキシブルダクトを使う。たわみ継手は送風機との接続用。", "block": 11, "group": 4}, {"id": "R04_zenki_32", "source": "R4前 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "重大災害とは、一時に3人以上の労働者が、業務上死傷または罹病した災害事故をいう。"}, {"label": "2", "text": "指差呼称は、指で差し示し、目で確認して、大きな声で呼称する安全確認の手法である。"}, {"label": "3", "text": "荷を吊り上げるワイヤーロープは、安全係数3を確保し、吊り角度を考慮して長さを選定する。"}, {"label": "4", "text": "一つの荷物で重量が100kg以上のものを貨物自動車に積む作業を行うときは、当該作業を指揮する者を定める。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["荷を吊り上げるワイヤーロープは、安全係数3を確保し、吊り角度を考慮して長さを選定する。"], "answerHints": [["安全係数3"]], "mnemonic": "正しくは：玉掛け用ワイヤーロープの安全係数は6以上。", "block": 11, "group": 4}, {"id": "R04_zenki_35", "source": "R4前 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "低圧ダクトに用いるコーナーボルト工法ダクトの板厚は、アングルフランジ工法ダクトの板厚と同じとしてよい。"}, {"label": "2", "text": "防火区画を貫通するダクトと当該防火区画の壁又は床との隙間には、グラスウール保温材を充てんする。"}, {"label": "3", "text": "送風機吸込口がダクトの直角曲り部近くにあるときは、直角曲がり部にガイドベーンを設ける。"}, {"label": "4", "text": "アングルフランジ工法ダクトの横走り主ダクトでは、ダクトの末端部にも振れ止め支持を行う。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火区画を貫通するダクトと当該防火区画の壁又は床との隙間には、グラスウール保温材を充てんする。"], "answerHints": [["グラスウール保温材"]], "mnemonic": "正しくは：防火区画貫通部の隙間はモルタル又はロックウール保温材で充てんする。", "block": 11, "group": 4}, {"id": "R04_zenki_38", "source": "R4前 No.38", "category": "施工管理法", "type": "single", "question": "JISで規定されている配管系の識別表示について、管内の「物質等の種類」とその「識別色」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "蒸気―――青"}, {"label": "2", "text": "油――――茶色"}, {"label": "3", "text": "ガス―――うすい黄"}, {"label": "4", "text": "電気―――うすい黄赤"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["蒸気―――青"], "answerHints": [["青"]], "mnemonic": "正しくは：蒸気は暗い赤。青は水。油＝茶色、ガス＝うすい黄、電気＝うすい黄赤。", "block": 11, "group": 4}, {"id": "R04_kouki_32", "source": "R4後 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "熱中症予防のための指標として、気温、湿度及び輻射熱に関する値を組み合わせて計算する暑さ指数(WBGT)がある。"}, {"label": "2", "text": "回転する刃物を使用する作業では、手が巻き込まれるおそれがあるので、手袋の使用を禁止する。"}, {"label": "3", "text": "労働者が、就業場所から他の就業場所へ移動する途中で被った災害は、通勤災害に該当しない。"}, {"label": "4", "text": "ツールボックスミーティングとは、関係する作業者が作業開始前に集まり、その日の作業、安全等について話合いを行うことである。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["労働者が、就業場所から他の就業場所へ移動する途中で被った災害は、通勤災害に該当しない。"], "answerHints": [["該当しない"]], "mnemonic": "正しくは：就業場所から他の就業場所への移動中の災害も通勤災害に該当する。", "block": 11, "group": 4}, {"id": "R04_kouki_35", "source": "R4後 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給排気ガラリの面風速は、騒音の発生等を考慮して決定する。"}, {"label": "2", "text": "ダクトの断面を変形させるときの縮小部の傾斜角度は、30度以下とする。"}, {"label": "3", "text": "送風機の接続ダクトに風量測定口を設ける場合は、送風機の吐出し口の直後に取り付ける。"}, {"label": "4", "text": "浴室等の多湿箇所の排気ダクトは、一般的に、その継目及び継手にシールを施す。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送風機の接続ダクトに風量測定口を設ける場合は、送風機の吐出し口の直後に取り付ける。"], "answerHints": [["吐出し口の直後"]], "mnemonic": "正しくは：風量測定口は送風機吐出し口の直後を避け、気流の安定した直線部に設ける。", "block": 11, "group": 4}, {"id": "R04_kouki_38", "source": "R3後 No.38 / R4後 No.38", "category": "施工管理法", "type": "single", "question": "空気調和設備の試運転調整における「測定対象」と「測定機器」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクト内圧力 ―― 直読式検知管"}, {"label": "2", "text": "ダクト内風量 ―― 熱線風速計"}, {"label": "3", "text": "室内温湿度 ――― アスマン通風乾湿計"}, {"label": "4", "text": "室内気流 ―――― カタ計"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクト内圧力 ―― 直読式検知管"], "answerHints": [["直読式検知管"]], "mnemonic": "正しくは：ダクト内圧力はマノメーター（ピトー管）で測る。検知管はガス濃度測定用。", "block": 11, "group": 4}, {"id": "R05_zenki_33", "source": "R5前 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "防振装置付きの機器や地震力が大きくなる重量機器は、可能な限り高層階に設置する。"}, {"label": "2", "text": "送風機は、レベルを水準器で確認し、水平が出ていない場合には基礎と共通架台の間にライナーを入れて調整する。"}, {"label": "3", "text": "冷凍機を据え付ける場合は、凝縮器のチューブ引出しのための有効な空間を確保する。"}, {"label": "4", "text": "パッケージ形空気調和機を据え付けた場合、冷媒名又はその記号及び冷媒封入量を表示する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防振装置付きの機器や地震力が大きくなる重量機器は、可能な限り高層階に設置する。"], "answerHints": [["高層階"]], "mnemonic": "正しくは：防振装置付き機器や重量機器は、可能な限り低層階に設置する。", "block": 11, "group": 4}, {"id": "R05_zenki_36", "source": "R5前 No.36", "category": "施工管理法", "type": "single", "question": "保温及び塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "露出配管の上塗り塗料は、一般的に、合成樹脂調合ペイント等を使用する。"}, {"label": "2", "text": "シートタイプの合成樹脂製カバーの固定は、専用のピンを使用する。"}, {"label": "3", "text": "配管用炭素鋼鋼管(白)は、下塗り塗料として変性エポキシ樹脂プライマーを使用する。"}, {"label": "4", "text": "グラスウール保温材は、ポリスチレンフォーム保温材に比べて、防湿性が優れている。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["グラスウール保温材は、ポリスチレンフォーム保温材に比べて、防湿性が優れている。"], "answerHints": [["防湿性が優れている"]], "mnemonic": "正しくは：グラスウールはポリスチレンフォームより高温域で使用できる。防湿性はポリスチレンフォームが優れる。", "block": 11, "group": 4}, {"id": "R04_zenki_49", "source": "R4前 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程表に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ガントチャート工程表は、現時点における各作業の進捗状況が容易に把握できる。"}, {"label": "2", "text": "バーチャート工程表は、ネットワーク工程表に比べ、工程が複雑な工事に適している。"}, {"label": "3", "text": "バーチャート工程表は、ガントチャート工程表に比べ、作業間の作業順序が分かりやすい。"}, {"label": "4", "text": "ネットワーク工程表は、ガントチャート工程表に比べ、工事途中での計画変更に対処しにくい。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表は、ネットワーク工程表に比べ、工程が複雑な工事に適している。", "ネットワーク工程表は、ガントチャート工程表に比べ、工事途中での計画変更に対処しにくい。"], "answerHints": [["工程が複雑な工事に適している"], ["対処しにくい"]], "mnemonic": "正しくは：複雑な工事に適するのはネットワーク工程表。ネットワーク工程表は計画変更に対処しやすい。", "block": 11, "group": 4}, {"id": "R04_zenki_52", "source": "R4前 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "フレキシブルダクトは、振動伝播防止のために、送風機とダクトの接続に使用する。"}, {"label": "2", "text": "亜鉛鉄板製のスパイラルダクトは、一般的に、補強は不要である。"}, {"label": "3", "text": "消音エルボや消音チャンバーの消音内貼材には、ポリスチレンフォーム保温材を使用する。"}, {"label": "4", "text": "共板フランジ工法ダクトのフランジの板厚は、ダクトの板厚と同じとする。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["フレキシブルダクトは、振動伝播防止のために、送風機とダクトの接続に使用する。", "消音エルボや消音チャンバーの消音内貼材には、ポリスチレンフォーム保温材を使用する。"], "answerHints": [["フレキシブルダクト"], ["ポリスチレンフォーム保温材"]], "mnemonic": "正しくは：送風機とダクトの接続にはたわみ継手を使う。消音内貼材にはグラスウール保温材を使う。", "block": 11, "group": 4}, {"id": "R04_kouki_51", "source": "R4後 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "雨水ますには、ます内に排水や固形物が滞留しないようにインバートを設ける。"}, {"label": "2", "text": "排水用硬質塩化ビニルライニング鋼管の接続には、排水鋼管用可とう継手(MDジョイント)を使用する。"}, {"label": "3", "text": "鋼管のねじ加工には、切削ねじ加工と転造ねじ加工がある。"}, {"label": "4", "text": "樹脂ライニング鋼管を切断する場合には、ねじ加工機に附属するパイプカッターを使用する。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["雨水ますには、ます内に排水や固形物が滞留しないようにインバートを設ける。", "樹脂ライニング鋼管を切断する場合には、ねじ加工機に附属するパイプカッターを使用する。"], "answerHints": [["インバート"], ["パイプカッター"]], "mnemonic": "正しくは：雨水ますには泥だまりを設ける（インバートは汚水ます）。樹脂ライニング鋼管の切断に、管端が絞られるパイプカッターは使わない（帯のこ盤等を使う）。", "block": 11, "group": 4}, {"id": "R05_zenki_50", "source": "R5前 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "揚水ポンプの吐出し側には、ポンプに近い順に、防振継手、仕切弁、逆止め弁を取り付ける。"}, {"label": "2", "text": "ファンコイルユニットの床置形は、一般的に、室の外壁の窓下等に据え付ける。"}, {"label": "3", "text": "送風機の振動が躯体に伝搬するおそれがある場合は、防振基礎とする。"}, {"label": "4", "text": "埋込式アンカーボルトとコンクリート基礎の端部は、50mm程度離す。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["揚水ポンプの吐出し側には、ポンプに近い順に、防振継手、仕切弁、逆止め弁を取り付ける。", "埋込式アンカーボルトとコンクリート基礎の端部は、50mm程度離す。"], "answerHints": [["仕切弁、逆止め弁"], ["50mm程度"]], "mnemonic": "正しくは：揚水ポンプ吐出し側はポンプに近い順に防振継手→逆止め弁→仕切弁。アンカーボルトは基礎端部から150mm程度離す。", "block": 11, "group": 4}, {"id": "R04_zenki_39", "source": "R4前 No.39", "category": "法規", "type": "single", "question": "労働安全衛生管理に関する記述のうち、「労働安全衛生法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、最大積載量が5トン未満の貨物自動車に荷を積む作業を行うときは、床面と荷台上の荷の上面との間を安全に昇降するための設備を設けなくてもよい。"}, {"label": "2", "text": "事業者は、労働者に危険を及ぼすおそれのないときを除き、フォークリフトを荷のつり上げの用途に使用してはならない。"}, {"label": "3", "text": "事業者は、高所作業車を用いて作業(道路上の走行の作業を除く。)を行うときは、あらかじめ、作業の方法を示した作業計画を定めなければならない。"}, {"label": "4", "text": "つり上げ荷重が5トン未満の移動式クレーンには、「クレーン等安全規則」は適用されない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["つり上げ荷重が5トン未満の移動式クレーンには、「クレーン等安全規則」は適用されない。"], "answerHints": [["5トン未満"]], "mnemonic": "正しくは：クレーン等安全規則はつり上げ荷重0.5トン以上の移動式クレーンに適用される。", "block": 11, "group": 4}, {"id": "R04_zenki_42", "source": "R4前 No.42", "category": "法規", "type": "single", "question": "建築物に設ける飲料用給水タンクに関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "有効容量が2m3以上の給水タンクには、圧力タンク等を除き、ほこりその他衛生上有害なものが入らない構造の通気のための装置を有効に設けなければならない。"}, {"label": "2", "text": "給水タンクには、外部から保守点検できる小規模な給水タンクを除き、保守点検を容易かつ安全に行うことができる位置に、直径45cm以上の円が内接できるマンホールを設けなければならない。"}, {"label": "3", "text": "給水タンク等の上部にポンプ、ボイラー、空気調和機等の機器を設ける場合においては、飲料水を汚染することのないように、衛生上必要な措置を講じなければならない。"}, {"label": "4", "text": "金属製の給水タンクには、衛生上支障のない有効なさび止めのための措置を講じなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["給水タンクには、外部から保守点検できる小規模な給水タンクを除き、保守点検を容易かつ安全に行うことができる位置に、直径45cm以上の円が内接できるマンホールを設けなければならない。"], "answerHints": [["直径45cm以上"]], "mnemonic": "正しくは：給水タンクのマンホールは直径60cm以上の円が内接できるもの。", "block": 11, "group": 4}, {"id": "R04_zenki_45", "source": "R4前 No.45", "category": "法規", "type": "single", "question": "「消防法」に基づく届出書等とその届出者の組合せのうち、「消防法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "消防計画作成届出書 ―――――――――――――― 施工者"}, {"label": "2", "text": "工事整備対象設備等着工届出書 ――――――――― 消防設備士"}, {"label": "3", "text": "危険物製造所・貯蔵所・取扱所設置許可申請書 ―― 設置者"}, {"label": "4", "text": "消防用設備等設置届出書 ―――――――――――― 防火対象物の関係者"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["消防計画作成届出書 ―――――――――――――― 施工者"], "answerHints": [["施工者"]], "mnemonic": "正しくは：消防計画作成届出書の届出者は防火管理者。", "block": 11, "group": 4}, {"id": "R04_zenki_48", "source": "R4前 No.48", "category": "法規", "type": "single", "question": "産業廃棄物等の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建設工事の元請業者が、当該工事において発生させた産業廃棄物を自ら処理施設へ運搬する場合は、産業廃棄物収集運搬業の許可を必要としない。"}, {"label": "2", "text": "産業廃棄物の不法投棄があった場合、責任を問われるのは産業廃棄物の処分業者で、排出事業者に責任が及ぶことはない。"}, {"label": "3", "text": "建築物の改築に伴い廃棄する蛍光灯の安定器にポリ塩化ビフェニルが含まれている場合、特別管理産業廃棄物として処理しなければならない。"}, {"label": "4", "text": "建築物の改築に伴って生じる紙くず及び繊維くずは、産業廃棄物として処理しなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["産業廃棄物の不法投棄があった場合、責任を問われるのは産業廃棄物の処分業者で、排出事業者に責任が及ぶことはない。"], "answerHints": [["排出事業者に責任が及ぶことはない"]], "mnemonic": "正しくは：不法投棄があれば、処理を委託した排出事業者にも責任が及ぶ（排出事業者責任）。", "block": 11, "group": 4}, {"id": "R04_kouki_42", "source": "R4後 No.42", "category": "法規", "type": "single", "question": "建築物に設ける中央管理方式の空気調和設備によって、居室の空気が適合しなければならない基準として、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "浮遊粉じんの量は、おおむね空気1m3につき0.15mg以下とする。"}, {"label": "2", "text": "一酸化炭素の含有率は、おおむね100万分の100以下とする。"}, {"label": "3", "text": "炭酸ガスの含有率は、おおむね100万分の1,000以下とする。"}, {"label": "4", "text": "相対湿度は、おおむね40%以上70%以下とする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["一酸化炭素の含有率は、おおむね100万分の100以下とする。"], "answerHints": [["100万分の100以下"]], "mnemonic": "正しくは：一酸化炭素の含有率はおおむね100万分の10以下（出題当時の基準）。", "block": 11, "group": 4}, {"id": "R04_kouki_45", "source": "R4後 No.45", "category": "法規", "type": "single", "question": "消防の用に供する設備のうち、「消防法」上、消火設備に該当しないものはどれか。", "choices": [{"label": "1", "text": "消火器"}, {"label": "2", "text": "屋内消火栓設備"}, {"label": "3", "text": "防火水槽"}, {"label": "4", "text": "スプリンクラー設備"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["防火水槽"], "answerHints": [["防火水槽"]], "mnemonic": "防火水槽は「消防用水」であり消火設備ではない。消火器・屋内消火栓・スプリンクラーは消火設備。", "block": 11, "group": 4}, {"id": "R04_kouki_48", "source": "R3後 No.48 / R4後 No.48", "category": "法規", "type": "single", "question": "廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "地山の掘削により生じる土砂は、産業廃棄物として処理する。"}, {"label": "2", "text": "廃エアコンディショナー(国内における日常生活に伴って生じたものに限る。)に含まれるポリ塩化ビフェニルを使用する部品は、特別管理一般廃棄物である。"}, {"label": "3", "text": "建築物の改築に伴い生じた衛生陶器の破片は、産業廃棄物として処理する。"}, {"label": "4", "text": "建築物の改築に伴い除去したビニル床タイルに、石綿をその重量の0.1%を超えて含有する場合、石綿含有産業廃棄物として処理する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["地山の掘削により生じる土砂は、産業廃棄物として処理する。"], "answerHints": [["産業廃棄物として処理する"]], "mnemonic": "正しくは：地山の掘削で生じる土砂は廃棄物に該当しない（建設発生土）。", "block": 11, "group": 4}, {"id": "R05_zenki_42", "source": "R5前 No.42", "category": "法規", "type": "single", "question": "建築設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "排水槽の通気管は、通気立て管又は伸頂通気管に接続しなければならない。"}, {"label": "2", "text": "給水管、配電管その他の管が、防火区画を貫通する場合、貫通する部分及び当該貫通する部分からそれぞれ両側に1m以内の距離にある部分を不燃材料で造らなければならない。"}, {"label": "3", "text": "排水再利用配管設備の水栓には、排水再利用水であることを示す表示をしなければならない。"}, {"label": "4", "text": "排水トラップは、二重トラップとならないように設けなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["排水槽の通気管は、通気立て管又は伸頂通気管に接続しなければならない。"], "answerHints": [["通気立て管又は伸頂通気管に接続"]], "mnemonic": "正しくは：排水槽の通気管は他の通気管に接続せず、直接単独で大気に開放する。", "block": 11, "group": 4}, {"id": "R05_zenki_45", "source": "R5前 No.45", "category": "法規", "type": "single", "question": "危険物に関する記述のうち、「消防法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "ガソリンの指定数量は、400リットルである。"}, {"label": "2", "text": "軽油の指定数量は、1,000リットルである。"}, {"label": "3", "text": "灯油の指定数量は、1,000リットルである。"}, {"label": "4", "text": "重油の指定数量は、2,000リットルである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["ガソリンの指定数量は、400リットルである。"], "answerHints": [["400リットル"]], "mnemonic": "正しくは：ガソリンの指定数量は200リットル（灯油・軽油1,000L、重油2,000L）。", "block": 11, "group": 4}, {"id": "R05_zenki_48", "source": "R5前 No.48", "category": "法規", "type": "single", "question": "産業廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、現場事務所から排出される生ゴミ、新聞、雑誌等は、産業廃棄物として処理しなければならない。"}, {"label": "2", "text": "事業者は、その事業活動に伴って生じた産業廃棄物の運搬先が2以上である場合、運搬先ごとに産業廃棄物管理票を交付しなければならない。"}, {"label": "3", "text": "事業者は、産業廃棄物の処理に電子情報処理組織を使用して、情報処理センターに登録する場合、当該産業廃棄物の種類ごとに登録しなければならない。"}, {"label": "4", "text": "事業者は、産業廃棄物の運搬又は処分を委託して産業廃棄物管理票を交付した場合、当該管理票の写しは管理票を交付した日から5年間保存しなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、現場事務所から排出される生ゴミ、新聞、雑誌等は、産業廃棄物として処理しなければならない。"], "answerHints": [["産業廃棄物として"]], "mnemonic": "正しくは：現場事務所の生ゴミ・新聞・雑誌等は一般廃棄物として処理する。", "block": 11, "group": 4}, {"id": "R04_zenki_03", "source": "R4前 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水は、一般的にニュートン流体として扱われる。"}, {"label": "2", "text": "1気圧のもとで水の密度は、4°C付近で最大となる。"}, {"label": "3", "text": "液体の粘性係数は、温度が高くなるにつれて減少する。"}, {"label": "4", "text": "大気圧の1気圧の大きさは、概ね深さ1mの水圧に相当する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["大気圧の1気圧の大きさは、概ね深さ1mの水圧に相当する。"], "answerHints": [["深さ1m"]], "mnemonic": "正しくは：1気圧は概ね深さ10mの水圧に相当する。", "block": 12, "group": 4}, {"id": "R04_zenki_06", "source": "R4前 No.6", "category": "一般基礎", "type": "single", "question": "コンクリート打設後の初期養生に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "硬化中のコンクリートに振動を与えると、締め固め効果が高まる。"}, {"label": "2", "text": "養生温度が低い場合は、高い場合よりもコンクリートの強度の発現が遅い。"}, {"label": "3", "text": "コンクリートの露出面をシートで覆い、直射日光や風から保護する。"}, {"label": "4", "text": "湿潤養生は、コンクリートの強度の発現をより促進させる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["硬化中のコンクリートに振動を与えると、締め固め効果が高まる。"], "answerHints": [["締め固め効果が高まる"]], "mnemonic": "正しくは：硬化中のコンクリートに振動を与えるとひび割れ等の原因になるので、振動を与えないようにする。", "block": 12, "group": 4}, {"id": "R04_kouki_03", "source": "R4後 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "圧力計が示すゲージ圧は、絶対圧から大気圧を差し引いた圧力である。"}, {"label": "2", "text": "毛管現象は、液体の表面張力によるものである。"}, {"label": "3", "text": "流体が直管路を満流で流れる場合、圧力損失の大きさは、流体の密度と関係しない。"}, {"label": "4", "text": "定常流は、流れの状態が、場所によってのみ定まり時間的には変化しない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["流体が直管路を満流で流れる場合、圧力損失の大きさは、流体の密度と関係しない。"], "answerHints": [["密度と関係しない"]], "mnemonic": "正しくは：直管路の圧力損失は流体の密度に比例する（ダルシー・ワイスバッハの式）。", "block": 12, "group": 4}, {"id": "R04_kouki_06", "source": "R4後 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリートの特性に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "鉄筋コンクリート造は、剛性が低く振動による影響を受けやすい。"}, {"label": "2", "text": "異形棒鋼は、丸鋼と比べてコンクリートとの付着力が大きい。"}, {"label": "3", "text": "コンクリートはアルカリ性のため、コンクリート中の鉄筋は錆びにくい。"}, {"label": "4", "text": "コンクリートと鉄筋の線膨張係数は、ほぼ等しい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鉄筋コンクリート造は、剛性が低く振動による影響を受けやすい。"], "answerHints": [["剛性が低く"]], "mnemonic": "正しくは：鉄筋コンクリート造は剛性が高く、振動の影響を受けにくい。", "block": 12, "group": 4}, {"id": "R05_zenki_03", "source": "R5前 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する用語の組合せのうち、関係のないものはどれか。", "choices": [{"label": "1", "text": "粘性係数―――――――――――摩擦応力"}, {"label": "2", "text": "パスカルの原理――――――――圧力"}, {"label": "3", "text": "ベンチュリー管――――――――流量計測"}, {"label": "4", "text": "ダルシー・ワイスバッハの式――表面張力"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["ダルシー・ワイスバッハの式――表面張力"], "answerHints": [["表面張力"]], "mnemonic": "ダルシー・ワイスバッハの式は直管の摩擦による圧力損失の式。表面張力は毛管現象と関係。", "block": 12, "group": 4}, {"id": "R05_zenki_06", "source": "R5前 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート造の建築物の鉄筋に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "鉄筋相互のあきの最小寸法は、鉄筋の強度によって決まる。"}, {"label": "2", "text": "帯筋は、柱のせん断力に対する補強筋である。"}, {"label": "3", "text": "鉄筋の折曲げ加工は、鋼材の品質が劣化しないよう常温で行う。"}, {"label": "4", "text": "鉄筋の継手は、1か所に集中させず相互にずらして設ける。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鉄筋相互のあきの最小寸法は、鉄筋の強度によって決まる。"], "answerHints": [["鉄筋の強度"]], "mnemonic": "正しくは：鉄筋相互のあきは、粗骨材の最大寸法や鉄筋の径によって決まる。", "block": 12, "group": 4}, {"id": "R04_zenki_10", "source": "R4前 No.10", "category": "空調・衛生", "type": "single", "question": "空気清浄装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ロール状ろ材を自動的に巻き取る自動更新方式は、一般空調用に使用される。"}, {"label": "2", "text": "HEPAフィルターは、クリーンルームなどで最終段フィルターとして使用される。"}, {"label": "3", "text": "活性炭などを使用した化学吸着式は、粉じんの除去に使用される。"}, {"label": "4", "text": "静電式は、一般空調用に使用される。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["活性炭などを使用した化学吸着式は、粉じんの除去に使用される。"], "answerHints": [["粉じんの除去"]], "mnemonic": "正しくは：活性炭などの化学吸着式は有害ガス・臭気の除去に使用される。", "block": 12, "group": 4}, {"id": "R04_zenki_13", "source": "R4前 No.13", "category": "空調・衛生", "type": "single", "question": "換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吸収冷温水機室の換気には、第3種機械換気を採用する。"}, {"label": "2", "text": "エアカーテンは、出入口に特別な気流を生じさせて、外気と室内空気の混合を抑制する。"}, {"label": "3", "text": "臭気、燃焼ガスなどの汚染源の異なる換気は、同一系統にしない。"}, {"label": "4", "text": "密閉式の燃焼器具を設けた室には、当該器具の燃焼空気のための換気設備を設けなくてもよい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["吸収冷温水機室の換気には、第3種機械換気を採用する。"], "answerHints": [["第3種機械換気"]], "mnemonic": "正しくは：吸収冷温水機室など燃焼機器のある室は第一種機械換気方式とする（燃焼空気の確保）。", "block": 12, "group": 4}, {"id": "R04_zenki_17", "source": "R4前 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水道直結方式は、高置タンク方式に比べ、水質汚染の可能性が低い。"}, {"label": "2", "text": "省エネルギー性を向上させる項目には、節水式衛生器具の採用、水道直結方式の採用(低層建物の場合)等がある。"}, {"label": "3", "text": "「建築物における衛生的環境の確保に関する法律」に基づく特定建築物において、雑用水用水槽は法令上の点検は義務付けられていない。"}, {"label": "4", "text": "給水管への逆サイホン作用による汚染の防止には、吐水口空間の確保が基本となる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["「建築物における衛生的環境の確保に関する法律」に基づく特定建築物において、雑用水用水槽は法令上の点検は義務付けられていない。"], "answerHints": [["義務付けられていない"]], "mnemonic": "正しくは：特定建築物では雑用水槽も法令上の点検が義務付けられている。", "block": 12, "group": 4}, {"id": "R04_zenki_20", "source": "R4前 No.20", "category": "空調・衛生", "type": "single", "question": "排水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "器具排水負荷単位法において、排水横主管は同じ管径であれば勾配に関係なく許容される排水負荷単位数は同じである。"}, {"label": "2", "text": "排水管径40mmの排水勾配は1/50とする。"}, {"label": "3", "text": "地中埋設排水管の管径は、50mm以上が望ましい。"}, {"label": "4", "text": "ボトルトラップはSトラップと比べて封水損失は少ない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["器具排水負荷単位法において、排水横主管は同じ管径であれば勾配に関係なく許容される排水負荷単位数は同じである。"], "answerHints": [["勾配に関係なく"]], "mnemonic": "正しくは：排水横主管の許容排水負荷単位数は、同じ管径でも勾配によって異なる。", "block": 12, "group": 4}, {"id": "R04_zenki_23", "source": "R4前 No.23", "category": "空調・衛生", "type": "single", "question": "浄化槽に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "厨房排水等、油脂類濃度が高い排水が流入する場合には、前処理として油脂分離槽又は油脂分離装置を設ける必要がある。"}, {"label": "2", "text": "処理工程の一次処理とは、主として沈降性の浮遊物を除去することである。"}, {"label": "3", "text": "小規模合併浄化槽では、窒素やりん等はほとんど除去することができる。"}, {"label": "4", "text": "生物処理法のひとつである嫌気性処理法では、有機物がメタンガスや二酸化炭素等に変化する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["小規模合併浄化槽では、窒素やりん等はほとんど除去することができる。"], "answerHints": [["ほとんど除去することができる"]], "mnemonic": "正しくは：小規模合併浄化槽では窒素やりんはほとんど除去できない。", "block": 12, "group": 4}, {"id": "R04_kouki_10", "source": "R4後 No.10", "category": "空調・衛生", "type": "single", "question": "エアフィルターの「種類」と「主な用途」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "HEPAフィルター ――― クリーンルーム"}, {"label": "2", "text": "活性炭フィルター ―― ガス処理"}, {"label": "3", "text": "自動巻取形 ――――― 一般空調"}, {"label": "4", "text": "電気集じん器 ―――― 厨房排気"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["電気集じん器 ―――― 厨房排気"], "answerHints": [["厨房排気"]], "mnemonic": "電気集じん器は一般空調用（微細な粉じん）。厨房排気にはグリスフィルターを使う。", "block": 12, "group": 4}, {"id": "R04_kouki_13", "source": "R4後 No.13", "category": "空調・衛生", "type": "single", "question": "換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "営業用厨房は、燃焼空気の供給のため室内を正圧とする。"}, {"label": "2", "text": "第一種機械換気方式は、給気側と排気側の両方に送風機を設ける方式である。"}, {"label": "3", "text": "駐車場の換気として、誘引誘導換気方式を採用する場合がある。"}, {"label": "4", "text": "第三種機械換気方式では、換気対象室内は負圧となる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["営業用厨房は、燃焼空気の供給のため室内を正圧とする。"], "answerHints": [["正圧"]], "mnemonic": "正しくは：営業用厨房は臭気・熱が他室へ漏れないよう室内を負圧とする。", "block": 12, "group": 4}, {"id": "R04_kouki_16", "source": "R4後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "下水道本管に接続する取付管の勾配は、1/100以上とする。"}, {"label": "2", "text": "公共下水道は、汚水を排除すべき排水施設の相当部分が暗きょ構造となっている。"}, {"label": "3", "text": "段差接合により下水道管きょを接合する場合、原則として副管を使用するのは、段差が1.5m以上の合流管きょ及び汚水管きょである。"}, {"label": "4", "text": "下水道本管に放流するための汚水ますの位置は、公道と民有地との境界線付近とし、ますの底部にはインバートを設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["段差接合により下水道管きょを接合する場合、原則として副管を使用するのは、段差が1.5m以上の合流管きょ及び汚水管きょである。"], "answerHints": [["1.5m以上"]], "mnemonic": "正しくは：段差接合で副管を使用するのは段差が0.6m以上の場合。", "block": 12, "group": 4}, {"id": "R04_kouki_19", "source": "R4後 No.19", "category": "空調・衛生", "type": "single", "question": "衛生器具の「名称」と当該器具の「トラップの最小口径」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "大便器 ――――――― 75mm"}, {"label": "2", "text": "掃除用流し ――――― 50mm"}, {"label": "3", "text": "汚物流し ―――――― 75mm"}, {"label": "4", "text": "壁掛け小型小便器 ―― 40mm"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["掃除用流し ――――― 50mm"], "answerHints": [["50mm"]], "mnemonic": "正しくは：掃除用流しのトラップ最小口径は65mm。", "block": 12, "group": 4}, {"id": "R05_zenki_10", "source": "R5前 No.10", "category": "空調・衛生", "type": "single", "question": "空気清浄装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ろ過式のろ材は、難燃性又は不燃性のものとする。"}, {"label": "2", "text": "性能は、定格風量における圧力損失、汚染除去率、汚染除去容量等で示す。"}, {"label": "3", "text": "ろ過式のろ材は、吸湿性が高いものとする。"}, {"label": "4", "text": "静電式は、高電圧を使い粉じんを帯電させて捕集する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ろ過式のろ材は、吸湿性が高いものとする。"], "answerHints": [["吸湿性が高い"]], "mnemonic": "正しくは：ろ過式のろ材は吸湿性が低いものとする。", "block": 12, "group": 4}, {"id": "R05_zenki_13", "source": "R5前 No.13", "category": "空調・衛生", "type": "single", "question": "機械換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ガスコンロの換気は、所定の排気フードを設けることにより換気量を低減することができる。"}, {"label": "2", "text": "臭気、燃焼ガス等の汚染源の異なる換気は、各々独立した換気系統とする。"}, {"label": "3", "text": "排風機は、吸込み側のダクトが短く、吐出し側のダクトが長くなるように設置する。"}, {"label": "4", "text": "便所は、室内の臭気を拡散させないよう、第三種機械換気方式とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排風機は、吸込み側のダクトが短く、吐出し側のダクトが長くなるように設置する。"], "answerHints": [["吐出し側のダクトが長くなる"]], "mnemonic": "正しくは：排風機は吸込み側ダクトを長く、吐出し側ダクトを短くする（正圧部分を短くし漏れを防ぐ）。", "block": 12, "group": 4}, {"id": "R05_zenki_16", "source": "R5前 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "都市下水路は、地方公共団体が管理するもので、公共下水道を含んでいる。"}, {"label": "2", "text": "汚水管きょの流速は、0.6〜3.0m/sとする。"}, {"label": "3", "text": "合流管きょの計画下水量は、計画時間最大汚水量に計画雨水量を加えたものとする。"}, {"label": "4", "text": "下水道本管に接続する取付管の最小管径は、150mmを標準とする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["都市下水路は、地方公共団体が管理するもので、公共下水道を含んでいる。"], "answerHints": [["公共下水道を含んでいる"]], "mnemonic": "正しくは：都市下水路は主に市街地の雨水を排除するもので、公共下水道は含まない。", "block": 12, "group": 4}, {"id": "R05_zenki_19", "source": "R5前 No.19", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水横枝管からのループ通気管は、通気立て管又は伸頂通気管に接続するか大気に開放する。"}, {"label": "2", "text": "グリース阻集器は、排水中に含まれている油脂分を除去する。"}, {"label": "3", "text": "排水トラップのディップとは、封水のあふれ面のことをいう。"}, {"label": "4", "text": "通気弁をパイプシャフトや屋根裏等に設置する場合は、点検口を設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水トラップのディップとは、封水のあふれ面のことをいう。"], "answerHints": [["封水のあふれ面"]], "mnemonic": "正しくは：ディップはトラップの水底面頂部。あふれ面はウェア。", "block": 12, "group": 4}, {"id": "R04_zenki_24", "source": "R4前 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ボイラーの容量は、最大連続負荷における毎時出力によって表され、温水ボイラーは熱出力〔W〕で表す。"}, {"label": "2", "text": "インバータ制御方式のパッケージ形空気調和機は、インバータを用いて電源の周波数を変化させて電動機の回転数を変化させることにより、冷暖房能力を制御する。"}, {"label": "3", "text": "大便器、小便器、洗面器等の衛生器具には、陶器以外にも、ほうろう、ステンレス、プラスチック等の器具がある。"}, {"label": "4", "text": "汚水用水中モーターポンプは、浄化槽への流入水等、固形物も含んだ水を排出するためのポンプである。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["汚水用水中モーターポンプは、浄化槽への流入水等、固形物も含んだ水を排出するためのポンプである。"], "answerHints": [["汚水用水中モーターポンプ"]], "mnemonic": "正しくは：固形物を含んだ水を排出するのは汚物用水中モーターポンプ。", "block": 12, "group": 4}, {"id": "R04_zenki_27", "source": "R4前 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "スパイラルダクトの接続には、差込み継手又はフランジ継手を用いる。"}, {"label": "2", "text": "エルボの内側半径は、円形ダクトではダクトの直径の1/2以上とする。"}, {"label": "3", "text": "ダクトの断面を変形させる場合、上流側の拡大角度及び下流側の縮小角度は45度以内とする。"}, {"label": "4", "text": "長方形ダクトの板厚は、長辺と短辺とも同じである。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクトの断面を変形させる場合、上流側の拡大角度及び下流側の縮小角度は45度以内とする。"], "answerHints": [["45度以内"]], "mnemonic": "正しくは：ダクト断面の変形は拡大角度15度以内、縮小角度30度以内。", "block": 12, "group": 4}, {"id": "R04_kouki_26", "source": "R4後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "バタフライ弁は、仕切弁に比べ、取付けスペースが小さい。"}, {"label": "2", "text": "逆止め弁は、チャッキ弁とも呼ばれ、スイング式、リフト式等がある。"}, {"label": "3", "text": "硬質ポリ塩化ビニル管の接合は、接着接合、ゴム輪接合等がある。"}, {"label": "4", "text": "硬質ポリ塩化ビニル管のVU管は、VP管に比べて設計圧力が高い。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["硬質ポリ塩化ビニル管のVU管は、VP管に比べて設計圧力が高い。"], "answerHints": [["設計圧力が高い"]], "mnemonic": "正しくは：VU管は薄肉で、VP管に比べて設計圧力が低い。", "block": 12, "group": 4}, {"id": "R05_zenki_25", "source": "R5前 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "水中モーターポンプに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水中モーターポンプの乾式は、水が内部に浸入しないよう空気又はその他の気体を充満密封したものである。"}, {"label": "2", "text": "汚水や厨房排水のような浮遊物質を含む排水槽では、電極棒により自動運転する。"}, {"label": "3", "text": "羽根車の種類は、一般的に、オープン形とクローズ形に分類される。"}, {"label": "4", "text": "汚物用水中モーターポンプは、浄化槽への流入水等、固形物も含んだ水を排出するためのポンプである。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["汚水や厨房排水のような浮遊物質を含む排水槽では、電極棒により自動運転する。"], "answerHints": [["電極棒"]], "mnemonic": "正しくは：浮遊物質を含む排水槽では電極棒は汚物付着で誤作動するため、フロートスイッチで自動運転する。", "block": 12, "group": 4}, {"id": "R04_zenki_29", "source": "R4前 No.29", "category": "施工管理法", "type": "single", "question": "公共工事における施工計画等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "施工期間中の各工事において養生が必要となる場合は、あらかじめ施工計画書に明記する。"}, {"label": "2", "text": "工事現場の施工体制において、主任技術者は現場代理人を兼任することはできない。"}, {"label": "3", "text": "現場説明書と設計図面の内容に相違がある場合は、現場説明書の内容を優先する。"}, {"label": "4", "text": "施工図は、作成範囲、作成順序、作成予定日等をあらかじめ定め、逐次完成させる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["工事現場の施工体制において、主任技術者は現場代理人を兼任することはできない。"], "answerHints": [["兼任することはできない"]], "mnemonic": "正しくは：主任技術者は現場代理人を兼任することができる。", "block": 12, "group": 4}, {"id": "R04_zenki_33", "source": "R4前 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吸収冷温水機は、運転時の振動が大きいため、一般的に、防振基礎に据え付ける。"}, {"label": "2", "text": "アンカーボルトは、機器の据付け後、ボルトの頂部のねじ山がナットから3山程度出る長さとする。"}, {"label": "3", "text": "パッケージ形空気調和機は、コンクリート基礎上に防振ゴムパッドを敷いて水平に据え付ける。"}, {"label": "4", "text": "アンカーボルトを選定する場合、常時荷重に対する許容引抜き荷重は、長期許容引抜き荷重とする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["吸収冷温水機は、運転時の振動が大きいため、一般的に、防振基礎に据え付ける。"], "answerHints": [["振動が大きい"]], "mnemonic": "正しくは：吸収冷温水機は運転時の振動が小さいので、一般的に防振基礎は不要。", "block": 12, "group": 4}, {"id": "R04_zenki_36", "source": "R3前 No.36 / R4前 No.36", "category": "施工管理法", "type": "single", "question": "保温、保冷、塗装等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷温水配管の吊りバンドの支持部には、合成樹脂製の支持受けを使用する。"}, {"label": "2", "text": "天井内に隠ぺいされる冷温水配管の保温は、水圧試験後に行う。"}, {"label": "3", "text": "アルミニウムペイントは、蒸気管や放熱器の塗装には使用しない。"}, {"label": "4", "text": "塗装場所の相対湿度が85%以上の場合、原則として、塗装を行わない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["アルミニウムペイントは、蒸気管や放熱器の塗装には使用しない。"], "answerHints": [["使用しない"]], "mnemonic": "正しくは：アルミニウムペイントは耐熱性があり、蒸気管や放熱器の塗装に使用される。", "block": 12, "group": 4}, {"id": "R04_kouki_29", "source": "R4後 No.29", "category": "施工管理法", "type": "single", "question": "公共工事の施工計画等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "工事に使用する資機材は、石綿を含有しないものとする。"}, {"label": "2", "text": "仮設計画は、設計図書に特別の定めがない場合、原則として請負者の責任において定める。"}, {"label": "3", "text": "現場説明書と質問回答書の内容に相違がある場合は、現場説明書の内容が優先される。"}, {"label": "4", "text": "工事写真は、後日の目視検査が容易でない箇所のほか、設計図書で定められている箇所についても撮影しなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["現場説明書と質問回答書の内容に相違がある場合は、現場説明書の内容が優先される。"], "answerHints": [["現場説明書の内容が優先される"]], "mnemonic": "正しくは：現場説明書と質問回答書が相違する場合は質問回答書が優先される。", "block": 12, "group": 4}, {"id": "R04_kouki_33", "source": "R4後 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飲料用受水タンクの上部には、排水設備や空気調和設備の配管等、飲料水以外の配管は通さないようにする。"}, {"label": "2", "text": "送風機及びモーターのプーリーの芯出しは、プーリーの外側面に定規、水糸等を当て出入りを調整する。"}, {"label": "3", "text": "汚物排水槽に設ける排水用水中モーターポンプは、点検、引上げに支障がないように、点検用マンホールの真下近くに設置する。"}, {"label": "4", "text": "壁付洗面器を軽量鉄骨ボード壁に取り付ける場合は、ボードに直接バックハンガーを取り付ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["壁付洗面器を軽量鉄骨ボード壁に取り付ける場合は、ボードに直接バックハンガーを取り付ける。"], "answerHints": [["ボードに直接"]], "mnemonic": "正しくは：軽量鉄骨ボード壁には補強材（下地）を入れ、そこにバックハンガーを取り付ける。", "block": 12, "group": 4}, {"id": "R04_kouki_36", "source": "R3後 No.36 / R4後 No.36", "category": "施工管理法", "type": "single", "question": "塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "塗料の調合は、原則として、工事現場で行う。"}, {"label": "2", "text": "塗装の工程間隔時間は、材料の種類、気象条件等に応じて定める。"}, {"label": "3", "text": "塗装場所の気温が5°C以下の場合、原則として、塗装は行わない。"}, {"label": "4", "text": "下塗り塗料としては、一般的に、さび止めペイントが使用される。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["塗料の調合は、原則として、工事現場で行う。"], "answerHints": [["工事現場で行う"]], "mnemonic": "正しくは：塗料の調合は原則として製造所で行う（現場調合はしない）。", "block": 12, "group": 4}, {"id": "R05_zenki_29", "source": "R5前 No.29", "category": "施工管理法", "type": "single", "question": "工事着工前に確認すべき事項として、適当でないものはどれか。", "choices": [{"label": "1", "text": "契約図書により、工事の内容や工事範囲、工事区分を確認する。"}, {"label": "2", "text": "試験成績表により、すべての機器の能力や仕様を確認する。"}, {"label": "3", "text": "工事の施工に伴って必要となる官公庁への届出や許可申請を確認する。"}, {"label": "4", "text": "工事敷地周辺の道路関係、交通事情、近隣との関係等について現地の状況を確認する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["試験成績表により、すべての機器の能力や仕様を確認する。"], "answerHints": [["試験成績表により"]], "mnemonic": "正しくは：着工前は設計図書で機器の能力・仕様を確認する。試験成績表は機器製作後に確認するもの。", "block": 12, "group": 4}, {"id": "R05_zenki_34", "source": "R5前 No.34", "category": "施工管理法", "type": "single", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "地中埋設配管で給水管と排水管が交差する場合には、給水管を排水管より上方に埋設する。"}, {"label": "2", "text": "絶縁フランジ接合は、鋼管とステンレス鋼管を接続する場合等に用いられる。"}, {"label": "3", "text": "給水管を地中埋設配管にて建物内へ引き込む部分には、防振継手を設ける。"}, {"label": "4", "text": "排水管の満水試験の保持時間は、最小30分とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給水管を地中埋設配管にて建物内へ引き込む部分には、防振継手を設ける。"], "answerHints": [["防振継手"]], "mnemonic": "正しくは：建物への引込み部には不同沈下に備えて変位吸収管継手（フレキシブル継手等）を設ける。", "block": 12, "group": 4}, {"id": "R05_zenki_37", "source": "R5前 No.37", "category": "施工管理法", "type": "single", "question": "多翼送風機の個別試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "軸受け部の温度と周囲の空気との温度差が、基準値以内であることを確認する。"}, {"label": "2", "text": "インバータ制御の場合は、回転数を徐々に上げながら規定風量となるように調整する。"}, {"label": "3", "text": "Vベルトがたわみなく強く張られた状態であることを確認する。"}, {"label": "4", "text": "送風機を手で回し、異常のないことを確認する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["Vベルトがたわみなく強く張られた状態であることを確認する。"], "answerHints": [["たわみなく強く張られた"]], "mnemonic": "正しくは：Vベルトは適度なたわみがある状態に張る。", "block": 12, "group": 4}, {"id": "R04_zenki_50", "source": "R4前 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "小型温水ボイラーをボイラー室内に設置する場合、ボイラー側面からボイラー室の壁面までの距離は、原則として、450mm以上とする。"}, {"label": "2", "text": "送風機やポンプのコンクリート基礎をあと施工する場合、当該コンクリート基礎は、ダボ鉄筋等で床スラブと一体化する。"}, {"label": "3", "text": "ボイラー室内の燃料タンクに液体燃料を貯蔵する場合、当該燃料タンクからボイラー側面までの距離は、原則として、1.2m以上とする。"}, {"label": "4", "text": "飲料用給水タンクの直上に天井スラブの梁がある場合、当該タンク上面から梁下面までの距離は、300mm以上を標準とする。"}], "answer": ["3", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ボイラー室内の燃料タンクに液体燃料を貯蔵する場合、当該燃料タンクからボイラー側面までの距離は、原則として、1.2m以上とする。", "飲料用給水タンクの直上に天井スラブの梁がある場合、当該タンク上面から梁下面までの距離は、300mm以上を標準とする。"], "answerHints": [["1.2m以上"], ["300mm以上"]], "mnemonic": "正しくは：燃料タンクからボイラー側面までは2m以上。給水タンク上面と梁下面との距離300mmでは保守点検空間として不足する（要確認）。", "block": 12, "group": 4}, {"id": "R04_kouki_49", "source": "R4後 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程表に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ガントチャート工程表は、各作業の進行度合いが把握しやすく、建築工事で頻繁に使用される。"}, {"label": "2", "text": "ガントチャート工程表は、各作業の前後関係が不明等の欠点があり、これを改善し発展させたものがバーチャート工程表である。"}, {"label": "3", "text": "バーチャート工程表は、作業間の順序関係が理解しやすく、大規模工事を管理するのに適している。"}, {"label": "4", "text": "ネットワーク工程表は、工期の短縮や遅れなどに速やかに対処・対応できる特徴を持っている。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ガントチャート工程表は、各作業の進行度合いが把握しやすく、建築工事で頻繁に使用される。", "バーチャート工程表は、作業間の順序関係が理解しやすく、大規模工事を管理するのに適している。"], "answerHints": [["頻繁に使用される"], ["大規模工事を管理するのに適している"]], "mnemonic": "正しくは：ガントチャートは作業間の関係や所要日数が不明で工程管理にはあまり使われない。大規模工事の管理に適するのはネットワーク工程表。", "block": 12, "group": 4}, {"id": "R04_kouki_52", "source": "R4後 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ダクトを拡大する場合は、15度以下の拡大角度とする。"}, {"label": "2", "text": "風量測定口の数は、一般的に、ダクトの長辺が700mmの場合は、1個とする。"}, {"label": "3", "text": "防火区画と防火ダンパーとの間のダクトは、厚さ1.2mm以上の鋼板製とする。"}, {"label": "4", "text": "外壁に取り付けるガラリには、衛生上有害なものの侵入を防ぐため、金網等を設ける。"}], "answer": ["2", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["風量測定口の数は、一般的に、ダクトの長辺が700mmの場合は、1個とする。", "防火区画と防火ダンパーとの間のダクトは、厚さ1.2mm以上の鋼板製とする。"], "answerHints": [["1個"], ["1.2mm以上"]], "mnemonic": "正しくは：長辺700mmのダクトの風量測定口は2個。防火区画貫通部と防火ダンパー間のダクトは厚さ1.5mm以上の鋼板製。", "block": 12, "group": 4}, {"id": "R05_zenki_51", "source": "R5前 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "架橋ポリエチレン管の接合は、電気融着接合又はメカニカル接合とする。"}, {"label": "2", "text": "一般配管用ステンレス鋼鋼管の管継手には、メカニカル形、ハウジング形等がある。"}, {"label": "3", "text": "排水横枝管が合流する場合は、合流する排水管の上部に接続する。"}, {"label": "4", "text": "飲料用受水タンクのオーバーフロー管には、トラップを設ける。"}], "answer": ["3", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["排水横枝管が合流する場合は、合流する排水管の上部に接続する。", "飲料用受水タンクのオーバーフロー管には、トラップを設ける。"], "answerHints": [["上部に接続"], ["トラップを設ける"]], "mnemonic": "正しくは：排水横枝管は45°以内の角度で水平に近く合流させる（上部から接続しない）。飲料用タンクのオーバーフロー管にはトラップを設けてはならない（間接排水）。", "block": 12, "group": 4}, {"id": "R04_zenki_40", "source": "R4前 No.40", "category": "法規", "type": "single", "question": "労働条件に関する記述のうち、「労働基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "使用者は、常時使用する労働者について、定められた様式によって労働者名簿を作成しなければならない。"}, {"label": "2", "text": "親権者若しくは後見人又は行政官庁は、労働契約が未成年者に不利であると認める場合においては、将来に向かって労働契約を解除することができる。"}, {"label": "3", "text": "使用者は、満18才に満たない者を危険な業務、衛生上又は福祉の面から有害な業務に従事させてはならない。"}, {"label": "4", "text": "使用者が、その年齢を証明する戸籍証明書を事業場に備え付けなければならないのは、満16才に満たない者を雇入れる場合である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["使用者が、その年齢を証明する戸籍証明書を事業場に備え付けなければならないのは、満16才に満たない者を雇入れる場合である。"], "answerHints": [["満16才"]], "mnemonic": "正しくは：年齢証明の戸籍証明書を備え付けるのは満18才に満たない者を使用する場合。", "block": 12, "group": 4}, {"id": "R04_zenki_43", "source": "R4前 No.43", "category": "法規", "type": "single", "question": "建設業に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "「建設業」とは、建設工事の完成を請け負う営業をいい、下請契約によるものを含まない。"}, {"label": "2", "text": "「下請契約」とは、建設工事を他の者から請け負った建設業を営む者と他の建設業を営む者との間で当該建設工事の全部又は一部について締結される請負契約をいう。"}, {"label": "3", "text": "「発注者」とは、建設工事の注文者のうち、他の者から請け負った建設工事の注文者を除いた者をいう。"}, {"label": "4", "text": "「元請負人」とは、下請契約における注文者で建設業者である者をいい、「下請負人」とは、下請契約における請負人をいう。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["「建設業」とは、建設工事の完成を請け負う営業をいい、下請契約によるものを含まない。"], "answerHints": [["含まない"]], "mnemonic": "正しくは：「建設業」は元請・下請その他いかなる名義でも建設工事の完成を請け負う営業（下請契約も含む）。", "block": 12, "group": 4}, {"id": "R04_zenki_46", "source": "R4前 No.46", "category": "法規", "type": "single", "question": "冷媒としてフロン類が充填されている機器のうち、「フロン類の使用の合理化及び管理の適正化に関する法律」の対象でないものはどれか。", "choices": [{"label": "1", "text": "家庭用エアコンディショナー"}, {"label": "2", "text": "ビル用マルチエアコンディショナー"}, {"label": "3", "text": "ターボ冷凍機"}, {"label": "4", "text": "冷水機"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["の対象でないもの"], "answerTexts": ["家庭用エアコンディショナー"], "answerHints": [["家庭用エアコンディショナー"]], "mnemonic": "フロン排出抑制法の対象は業務用の冷凍空調機器。家庭用エアコンは家電リサイクル法の対象。", "block": 12, "group": 4}, {"id": "R04_kouki_40", "source": "R4後 No.40", "category": "法規", "type": "single", "question": "災害補償に関する記述のうち、「労働基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "労働者が業務上負傷し、又は疾病にかかった場合においては、使用者は、その費用で必要な療養を行い、又は必要な療養の費用を負担しなければならない。"}, {"label": "2", "text": "労働者が業務上負傷し、労働することができないために賃金を受けない場合においては、使用者は、平均賃金の60/100の休業補償を行わなければならない。"}, {"label": "3", "text": "労働者が業務上負傷し、又は疾病にかかり、治った場合において、その身体に障害が存するときは、使用者は、その障害の程度に応じて、金銭的障害補償を行わなければならない。"}, {"label": "4", "text": "労働者が重大な過失によって業務上負傷したときに、使用者がその過失について行政官庁の認定を受けた場合においても、休業補償又は障害補償を行わなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["労働者が重大な過失によって業務上負傷したときに、使用者がその過失について行政官庁の認定を受けた場合においても、休業補償又は障害補償を行わなければならない。"], "answerHints": [["行わなければならない"]], "mnemonic": "正しくは：労働者の重大な過失で行政官庁の認定を受けた場合、休業補償・障害補償を行わなくてもよい。", "block": 12, "group": 4}, {"id": "R04_kouki_43", "source": "R4後 No.43", "category": "法規", "type": "single", "question": "建設業の許可を受けた建設業者が、現場に置く主任技術者等に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "主任技術者は、当該建設工事の施工計画の作成、工程管理、品質管理その他の技術上の管理及び当該建設工事の施工に従事する者の技術上の指導監督の職務を誠実に行わなければならない。"}, {"label": "2", "text": "工事現場における建設工事の施工に従事する者は、主任技術者又は監理技術者がその職務として行う指導に従わなければならない。"}, {"label": "3", "text": "発注者から直接建設工事を請け負った特定建設業者は、その工事の下請契約の請負代金の総額が一定額以上の場合、主任技術者の代わりに監理技術者を置かなければならない。"}, {"label": "4", "text": "主任技術者は、請負契約の履行を確保するため、請負人に代わって工事の施工に関する一切の事項を処理しなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["主任技術者は、請負契約の履行を確保するため、請負人に代わって工事の施工に関する一切の事項を処理しなければならない。"], "answerHints": [["請負人に代わって"]], "mnemonic": "正しくは：請負人に代わって一切の事項を処理するのは現場代理人。主任技術者の職務は施工の技術上の管理と指導監督。", "block": 12, "group": 4}, {"id": "R04_kouki_46", "source": "R4後 No.46", "category": "法規", "type": "single", "question": "次の建設資材のうち、「建設工事に係る資材の再資源化等に関する法律」上、再資源化が特に必要とされる特定建設資材に該当しないものはどれか。", "choices": [{"label": "1", "text": "コンクリート及び鉄から成る建設資材"}, {"label": "2", "text": "アスファルト・コンクリート"}, {"label": "3", "text": "アスファルト・ルーフィング"}, {"label": "4", "text": "木材"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["アスファルト・ルーフィング"], "answerHints": [["アスファルト・ルーフィング"]], "mnemonic": "特定建設資材はコンクリート、コンクリート及び鉄から成る資材、木材、アスファルト・コンクリートの4品目。", "block": 12, "group": 4}, {"id": "R05_zenki_39", "source": "R5前 No.39", "category": "法規", "type": "single", "question": "建設業における安全衛生管理に関する記述のうち、「労働安全衛生法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、常時10人以上50人未満の労働者を使用する事業場ごとに、安全衛生推進者を選任しなければならない。"}, {"label": "2", "text": "事業者は、作業主任者が必要な場合、都道府県労働局長の免許を受けた者又は都道府県労働局長の登録を受けた者が行う技能講習を修了した者のうちから選任しなければならない。"}, {"label": "3", "text": "事業者は、高所作業車を用いて作業を行うときは、当該作業の指揮者を定め、その者に作業計画に基づき作業の指揮を行わせなければならない。"}, {"label": "4", "text": "事業者は、移動はしごを使用する場合、はしごの幅は20cm以上のものでなければ使用してはならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、移動はしごを使用する場合、はしごの幅は20cm以上のものでなければ使用してはならない。"], "answerHints": [["20cm以上"]], "mnemonic": "正しくは：移動はしごの幅は30cm以上。", "block": 12, "group": 4}, {"id": "R05_zenki_43", "source": "R5前 No.43", "category": "法規", "type": "single", "question": "建設業の許可に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "「国土交通大臣の許可」と「都道府県知事の許可」では、どちらも工事可能な区域に制限はない。"}, {"label": "2", "text": "「国土交通大臣の許可」と「都道府県知事の許可」では、どちらも営業所の設置可能な区域に制限はない。"}, {"label": "3", "text": "「国土交通大臣の許可」と「都道府県知事の許可」では、どちらも受注可能な請負金額は変わらない。"}, {"label": "4", "text": "「国土交通大臣の許可」と「都道府県知事の許可」では、どちらも許可の有効期間は5年間で変わらない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["「国土交通大臣の許可」と「都道府県知事の許可」では、どちらも営業所の設置可能な区域に制限はない。"], "answerHints": [["営業所の設置可能な区域に制限はない"]], "mnemonic": "正しくは：知事許可は1つの都道府県内にのみ営業所を設置できる（工事可能な区域にはどちらも制限なし）。", "block": 12, "group": 4}, {"id": "R05_zenki_46", "source": "R5前 No.46", "category": "法規", "type": "single", "question": "浄化槽に関する記述のうち、「浄化槽法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "浄化槽を新設する場合は、原則として、合併処理浄化槽を設置しなければならない。"}, {"label": "2", "text": "浄化槽からの放流水は、生物化学的酸素要求量を20mg/L以下に処理したものでなければならない。"}, {"label": "3", "text": "浄化槽設備士は、その職務を行うときは、浄化槽設備士証を携帯していなければならない。"}, {"label": "4", "text": "浄化槽工事業を営もうとする者は、当該業を行おうとする区域を管轄する市町村長の登録を受けなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["浄化槽工事業を営もうとする者は、当該業を行おうとする区域を管轄する市町村長の登録を受けなければならない。"], "answerHints": [["市町村長"]], "mnemonic": "正しくは：浄化槽工事業は都道府県知事の登録を受ける。", "block": 12, "group": 4}, {"id": "R05_kouki_01", "source": "R5後 No.1", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか", "choices": [{"label": "1", "text": "飽和湿り空気の相対湿度は100%である。"}, {"label": "2", "text": "絶対湿度は、湿り空気中に含まれている乾き空気1kgに対する水蒸気の質量で示す。"}, {"label": "3", "text": "飽和湿り空気の乾球温度と湿球温度は等しい。"}, {"label": "4", "text": "湿り空気を加熱すると、その絶対湿度は下がる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["湿り空気を加熱すると、その絶対湿度は下がる。"], "answerHints": [["絶対湿度は下がる"]], "mnemonic": "正しくは：湿り空気を加熱しても水蒸気量は変わらないので、絶対湿度は変化しない（相対湿度は下がる）。", "block": 13, "group": 5}, {"id": "R05_kouki_04", "source": "R5後 No.4", "category": "一般基礎", "type": "single", "question": "伝熱に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "熱伝導とは、物体の内部において、温度の高い方から低い方に熱が伝わる現象をいう。"}, {"label": "2", "text": "個体壁とこれに接する流体間の熱伝達量は、固定表面と流体の温度差に反比例する。"}, {"label": "3", "text": "熱伝導率は材料固有のものであり、熱の伝わりやすさの度合いを示すものである。"}, {"label": "4", "text": "熱は、低温の物体から高温の物体へ自然に移ることはない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["個体壁とこれに接する流体間の熱伝達量は、固定表面と流体の温度差に反比例する。"], "answerHints": [["反比例する"]], "mnemonic": "正しくは：熱伝達量は、固体表面と流体の温度差に比例する。", "block": 13, "group": 5}, {"id": "R06_zenki_01", "source": "R6前 No.1", "category": "一般基礎", "type": "single", "question": "水に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "濁度は、水の濁りの程度を示す。"}, {"label": "2", "text": "CODは、水中に溶存する酸素量である。"}, {"label": "3", "text": "色度は、水の色の程度を示す。"}, {"label": "4", "text": "硬水は、カルシウムイオンやマグネシウムイオンを多く含む水である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["CODは、水中に溶存する酸素量である。"], "answerHints": [["水中に溶存する酸素量"]], "mnemonic": "正しくは：CODは化学的酸素要求量（酸化剤で有機物を酸化するのに消費される酸素量）。水中に溶けている酸素量はDO。", "block": 13, "group": 5}, {"id": "R06_zenki_05", "source": "R6前 No.5", "category": "一般基礎", "type": "single", "question": "電気設備に関する用語の組合せのうち、関係のないものはどれか。", "choices": [{"label": "1", "text": "配線用遮断器 ――― 力率改善"}, {"label": "2", "text": "接地 ――――――― 感電防止"}, {"label": "3", "text": "三相3線式 ―――― 配電方式"}, {"label": "4", "text": "サーマルリレー ―― 過負荷検出"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["配線用遮断器 ――― 力率改善"], "answerHints": [["力率改善"]], "mnemonic": "配線用遮断器は過電流・短絡の保護。力率改善は進相コンデンサ。", "block": 13, "group": 5}, {"id": "R06_kouki_04", "source": "R6後 No.4", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "湿り空気を加熱すると、その絶対湿度は下がる。"}, {"label": "2", "text": "絶対湿度は、湿り空気中の乾き空気1kg に対する水蒸気の質量で示す。"}, {"label": "3", "text": "飽和湿り空気の乾球温度と湿球温度は等しい。"}, {"label": "4", "text": "飽和湿り空気の相対湿度は100 %である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["湿り空気を加熱すると、その絶対湿度は下がる。"], "answerHints": [["絶対湿度は下がる"]], "mnemonic": "正しくは：湿り空気を加熱しても絶対湿度は変化しない（相対湿度は下がる）。", "block": 13, "group": 5}, {"id": "R05_kouki_07", "source": "R5後 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和設備の計画に関する記述のうち、省エネルギーの観点から、適当でないものはどれか。", "choices": [{"label": "1", "text": "空調用外気の取入れには、全熱交換器を採用する。"}, {"label": "2", "text": "高効率の機器を採用する。"}, {"label": "3", "text": "熱源機器を複数台に分割する。"}, {"label": "4", "text": "暖房時に外気導入量を多くする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["暖房時に外気導入量を多くする。"], "answerHints": [["外気導入量を多くする"]], "mnemonic": "正しくは：暖房時の外気導入量は必要最小限に抑えるのが省エネ。", "block": 13, "group": 5}, {"id": "R05_kouki_11", "source": "R5後 No.11", "category": "空調・衛生", "type": "single", "question": "コールドドラフトの防止に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "自然対流形の放熱器では、放熱器の表面温度と室内温度の差を小さくする。"}, {"label": "2", "text": "放熱器は、内壁側に設置する。"}, {"label": "3", "text": "エアフローウィンドウで窓面の熱負荷を低減する。"}, {"label": "4", "text": "外壁に面する建具の気密性を高め、隙間風を減らす。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["放熱器は、内壁側に設置する。"], "answerHints": [["内壁側"]], "mnemonic": "正しくは：コールドドラフト防止には、放熱器を外壁側（窓下）に設置する。", "block": 13, "group": 5}, {"id": "R05_kouki_14", "source": "R5後 No.14", "category": "空調・衛生", "type": "single", "question": "換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "自然換気は、温度差による浮力等によって室内の空気を屋外へ排出する。"}, {"label": "2", "text": "機械換気は、送風機等を利用して室内の空気を入れ替える。"}, {"label": "3", "text": "必要換気量とは、室内を循環する空気量で、外気は含まれない。"}, {"label": "4", "text": "局所換気とは、汚染物質が発生する場所を局部的に換気する方法である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["必要換気量とは、室内を循環する空気量で、外気は含まれない。"], "answerHints": [["外気は含まれない"]], "mnemonic": "正しくは：必要換気量とは、室内に取り入れる外気量のこと。", "block": 13, "group": 5}, {"id": "R05_kouki_17", "source": "R5後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "受水タンクのオーバーフローの取り出しは、給水管の吐水口端の高さより上方からとする。"}, {"label": "2", "text": "揚程が30mを超える給水ポンプの吐出し側に取り付ける逆止め弁は、衝撃吸収式とする。"}, {"label": "3", "text": "受水タンクへの給水には、ボールタップや定水位弁が用いられる。"}, {"label": "4", "text": "クロスコネクションとは、飲料水系統とその他の系統が、配管・装置により直接接続されることをいう。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["受水タンクのオーバーフローの取り出しは、給水管の吐水口端の高さより上方からとする。"], "answerHints": [["上方から"]], "mnemonic": "正しくは：オーバーフローの取り出しは、給水管の吐水口端の高さより下方からとする。", "block": 13, "group": 5}, {"id": "R05_kouki_20", "source": "R5後 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水槽の吸込ピットは、排水用水中モーターポンプ吸込部の周囲及び下部に200mm以上の間隔を持たせる。"}, {"label": "2", "text": "排水立て管の上部は、一般的に、伸頂通気管として延長し、大気に開放する。"}, {"label": "3", "text": "排水管は、立て管又は横管のいずれの場合でも、排水の流下方向の管径は縮小しない。"}, {"label": "4", "text": "ループ通気管は、最上流の器具排水管が排水横枝管に接続した点のすぐ上流から立ち上げる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ループ通気管は、最上流の器具排水管が排水横枝管に接続した点のすぐ上流から立ち上げる。"], "answerHints": [["すぐ上流"]], "mnemonic": "正しくは：ループ通気管は、最上流の器具排水管が接続した点のすぐ下流から立ち上げる。", "block": 13, "group": 5}, {"id": "R06_zenki_07", "source": "R6前 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "定風量単一ダクト方式は、ファンコイルユニット・ダクト併用方式に比べて送風量が小さくなる。"}, {"label": "2", "text": "ファンコイルユニット・ダクト併用方式は、空調対象室への熱媒体として空気と水を使用する。"}, {"label": "3", "text": "定風量単一ダクト方式は、送風量が一定である。"}, {"label": "4", "text": "ファンコイルユニット・ダクト併用方式は、ファンコイルユニット毎の個別制御が可能である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["定風量単一ダクト方式は、ファンコイルユニット・ダクト併用方式に比べて送風量が小さくなる。"], "answerHints": [["送風量が小さくなる"]], "mnemonic": "正しくは：定風量単一ダクト方式は全空気方式なので、FCU・ダクト併用方式より送風量が大きくなる。", "block": 13, "group": 5}, {"id": "R06_zenki_10", "source": "R6前 No.10", "category": "空調・衛生", "type": "single", "question": "空気清浄装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "自動巻取形は、ロール状に巻いたろ材を自動的に巻き取る方式のため長時間使用できる。"}, {"label": "2", "text": "計数法とは、フィルターい捕集された粉じんの質量から捕集率を求める方法である。"}, {"label": "3", "text": "ろ過式のろ材には、天然繊維、ガラス、セラミックス等が使用されている。"}, {"label": "4", "text": "フィルターの通過速度を低く抑えるために、ろ材を折り込んだものや袋状にしたものがある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["計数法とは、フィルターい捕集された粉じんの質量から捕集率を求める方法である。"], "answerHints": [["粉じんの質量"]], "mnemonic": "正しくは：計数法は粉じんの個数から捕集率を求める。質量から求めるのは質量法。", "block": 13, "group": 5}, {"id": "R06_zenki_13", "source": "R6前 No.13", "category": "空調・衛生", "type": "single", "question": "次のうち、第三種機械換気方式を用いることが適当でないものはどれか。", "choices": [{"label": "1", "text": "倉庫"}, {"label": "2", "text": "湯沸室"}, {"label": "3", "text": "電気室"}, {"label": "4", "text": "ボイラー室"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボイラー室"], "answerHints": [["ボイラー室"]], "mnemonic": "ボイラー室は燃焼空気の供給が必要なので第一種（または第二種）。倉庫・湯沸室・電気室は第三種でもよい。", "block": 13, "group": 5}, {"id": "R06_zenki_16", "source": "R6前 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "下水道は、公共下水道、流域下水道及び都市下水路に分けられる。"}, {"label": "2", "text": "下水道本管に接続する取付管の勾配は、1/100以上とする。"}, {"label": "3", "text": "排水設備の雨水ますの底には、深さ10cm以上のどろためを設ける。"}, {"label": "4", "text": "管きょの流速は、一般的に、下流に行くに従い漸増させ、勾配は、下流に行くに従い緩やかにする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水設備の雨水ますの底には、深さ10cm以上のどろためを設ける。"], "answerHints": [["深さ10cm以上"]], "mnemonic": "正しくは：雨水ますの底には深さ15cm以上のどろためを設ける。", "block": 13, "group": 5}, {"id": "R06_zenki_20", "source": "R5前 No.20 / R6前 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "通気立て管の下部は、最低位の排水横枝管より高い位置で排水立て管に接続する。"}, {"label": "2", "text": "各個通気方式は、誘導サイホン作用及び自己サイホン作用の防止に有効である。"}, {"label": "3", "text": "排水ますは、屋外排水管の直進距離が管径の120倍を超えない範囲で設ける。"}, {"label": "4", "text": "排水管に設ける通気管の最小管径は、30mmとする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["通気立て管の下部は、最低位の排水横枝管より高い位置で排水立て管に接続する。"], "answerHints": [["高い位置で"]], "mnemonic": "正しくは：通気立て管の下部は、最低位の排水横枝管より低い位置で排水立て管に接続するか、排水横主管に接続する。", "block": 13, "group": 5}, {"id": "R06_zenki_23", "source": "R6前 No.23", "category": "空調・衛生", "type": "single", "question": "FRP製浄化槽の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "深く掘り過ぎて埋め戻すと、設置後不等沈下するおそれがある。"}, {"label": "2", "text": "槽本体の水平確認は、水準器や内壁に示されている水準目安線等で確認する。"}, {"label": "3", "text": "地下水位の高い場所に設置する場合は、浮上防止対策として、槽の周囲に山砂を入れ突き固め、水締めを行う。"}, {"label": "4", "text": "試運転は、浄化槽に水を流し、各槽の水位、流れの状況、ブロア等の稼働状況を確認し調整を行う。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["地下水位の高い場所に設置する場合は、浮上防止対策として、槽の周囲に山砂を入れ突き固め、水締めを行う。"], "answerHints": [["浮上防止対策として"]], "mnemonic": "正しくは：浮上防止は、底版コンクリートに浮上防止金具等で槽を固定して行う（山砂の水締めは通常の埋戻し）。", "block": 13, "group": 5}, {"id": "R06_kouki_10", "source": "R6後 No.10", "category": "空調・衛生", "type": "single", "question": "エアフィルターの 種類」と 主な用途」の組合せのうち、適当でないものはどれか。 [種類] [主な用途]", "choices": [{"label": "1", "text": "自動巻取形 厨房排気"}, {"label": "2", "text": "粗じん用エアフィルター 外気用"}, {"label": "3", "text": "電気集じん器 一般空調用"}, {"label": "4", "text": "活性炭フィルター 有害ガス除去"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["自動巻取形 厨房排気"], "answerHints": [["厨房排気"]], "mnemonic": "自動巻取形は一般空調用（粗じん用）。厨房排気にはグリスフィルター。", "block": 13, "group": 5}, {"id": "R06_kouki_13", "source": "R6後 No.13", "category": "空調・衛生", "type": "single", "question": "換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "温度差を利用する自然換気方式では、換気対象室の高い位置に排気口を設ける。"}, {"label": "2", "text": "無窓の居室の換気は、第一種機械換気方式とする。"}, {"label": "3", "text": "第二種機械換気方式は、排気口を設けない。"}, {"label": "4", "text": "便所の換気は、臭気の拡散防止のため第三種機械換気方式とし室内を負圧とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["第二種機械換気方式は、排気口を設けない。"], "answerHints": [["排気口を設けない"]], "mnemonic": "正しくは：第二種機械換気は給気が送風機、排気は排気口（自然排気）で室内を正圧にする。", "block": 13, "group": 5}, {"id": "R06_kouki_16", "source": "R6後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "管きょのますは、管きょの長さがその内径又は内のり幅の200 倍を超えない範囲内に設ける。"}, {"label": "2", "text": "汚水ますのマンホールは、密閉することができるふたを設ける。"}, {"label": "3", "text": "公共下水道に流入させるための建物敷地内の排水管の土被りは、原則として20 cm 以上と する。"}, {"label": "4", "text": "敷地からの下水は、排水設備を通じて公共下水道に排除される。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["管きょのますは、管きょの長さがその内径又は内のり幅の200 倍を超えない範囲内に設ける。"], "answerHints": [["200 倍"]], "mnemonic": "正しくは：ますは、管きょの長さが内径又は内のり幅の120倍を超えない範囲内に設ける。", "block": 13, "group": 5}, {"id": "R06_kouki_19", "source": "R6後 No.19", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "通気管の最小管径は、25 mm とする。"}, {"label": "2", "text": "トラップは、封水により、排水管からの下水ガス等の室内への浸入を防止する。"}, {"label": "3", "text": "飲料用タンクの間接排水管の排水口空間は、排水管の管径によらず、最小150 mm とする。"}, {"label": "4", "text": "横走排水管に設ける掃除口の取付け間隔は、管径が100 mm 以下の場合は15 m 以内、 100 mm を超える場合は30 m 以内が望ましい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["通気管の最小管径は、25 mm とする。"], "answerHints": [["25 mm"]], "mnemonic": "正しくは：通気管の最小管径は30mm。", "block": 13, "group": 5}, {"id": "R06_kouki_23", "source": "R5後 No.23 / R6後 No.23", "category": "空調・衛生", "type": "single", "question": "JIS に規定する 建築物の用途別による屎尿浄化槽の処理対象人員算定基準」におい て、処理対象人員を算定する際、延べ面積によることが適当でないものはどれか。", "choices": [{"label": "1", "text": "事務所"}, {"label": "2", "text": "集会場"}, {"label": "3", "text": "公衆便所"}, {"label": "4", "text": "共同住宅"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["公衆便所"], "answerHints": [["公衆便所"]], "mnemonic": "公衆便所の処理対象人員は総便器数で算定。事務所・集会場・共同住宅は延べ面積で算定。", "block": 13, "group": 5}, {"id": "R05_kouki_26", "source": "R5後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "Y形ストレーナーは、円筒形のスクリーンを流路に対して45度傾けた構造で、横引きの配管では、上部にスクリーンを引き抜く。"}, {"label": "2", "text": "銅管は、肉厚によりK、L及びMタイプに分類される。"}, {"label": "3", "text": "弁を中間開度にして流量調整を行う場合には、玉形弁とバタフライ弁は適しているが、ボール弁と仕切弁は適していない。"}, {"label": "4", "text": "水道用硬質ポリ塩化ビニル管の種類には、VPとHIVPがある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["Y形ストレーナーは、円筒形のスクリーンを流路に対して45度傾けた構造で、横引きの配管では、上部にスクリーンを引き抜く。"], "answerHints": [["上部に"]], "mnemonic": "正しくは：横引き配管のY形ストレーナーは、下部にスクリーンを引き抜く。", "block": 13, "group": 5}, {"id": "R06_zenki_25", "source": "R6前 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "水中モーターポンプに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "汚物用水中モーターポンプは、浄化槽への流入水等、固形物も含んだ水を排出するためのポンプである。"}, {"label": "2", "text": "汚水や厨房排水のような浮遊物質を含む排水漕では、電極棒による自動運転とする。"}, {"label": "3", "text": "羽根車の種類は、一般的に、オープン形とクローズ形に分類される。"}, {"label": "4", "text": "水中モーターポンプの乾式は、水が内部に浸入しないよう空気又はその他の気体を充満密封したものである。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["汚水や厨房排水のような浮遊物質を含む排水漕では、電極棒による自動運転とする。"], "answerHints": [["電極棒"]], "mnemonic": "正しくは：浮遊物質を含む汚水・厨房排水の排水槽では、フロートスイッチによる自動運転とする（電極棒は汚れで誤作動）。", "block": 13, "group": 5}, {"id": "R06_kouki_24", "source": "R6後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "空気調和機等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ユニット形空気調和機の風量調節は、インバーターやスクロールダンパー等で行う。"}, {"label": "2", "text": "コンパクト形空気調和機は、ユニット形空気調和機と同様の保守・点検が必要である。"}, {"label": "3", "text": "ファンコイルユニットは、冷媒にフロンを使用して室内空気を冷却除湿又は加熱する機器で ある。"}, {"label": "4", "text": "ユニット形空気調和機は、一般的に、冷水と温水を切り替えて供給し、冷水コイルと温水コ イルを兼用することが多い。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ファンコイルユニットは、冷媒にフロンを使用して室内空気を冷却除湿又は加熱する機器で ある。"], "answerHints": [["冷媒にフロン"]], "mnemonic": "正しくは：ファンコイルユニットは、冷水・温水を使用して室内空気を冷却除湿又は加熱する。", "block": 13, "group": 5}, {"id": "R05_kouki_29", "source": "R5後 No.29", "category": "施工管理法", "type": "single", "question": "公共工事の施工計画等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "工事に使用する資機材は、石綿を含有しないものとする。"}, {"label": "2", "text": "仮設計画は、設計図書に特別の定めがない場合、原則として受注者の責任において定める。"}, {"label": "3", "text": "工事写真は、後日の目視検査が容易でない箇所のほか、設計図書で定められている箇所についても撮影しなければならない。"}, {"label": "4", "text": "現場説明書と質問回答書の内容に相違がある場合は、現場説明書の内容が優先される。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["現場説明書と質問回答書の内容に相違がある場合は、現場説明書の内容が優先される。"], "answerHints": [["現場説明書の内容が優先"]], "mnemonic": "正しくは：質問回答書が現場説明書より優先される（質問回答書＞現場説明書＞特記仕様書＞図面＞標準仕様書）。", "block": 13, "group": 5}, {"id": "R05_kouki_34", "source": "R5後 No.34", "category": "施工管理法", "type": "single", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配管用炭素鋼鋼管を雑排水系統に使用する場合、配管用鋼製突合せ溶接式管継手で接続する。"}, {"label": "2", "text": "給水用の塩ビライニング鋼管に用いる仕切弁には、管端防食ねじ込み形弁がある。"}, {"label": "3", "text": "鋼管の突合わせ溶接による接合は、開先加工等を行い、ルート間隔を保持して行う。"}, {"label": "4", "text": "排水・通気用耐火二層管の接合には、接着接合、ゴム輪接合(伸縮継手用)がある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["配管用炭素鋼鋼管を雑排水系統に使用する場合、配管用鋼製突合せ溶接式管継手で接続する。"], "answerHints": [["配管用鋼製突合せ溶接式管継手"]], "mnemonic": "正しくは：雑排水系統の配管用炭素鋼鋼管は、ねじ込み式排水管継手（ドレネージ継手）やMD継手で接続する。", "block": 13, "group": 5}, {"id": "R05_kouki_37", "source": "R5後 No.37", "category": "施工管理法", "type": "single", "question": "渦巻ポンプの試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ポンプを手で回して回転むらがないか確認する。"}, {"label": "2", "text": "瞬時運転を行い、ポンプの回転方向を確認する。"}, {"label": "3", "text": "メカニカルシール部からの水滴の滴下が一定量継続してあることを確認する。"}, {"label": "4", "text": "軸受温度が周囲空気温度より過度に高くなっていないことを確認する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["メカニカルシール部からの水滴の滴下が一定量継続してあることを確認する。"], "answerHints": [["メカニカルシール部"]], "mnemonic": "正しくは：水滴の滴下が一定量あるのはグランドパッキン。メカニカルシールは漏れがほとんどないことを確認する。", "block": 13, "group": 5}, {"id": "R06_zenki_32", "source": "R6前 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "高さが2mの箇所で作業を行う場合、墜落により労働者に危険を及ぼすおそれのあるときは、作業床を設け、作業床の端、開口部等には囲い、手すり、覆い等を設ける。"}, {"label": "2", "text": "事業者は、足場の組立ての作業に労働者をつかせるときは、当該業務に関する安全又は衛生のための特別の教育を行う。"}, {"label": "3", "text": "熱中症予防のため屋外朝礼広場のWBGT値を確認したときは、作業場所での確認は必要ない。"}, {"label": "4", "text": "通風が不十分な場所でアルゴン等を使用して行う溶接の作業に労働者を従事させるときは、作業場所の空気中の酸素濃度を18%以上に保つように換気するか空気呼吸器等を使用させる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["熱中症予防のため屋外朝礼広場のWBGT値を確認したときは、作業場所での確認は必要ない。"], "answerHints": [["作業場所での確認は必要ない"]], "mnemonic": "正しくは：WBGT値は実際の作業場所で確認する必要がある。", "block": 13, "group": 5}, {"id": "R06_zenki_35", "source": "R6前 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクトに設けるリブ補強は、ダクトの変形や騒音及び振動の発生を防止するために設ける。"}, {"label": "2", "text": "外壁を貫通するダクトとスリーブとの隙間は、バックアップ材等を充填し、シーリング材にて水密を確保する。"}, {"label": "3", "text": "共板フランジ工法ダクトとアングルフランジ工法ダクトでは、横走りダクトの許容最大吊り間隔は同じである。"}, {"label": "4", "text": "厨房の排気ダクトには、ダクト内の点検ができるように点検口等を設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["共板フランジ工法ダクトとアングルフランジ工法ダクトでは、横走りダクトの許容最大吊り間隔は同じである。"], "answerHints": [["同じである"]], "mnemonic": "正しくは：横走りダクトの最大吊り間隔は、共板フランジ工法2m、アングルフランジ工法3mで異なる。", "block": 13, "group": 5}, {"id": "R06_zenki_38", "source": "R6前 No.38", "category": "施工管理法", "type": "single", "question": "試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "渦巻ポンプは、機器及び配管系統のエア抜きをした後に行う。"}, {"label": "2", "text": "高置タンク方式の給水設備では、高置タンクに最も近い水栓で残留塩素の測定を行う。"}, {"label": "3", "text": "揚水ポンプは、水位による発停や警報の発報を確認する。"}, {"label": "4", "text": "屋外騒音の測定は、冷却塔等の騒音の発生源となる機器を運転して、敷地境界線上で行う。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["高置タンク方式の給水設備では、高置タンクに最も近い水栓で残留塩素の測定を行う。"], "answerHints": [["最も近い"]], "mnemonic": "正しくは：残留塩素の測定は、高置タンクから最も遠い水栓で行う。", "block": 13, "group": 5}, {"id": "R06_kouki_34", "source": "R6後 No.34", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ビニル管を切断する場合は、専用のカッタ又は、目の細かいのこぎりを使用する。"}, {"label": "2", "text": "飲料用給水管と井水管を接続する場合は、絶縁フランジ接合とする。"}, {"label": "3", "text": "排水横枝管から通気管を取り出す場合は、排水横枝管の中心線から垂直上方ないし垂直 上方から45°以内の角度で取り出す。"}, {"label": "4", "text": "機器や器具の構造により、吐水口空間が確保できない場合には、バキュームブレーカーを設置 する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用給水管と井水管を接続する場合は、絶縁フランジ接合とする。"], "answerHints": [["絶縁フランジ接合とする"]], "mnemonic": "正しくは：飲料用給水管と井水管は接続してはならない（クロスコネクション禁止）。", "block": 13, "group": 5}, {"id": "R06_kouki_37", "source": "R6後 No.37", "category": "施工管理法", "type": "single", "question": "試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "多翼送風機は、軸受の温度を確認する。"}, {"label": "2", "text": "渦巻ポンプは、吐出し側の弁を全開から徐々に閉じて流量調整を行う。"}, {"label": "3", "text": "ボイラーは、地震感知装置による燃料停止の作動を確認する。"}, {"label": "4", "text": "冷凍機は、関連機器とのインターロックを確認してから起動する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["渦巻ポンプは、吐出し側の弁を全開から徐々に閉じて流量調整を行う。"], "answerHints": [["全開から徐々に閉じて"]], "mnemonic": "正しくは：渦巻ポンプは吐出し側の弁を全閉から徐々に開いて流量調整する。", "block": 13, "group": 5}, {"id": "R05_kouki_50", "source": "R5後 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ポンプは、現場にて電動機との軸心に狂いのないことを確認する。"}, {"label": "2", "text": "高さが2mを超える高置タンクの昇降タラップには、転落防止防護柵を設ける。"}, {"label": "3", "text": "冷却塔は、補給水口の高さが高置タンクの低水位と同じ高さとなるように据え付ける。"}, {"label": "4", "text": "送風機は、あらかじめ心出し調整されて出荷されているので、現場での調整は不要である。"}], "answer": ["3", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["冷却塔は、補給水口の高さが高置タンクの低水位と同じ高さとなるように据え付ける。", "送風機は、あらかじめ心出し調整されて出荷されているので、現場での調整は不要である。"], "answerHints": [["同じ高さ"], ["現場での調整は不要"]], "mnemonic": "正しくは：冷却塔の補給水口は高置タンクの低水位から必要な落差（水頭）をとる。送風機は現場でも心出し調整を行う。", "block": 13, "group": 5}, {"id": "R06_zenki_49", "source": "R6前 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程管理に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "タクト工程表は、同一の作業内容が繰り返し行われる場合に適している。"}, {"label": "2", "text": "ガントチャート工程表は、バーチャート工程表に比べて必要な作業日数が把握しやすい。"}, {"label": "3", "text": "工程計画の立案では、天候や季節、地域の行事等の作業不可能日数も考慮する。"}, {"label": "4", "text": "ネットワーク工程表は、工事途中での工事内容の変更に対応しにくい。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ガントチャート工程表は、バーチャート工程表に比べて必要な作業日数が把握しやすい。", "ネットワーク工程表は、工事途中での工事内容の変更に対応しにくい。"], "answerHints": [["把握しやすい"], ["対応しにくい"]], "mnemonic": "正しくは：ガントチャートは必要な作業日数が把握しにくい。ネットワーク工程表は計画変更に対処しやすい。", "block": 13, "group": 5}, {"id": "R06_zenki_52", "source": "R6前 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "共板フランジ工法ダクトの接続は、フランジ押さえ金具のみで行い、ボルト・ナットを使用しない。"}, {"label": "2", "text": "外壁の延焼のおそれのある部分の給・排気口には、防火覆い又は防火ダンパーを設ける。"}, {"label": "3", "text": "吹出口の配置は、吹出し空気の拡散半径や到達距離等を考慮し決定する。"}, {"label": "4", "text": "送風機の吐出し口直後のダクトを曲げる場合は、羽根の回転方向と逆方向とする。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["共板フランジ工法ダクトの接続は、フランジ押さえ金具のみで行い、ボルト・ナットを使用しない。", "送風機の吐出し口直後のダクトを曲げる場合は、羽根の回転方向と逆方向とする。"], "answerHints": [["ボルト・ナットを使用しない"], ["逆方向"]], "mnemonic": "正しくは：共板フランジはフランジ押さえ金具と四隅のボルト・ナットで接続する。送風機吐出し直後の曲げは羽根の回転方向と同じ方向とする。", "block": 13, "group": 5}, {"id": "R06_kouki_52", "source": "R6後 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "風量調整ダンパーは、気流の整流されたところに取り付ける。"}, {"label": "2", "text": "防火区画貫通部と防火ダンパーとの間のダクトは、厚さ1.2 mm以上の鋼板製とする。"}, {"label": "3", "text": "フレキシブルダクトを使用する場合は、有効断面を損なわないよう施工する。"}, {"label": "4", "text": "スパイラルダクトの差込み接合では、継目をダクト用テープで一重巻きをする。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["防火区画貫通部と防火ダンパーとの間のダクトは、厚さ1.2 mm以上の鋼板製とする。", "スパイラルダクトの差込み接合では、継目をダクト用テープで一重巻きをする。"], "answerHints": [["1.2 mm以上"], ["一重巻き"]], "mnemonic": "正しくは：防火区画貫通部と防火ダンパー間のダクトは厚さ1.5mm以上。スパイラルダクトの差込み接合はダクト用テープで二重巻き。", "block": 13, "group": 5}, {"id": "R05_kouki_41", "source": "R5後 No.41", "category": "法規", "type": "single", "question": "建築物の用語に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "娯楽のために継続的に使用する室は、居室ではない。"}, {"label": "2", "text": "事務所ビルの屋上に設ける避雷針は、建築設備である。"}, {"label": "3", "text": "金属板とガラスは、いずれも不燃材料である。"}, {"label": "4", "text": "主要構造部が耐火構造である建築物は、耐火建築物である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["娯楽のために継続的に使用する室は、居室ではない。"], "answerHints": [["居室ではない"]], "mnemonic": "正しくは：居住・執務・作業・集会・娯楽等のために継続的に使用する室は居室である。", "block": 13, "group": 5}, {"id": "R05_kouki_44", "source": "R5後 No.44", "category": "法規", "type": "single", "question": "建設業の許可を受けた建設業者が、発注者から直接請け負った建設工事の現場に掲げる標識の記載事項として、「建設業法」上、定められていないものはどれか。", "choices": [{"label": "1", "text": "一般建設業又は特定建設業の別"}, {"label": "2", "text": "商号又は名称"}, {"label": "3", "text": "現場代理人の氏名"}, {"label": "4", "text": "代表者の氏名"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["現場代理人の氏名"], "answerHints": [["現場代理人の氏名"]], "mnemonic": "標識に記載するのは主任技術者（監理技術者）の氏名。現場代理人の氏名は定められていない。", "block": 13, "group": 5}, {"id": "R05_kouki_47", "source": "R5後 No.47", "category": "法規", "type": "single", "question": "次の建築設備のうち、「建築物のエネルギー消費性能の向上に関する法律」上、エネルギー消費性能の対象として規定されていないものはどれか。", "choices": [{"label": "1", "text": "給湯設備"}, {"label": "2", "text": "昇降機"}, {"label": "3", "text": "空気調和設備その他の機械換気設備"}, {"label": "4", "text": "ガス設備"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["対象として規定されていないもの"], "answerTexts": ["ガス設備"], "answerHints": [["ガス設備"]], "mnemonic": "建築物省エネ法の対象設備は空調・換気・照明・給湯・昇降機。ガス設備は対象外。", "block": 13, "group": 5}, {"id": "R06_zenki_40", "source": "R6前 No.40", "category": "法規", "type": "single", "question": "労働条件に関する記述のうち、「労働基準法」上、誤っているものはどれか。ただし、労働組合等との協定等による別の定めがある場合を除く。", "choices": [{"label": "1", "text": "使用者から明示された労働条件が事実と相違する場合においては、労働者は、即時に労働契約を解除することができる。"}, {"label": "2", "text": "使用者は、労働者に、休憩時間を自由に利用させなければならない。"}, {"label": "3", "text": "使用者は、労働者に、休憩時間を一斉に与えなければならない。"}, {"label": "4", "text": "使用者は、労働者に、休憩時間を除き1日について6時間を超えて、労働させてはならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["使用者は、労働者に、休憩時間を除き1日について6時間を超えて、労働させてはならない。"], "answerHints": [["6時間"]], "mnemonic": "正しくは：休憩時間を除き1日8時間を超えて労働させてはならない。", "block": 13, "group": 5}, {"id": "R06_zenki_43", "source": "R6前 No.43", "category": "法規", "type": "single", "question": "「建設業法」の用語に関する記述のうち、誤っているものはどれか。", "choices": [{"label": "1", "text": "「建設業」とは、建設工事の完成を請け負う営業をいい、元請、下請その他いかなる名義をもってするかは問わない。"}, {"label": "2", "text": "「発注者」とは、建設工事の注文者のうち、他の者から請け負った建設工事の注文者を除いた者をいう。"}, {"label": "3", "text": "「元請負人」とは、下請契約における注文者をいい、建設業者であるものに限らない。"}, {"label": "4", "text": "水道施設工事は、「建設工事」に含まれる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["「元請負人」とは、下請契約における注文者をいい、建設業者であるものに限らない。"], "answerHints": [["建設業者であるものに限らない"]], "mnemonic": "正しくは：元請負人とは、下請契約における注文者で建設業者であるものをいう。", "block": 13, "group": 5}, {"id": "R06_zenki_46", "source": "R6前 No.46", "category": "法規", "type": "single", "question": "騒音の規制に関する記述のうち、「騒音規制法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "特定建設作業とは、建設工事として行われる作業のうち、特定建設業者が行う作業をいう。"}, {"label": "2", "text": "指定地域とは、特定工場等において発生する騒音及び特定建設作業に伴って発生する騒音について規制する地域として指定された地域をいう。"}, {"label": "3", "text": "指定地域内において特定建設作業を伴う建設工事を施工しようとする者は、当該特定建設作業の開始の日の7日前までに、届け出なければならない。"}, {"label": "4", "text": "指定地域内における特定建設作業の実施の届出の事項には、騒音の防止の方法が含まれる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["特定建設作業とは、建設工事として行われる作業のうち、特定建設業者が行う作業をいう。"], "answerHints": [["特定建設業者が行う作業"]], "mnemonic": "正しくは：特定建設作業とは、建設工事のうち著しい騒音を発生する作業で政令で定めるもの。", "block": 13, "group": 5}, {"id": "R06_kouki_39", "source": "R6後 No.39", "category": "法規", "type": "single", "question": "建設工事における安全衛生管理に関する記述のうち、労働安全衛生法」上、 誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、高所作業車を用いて作業を行うときは、当該作業の指揮者を定め、その者に作 業計画に基づき作業の指揮を行わせなければならない。"}, {"label": "2", "text": "事業者は、労働者を雇い入れたときは、当該労働者に対し、その従事する業務に関する安全 又は衛生のための教育を行わなければならないが、作業内容を変更した場合は行う必要はな い。"}, {"label": "3", "text": "事業者は、明り掘削の作業を行う場合において、運搬機械等が、労働者の作業箇所に後進 して接近するときは、誘導者を配置し、その者にこれらの機械を誘導させなければならない。"}, {"label": "4", "text": "事業者は、中高年齢者その他労働災害の防止上その就業に当たって特に配慮を必要とする 者については、これらの者の心身の条件に応じて適正な配置を行うように努めなければなら ない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、労働者を雇い入れたときは、当該労働者に対し、その従事する業務に関する安全 又は衛生のための教育を行わなければならないが、作業内容を変更した場合は行う必要はな い。"], "answerHints": [["行う必要はな"]], "mnemonic": "正しくは：雇入れ時だけでなく、作業内容を変更したときも安全衛生教育を行わなければならない。", "block": 13, "group": 5}, {"id": "R06_kouki_42", "source": "R6後 No.42", "category": "法規", "type": "single", "question": "建築物に設ける排水設備に関する記述のうち、建築基準法」上、誤っているものはど れか。", "choices": [{"label": "1", "text": "雨水排水管(雨水排水立て管を除く。)を汚水排水のための配管設備に連結する場合において は、当該雨水排水管に排水トラップを設けなければならない。"}, {"label": "2", "text": "排水トラップの深さは、阻集器を兼ねない場合、5cm 以上10 cm 以下としなければならな い。"}, {"label": "3", "text": "排水管は、給水ポンプ、空気調和機その他これらに類する機器の排水管に直接連結してはな らない。"}, {"label": "4", "text": "排水槽に設けるマンホールは、直径50 cm 以上の円が内接することができるものとしなけれ ばならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["排水槽に設けるマンホールは、直径50 cm 以上の円が内接することができるものとしなけれ ばならない。"], "answerHints": [["直径50 cm 以上"]], "mnemonic": "正しくは：排水槽のマンホールは、原則として直径60cm以上の円が内接できるものとする。", "block": 13, "group": 5}, {"id": "R06_kouki_46", "source": "R6後 No.46", "category": "法規", "type": "single", "question": "冷媒としてフロン類が充填されている機器のうち、フロン類の使用の合理化及び管理の 適正化に関する法律」における第一種特定製品に該当しないものはどれか。", "choices": [{"label": "1", "text": "業務用マルチエアコンディショナー"}, {"label": "2", "text": "業務用スクリュー冷凍機"}, {"label": "3", "text": "家庭用エアコンディショナー"}, {"label": "4", "text": "業務用冷水機"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["家庭用エアコンディショナー"], "answerHints": [["家庭用エアコンディショナー"]], "mnemonic": "第一種特定製品は業務用の冷凍空調機器。家庭用エアコンは家電リサイクル法の対象で該当しない。", "block": 13, "group": 5}, {"id": "R05_kouki_02", "source": "R5後 No.2", "category": "一般基礎", "type": "single", "question": "空気環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "室内の浮遊粉じんは、人体の呼吸器系に影響を及ぼす。"}, {"label": "2", "text": "臭気は、空気汚染を示す指標の一つであり、臭気強度や臭気指数で表す。"}, {"label": "3", "text": "居室の必要換気量は、一酸化炭素濃度の許容値に基づき算出する。"}, {"label": "4", "text": "ホルムアルデヒドの室内濃度が高くなると、目や呼吸器系を刺激し健康に影響を及ぼす。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["居室の必要換気量は、一酸化炭素濃度の許容値に基づき算出する。"], "answerHints": [["一酸化炭素濃度"]], "mnemonic": "正しくは：居室の必要換気量は、二酸化炭素濃度の許容値に基づき算出する。", "block": 14, "group": 5}, {"id": "R05_kouki_05", "source": "R5後 No.5", "category": "一般基礎", "type": "single", "question": "電気設備において「記号又は文字記号」と「名称」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "F―――――ヒューズ"}, {"label": "2", "text": "FEP―――波付硬質合成樹脂管"}, {"label": "3", "text": "VT――――計器用変圧器"}, {"label": "4", "text": "SC――――過負荷欠相継電器"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["SC――――過負荷欠相継電器"], "answerHints": [["過負荷欠相継電器"]], "mnemonic": "正しくは：SCは進相コンデンサ（過負荷欠相継電器は2E）。", "block": 14, "group": 5}, {"id": "R06_zenki_02", "source": "R6前 No.2", "category": "一般基礎", "type": "single", "question": "流体の速度が2倍となったとき、運動エネルギーの変化後の倍率として、適当なものはどれか。", "choices": [{"label": "1", "text": "1/4倍"}, {"label": "2", "text": "1/2倍"}, {"label": "3", "text": "2倍"}, {"label": "4", "text": "4倍"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["4倍"], "answerHints": [["4倍"]], "mnemonic": "運動エネルギーは1/2mv²なので、速度が2倍なら4倍。", "block": 14, "group": 5}, {"id": "R06_kouki_01", "source": "R6後 No.1", "category": "一般基礎", "type": "single", "question": "空気環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "室内空気の汚染度を示す指標の一つには、浮遊物質(SS)がある。"}, {"label": "2", "text": "空気齢とは、外気が室内に導入されてからある地点に到達するまでの平均時間をいう。"}, {"label": "3", "text": "大気中における二酸化炭素濃度は、季節変動を繰り返しながら経年的に増加傾向にある。"}, {"label": "4", "text": "一酸化炭素は、無色無臭であるが、人体に有害である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["室内空気の汚染度を示す指標の一つには、浮遊物質(SS)がある。"], "answerHints": [["浮遊物質(SS)"]], "mnemonic": "正しくは：浮遊物質(SS)は水質の指標。室内空気の指標は浮遊粉じん・CO2・CO等。", "block": 14, "group": 5}, {"id": "R06_kouki_05", "source": "R6後 No.5", "category": "一般基礎", "type": "single", "question": "電気設備における、合成樹脂製可とう電線管(PF 管)を金属管と比較した場合の長所と して、適当でないものはどれか。", "choices": [{"label": "1", "text": "曲げやすい。"}, {"label": "2", "text": "錆びない。"}, {"label": "3", "text": "熱に強い。"}, {"label": "4", "text": "非磁性体である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["熱に強い。"], "answerHints": [["熱に強い"]], "mnemonic": "正しくは：PF管は合成樹脂製なので金属管より熱に弱い。", "block": 14, "group": 5}, {"id": "R05_kouki_09", "source": "R5後 No.9", "category": "空調・衛生", "type": "single", "question": "熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "日射負荷には、顕熱と潜熱がある。"}, {"label": "2", "text": "外気負荷には、顕熱と潜熱がある。"}, {"label": "3", "text": "顕熱比(SHF)とは、全熱負荷のうち顕熱負荷が占める割合をいう。"}, {"label": "4", "text": "冷房負荷及び暖房負荷には、それぞれ顕熱と潜熱がある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["日射負荷には、顕熱と潜熱がある。"], "answerHints": [["日射負荷"]], "mnemonic": "正しくは：日射負荷は顕熱のみ。顕熱と潜熱があるのは外気負荷。", "block": 14, "group": 5}, {"id": "R05_kouki_12", "source": "R5後 No.12", "category": "空調・衛生", "type": "single", "question": "空冷ヒートポンプパッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷房の場合、外気温度が高いほど運転効率は低下する。"}, {"label": "2", "text": "マルチパッケージ形空気調和機には、系統内で熱回収される冷暖同時型がある。"}, {"label": "3", "text": "屋内機と屋外機間の高低差には、制限がない。"}, {"label": "4", "text": "暖房運転において外気温度が低いときには、屋外機コイルに霜が付着することがある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["屋内機と屋外機間の高低差には、制限がない。"], "answerHints": [["制限がない"]], "mnemonic": "正しくは：屋内機と屋外機間の高低差（冷媒配管長）には制限がある。", "block": 14, "group": 5}, {"id": "R05_kouki_15", "source": "R5後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配水管への取付口の位置は、他の給水装置の取付口から15cm以上離すものとする。"}, {"label": "2", "text": "軟弱地盤や構造物との取り合い部等の不同沈下のおそれのある箇所には、可とう性のある伸縮継手を設ける。"}, {"label": "3", "text": "給水装置とは、水道事業者の布設した配水管から分岐して設けられた給水管及びこれに直結する給水用具をいう。"}, {"label": "4", "text": "市街地等の道路部分に布設する外径80mm以上の配水管には、管理者名、布設年次等を明示するテープを取り付ける。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["配水管への取付口の位置は、他の給水装置の取付口から15cm以上離すものとする。"], "answerHints": [["15cm以上"]], "mnemonic": "正しくは：配水管への取付口は、他の給水装置の取付口から30cm以上離す。", "block": 14, "group": 5}, {"id": "R05_kouki_18", "source": "R5後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "瞬間式湯沸器の加熱能力は、瞬時最大流量に基づき算定する。"}, {"label": "2", "text": "貯湯式給湯器には、開放型と密閉型がある。"}, {"label": "3", "text": "密閉式膨張タンクは、機械室には設置できない。"}, {"label": "4", "text": "集合住宅の住戸内配管は、さや管ヘッダー方式とする場合がある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["密閉式膨張タンクは、機械室には設置できない。"], "answerHints": [["設置できない"]], "mnemonic": "正しくは：密閉式膨張タンクは設置位置の制約が少なく、機械室にも設置できる。", "block": 14, "group": 5}, {"id": "R05_kouki_21", "source": "R4後 No.21 / R5後 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備において、加圧送水装置の方式として、適当でないものはどれか。", "choices": [{"label": "1", "text": "高架水槽による方式"}, {"label": "2", "text": "水道直結による方式"}, {"label": "3", "text": "圧力水槽による方式"}, {"label": "4", "text": "ポンプによる方式"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水道直結による方式"], "answerHints": [["水道直結による方式"]], "mnemonic": "屋内消火栓の加圧送水装置は高架水槽・圧力水槽・ポンプの3方式。水道直結は該当しない。", "block": 14, "group": 5}, {"id": "R06_zenki_08", "source": "R6前 No.8", "category": "空調・衛生", "type": "single", "question": "変風量単一ダクト方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給気温度は一定とし、各室への送風量を変化させることで室温を制御する。"}, {"label": "2", "text": "VAVユニットからの発生騒音には、考慮が必要である。"}, {"label": "3", "text": "代表室のサーモスタットの信号により、空気調和機の送風量を制御する。"}, {"label": "4", "text": "送風量の減少時においても、必要外気量を確保する必要がある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["代表室のサーモスタットの信号により、空気調和機の送風量を制御する。"], "answerHints": [["代表室のサーモスタット"]], "mnemonic": "正しくは：変風量方式は各室のサーモスタットでVAVユニットの風量を制御し、空調機送風量はダクト内静圧等で制御する。", "block": 14, "group": 5}, {"id": "R06_zenki_11", "source": "R6前 No.11", "category": "空調・衛生", "type": "single", "question": "温水暖房における膨張タンクに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "開放式膨張タンクの場合、膨張管の接続位置は、ポンプの吐出し側とする。"}, {"label": "2", "text": "開放式膨張タンクにボイラーの逃がし管を接続する場合、その途中に弁は設けない。"}, {"label": "3", "text": "開放式膨張タンクは、装置内のエア抜きとしても利用できる。"}, {"label": "4", "text": "密閉式膨張タンクは、設置場所の制限が少ないため、ボイラー室等に設置できる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["開放式膨張タンクの場合、膨張管の接続位置は、ポンプの吐出し側とする。"], "answerHints": [["ポンプの吐出し側"]], "mnemonic": "正しくは：開放式膨張タンクの膨張管は、ポンプの吸込み側に接続する。", "block": 14, "group": 5}, {"id": "R06_zenki_14", "source": "R6前 No.14", "category": "空調・衛生", "type": "single", "question": "第三種機械換気方式における排気ガラリの面積を求めるために、必要な要素として適当でないものはどれか。", "choices": [{"label": "1", "text": "排気風量"}, {"label": "2", "text": "ガラリの有効開口率"}, {"label": "3", "text": "有効開口面風速"}, {"label": "4", "text": "排気温度"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排気温度"], "answerHints": [["排気温度"]], "mnemonic": "ガラリ面積＝排気風量÷（有効開口面風速×有効開口率）。排気温度は不要。", "block": 14, "group": 5}, {"id": "R06_zenki_17", "source": "R6前 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水道直結方式は、給水負荷が最大となる瞬間に対応するために、ピーク時の給水使用量を予想する必要がある。"}, {"label": "2", "text": "高置タンク方式は、他の給水方式に比べ、給水圧力の変動が大きい。"}, {"label": "3", "text": "設置器具数が少ない場合には、管均等表を利用して管径を決定する方法もある。"}, {"label": "4", "text": "受水タンク、高置タンク等は、水を汚染するほこり等がタンク内に入らないよう据付け場所を考慮する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["高置タンク方式は、他の給水方式に比べ、給水圧力の変動が大きい。"], "answerHints": [["変動が大きい"]], "mnemonic": "正しくは：高置タンク方式は、他の給水方式に比べて給水圧力の変動が小さい。", "block": 14, "group": 5}, {"id": "R06_zenki_21", "source": "R6前 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吸水管は、ポンプごとに専用とする。"}, {"label": "2", "text": "水源の水位がポンプより高い位置にある場合、吸水管には逆止め弁を設ける。"}, {"label": "3", "text": "加圧送水装置には、高架水槽、圧力水槽又はポンプを用いるものがある。"}, {"label": "4", "text": "消火栓は、防火対象物の階ごとに、その階の各部分からホース接続口までの水平距離が規定された長さ以内となるように設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水源の水位がポンプより高い位置にある場合、吸水管には逆止め弁を設ける。"], "answerHints": [["逆止め弁"]], "mnemonic": "正しくは：水源水位がポンプより高い場合、吸水管には止水弁（仕切弁）を設ける。水位が低い場合はフート弁。", "block": 14, "group": 5}, {"id": "R06_kouki_07", "source": "R6後 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和設備の計画に関する記述のうち、省エネルギーの観点から、適当でないものは どれか。", "choices": [{"label": "1", "text": "外気の取入れに全熱交換器を採用する。"}, {"label": "2", "text": "高効率の機器を採用する。"}, {"label": "3", "text": "熱源機器を複数台に分割する。"}, {"label": "4", "text": "暖房時に外気導入量を多くする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["暖房時に外気導入量を多くする。"], "answerHints": [["外気導入量を多くする"]], "mnemonic": "正しくは：暖房時の外気導入量は必要最小限に抑えるのが省エネ。", "block": 14, "group": 5}, {"id": "R06_kouki_11", "source": "R6後 No.11", "category": "空調・衛生", "type": "single", "question": "吸収冷温水機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "冷媒は水なので、フロン系の冷媒は使用していない。"}, {"label": "2", "text": "木質ペレットを燃料として使用する機種もある。"}, {"label": "3", "text": "立ち上がり時間は、一般的に、圧縮式冷凍機に比べて長い。"}, {"label": "4", "text": "電力消費量は、遠心冷凍機に比べて大きい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["電力消費量は、遠心冷凍機に比べて大きい。"], "answerHints": [["遠心冷凍機に比べて大きい"]], "mnemonic": "正しくは：吸収冷温水機の電力消費量は、遠心冷凍機に比べて小さい。", "block": 14, "group": 5}, {"id": "R06_kouki_14", "source": "R6後 No.14", "category": "空調・衛生", "type": "single", "question": "換気の 対象となる室」と 主な目的」の組合せのうち、適当でないものはどれか。 [対象となる室] [主な目的]", "choices": [{"label": "1", "text": "居室 室内空気の浄化"}, {"label": "2", "text": "ボイラー室 酸素供給"}, {"label": "3", "text": "電気室 湿気の排除"}, {"label": "4", "text": "車庫 有害ガスの排除"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["電気室 湿気の排除"], "answerHints": [["湿気の排除"]], "mnemonic": "電気室の換気の主目的は熱の排除。", "block": 14, "group": 5}, {"id": "R06_kouki_17", "source": "R6後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "受水タンクのオーバーフロー管の管端は、間接排水とする。"}, {"label": "2", "text": "高置タンク方式は、他の給水方式に比べ、給水圧力の変動が大きくなる。"}, {"label": "3", "text": "水道直結増圧方式は、高置タンク方式に比べ、一般的に、ポンプの吐出し量が大きくなる。"}, {"label": "4", "text": "クロスコネクションとは、飲料水系統とその他の系統が、配管・装置により直接接続される ことをいう。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["高置タンク方式は、他の給水方式に比べ、給水圧力の変動が大きくなる。"], "answerHints": [["変動が大きくなる"]], "mnemonic": "正しくは：高置タンク方式は、他の給水方式に比べて給水圧力の変動が小さい。", "block": 14, "group": 5}, {"id": "R06_kouki_20", "source": "R6後 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "トラップは、サイホン式と非サイホン式に大別される。"}, {"label": "2", "text": "建物内の排水方式における分流式とは、汚水と雑排水を別の排水系統とすることである。"}, {"label": "3", "text": "通気横走り管は、管内の水滴が自然流下によって排水管に流れるように勾配をつける。"}, {"label": "4", "text": "通気立て管の下部は、最低位の排水横枝管より高い位置で排水立て管に接続する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["通気立て管の下部は、最低位の排水横枝管より高い位置で排水立て管に接続する。"], "answerHints": [["高い位置で"]], "mnemonic": "正しくは：通気立て管の下部は、最低位の排水横枝管より低い位置で排水立て管に接続するか、排水横主管に接続する。", "block": 14, "group": 5}, {"id": "R05_kouki_24", "source": "R5後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "飲料用給水タンクに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "FRP製パネルタンクには、FRPを表面材とし合成樹脂発泡体を心材としたサンドイッチ構造のものがある。"}, {"label": "2", "text": "ステンレス鋼鈑製パネルタンクは、タンク上部の気相部に塩素が滞留しやすいため耐食性に優れたステンレスを使用する。"}, {"label": "3", "text": "鋼製タンク内面は、防食処理として一定の膜厚を形成したエポキシ樹脂等の樹脂系塗料を施す。"}, {"label": "4", "text": "給水タンクのオーバーフロー管には、衛生上有害なものが入らないように、トラップを設ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給水タンクのオーバーフロー管には、衛生上有害なものが入らないように、トラップを設ける。"], "answerHints": [["トラップを設ける"]], "mnemonic": "正しくは：給水タンクのオーバーフロー管にはトラップを設けず、管端に防虫網を設けて間接排水とする。", "block": 14, "group": 5}, {"id": "R05_kouki_27", "source": "R5後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクトに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "エルボの内側半径は、円形ダクトではダクトの直径の1/2以上とする。"}, {"label": "2", "text": "ダクトの断面を拡大や縮小する場合、拡大角度及び縮小角度ともに45度以内とする。"}, {"label": "3", "text": "案内羽根(ガイドベーン)は、直角エルボ等に設け、圧力損失を低減する。"}, {"label": "4", "text": "共板フランジ用ガスケットは、弾力性のあるものを使用する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクトの断面を拡大や縮小する場合、拡大角度及び縮小角度ともに45度以内とする。"], "answerHints": [["拡大角度及び縮小角度ともに45度以内"]], "mnemonic": "正しくは：ダクトの拡大角度は15度以内、縮小角度は30度以内。", "block": 14, "group": 5}, {"id": "R06_zenki_26", "source": "R6前 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配管用炭素鋼鋼管(JIS)には黒管と白管があり、白管は、黒管に溶融亜鉛めっきを施したものである。"}, {"label": "2", "text": "水道用ステンレス鋼鋼管(JWWA)は、1MPa以下で使用され、SUS304 とSUS316の2種類がある。"}, {"label": "3", "text": "硬質ポリ塩化ビニル管(JIS)のVU管は、VP管に比べて設計圧力が低い。"}, {"label": "4", "text": "定水位調整弁は、汚水槽や雑排水槽の水位を一定に保つ目的で使用する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["定水位調整弁は、汚水槽や雑排水槽の水位を一定に保つ目的で使用する。"], "answerHints": [["汚水槽や雑排水槽"]], "mnemonic": "正しくは：定水位調整弁は、受水タンク等への給水を制御して水位を一定に保つ目的で使用する。", "block": 14, "group": 5}, {"id": "R06_kouki_26", "source": "R6後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ボール弁は、ハンドルの操作によりボール状の弁体が回転し、開閉を行うものである。"}, {"label": "2", "text": "架橋ポリエチレン管は、構造により単層管と二層管がある。"}, {"label": "3", "text": "水道用硬質塩化ビニルライニング鋼管のうち、SGP-VA は配管用炭素鋼鋼管の内面と外面に 硬質ポリ塩化ビニルをライニングしたものである。"}, {"label": "4", "text": "逆止め弁は、チャッキ弁とも呼ばれ、スイング式やリフト式がある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水道用硬質塩化ビニルライニング鋼管のうち、SGP-VA は配管用炭素鋼鋼管の内面と外面に 硬質ポリ塩化ビニルをライニングしたものである。"], "answerHints": [["SGP-VA"]], "mnemonic": "正しくは：内面と外面に硬質ポリ塩化ビニルをライニングしたものはSGP-VD。VAは内面ライニング（外面は一次防錆塗装）。", "block": 14, "group": 5}, {"id": "R05_kouki_32", "source": "R5後 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "労働者が、就業場所から他の就業場所へ移動する途中で被った災害は、通勤災害に該当しない。"}, {"label": "2", "text": "地盤が軟弱な場所で移動式クレーンを用いる場合、転倒を防止するため必要な広さ及び強度を有する鉄板等を敷設した上に設置し作業を行う。"}, {"label": "3", "text": "熱中症予防のための指標として、気温、湿度及び輻射熱に関する値を組み合せて計算する暑さ指数(WBGT)がある。"}, {"label": "4", "text": "ツールボックスミーティングとは、関係する作業者が作業開始前に集まり、作業、安全等について話合いを行うことである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["労働者が、就業場所から他の就業場所へ移動する途中で被った災害は、通勤災害に該当しない。"], "answerHints": [["通勤災害に該当しない"]], "mnemonic": "正しくは：就業場所から他の就業場所への移動中の災害も通勤災害に該当する。", "block": 14, "group": 5}, {"id": "R05_kouki_35", "source": "R5後 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "長辺が300mm以下の防火ダンパーの支持は、2点吊りとする。"}, {"label": "2", "text": "スパイラルダクトの差込み接合では、継手をビスで固定しダクト用テープで1重巻きを行う。"}, {"label": "3", "text": "厨房の排気フードの吊りは、4隅のほか1,500mm以下の間隔で行う。"}, {"label": "4", "text": "浴室の排気ダクトは、排気ガラリに向けて下がり勾配とするか、水抜きを設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["スパイラルダクトの差込み接合では、継手をビスで固定しダクト用テープで1重巻きを行う。"], "answerHints": [["1重巻き"]], "mnemonic": "正しくは：スパイラルダクトの差込み接合は、ビスで固定しダクト用テープで2重巻きを行う。", "block": 14, "group": 5}, {"id": "R05_kouki_38", "source": "R5後 No.38", "category": "施工管理法", "type": "single", "question": "風量調整等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "吹出口や吸込口の風量測定を行う場合は、補助ダクトを用いて行う。"}, {"label": "2", "text": "ダクト内の風量は、ダクト内の風速を測定して求める。"}, {"label": "3", "text": "風量調整は、給排気口のシャッターや分岐部の風量調整ダンパーを全閉にした後に行う。"}, {"label": "4", "text": "風量調整は、機器の試験成績表、ダクト図、風量計算書等を用いて行う。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["風量調整は、給排気口のシャッターや分岐部の風量調整ダンパーを全閉にした後に行う。"], "answerHints": [["全閉にした後"]], "mnemonic": "正しくは：風量調整は、シャッターや風量調整ダンパーを全開にした後に行う。", "block": 14, "group": 5}, {"id": "R06_zenki_33", "source": "R6前 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "空気調和機の基礎の高さは、ドレン管の排水トラップの深さが確保できるように150mm程度とする。"}, {"label": "2", "text": "飲料用給水タンクは、タンク底部から設置床までの距離を300mm確保して据え付ける。"}, {"label": "3", "text": "排水用水中モーターポンプは、ピットの壁から200mm程度離して設置する。"}, {"label": "4", "text": "ボイラー室内の燃料タンクに液体燃料を貯蔵する場合、当該燃料タンクからボイラーの外側までの距離は、原則として、2m以上とする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用給水タンクは、タンク底部から設置床までの距離を300mm確保して据え付ける。"], "answerHints": [["300mm"]], "mnemonic": "正しくは：飲料用給水タンクは、底部から床までの距離を600mm以上確保する（6面点検）。", "block": 14, "group": 5}, {"id": "R06_zenki_36", "source": "R6前 No.36", "category": "施工管理法", "type": "single", "question": "保温及び塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "グラスウール保温材は、ポリスチレンフォーム保温材に比べて、防湿性が優れている。"}, {"label": "2", "text": "シートタイプの合成樹脂製カバーの固定は、専用のピンを使用する。"}, {"label": "3", "text": "配管用炭素鋼鋼管(白)の下塗り塗料は、変性エポキシ樹脂プライマーを使用する。"}, {"label": "4", "text": "露出配管の上塗り塗料は、合成樹脂調合ペイント等を使用する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["グラスウール保温材は、ポリスチレンフォーム保温材に比べて、防湿性が優れている。"], "answerHints": [["防湿性が優れている"]], "mnemonic": "正しくは：グラスウールはポリスチレンフォームに比べて高温域で使用できるが、防湿性は劣る。", "block": 14, "group": 5}, {"id": "R06_kouki_31", "source": "R5後 No.31 / R6後 No.31", "category": "施工管理法", "type": "single", "question": "品質管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "品質管理の目的は、設計図書等で要求された品質を満足するように施工することである。"}, {"label": "2", "text": "品質管理を行うと品質は向上するが、手直しが増加し原価が上がる。"}, {"label": "3", "text": "品質管理において、4つの段階PDCA を繰り返すことをデミングサークルという。"}, {"label": "4", "text": "主要機器の試験や防火区画の貫通処理は、全数検査とする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["品質管理を行うと品質は向上するが、手直しが増加し原価が上がる。"], "answerHints": [["手直しが増加し原価が上がる"]], "mnemonic": "正しくは：品質管理を行うと手直しが減少し、原価が下がる。", "block": 14, "group": 5}, {"id": "R06_kouki_35", "source": "R6後 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "フレキシブルダクトは、一般的に、ダクトと制気口ボックスの接続等に用いられる。"}, {"label": "2", "text": "シーリングディフューザー形吹出口は、内コーンを上下させることにより、冷房時や暖房時 に適した気流に変更できる。"}, {"label": "3", "text": "ユニバーサル形吹出口は、シャッターを開閉させて風向調整を行う。"}, {"label": "4", "text": "風量測定口は、送風機の吐出し部、ダンパー等のすぐ下流部には取り付けない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ユニバーサル形吹出口は、シャッターを開閉させて風向調整を行う。"], "answerHints": [["シャッターを開閉させて"]], "mnemonic": "正しくは：ユニバーサル形吹出口は、羽根（ベーン）の角度を変えて風向調整を行う。", "block": 14, "group": 5}, {"id": "R06_kouki_38", "source": "R6後 No.38", "category": "施工管理法", "type": "single", "question": "測定対象」と 測定機器」の組合せのうち、適当でないものはどれか。 [測定対象] [測定機器]", "choices": [{"label": "1", "text": "室内気流 熱線風速計"}, {"label": "2", "text": "温湿度 アスマン通風乾湿計"}, {"label": "3", "text": "浮遊粉じん デジタル粉じん計"}, {"label": "4", "text": "騒音 検知管"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["騒音 検知管"], "answerHints": [["検知管"]], "mnemonic": "騒音は騒音計で測定。検知管はCO・CO2等のガス濃度の測定に使う。", "block": 14, "group": 5}, {"id": "R05_kouki_51", "source": "R5後 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "飲料用冷水器の排水管は、雑排水系統の排水管に直接連結する。"}, {"label": "2", "text": "呼び径40以下の鋼管の場合、形鋼振れ止め支持は、原則として不要である。"}, {"label": "3", "text": "汚水管(大便器)の最小管径は、50mmとする。"}, {"label": "4", "text": "冷媒用断熱材被覆銅管の接合には、フレア接合、差込接合等がある。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用冷水器の排水管は、雑排水系統の排水管に直接連結する。", "汚水管(大便器)の最小管径は、50mmとする。"], "answerHints": [["直接連結する"], ["50mm"]], "mnemonic": "正しくは：飲料用冷水器の排水は間接排水とし、他の排水管に直接連結しない。大便器の汚水管の最小管径は75mm。", "block": 14, "group": 5}, {"id": "R06_zenki_50", "source": "R6前 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "フート弁からのポンプの吸込管は、ポンプに向かって下がり勾配となるよう据え付ける。"}, {"label": "2", "text": "空冷ヒートポンプパッケージ形空気調和機の屋外機を設置する際には、霜取りの排水を考慮する。"}, {"label": "3", "text": "排水用水中モーターポンプの据付け位置は、排水流入口の真下付近とする。"}, {"label": "4", "text": "吸収冷温水機は、据付け後に工場出荷時の気密が保持されているか確認する。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["フート弁からのポンプの吸込管は、ポンプに向かって下がり勾配となるよう据え付ける。", "排水用水中モーターポンプの据付け位置は、排水流入口の真下付近とする。"], "answerHints": [["下がり勾配"], ["真下付近"]], "mnemonic": "正しくは：ポンプの吸込管はポンプに向かって上がり勾配とする。排水用水中ポンプは排水流入口から離れた位置に据え付ける。", "block": 14, "group": 5}, {"id": "R06_kouki_50", "source": "R6後 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "小型温水ボイラーをボイラー室内に設置する場合、ボイラー側面からボイラー室の壁面までの 距離は、300 mm 以上とする。"}, {"label": "2", "text": "遠心送風機の据付け時の調整において、ベルトの張りが強すぎると軸受の過熱の原因になる。"}, {"label": "3", "text": "冷水ポンプのコンクリート基礎は、基礎表面に排水溝を設け、間接排水できるものとする。"}, {"label": "4", "text": "排水用水中モーターポンプは、ピットの壁から50 mm 程度離して設置する。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["小型温水ボイラーをボイラー室内に設置する場合、ボイラー側面からボイラー室の壁面までの 距離は、300 mm 以上とする。", "排水用水中モーターポンプは、ピットの壁から50 mm 程度離して設置する。"], "answerHints": [["300 mm"], ["50 mm 程度"]], "mnemonic": "正しくは：小型ボイラー側面から壁面までは450mm以上。排水用水中モーターポンプはピットの壁から200mm程度離す。", "block": 14, "group": 5}, {"id": "R05_kouki_39", "source": "R4後 No.39 / R5後 No.39", "category": "法規", "type": "single", "question": "建設工事の作業所における安全衛生管理に関する記述のうち、「労働安全衛生法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、労働者の作業内容を変更したときは、当該労働者に対し、その従事する業務に関する安全又は衛生のための教育を行わなければならない。"}, {"label": "2", "text": "事業者は、移動はしごを使用する場合、はしごの幅は30cm以上のものでなければ使用してはならない。"}, {"label": "3", "text": "事業者は、酸素欠乏危険作業に労働者を従事させる場合は、当該作業を行う場所の空気中の酸素の濃度を15%以上に保つように換気しなければならない。"}, {"label": "4", "text": "事業者は、可燃性ガス及び酸素を用いて行う金属の溶接、溶断又は加熱の業務に使用するガス等の容器の温度を40度以下に保たなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、酸素欠乏危険作業に労働者を従事させる場合は、当該作業を行う場所の空気中の酸素の濃度を15%以上に保つように換気しなければならない。"], "answerHints": [["15%以上"]], "mnemonic": "正しくは：酸素欠乏危険作業では、空気中の酸素濃度を18%以上に保つように換気する。", "block": 14, "group": 5}, {"id": "R05_kouki_42", "source": "R5後 No.42", "category": "法規", "type": "single", "question": "建築物に設ける配管設備に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "給水立て主管から各階への分岐管等主要な分岐管には、止水弁を設ける。"}, {"label": "2", "text": "雨水排水立て管は、汚水排水管若しくは通気管と兼用してもよい。"}, {"label": "3", "text": "飲料水の配管設備の水栓の開口部は、流し台のあふれ面との垂直距離を適当に保つ等有効な水の逆流防止のための措置を講じる。"}, {"label": "4", "text": "排水のための配管設備の汚水に接する部分は、不浸透質の耐水材料で造る。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["雨水排水立て管は、汚水排水管若しくは通気管と兼用してもよい。"], "answerHints": [["兼用してもよい"]], "mnemonic": "正しくは：雨水排水立て管は、汚水排水管・通気管と兼用し、又はこれらに連結してはならない。", "block": 14, "group": 5}, {"id": "R05_kouki_45", "source": "R5後 No.45", "category": "法規", "type": "single", "question": "屋内消火栓設備に関する記述のうち、「消防法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "屋内消火栓箱の上部には、設置の標示のために赤色の灯火を設ける。"}, {"label": "2", "text": "加圧送水装置の始動を明示する表示灯は、屋内消火栓箱の内部又はその直近の箇所に設ける。"}, {"label": "3", "text": "1号消火栓の主配管のうち、立上り管は、管の呼びで50mm以上のものとする。"}, {"label": "4", "text": "1号消火栓以外の場合は、非常電源の附置は不要である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["1号消火栓以外の場合は、非常電源の附置は不要である。"], "answerHints": [["非常電源の附置は不要"]], "mnemonic": "正しくは：屋内消火栓設備は1号・2号を問わず非常電源を附置する。", "block": 14, "group": 5}, {"id": "R05_kouki_48", "source": "R5後 No.48", "category": "法規", "type": "single", "question": "産業廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、産業廃棄物管理票を、産業廃棄物の種類にかかわらず、一括して交付することができる。"}, {"label": "2", "text": "廃エアコンディショナー(国内における日常生活に伴って生じたものに限る。)に含まれるポリ塩化ビフェニルを使用する部品は、特別管理一般廃棄物である。"}, {"label": "3", "text": "事業者は、その事業活動に伴い生じた産業廃棄物の運搬を委託する場合、運搬先が2以上である場合にあっては、運搬先ごとに産業廃棄物管理票を交付しなければならない。"}, {"label": "4", "text": "建築物の改築に伴い生じた衛生陶器の破片は、産業廃棄物として処理する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、産業廃棄物管理票を、産業廃棄物の種類にかかわらず、一括して交付することができる。"], "answerHints": [["種類にかかわらず、一括して"]], "mnemonic": "正しくは：産業廃棄物管理票は、産業廃棄物の種類ごとに交付する。", "block": 14, "group": 5}, {"id": "R06_zenki_41", "source": "R5前 No.41 / R6前 No.41", "category": "法規", "type": "single", "question": "建築物の用語に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "工場は、特殊建築物である。"}, {"label": "2", "text": "階段は、構造耐力上主要な部分である。"}, {"label": "3", "text": "建築物に設ける昇降機は、建築設備である。"}, {"label": "4", "text": "屋根は、主要構造部である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["階段は、構造耐力上主要な部分である。"], "answerHints": [["階段"]], "mnemonic": "正しくは：階段は主要構造部。構造耐力上主要な部分は基礎・柱・壁・床版・屋根版・横架材等。", "block": 14, "group": 5}, {"id": "R06_zenki_44", "source": "R6前 No.44", "category": "法規", "type": "single", "question": "請負契約書に記載しなければならない事項に関する記述のうち、「建設業法」上、定められていないものはどれか。", "choices": [{"label": "1", "text": "請負代金の額"}, {"label": "2", "text": "工事着手の時期及び工事完成の時期"}, {"label": "3", "text": "工事の施工により第三者が損害を受けた場合における賠償金の負担に関する定め"}, {"label": "4", "text": "下請契約を行うときは、下請負人の名称"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["下請契約を行うときは、下請負人の名称"], "answerHints": [["下請負人の名称"]], "mnemonic": "請負契約書の記載事項に下請負人の名称は定められていない。", "block": 14, "group": 5}, {"id": "R06_zenki_47", "source": "R6前 No.47", "category": "法規", "type": "single", "question": "建築物に係る建設工事のうち、「建設工事に係る資材の再資源化等に関する法律」上、特定建設資材廃棄物をその種類ごとに分別しつつ施工しなければならない工事に該当しないものはどれか。ただし、都道府県が条例で、適用すべき建設工事の規模に関する基準を定めた区域を除く。", "choices": [{"label": "1", "text": "模様替工事で請負代金の額が1億円であるもの"}, {"label": "2", "text": "新築工事で床面積の合計が500m2であるもの"}, {"label": "3", "text": "増築工事で増築部分の床面積の合計が500m2であるもの"}, {"label": "4", "text": "解体工事で解体部分の床面積の合計が50m2であるもの"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["解体工事で解体部分の床面積の合計が50m2であるもの"], "answerHints": [["50m2"]], "mnemonic": "正しくは：解体工事は床面積80m²以上が分別解体等の対象（新築・増築は500m²以上、修繕・模様替は1億円以上）。", "block": 14, "group": 5}, {"id": "R06_kouki_40", "source": "R6後 No.40", "category": "法規", "type": "single", "question": "災害補償に関する記述のうち、労働基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "労働者が重大な過失によって業務上負傷し、又は疾病にかかり、且つ使用者がその過失に ついて行政官庁の認定を受けた場合においては、休業補償又は障害補償を行わなくても よい。"}, {"label": "2", "text": "労働者が業務上負傷し、又は疾病にかかった場合においては、使用者は、その費用で必要な 療養を行い、又は必要な療養の費用を負担しなければならない。"}, {"label": "3", "text": "労働者が業務上負傷し、又は疾病にかかり、治った場合において、その身体に障害が存す るときは、使用者は、その障害の程度に応じて、金銭的障害補償を行わなければならない。"}, {"label": "4", "text": "労働者が業務上負傷し、又は疾病にかかった場合に、療養のため、労働することができな いために賃金を受けない場合においては、使用者は、労働者の療養中平均賃金の全額の休 業補償を行わなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["労働者が業務上負傷し、又は疾病にかかった場合に、療養のため、労働することができな いために賃金を受けない場合においては、使用者は、労働者の療養中平均賃金の全額の休 業補償を行わなければならない。"], "answerHints": [["全額"]], "mnemonic": "正しくは：休業補償は平均賃金の100分の60。", "block": 14, "group": 5}, {"id": "R06_kouki_44", "source": "R6後 No.44", "category": "法規", "type": "single", "question": "建設業の許可を受けた建設業者が、現場に置く主任技術者等に関する記述のうち、 建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "請負人が請負契約の履行に関し工事現場に置く主任技術者は、現場代理人を兼ねることがで きる。"}, {"label": "2", "text": "一定金額以上で請け負った共同住宅の建設工事に置く主任技術者は、工事現場ごとに、専 任の者でなければならない。"}, {"label": "3", "text": "発注者から直接建設工事を請け負った特定建設業者は、その工事の下請契約の請負代金の 総額が一定金額以上の場合、主任技術者の代わりに監理技術者を置かなければならない。"}, {"label": "4", "text": "主任技術者は、請負契約の履行を確保するため、請負人に代わって工事の施工に関する一切 の事項を処理しなければならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["主任技術者は、請負契約の履行を確保するため、請負人に代わって工事の施工に関する一切 の事項を処理しなければならない。"], "answerHints": [["請負人に代わって"]], "mnemonic": "正しくは：主任技術者の職務は施工計画の作成、工程・品質管理等の技術上の管理と指導監督（請負人に代わって処理するものではない）。", "block": 14, "group": 5}, {"id": "R06_kouki_47", "source": "R6後 No.47", "category": "法規", "type": "single", "question": "測定項目」と 法律」の組合せのうち、当該測定項目がその法律に 規定されていないものはどれか。 [測定項目] [法律]", "choices": [{"label": "1", "text": "化学的酸素要求量(COD) 大気汚染防止法"}, {"label": "2", "text": "二酸化炭素の含有率 建築物における衛生的環境の確保に関する法律"}, {"label": "3", "text": "生物化学的酸素要求量(BOD) 浄化槽法"}, {"label": "4", "text": "水素イオン濃度 水質汚濁防止法"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["その法律に 規定されていないもの"], "answerTexts": ["化学的酸素要求量(COD) 大気汚染防止法"], "answerHints": [["大気汚染防止法"]], "mnemonic": "CODは水質汚濁防止法の測定項目。大気汚染防止法には規定されていない。", "block": 14, "group": 5}, {"id": "R05_kouki_03", "source": "R5後 No.3", "category": "一般基礎", "type": "single", "question": "流体に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "全圧とは、静圧と位置圧の和をいう。"}, {"label": "2", "text": "水の粘性係数は、空気の粘性係数より大きい。"}, {"label": "3", "text": "ピトー管は、流速の測定に用いられる。"}, {"label": "4", "text": "レイノルズ数が大きくなると、乱流になる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["全圧とは、静圧と位置圧の和をいう。"], "answerHints": [["静圧と位置圧の和"]], "mnemonic": "正しくは：全圧とは、静圧と動圧の和。", "block": 15, "group": 5}, {"id": "R05_kouki_06", "source": "R5後 No.6", "category": "一般基礎", "type": "single", "question": "コンクリート工事に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水セメント比が大きくなると、コンクリートの圧縮強度も大きくなる。"}, {"label": "2", "text": "コンクリートは、気温が高いと早く固まり、低いとゆっくり固まる。"}, {"label": "3", "text": "梁の打継ぎは、せん断力の小さい梁中央付近に設ける。"}, {"label": "4", "text": "コンクリートを打ち込む場合、原則として横流しをしてはいけない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水セメント比が大きくなると、コンクリートの圧縮強度も大きくなる。"], "answerHints": [["圧縮強度も大きくなる"]], "mnemonic": "正しくは：水セメント比が大きくなると、圧縮強度は小さくなる。", "block": 15, "group": 5}, {"id": "R06_zenki_03", "source": "R6前 No.3", "category": "一般基礎", "type": "single", "question": "圧力2.0×105Pa、体積8.0Lの理想気体を、温度一定で圧力4.0×105Paにしたときの体積の値として、適当なものはどれか。", "choices": [{"label": "1", "text": "2.0L"}, {"label": "2", "text": "4.0L"}, {"label": "3", "text": "8.0L"}, {"label": "4", "text": "16.0L"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["4.0L"], "answerHints": [["4.0L"]], "mnemonic": "温度一定ならPV一定（ボイルの法則）。圧力2倍で体積1/2、8.0L→4.0L。", "block": 15, "group": 5}, {"id": "R06_kouki_06", "source": "R6後 No.6", "category": "一般基礎", "type": "single", "question": "コンクリートに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "コンクリートは、スランプの値が小さいほど流動性は高くなる。"}, {"label": "2", "text": "コンクリートは、アルカリ性のため、コンクリート中の鉄筋はさびにくい。"}, {"label": "3", "text": "コンクリートに破壊以下の一定の応力をかけ続けることで、時間の増加とともにひずみが増 大する現象をクリープという。"}, {"label": "4", "text": "コンクリートの圧縮強度は、引張強度より大きい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["コンクリートは、スランプの値が小さいほど流動性は高くなる。"], "answerHints": [["小さいほど"]], "mnemonic": "正しくは：スランプの値が大きいほど流動性は高い。", "block": 15, "group": 5}, {"id": "R05_kouki_10", "source": "R5後 No.10", "category": "空調・衛生", "type": "single", "question": "空気清浄装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "静電式は、一般空調用に使用される。"}, {"label": "2", "text": "ろ過式には、粗じん用からHEPA用まで多くの種類がある。"}, {"label": "3", "text": "粒子捕集原理には、遮り、静電気等がある。"}, {"label": "4", "text": "空気通過速度を速くすることで、圧力損失を小さくしている。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["空気通過速度を速くすることで、圧力損失を小さくしている。"], "answerHints": [["速くする"]], "mnemonic": "正しくは：空気通過速度を遅くすることで、圧力損失を小さくしている。", "block": 15, "group": 5}, {"id": "R05_kouki_13", "source": "R5後 No.13", "category": "空調・衛生", "type": "single", "question": "換気の「対象となる室」と「換気の必要な主な要因」の組合せのうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "電気室――――汚染物質"}, {"label": "2", "text": "シャワー室――湿気"}, {"label": "3", "text": "ボイラー室――燃焼空気供給"}, {"label": "4", "text": "書庫―――――臭気"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["電気室――――汚染物質"], "answerHints": [["汚染物質"]], "mnemonic": "電気室の換気の主な要因は熱（発熱の排除）。", "block": 15, "group": 5}, {"id": "R05_kouki_16", "source": "R5後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "下水とは、生活若しくは事業(耕作の事業を除く。)に起因し、若しくは付随する廃水又は雨水をいう。"}, {"label": "2", "text": "分流式では、降雨時の路面排水が直接公共用水域に放流される。"}, {"label": "3", "text": "公共下水道の設置、改築、修繕、維持その他の管理は、市町村が行う。"}, {"label": "4", "text": "下水道本管への取付管の接続は、管底に接続する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["下水道本管への取付管の接続は、管底に接続する。"], "answerHints": [["管底に接続"]], "mnemonic": "正しくは：取付管は、下水道本管の中心線より上方に接続する。", "block": 15, "group": 5}, {"id": "R05_kouki_19", "source": "R5後 No.19", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "通気管の最小管径は、25mmとする。"}, {"label": "2", "text": "トラップの深さは、浅いと封水が切れやすく、深いと底部に固形物が溜まるため、50~100mmとする。"}, {"label": "3", "text": "飲料用タンクの間接排水管の排水口空間は、排水管の管径によらず、最小150mmとする。"}, {"label": "4", "text": "横走排水管に設ける掃除口の取付け間隔は、管径が100mm以下の場合は15m以内、100mmを超える場合は30m以内が望ましい。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["通気管の最小管径は、25mmとする。"], "answerHints": [["25mm"]], "mnemonic": "正しくは：通気管の最小管径は30mm。", "block": 15, "group": 5}, {"id": "R05_kouki_22", "source": "R5後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液化石油ガス(LPG)は、調整器で燃焼に適した圧力に減圧する。"}, {"label": "2", "text": "液化天然ガス(LNG)は、液化する際に硫黄分やその他の不純物が除去されている。"}, {"label": "3", "text": "ガスの比重の大小は、ガス燃焼機器ノズルからのガス噴出量に影響しない。"}, {"label": "4", "text": "液化石油ガス(LPG)は、本来、無色無臭のガスである。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ガスの比重の大小は、ガス燃焼機器ノズルからのガス噴出量に影響しない。"], "answerHints": [["影響しない"]], "mnemonic": "正しくは：ガスの比重の大小は、ノズルからのガス噴出量に影響する。", "block": 15, "group": 5}, {"id": "R06_zenki_09", "source": "R6前 No.9", "category": "空調・衛生", "type": "single", "question": "熱負荷計算に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "二重サッシ窓で、ブラインドを室内に設置する場合と二重サッシ内に設置する場合では、日射負荷は同じである。"}, {"label": "2", "text": "暖房負荷計算では、一般的に、日射負荷は考慮しない。"}, {"label": "3", "text": "窓ガラス面の通過熱負荷計算では、一般的に、内外温度差を使用する。"}, {"label": "4", "text": "冷房負荷計算において、LED照明を採用すると蛍光灯に比べて熱負荷は減少する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["二重サッシ窓で、ブラインドを室内に設置する場合と二重サッシ内に設置する場合では、日射負荷は同じである。"], "answerHints": [["同じである"]], "mnemonic": "正しくは：ブラインドは室内より二重サッシ内に設置する方が日射負荷は小さくなる。", "block": 15, "group": 5}, {"id": "R06_zenki_12", "source": "R6前 No.12", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ヒートポンプ方式のマルチパッケージ形空気調和機の冷媒配管方式には、2管式と3管式がある。"}, {"label": "2", "text": "空気熱源ヒートポンプ方式では、冷媒配管が短くなるほど冷暖房能力が減少する。"}, {"label": "3", "text": "業務用パッケージ形空気調和機は、一般的に、代替フロン(HFC)が使用されており、「フロン類の使用の合理化及び管理の適正化に関する法律」の対象となっている。"}, {"label": "4", "text": "ガスエンジンヒートポンプ方式は、ガスエンジンの排熱を暖房用に利用している。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["空気熱源ヒートポンプ方式では、冷媒配管が短くなるほど冷暖房能力が減少する。"], "answerHints": [["短くなるほど"]], "mnemonic": "正しくは：冷媒配管が長くなるほど冷暖房能力が減少する。", "block": 15, "group": 5}, {"id": "R06_zenki_15", "source": "R6前 No.15", "category": "空調・衛生", "type": "single", "question": "上水道施設に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "送水施設は、浄化した水を需要者に必要な圧力で必要な量を供給する施設である。"}, {"label": "2", "text": "浄水施設の沈殿池は、フロック形成池から出た原水のフロックを沈殿除去し、ろ過池の負荷を軽くする。"}, {"label": "3", "text": "導水施設は、取水施設から浄水施設まで原水を送る施設である。"}, {"label": "4", "text": "浄水施設のろ過池における緩速ろ過方式は、低濁度の原水を処理するのに適している。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["送水施設は、浄化した水を需要者に必要な圧力で必要な量を供給する施設である。"], "answerHints": [["送水施設"]], "mnemonic": "正しくは：需要者に必要な圧力・量で供給するのは配水施設。送水施設は浄水施設から配水施設へ送る施設。", "block": 15, "group": 5}, {"id": "R06_zenki_19", "source": "R6前 No.19", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "管径50mmの排水横枝管の勾配は、1/50以上とする。"}, {"label": "2", "text": "排水ますの内のりは、ますの深さが深いほど大きくする。"}, {"label": "3", "text": "間接排水を受ける水受け容器には、トラップを設けない。"}, {"label": "4", "text": "排水漕の通気管の管径は、50mm以上とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["間接排水を受ける水受け容器には、トラップを設けない。"], "answerHints": [["トラップを設けない"]], "mnemonic": "正しくは：間接排水を受ける水受け容器にはトラップを設ける。", "block": 15, "group": 5}, {"id": "R06_zenki_22", "source": "R5前 No.22 / R6前 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "開放式ガス機器とは、燃焼用の空気を屋内から取り、燃焼排ガスを排気筒により屋外に排気する方式をいう。"}, {"label": "2", "text": "内容積が20L以上の液化石油ガス(LPG)容器は、原則として、通風の良い屋外に置く。"}, {"label": "3", "text": "液化石油ガス(LPG)は、常温・常圧では気体であるものに加圧等を行い液化させたものである。"}, {"label": "4", "text": "マイコンガスメーターは、供給圧力が0.2kPaを下回っていることを継続して検知した場合等に供給を遮断する機能をもつ。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["開放式ガス機器とは、燃焼用の空気を屋内から取り、燃焼排ガスを排気筒により屋外に排気する方式をいう。"], "answerHints": [["排気筒により屋外に排気"]], "mnemonic": "正しくは：開放式は燃焼空気を屋内から取り、排ガスも屋内に出す。排気筒で屋外に出すのは半密閉式。", "block": 15, "group": 5}, {"id": "R06_kouki_09", "source": "R6後 No.9", "category": "空調・衛生", "type": "single", "question": "冷房時の熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ガラス面日射負荷は、日影の場合も考慮する。"}, {"label": "2", "text": "日射負荷には、顕熱と潜熱がある。"}, {"label": "3", "text": "照明器具による熱負荷は、顕熱のみである。"}, {"label": "4", "text": "人体や事務機器からの熱負荷は、室内負荷として考慮する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["日射負荷には、顕熱と潜熱がある。"], "answerHints": [["顕熱と潜熱"]], "mnemonic": "正しくは：日射負荷は顕熱のみ。顕熱と潜熱があるのは外気負荷等。", "block": 15, "group": 5}, {"id": "R06_kouki_12", "source": "R6後 No.12", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "マルチパッケージ形空気調和機には、屋外機の圧縮機をガスエンジンで駆動するものがあ る。"}, {"label": "2", "text": "マルチパッケージ形空気調和機は、同一冷媒配管系統の屋内機ごとに冷房と暖房が自由に選 択できるものがある。"}, {"label": "3", "text": "マルチパッケージ形空調機方式は、中央熱源方式に比べて機械室面積等が広く必要となる。"}, {"label": "4", "text": "パッケージ形空気調和機は、冷媒配管の長さに制限がある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["マルチパッケージ形空調機方式は、中央熱源方式に比べて機械室面積等が広く必要となる。"], "answerHints": [["広く必要"]], "mnemonic": "正しくは：マルチパッケージ形空調機方式は、中央熱源方式に比べて機械室面積が小さくて済む。", "block": 15, "group": 5}, {"id": "R06_kouki_15", "source": "R6後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水道水の消毒薬には、次亜塩素酸ナトリウム等が使用される。"}, {"label": "2", "text": "遊離残留塩素より結合残留塩素の方が、殺菌力が高い。"}, {"label": "3", "text": "水道水の水質基準のうち、pH 値は、5.8 以上8.6 以下とされている。"}, {"label": "4", "text": "消防法」に規定する有効容量が10 m3 を超える消防用水槽であって、全く飲用に供される ことのないものは、簡易専用水道に該当しない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["遊離残留塩素より結合残留塩素の方が、殺菌力が高い。"], "answerHints": [["結合残留塩素の方が"]], "mnemonic": "正しくは：結合残留塩素より遊離残留塩素の方が殺菌力が高い。", "block": 15, "group": 5}, {"id": "R06_kouki_18", "source": "R6後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "潜熱回収型給湯器には、潜熱回収時の凝縮水を中和処理する装置が組み込まれている。"}, {"label": "2", "text": "中央給湯方式の膨張タンクは、装置内の圧力が水の膨張により異常に上昇しないように 設ける。"}, {"label": "3", "text": "給湯管に使用される架橋ポリエチレン管の線膨張係数は、ステンレス鋼鋼管の線膨張係数 に比べて小さい。"}, {"label": "4", "text": "給湯温度は、貯湯タンク内での湯温が60 °C以上を維持できるようにする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給湯管に使用される架橋ポリエチレン管の線膨張係数は、ステンレス鋼鋼管の線膨張係数 に比べて小さい。"], "answerHints": [["比べて小さい"]], "mnemonic": "正しくは：架橋ポリエチレン管の線膨張係数は、ステンレス鋼鋼管に比べて大きい。", "block": 15, "group": 5}, {"id": "R06_kouki_22", "source": "R6後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "一般家庭用のガスメーターは、原則としてマイコンメーターとする。"}, {"label": "2", "text": "液化石油ガス(LPG)のガス漏れ警報器の有効期間は、7年である。"}, {"label": "3", "text": "液化石油ガス(LPG)は、空気中に漏えいすると低い場所に滞留しやすい。"}, {"label": "4", "text": "ガス事業法」による特定ガス用品の基準に適合している器具には、PS マークが表示され る。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化石油ガス(LPG)のガス漏れ警報器の有効期間は、7年である。"], "answerHints": [["7年"]], "mnemonic": "正しくは：LPG用ガス漏れ警報器の有効期間は5年。", "block": 15, "group": 5}, {"id": "R05_kouki_25", "source": "R5後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "保温材に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "JIS規格では、ホルムアルデヒド放散量に応じた等級区分が示されている。"}, {"label": "2", "text": "グラスウール保温材は、ポリスチレンフォーム保温材に比べて、高温域で使用できる。"}, {"label": "3", "text": "ロックウール保温材は、耐火性に優れ、配管等の防火区画の貫通部等に使用される。"}, {"label": "4", "text": "ポリスチレンフォーム保温材は、人造鉱物繊維保温材である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ポリスチレンフォーム保温材は、人造鉱物繊維保温材である。"], "answerHints": [["人造鉱物繊維保温材"]], "mnemonic": "正しくは：ポリスチレンフォームは発泡プラスチック保温材。人造鉱物繊維保温材はグラスウール・ロックウール。", "block": 15, "group": 5}, {"id": "R06_zenki_24", "source": "R6前 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "送風機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "遠心送風機には、多翼送風機、後向き送風機等がある。"}, {"label": "2", "text": "斜流送風機は、風量・静圧とも遠心式と軸流式の中間に位置する。"}, {"label": "3", "text": "軸流送風機は、低圧力・小風量を扱うのに適している。"}, {"label": "4", "text": "遠心送風機には、片吸込みと両吸込みがある。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["軸流送風機は、低圧力・小風量を扱うのに適している。"], "answerHints": [["小風量"]], "mnemonic": "正しくは：軸流送風機は低圧力・大風量を扱うのに適している。", "block": 15, "group": 5}, {"id": "R06_zenki_27", "source": "R6前 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "防火ダンパーのケーシング及び可動羽根の板厚は、風量調節ダンパーと同じである。"}, {"label": "2", "text": "共板フランジ工法は、ダクト本体を成形加工してフランジにする。"}, {"label": "3", "text": "パンカルーバーは、球面の一部にノズル形の吹出口を設けたもので、気流を自由な方向に吹き出すことができる。"}, {"label": "4", "text": "スパイラルダクトの接続には、差込み継手又はフランジ継手を用いる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火ダンパーのケーシング及び可動羽根の板厚は、風量調節ダンパーと同じである。"], "answerHints": [["風量調節ダンパーと同じ"]], "mnemonic": "正しくは：防火ダンパーのケーシング・可動羽根の板厚は1.5mm以上で、風量調節ダンパーより厚い。", "block": 15, "group": 5}, {"id": "R06_kouki_27", "source": "R6後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "風量調節ダンパーの多翼型には、平行翼型と対向翼型がある。"}, {"label": "2", "text": "シーリングディフューザー形吹出口は、誘引作用が大きく気流拡散に優れている。"}, {"label": "3", "text": "長方形ダクトのアスペクト比(長辺/短辺)は、原則として4以下とする。"}, {"label": "4", "text": "長方形ダクトの板厚は、ダクトの周長により決定する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["長方形ダクトの板厚は、ダクトの周長により決定する。"], "answerHints": [["周長"]], "mnemonic": "正しくは：長方形ダクトの板厚は、ダクトの長辺の長さにより決定する。", "block": 15, "group": 5}, {"id": "R05_kouki_33", "source": "R5後 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "防振基礎には、地震時の移動、転倒防止のための耐震ストッパーを設ける。"}, {"label": "2", "text": "建物内に設置する飲料用受水タンク上部と天井との距離は、600mm以上とする。"}, {"label": "3", "text": "機器を据え付けるコンクリート基礎は、水平に仕上げる。"}, {"label": "4", "text": "洗面器をコンクリート壁に取り付ける場合は、一般的に、エキスパンションボルト又は樹脂製プラグを使用する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["建物内に設置する飲料用受水タンク上部と天井との距離は、600mm以上とする。"], "answerHints": [["600mm以上"]], "mnemonic": "正しくは：受水タンク上部と天井との距離は1m以上（側面・底部は600mm以上）。", "block": 15, "group": 5}, {"id": "R05_kouki_36", "source": "R5後 No.36", "category": "施工管理法", "type": "single", "question": "保温及び塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "保温の厚さは、保温材のみの厚さとし、補助材及び外装材の厚さは含まない。"}, {"label": "2", "text": "塗装場所の相対湿度が85%以上の場合、原則として塗装を行わない。"}, {"label": "3", "text": "冷水配管を直接吊りバンドで支持する場合は、合成樹脂製支持受けを使用する。"}, {"label": "4", "text": "給水ポンプ回りの防振継手は、原則として保温を行う。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給水ポンプ回りの防振継手は、原則として保温を行う。"], "answerHints": [["保温を行う"]], "mnemonic": "正しくは：ポンプ回りの防振継手は、原則として保温を行わない。", "block": 15, "group": 5}, {"id": "R06_zenki_31", "source": "R5前 No.31 / R6前 No.31", "category": "施工管理法", "type": "single", "question": "次の確認項目のうち、抜取検査を行うものとして、適当でないものはどれか。", "choices": [{"label": "1", "text": "埋設排水管の勾配"}, {"label": "2", "text": "防火ダンパー用温度ヒューズの作動試験"}, {"label": "3", "text": "ダクトの吊り間隔"}, {"label": "4", "text": "コンクリートの強度試験"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["埋設排水管の勾配"], "answerHints": [["埋設排水管の勾配"]], "mnemonic": "埋設排水管の勾配は後から確認できないため全数検査。温度ヒューズ作動試験・吊り間隔・コンクリート強度は抜取検査。", "block": 15, "group": 5}, {"id": "R06_zenki_34", "source": "R6前 No.34", "category": "施工管理法", "type": "single", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "私道内の車両通路では、給水管の埋設深さを600mm以上とする。"}, {"label": "2", "text": "冷媒管は、配管完了後、冷媒の充填を行う前に気密試験及び真空脱気を行う。"}, {"label": "3", "text": "通気管は、排水横枝管の上部から、垂直ないし45°以内の角度で取り出す。"}, {"label": "4", "text": "飲料用給水タンクに設ける間接排水管の排水口空間は、最小100mmとする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用給水タンクに設ける間接排水管の排水口空間は、最小100mmとする。"], "answerHints": [["最小100mm"]], "mnemonic": "正しくは：飲料用給水タンクの間接排水管の排水口空間は最小150mm。", "block": 15, "group": 5}, {"id": "R06_zenki_37", "source": "R6前 No.37", "category": "施工管理法", "type": "single", "question": "多翼送風機の試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "瞬時運転し、回転方向を確認する。"}, {"label": "2", "text": "風量調整は、風量調整ダンパーが全開となっていることを確認してから開始する。"}, {"label": "3", "text": "風量は、過電流に注意しながら規定風量に調整する。"}, {"label": "4", "text": "Vベルトは、指で押したときベルトの厚さ程度たわむことを確認する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["風量調整は、風量調整ダンパーが全開となっていることを確認してから開始する。"], "answerHints": [["全開となっている"]], "mnemonic": "正しくは：多翼送風機の風量調整は、風量調整ダンパーが全閉となっていることを確認してから開始する。", "block": 15, "group": 5}, {"id": "R06_kouki_33", "source": "R6後 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "汚物排水槽に設ける排水用水中モーターポンプは、点検、引き上げに支障がないように、マ ンホールの真下付近に設置する。"}, {"label": "2", "text": "遠心ポンプを設置する場合、床からの高さは、一般的に300 mm 以上とする。"}, {"label": "3", "text": "軸流送風機をダクトの途中に取り付ける場合は、吸込み側、吐出し側共に、たわみ継手を介 して設置する。"}, {"label": "4", "text": "機器の据付け後、アンカーボルトの頂部のねじ山は、ナットから出ないようにする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["機器の据付け後、アンカーボルトの頂部のねじ山は、ナットから出ないようにする。"], "answerHints": [["ナットから出ないようにする"]], "mnemonic": "正しくは：アンカーボルトの頂部は、ナットから3山程度ねじ山が出るようにする。", "block": 15, "group": 5}, {"id": "R06_kouki_36", "source": "R6後 No.36", "category": "施工管理法", "type": "single", "question": "保温及び塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "保温の厚さは、保温材のみの厚さとし、補助材及び外装材の厚さは含まない。"}, {"label": "2", "text": "塗装場所の相対湿度が85 %以上の場合、原則として塗装を行わない。"}, {"label": "3", "text": "冷水配管を吊りバンドで支持する場合は、合成樹脂製支持受けを使用する。"}, {"label": "4", "text": "給水ポンプ回りの防振継手は、原則として保温を行う。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給水ポンプ回りの防振継手は、原則として保温を行う。"], "answerHints": [["保温を行う"]], "mnemonic": "正しくは：ポンプ回りの防振継手は、原則として保温を行わない。", "block": 15, "group": 5}, {"id": "R05_kouki_49", "source": "R5後 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程表に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "バーチャート工程表は、縦軸に作業名、横軸に達成度をとり、現在の進行状態を棒グラフで表したものである。"}, {"label": "2", "text": "ガントチャート工程表は、縦軸に作業名、横軸に工期をとったもので、各作業の施工時期や所要日数が明確に表示される。"}, {"label": "3", "text": "曲線式工程表は、上方許容限界曲線と下方許容限界曲線とで囲まれた形からバナナ曲線とも呼ばれている。"}, {"label": "4", "text": "総合工程表には、諸官庁への申請の時期や工事に影響を与える主要な事項の日程についても記載する。"}], "answer": ["1", "2"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表は、縦軸に作業名、横軸に達成度をとり、現在の進行状態を棒グラフで表したものである。", "ガントチャート工程表は、縦軸に作業名、横軸に工期をとったもので、各作業の施工時期や所要日数が明確に表示される。"], "answerHints": [["横軸に達成度"], ["横軸に工期"]], "mnemonic": "バーチャートは横軸に工期（所要日数がわかる）、ガントチャートは横軸に達成度（所要日数がわからない）。", "block": 15, "group": 5}, {"id": "R05_kouki_52", "source": "R5後 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "隠ぺい部に防火ダンパーを設置する場合には、450mm × 450mm以上の点検口を設ける。"}, {"label": "2", "text": "防火ダンパーの温度ヒューズの作動温度は、一般排気及び厨房排気ともに72°Cとする。"}, {"label": "3", "text": "ダクトのアスペクト比(長辺と短辺の比)は、原則として4以下とする。"}, {"label": "4", "text": "長方形ダクトは、断面積が同じ場合、アスペクト比を変えても圧力損失は変わらない。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["防火ダンパーの温度ヒューズの作動温度は、一般排気及び厨房排気ともに72°Cとする。", "長方形ダクトは、断面積が同じ場合、アスペクト比を変えても圧力損失は変わらない。"], "answerHints": [["厨房排気ともに72°C"], ["圧力損失は変わらない"]], "mnemonic": "正しくは：温度ヒューズは一般排気72℃、厨房排気120℃。断面積が同じでもアスペクト比が大きいほど圧力損失は大きくなる。", "block": 15, "group": 5}, {"id": "R06_zenki_51", "source": "R6前 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "水道用硬質塩化ビニルライニング鋼管のねじ接合では、配管切断後にライニング部の面取りを行う。"}, {"label": "2", "text": "硬質ポリ塩化ビニル管の接着接合では、テーパ形状の受口内面のみに接着剤を塗布する。"}, {"label": "3", "text": "汚水槽の通気管は、その他の排水系統の通気立て管を介して大気に開放する。"}, {"label": "4", "text": "冷媒用断熱材被覆銅管は、断熱材の厚みが減少しないよう支持部に保護プレートを設ける。"}], "answer": ["2", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["硬質ポリ塩化ビニル管の接着接合では、テーパ形状の受口内面のみに接着剤を塗布する。", "汚水槽の通気管は、その他の排水系統の通気立て管を介して大気に開放する。"], "answerHints": [["受口内面のみ"], ["通気立て管を介して"]], "mnemonic": "正しくは：接着剤は受口内面と管差口外面の両方に塗布する。汚水槽の通気管は単独で大気に開放する。", "block": 15, "group": 5}, {"id": "R06_kouki_51", "source": "R6後 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管の施工に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "冷温水配管の熱伸縮を吸収するために、フレキシブルジョイントを使用する。"}, {"label": "2", "text": "鋼管のねじ接合においては、余ねじ部に錆止めペイントを塗布する。"}, {"label": "3", "text": "排水立て管は、下層階に行くに従い、途中で合流する排水量に応じて管径を大きくする。"}, {"label": "4", "text": "屋外からの配管の建築物導入部には、地盤沈下等の変位を吸収できる継手又は装置を設け る。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["冷温水配管の熱伸縮を吸収するために、フレキシブルジョイントを使用する。", "排水立て管は、下層階に行くに従い、途中で合流する排水量に応じて管径を大きくする。"], "answerHints": [["フレキシブルジョイント"], ["管径を大きくする"]], "mnemonic": "正しくは：熱伸縮の吸収には伸縮管継手を使う。排水立て管は最下部の最大排水量に対する管径で、上部まで同一管径とする。", "block": 15, "group": 5}, {"id": "R05_kouki_40", "source": "R5後 No.40", "category": "法規", "type": "single", "question": "労働者に支払う賃金に関する記述のうち、「労働基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "出来高払制その他の請負制で使用する労働者については、使用者は、労働時間に応じ一定額の賃金の保障をしなければならない。"}, {"label": "2", "text": "賃金とは、賃金、給料、手当等、労働の対償として使用者が労働者に支払うものをいい、賞与はこれに含まれない。"}, {"label": "3", "text": "未成年者の親権者又は後見人は、未成年者の賃金を代わって受け取ってはならない。"}, {"label": "4", "text": "使用者は、労働者が疾病の費用に充てるために請求する場合においては、支払期日前であっても、既往の労働に対する賃金を支払わなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["賃金とは、賃金、給料、手当等、労働の対償として使用者が労働者に支払うものをいい、賞与はこれに含まれない。"], "answerHints": [["賞与はこれに含まれない"]], "mnemonic": "正しくは：賞与も労働の対償として使用者が支払うものであれば賃金に含まれる。", "block": 15, "group": 5}, {"id": "R05_kouki_43", "source": "R5後 No.43", "category": "法規", "type": "single", "question": "建設業者が請け負った管工事について、「建設業法」上、当該工事現場に置かなければならない主任技術者の要件に、該当しないものはどれか。", "choices": [{"label": "1", "text": "検定種目を管工事施工管理とする2級技術検定の第二次検定に合格した者"}, {"label": "2", "text": "一級建築士免許の交付を受けた者"}, {"label": "3", "text": "管工事に関し10年以上の実務経験を有する者"}, {"label": "4", "text": "建築設備士となった後、管工事に関し1年以上の実務経験を有する者"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["一級建築士免許の交付を受けた者"], "answerHints": [["一級建築士免許"]], "mnemonic": "管工事の主任技術者になれるのは管工事施工管理技士、10年以上の実務経験者、建築設備士＋1年以上の実務経験者等。建築士は該当しない。", "block": 15, "group": 5}, {"id": "R05_kouki_46", "source": "R5後 No.46", "category": "法規", "type": "single", "question": "業務用冷凍空調機器(カーエアコンを除く。)に関する記述のうち、第一種特定製品の管理者がフロン類の管理の適正化のために取り組むべき事項として、「フロン類の使用の合理化及び管理の適正化に関する法律」上、定められていないものはどれか。", "choices": [{"label": "1", "text": "簡易点検の実施"}, {"label": "2", "text": "点検及び整備に係る記録簿の保存"}, {"label": "3", "text": "フロン類の再生の実施"}, {"label": "4", "text": "フロン類の漏えいを確認した場合の漏えいに係る点検及び漏えい箇所の修理"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["フロン類の再生の実施"], "answerHints": [["フロン類の再生の実施"]], "mnemonic": "管理者の取組は簡易点検・定期点検、漏えい時の点検・修理、記録簿の保存。再生は再生業者が行う。", "block": 15, "group": 5}, {"id": "R06_zenki_39", "source": "R6前 No.39", "category": "法規", "type": "single", "question": "建設工事現場における作業のうち、「労働安全衛生法」上、作業主任者を選任すべき作業に該当しないものはどれか。", "choices": [{"label": "1", "text": "つり上げ荷重が1トン未満の移動式クレーンの玉掛けの作業"}, {"label": "2", "text": "アセチレン溶接装置又はガス集合溶接装置を用いて行う金属の溶接、溶断又は加熱の作業"}, {"label": "3", "text": "ボイラー(小型ボイラーを除く。)の取扱いの作業"}, {"label": "4", "text": "掘削面の高さが2m以上となる地山の掘削(ずい道及びたて坑以外の杭の掘削を除く。)の作業"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["つり上げ荷重が1トン未満の移動式クレーンの玉掛けの作業"], "answerHints": [["玉掛けの作業"]], "mnemonic": "玉掛けは作業主任者の選任不要（1t未満は特別教育、1t以上は技能講習）。ガス溶接・ボイラー取扱い・2m以上の地山掘削は作業主任者が必要。", "block": 15, "group": 5}, {"id": "R06_zenki_42", "source": "R6前 No.42", "category": "法規", "type": "single", "question": "次の項目のうち、「建築基準法」上、建築物の居室に設ける中央管理方式の空気調和設備の性能として、定められていないものはどれか。", "choices": [{"label": "1", "text": "温度"}, {"label": "2", "text": "浮遊粉じん量"}, {"label": "3", "text": "炭酸ガスの含有率"}, {"label": "4", "text": "酸素の含有率"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["酸素の含有率"], "answerHints": [["酸素の含有率"]], "mnemonic": "中央管理方式の空調の基準は浮遊粉じん量・CO含有率・CO2含有率・温度・相対湿度・気流。酸素は定められていない。", "block": 15, "group": 5}, {"id": "R06_zenki_45", "source": "R6前 No.45", "category": "法規", "type": "single", "question": "危険物に関する記述のうち、「消防法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "屋内タンク貯蔵所には、見やすい箇所に屋内タンク貯蔵所である旨を表示した標識を設ける。"}, {"label": "2", "text": "危険物を貯蔵し、又は取り扱う屋内タンクは、平家建の建築物に設けられたタンク専用室に設置する。"}, {"label": "3", "text": "指定数量以上の危険物は、原則として、貯蔵所以外の場所でこれを貯蔵してはならない。"}, {"label": "4", "text": "品名又は指定数量を異にする二以上の危険物を同一の場所で貯蔵する場合、それぞれの危険物が指定数量未満であれば指定数量以上の貯蔵所とはならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["品名又は指定数量を異にする二以上の危険物を同一の場所で貯蔵する場合、それぞれの危険物が指定数量未満であれば指定数量以上の貯蔵所とはならない。"], "answerHints": [["指定数量以上の貯蔵所とはならない"]], "mnemonic": "正しくは：各危険物の数量を指定数量で除した値の和が1以上なら、指定数量以上の危険物を貯蔵しているものとみなす。", "block": 15, "group": 5}, {"id": "R06_zenki_48", "source": "R6前 No.48", "category": "法規", "type": "single", "question": "廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、その事業活動に伴って生じた廃棄物を自らの責任において適正に処理しなければならない。"}, {"label": "2", "text": "事業者は、その産業廃棄物(特別管理産業廃棄物を除く。)が運搬されるまでの間、産業廃棄物保管基準に従い、生活環境の保全上支障のないようにこれを保管しなければならない。"}, {"label": "3", "text": "建設工事の元請業者が、当該工事において発生させた産業廃棄物を自ら処理施設へ運搬する場合は、産業廃棄物収集運搬業の許可を受けなければならない。"}, {"label": "4", "text": "産業廃棄物管理票交付者は、管理票の写しを送付を受けたときは、当該運搬又は処分が終了したことを当該管理票の写しにより確認しなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設工事の元請業者が、当該工事において発生させた産業廃棄物を自ら処理施設へ運搬する場合は、産業廃棄物収集運搬業の許可を受けなければならない。"], "answerHints": [["許可を受けなければならない"]], "mnemonic": "正しくは：排出事業者（元請業者）が自ら産業廃棄物を運搬する場合、収集運搬業の許可は必要としない。", "block": 15, "group": 5}, {"id": "R06_kouki_41", "source": "R6後 No.41", "category": "法規", "type": "single", "question": "建築物の面積、高さ及び階に関する記述のうち、建築基準法」上、誤っているものは どれか。", "choices": [{"label": "1", "text": "建築物の外壁又はこれに代わる柱の中心線から水平距離1m 突き出たひさしの水平投影面積 は、当該建築物の建築面積に算入しない。"}, {"label": "2", "text": "建築物のエレベーター機械室、装飾塔その他これらに類する屋上部分は、その部分の面積に かかわらず建築物の階数に算入しない。"}, {"label": "3", "text": "地階とは、床が地盤面下にある階で、床面から地盤面までの高さがその階の天井の高さの 以上のものをいう。"}, {"label": "4", "text": "建築物の階段室、エレベーター機械室その他これらに類する屋上部分は、その部分の面積の 合計が所定の条件を満たせば、建築物の高さに算入しない場合がある。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建築物のエレベーター機械室、装飾塔その他これらに類する屋上部分は、その部分の面積に かかわらず建築物の階数に算入しない。"], "answerHints": [["かかわらず"]], "mnemonic": "正しくは：屋上部分は、水平投影面積の合計が建築面積の1/8以下の場合に限り階数に算入しない。", "block": 15, "group": 5}, {"id": "R06_kouki_45", "source": "R6後 No.45", "category": "法規", "type": "single", "question": "消防用設備のうち、消防法」上、非常電源を附置する必要のないものはどれか。", "choices": [{"label": "1", "text": "連結散水設備"}, {"label": "2", "text": "屋内消火栓設備"}, {"label": "3", "text": "スプリンクラー設備"}, {"label": "4", "text": "ハロゲン化物消火設備"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["必要のないもの"], "answerTexts": ["連結散水設備"], "answerHints": [["連結散水設備"]], "mnemonic": "連結散水設備は消防ポンプ車から送水するため非常電源不要。屋内消火栓・スプリンクラー・ハロゲン化物消火設備は必要。", "block": 15, "group": 5}, {"id": "R06_kouki_48", "source": "R6後 No.48", "category": "法規", "type": "single", "question": "廃棄物の処理に関する記述のうち、廃棄物の処理及び清掃に関する法律」上、 誤っているものはどれか。", "choices": [{"label": "1", "text": "廃棄物とは、ごみ、粗大ごみ、燃え殻、汚泥、ふん尿、廃油、廃酸、廃アルカリ、動物の死体 その他の汚物又は不要物であって、固形状又は液状のもの(放射性物質及びこれによって汚 染された物を除く。)をいう。"}, {"label": "2", "text": "事業活動に伴って生じた廃棄物のうち、木くず(建設業に係るもの(工作物の新築、改築又 は除去に伴って生じたものに限る。))は、一般廃棄物である。"}, {"label": "3", "text": "廃エアコンディショナー(国内における日常生活に伴って生じたものに限る。)に含まれるポ リ塩化ビフェニルを使用する部品は、特別管理一般廃棄物である。"}, {"label": "4", "text": "建築物の改築に伴って生じた産業廃棄物であって、石綿をその重量の0.1 %を超えて含有 する場合(廃石綿等を除く。)、石綿含有産業廃棄物として処理する。 せん。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業活動に伴って生じた廃棄物のうち、木くず(建設業に係るもの(工作物の新築、改築又 は除去に伴って生じたものに限る。))は、一般廃棄物である。"], "answerHints": [["一般廃棄物である"]], "mnemonic": "正しくは：建設業に係る木くず（工作物の新築・改築・除去に伴うもの）は産業廃棄物。", "block": 15, "group": 5}, {"id": "R07_zenki_01", "source": "R7前 No.1", "category": "一般基礎", "type": "single", "question": "水に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "1気圧のもとでは、水の蒸発熱は氷の融解熱より大きい。"}, {"label": "2", "text": "1気圧のもとでは、水の密度が最大になる温度は約4°Cである。"}, {"label": "3", "text": "pH は、水素イオンの濃度を示す指標である。"}, {"label": "4", "text": "0°C1気圧における氷の密度は、水の密度より大きい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["0°C1気圧における氷の密度は、水の密度より大きい。"], "answerHints": [["水の密度より大きい"]], "mnemonic": "正しくは：0℃の氷の密度は水より小さい（だから氷は水に浮く）。", "block": 16, "group": 6}, {"id": "R07_zenki_05", "source": "R7前 No.5", "category": "一般基礎", "type": "single", "question": "三相誘導電動機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "全電圧始動方式は、始動時に定格電流より大きな電流が流れる。"}, {"label": "2", "text": "電動機の過負荷保護には、サーマルリレーと電磁接触器を用いる方法がある。"}, {"label": "3", "text": "3本の結線のうち2本を入れ替えると、電動機の回転方向が変わる。"}, {"label": "4", "text": "スターデルタ始動方式は、始動時のトルクが全電圧始動方式と同じである。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["スターデルタ始動方式は、始動時のトルクが全電圧始動方式と同じである。"], "answerHints": [["全電圧始動方式と同じ"]], "mnemonic": "正しくは：スターデルタ始動の始動トルク（と始動電流）は全電圧始動の約1/3に小さくなる。", "block": 16, "group": 6}, {"id": "R07_kouki_02", "source": "R7後 No.2", "category": "一般基礎", "type": "single", "question": "水平な円管の直管部を流れる流体について、全圧、静圧及び動圧の関係を表す式として、 適当なものはどれか。 ただし、Pt:全圧(Pa)、Ps:静圧(Pa)、ρ:流体の密度(kg/m3)、v:流速(m/s) とする。", "choices": [{"label": "1", "text": "Pt ＝Ps +ρv"}, {"label": "2", "text": "Ps ＝Pt +ρv ρv2"}, {"label": "3", "text": "Pt ＝Ps + ρv2"}, {"label": "4", "text": "Ps ＝Pt +"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["Pt ＝Ps + ρv2"], "answerHints": [["Pt ＝Ps + ρv2"]], "mnemonic": "全圧＝静圧＋動圧。動圧は（1/2）ρv²。", "block": 16, "group": 6}, {"id": "R07_kouki_06", "source": "R7後 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート構造に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "鉄筋コンクリートは、主に、鉄筋が引張応力を、コンクリートが圧縮応力を負担する。"}, {"label": "2", "text": "鉄筋とコンクリートの線膨張係数は、常温においてほぼ等しい。"}, {"label": "3", "text": "鉄筋の継手の位置は、応力の大きい部分に設ける。"}, {"label": "4", "text": "構造体に作用する外力として、風圧力も考慮する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鉄筋の継手の位置は、応力の大きい部分に設ける。"], "answerHints": [["応力の大きい部分"]], "mnemonic": "正しくは：鉄筋の継手は応力の小さい部分に設ける。", "block": 16, "group": 6}, {"id": "R08_zenki_03", "source": "R8前 No.3", "category": "一般基礎", "type": "single", "question": "湿り空気に関する記述のうち、適当でないものはどれか。 ただし、湿り空気の全圧力は一定とする。", "choices": [{"label": "1", "text": "空気中に含むことのできる水蒸気量は、乾球温度が高くなると多くなる。"}, {"label": "2", "text": "飽和湿り空気は、その乾球温度では、それ以上水蒸気を含むことができない。"}, {"label": "3", "text": "相対湿度が同じ場合、絶対湿度の低い湿り空気のほうが露点温度が高い。"}, {"label": "4", "text": "飽和湿り空気の乾球温度と湿球温度は等しい。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["相対湿度が同じ場合、絶対湿度の低い湿り空気のほうが露点温度が高い。"], "answerHints": [["露点温度が高い"]], "mnemonic": "正しくは：相対湿度が同じなら、絶対湿度の低い空気のほうが露点温度は低い。", "block": 16, "group": 6}, {"id": "R08_zenki_06", "source": "R8前 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート造に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水セメント比が大きくなると、コンクリートの圧縮強度は高くなる。"}, {"label": "2", "text": "鉄筋は、異形棒鋼のほうが丸鋼よりもコンクリートに対する付着性がよい。"}, {"label": "3", "text": "コンクリートの打設後、硬化中のコンクリートには、振動及び外力を加えないようにする。"}, {"label": "4", "text": "コンクリートは、打設後、所定の強度を発揮するまで、十分に湿潤状態を保つ。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水セメント比が大きくなると、コンクリートの圧縮強度は高くなる。"], "answerHints": [["圧縮強度は高くなる"]], "mnemonic": "正しくは：水セメント比が大きくなると圧縮強度は低くなる（小さいほど強い）。", "block": 16, "group": 6}, {"id": "R07_zenki_10", "source": "R7前 No.10", "category": "空調・衛生", "type": "single", "question": "空気清浄装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "中・高性能フィルターは、ろ材の通過風速を高くして圧力損失を大きくする構造となってい る。"}, {"label": "2", "text": "捕集率とは、空気清浄装置に流入する粉じんの捕集割合を示すものである。"}, {"label": "3", "text": "空気清浄装置の圧力損失は、装置の上流側と下流側の圧力差で表される。"}, {"label": "4", "text": "ろ過式のろ材の材質は、吸湿性の少ないことが要求される。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["中・高性能フィルターは、ろ材の通過風速を高くして圧力損失を大きくする構造となってい る。"], "answerHints": [["高くして", "大きくする"]], "mnemonic": "正しくは：中・高性能フィルターは、ろ材の通過風速を低くして圧力損失を小さくする構造。", "block": 16, "group": 6}, {"id": "R07_zenki_13", "source": "R7前 No.13", "category": "空調・衛生", "type": "single", "question": "次の室のうち、第三種機械換気方式を用いることが適当でないものはどれか。", "choices": [{"label": "1", "text": "ボイラー室"}, {"label": "2", "text": "書庫"}, {"label": "3", "text": "便所"}, {"label": "4", "text": "シャワー室"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボイラー室"], "answerHints": [["ボイラー室"]], "mnemonic": "ボイラー室は燃焼用空気が必要なので第一種換気。便所・書庫・シャワー室は第三種（負圧）でよい。", "block": 16, "group": 6}, {"id": "R07_zenki_16", "source": "R7前 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "分流式は、汚水と雨水を別々の管路系統とする方式である。"}, {"label": "2", "text": "流域下水道は、終末処理場を持たない。"}, {"label": "3", "text": "取付管は、民有地と道路の境界にあるますと下水道本管を結ぶ管である。"}, {"label": "4", "text": "公共下水道の管理は、地方公共団体が行う。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["流域下水道は、終末処理場を持たない。"], "answerHints": [["終末処理場を持たない"]], "mnemonic": "正しくは：流域下水道は終末処理場を有する（終末処理場を持たないのは流域関連公共下水道）。", "block": 16, "group": 6}, {"id": "R07_zenki_19", "source": "R7前 No.19", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "伸頂通気管の管径は、排水立て管の管径の 以上とする。"}, {"label": "2", "text": "排水管径を決定する方法として、器具排水負荷単位法や定常流量法がある。"}, {"label": "3", "text": "排水管から取り出した通気管どうしを床下で接続してはならない。"}, {"label": "4", "text": "各個通気管は、器具トラップの下流側の排水管より取り出す。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["伸頂通気管の管径は、排水立て管の管径の 以上とする。"], "answerHints": [["管径の 以上"]], "mnemonic": "正しくは：伸頂通気管は排水立て管の管径より小さくしない（1/2以上は誤り）。", "block": 16, "group": 6}, {"id": "R07_zenki_22", "source": "R7前 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液化天然ガス(LNG)は、メタンを主成分とした天然ガスを冷却して液化したものである。"}, {"label": "2", "text": "液化天然ガス(LNG)は、液化石油ガス(LPG)より単位容積あたりの発熱量が大きい。"}, {"label": "3", "text": "都市ガスの導管の敷設位置による区分としての「内管」とは、需要家に引き込まれる導管のう ち、敷地境界線からガス栓までの導管をいう。"}, {"label": "4", "text": "液化石油ガス(LPG)のガス容器は、常に温度を40 °C以下に保つ措置を講じる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化天然ガス(LNG)は、液化石油ガス(LPG)より単位容積あたりの発熱量が大きい。"], "answerHints": [["発熱量が大きい"]], "mnemonic": "正しくは：LNG（メタン主体）はLPG（プロパン主体）より単位容積あたりの発熱量が小さい。", "block": 16, "group": 6}, {"id": "R07_kouki_09", "source": "R7後 No.9", "category": "空調・衛生", "type": "single", "question": "空気清浄装置に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ろ過式は、繊維などの多孔質空間を通過させることで粉じんを捕集する。"}, {"label": "2", "text": "静電式は、有害ガスや臭気を除去することができる。"}, {"label": "3", "text": "折込み形のフィルターは、ろ過面積を広くすることで圧力損失を減らしている。"}, {"label": "4", "text": "衝突粘着式は、粘着剤を塗布した金網、金属板等に粉じんを衝突付着させるものである。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["静電式は、有害ガスや臭気を除去することができる。"], "answerHints": [["有害ガスや臭気"]], "mnemonic": "正しくは：静電式は粉じん除去用。有害ガス・臭気の除去は活性炭等の吸着式。", "block": 16, "group": 6}, {"id": "R07_kouki_12", "source": "R7後 No.12", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "インバーター制御のものは、リアクトルの設置等による高調波対策が必要である。"}, {"label": "2", "text": "空冷式は、屋内機と屋外機間の高低差の制限はない。"}, {"label": "3", "text": "「高圧ガス保安法」の適用を受ける場合がある。"}, {"label": "4", "text": "圧縮機は、ロータリー形、スクロール形等が多く使用されている。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["空冷式は、屋内機と屋外機間の高低差の制限はない。"], "answerHints": [["高低差の制限はない"]], "mnemonic": "正しくは：空冷式は屋内機と屋外機の間の高低差・配管長に制限がある。", "block": 16, "group": 6}, {"id": "R07_kouki_15", "source": "R7後 No.15", "category": "空調・衛生", "type": "single", "question": "上水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "「水道法」でいう給水装置には、建築物に設置される受水タンクも含まれる。"}, {"label": "2", "text": "簡易専用水道とは、水道事業の用に供する水道から供給を受ける水のみを水源とし、水の供 給を受けるために設けられる水槽の有効容量の合計が10 m3 を超えるものをいう。"}, {"label": "3", "text": "配水管への取付口の位置は、他の給水装置の取付口から30 cm 以上離す。"}, {"label": "4", "text": "水道事業者は、当該水道事業者の給水区域において、給水装置工事を適正に施行すること ができると認められる者を指定することができる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["「水道法」でいう給水装置には、建築物に設置される受水タンクも含まれる。"], "answerHints": [["受水タンクも含まれる"]], "mnemonic": "正しくは：給水装置は配水管から分岐した給水管と直結する給水用具まで。受水タンク以降は含まれない。", "block": 16, "group": 6}, {"id": "R07_kouki_18", "source": "R7後 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "中央給湯方式の場合、配管は可能な限り最短経路とし、熱損失を防止する。"}, {"label": "2", "text": "中央給湯方式に設ける膨張タンクには、密閉式と開放式がある。"}, {"label": "3", "text": "湯沸室の給茶用の給湯には、一般的に、局所式給湯設備が採用される。"}, {"label": "4", "text": "ヒートポンプ給湯機は、出湯能力の表示として、「号」が用いられる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ヒートポンプ給湯機は、出湯能力の表示として、「号」が用いられる。"], "answerHints": [["「号」"]], "mnemonic": "正しくは：ヒートポンプ給湯機の能力表示はkW。「号」はガス瞬間湯沸器の表示。", "block": 16, "group": 6}, {"id": "R07_kouki_21", "source": "R6後 No.21 / R7後 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "一人で操作することができる屋内消火栓設備の消防用ホースは、保形ホースとする。"}, {"label": "2", "text": "屋内消火栓箱には、その表面に「消火栓」と表示する。"}, {"label": "3", "text": "加圧送水装置は、火災等の災害による被害を受けるおそれが少ない箇所に設ける。"}, {"label": "4", "text": "易操作性1号消火栓は、消火栓箱で加圧送水装置の停止操作ができる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["易操作性1号消火栓は、消火栓箱で加圧送水装置の停止操作ができる。"], "answerHints": [["停止操作ができる"]], "mnemonic": "正しくは：易操作性1号消火栓は消火栓箱の操作で起動できるが、加圧送水装置の停止は制御盤で行う。", "block": 16, "group": 6}, {"id": "R08_zenki_07", "source": "R8前 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ファンコイルユニット・ダクト併用方式は、空調対象室毎の温度調整が可能である。"}, {"label": "2", "text": "定風量単一ダクト方式は、ファンコイルユニット・ダクト併用方式に比べて、空気調和機の 送風量が小さくなる。"}, {"label": "3", "text": "ファンコイルユニット・ダクト併用方式は、一般的に、空調対象室内にファンコイルユニッ トが設置されるため、ファンコイルユニット及び水配管からの水損リスクがある。"}, {"label": "4", "text": "定風量単一ダクト方式は、空気調和機で処理した空気をダクトにより、一定の風量で空調 対象室内に送風する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["定風量単一ダクト方式は、ファンコイルユニット・ダクト併用方式に比べて、空気調和機の 送風量が小さくなる。"], "answerHints": [["送風量が小さくなる"]], "mnemonic": "正しくは：定風量単一ダクト方式は全負荷を空気で運ぶので、FCU・ダクト併用方式より送風量が大きい。", "block": 16, "group": 6}, {"id": "R08_zenki_11", "source": "R8前 No.11", "category": "空調・衛生", "type": "single", "question": "温水暖房における膨張タンクに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "密閉式膨張タンクを用いる場合は、配管系が異常に圧力上昇することを防止するために 安全弁を設ける。"}, {"label": "2", "text": "開放式膨張タンクは、配管系のエア抜きとしても利用できる。"}, {"label": "3", "text": "密閉式膨張タンクは、開放式膨張タンクに比べ、設置場所の制限が少ない。"}, {"label": "4", "text": "開放式膨張タンクにボイラーの逃がし管を接続する場合は、その途中に保守用の仕切弁を設 ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["開放式膨張タンクにボイラーの逃がし管を接続する場合は、その途中に保守用の仕切弁を設 ける。"], "answerHints": [["保守用の仕切弁"]], "mnemonic": "正しくは：ボイラーの逃がし管には弁を設けない。", "block": 16, "group": 6}, {"id": "R08_zenki_14", "source": "R8前 No.14", "category": "空調・衛生", "type": "single", "question": "換気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "第三種機械換気方式では、換気対象室内は負圧となる。"}, {"label": "2", "text": "火気使用室等で、室内の空気汚染の発生源が局所的に限定される場合には、局所換気が有効 である。"}, {"label": "3", "text": "第二種機械換気方式では、換気対象室内は正圧となる。"}, {"label": "4", "text": "温度差を利用する自然換気方式では、換気対象室の高い位置に給気口を設ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["温度差を利用する自然換気方式では、換気対象室の高い位置に給気口を設ける。"], "answerHints": [["高い位置に給気口"]], "mnemonic": "正しくは：温度差換気は低い位置に給気口、高い位置に排気口。", "block": 16, "group": 6}, {"id": "R08_zenki_17", "source": "R8前 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "受水タンクへの給水には、ウォーターハンマーを起こりにくくするため、一般的に、定水位 調整弁が用いられる。"}, {"label": "2", "text": "水道直結増圧方式は、受水タンクを設ける必要がない。"}, {"label": "3", "text": "受水タンクは、保守点検及び清掃を考慮し、2 槽分割等にする。"}, {"label": "4", "text": "ホースを接続して使用する水栓には、逆サイホン防止のために逆止弁を設ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ホースを接続して使用する水栓には、逆サイホン防止のために逆止弁を設ける。"], "answerHints": [["逆止弁"]], "mnemonic": "正しくは：ホース接続水栓には逆サイホン防止のためバキュームブレーカーを設ける。", "block": 16, "group": 6}, {"id": "R08_zenki_20", "source": "R8前 No.20", "category": "空調・衛生", "type": "single", "question": "排水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋内からの排水管を屋外排水管に接続する場合は、排水ますを介して行う。"}, {"label": "2", "text": "排水横主管及び排水横枝管の起点部には、掃除口を設ける。"}, {"label": "3", "text": "トラップの封水は、誘導サイホン作用、自己サイホン作用、蒸発、毛管現象等により破封す る。"}, {"label": "4", "text": "ドラムトラップは、サイホン式トラップの一種である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ドラムトラップは、サイホン式トラップの一種である。"], "answerHints": [["サイホン式トラップの一種"]], "mnemonic": "正しくは：ドラムトラップは非サイホン式トラップ。", "block": 16, "group": 6}, {"id": "R08_zenki_23", "source": "R8前 No.23", "category": "空調・衛生", "type": "single", "question": "浄化槽に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "浄化槽は、水洗便所のし尿や工場廃水等の汚水を処理する設備又は施設である。"}, {"label": "2", "text": "浄化槽の躯体は、FRP 製、鉄筋コンクリート製等がある。"}, {"label": "3", "text": "処理工程の一次処理とは、主として沈降性の浮遊物質を除去することである。"}, {"label": "4", "text": "脱窒ろ床接触ばっ気方式では、BOD と窒素を除去することができる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["浄化槽は、水洗便所のし尿や工場廃水等の汚水を処理する設備又は施設である。"], "answerHints": [["工場廃水"]], "mnemonic": "正しくは：浄化槽はし尿と生活雑排水を処理する設備。工場廃水は対象外。", "block": 16, "group": 6}, {"id": "R07_zenki_26", "source": "R7前 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "仕切弁は、弁体が上下に動き流体を仕切るものである。"}, {"label": "2", "text": "水道用硬質塩化ビニルライニング鋼管(SGP-VD)は、一般的に、地中埋設配管に用いられ る。"}, {"label": "3", "text": "バタフライ弁は、仕切弁に比べ取付けスペースが大きい。"}, {"label": "4", "text": "排水用リサイクル硬質ポリ塩化ビニル管(REP-VU)は、一般的に、屋外排水配管に用いら れる。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["バタフライ弁は、仕切弁に比べ取付けスペースが大きい。"], "answerHints": [["取付けスペースが大きい"]], "mnemonic": "正しくは：バタフライ弁は仕切弁に比べ、取付けスペースが小さい。", "block": 16, "group": 6}, {"id": "R07_kouki_25", "source": "R6後 No.25 / R7後 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "給湯機器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "密閉式のガス給湯器は、燃焼用の空気を屋内からとり、燃焼廃ガスは屋外に排出する機器 である。"}, {"label": "2", "text": "貯湯式電気温水器には、元止め式と先止め式がある。"}, {"label": "3", "text": "元止め式のガス瞬間湯沸器は、本体の湯栓を操作して給湯するものである。"}, {"label": "4", "text": "ヒートポンプ給湯機は、大気中の熱エネルギーを給湯の加熱に利用するものである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["密閉式のガス給湯器は、燃焼用の空気を屋内からとり、燃焼廃ガスは屋外に排出する機器 である。"], "answerHints": [["屋内からとり"]], "mnemonic": "正しくは：密閉式は燃焼用空気を屋外から取り入れ屋外へ排気。屋内から取り屋外へ排気するのは半密閉式。", "block": 16, "group": 6}, {"id": "R08_zenki_24", "source": "R8前 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "飲料用給水タンクに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "鋼板製一体形タンク内面の防錆処理は、エポキシ樹脂ライニング等を施す。"}, {"label": "2", "text": "FRP 製タンクは、日光を遮断し、紫外線にも強い。"}, {"label": "3", "text": "FRP 製パネルタンクには、FRP を表面材とし、合成樹脂発泡材を心材としたサンドイッチ構 造のものがある。"}, {"label": "4", "text": "木製タンクは、金属製タンクに比べ熱伝導率が小さい。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["FRP 製タンクは、日光を遮断し、紫外線にも強い。"], "answerHints": [["日光を遮断し、紫外線にも強い"]], "mnemonic": "正しくは：FRP製タンクは光を通しやすく（藻が発生しやすい）、紫外線に弱い。", "block": 16, "group": 6}, {"id": "R08_zenki_27", "source": "R8前 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "たわみ継手は、ダクトと当該ダクトを接続する機器との位置合わせのために使用する。"}, {"label": "2", "text": "コーナーボルト工法には、共板フランジ工法とスライドオンフランジ工法がある。"}, {"label": "3", "text": "防火ダンパーのケーシング及び羽根は、厚さ 1.5 mm 以上の鋼板製のものとする。"}, {"label": "4", "text": "防火ダンパーには、温度ヒューズ型ダンパーや煙感知器連動型ダンパー等がある。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["たわみ継手は、ダクトと当該ダクトを接続する機器との位置合わせのために使用する。"], "answerHints": [["位置合わせ"]], "mnemonic": "正しくは：たわみ継手は送風機等の振動をダクトに伝えないために使用する。", "block": 16, "group": 6}, {"id": "R07_zenki_32", "source": "R7前 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "高さが2m の作業場所に作業床を設ける場合は、床材間のすき間は3cm 以下になるように する。"}, {"label": "2", "text": "作業場所の高さ又は深さが、2m までは昇降設備を設けなくてよい。"}, {"label": "3", "text": "荷を吊り上げるワイヤーロープは、安全係数6以上とし、吊り角度を考慮して長さを選定す る。"}, {"label": "4", "text": "脚立は、滑り止めの付いた丈夫な構造で、著しい損傷や腐食がないものを使用する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["作業場所の高さ又は深さが、2m までは昇降設備を設けなくてよい。"], "answerHints": [["2m まで"]], "mnemonic": "正しくは：高さ又は深さが1.5mを超える箇所では昇降設備を設ける。", "block": 16, "group": 6}, {"id": "R07_zenki_35", "source": "R7前 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクトの断面を拡大する場合の角度は、30 度以下とする。"}, {"label": "2", "text": "亜鉛鉄板製長方形ダクトの板厚は、ダクトの長辺の寸法により決定する。"}, {"label": "3", "text": "浴室等の多湿箇所に使用する排気ダクトは、継手と継目にシールを行う。"}, {"label": "4", "text": "外壁に取付ける換気用の外気取入口と排気口は、互いに短絡しない位置に配置する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクトの断面を拡大する場合の角度は、30 度以下とする。"], "answerHints": [["30 度以下"]], "mnemonic": "正しくは：ダクト断面の拡大は15度以下、縮小は30度以下。", "block": 16, "group": 6}, {"id": "R07_zenki_38", "source": "R7前 No.38", "category": "施工管理法", "type": "single", "question": "異種管の接合において、電気的に絶縁する必要がある配管材の組合せとして、適当なもの はどれか。", "choices": [{"label": "1", "text": "鋼管とビニル管"}, {"label": "2", "text": "銅管とビニル管"}, {"label": "3", "text": "鋼管とステンレス鋼管"}, {"label": "4", "text": "ステンレス鋼管と銅管"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["鋼管とステンレス鋼管"], "answerHints": [["鋼管とステンレス鋼管"]], "mnemonic": "鋼管×ステンレス鋼管・鋼管×銅管は異種金属接触腐食を防ぐため絶縁接合。ビニル管との接合やステンレス×銅は不要。", "block": 16, "group": 6}, {"id": "R07_kouki_32", "source": "R6後 No.32 / R7後 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "建設工事の死亡災害は、墜落・転落よりも飛来・落下による事故が多い。"}, {"label": "2", "text": "労働災害の発生原因には、人的原因である不安全な行動と、物的要因である不安全な状態が ある。"}, {"label": "3", "text": "建設工事に伴う災害には、被害が工事関係者に限定される労働災害と、被害が工事関係者以外 の第三者に及ぶ公衆災害とがある。"}, {"label": "4", "text": "重大災害とは、一時に3人以上の労働者が、業務上死傷又は罹病した災害をいう。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["建設工事の死亡災害は、墜落・転落よりも飛来・落下による事故が多い。"], "answerHints": [["よりも飛来・落下"]], "mnemonic": "正しくは：建設工事の死亡災害は墜落・転落によるものが最も多い。", "block": 16, "group": 6}, {"id": "R07_kouki_35", "source": "R7後 No.35", "category": "施工管理法", "type": "single", "question": "ダクトの施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "コーナーボルト工法ダクトは、アングルフランジ工法ダクトとダクトの寸法が同一の場合、薄 い板厚としてよい。"}, {"label": "2", "text": "亜鉛鉄板製のスパイラルダクトは、一般的に、補強は不要である。"}, {"label": "3", "text": "厨房の排気に長方形ダクトを使用する場合、ダクトの角の継目が下面とならないように取り 付ける。"}, {"label": "4", "text": "ダクトに設けるリブ補強は、ダクトの変形や騒音及び振動の発生を防止するために設ける。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["コーナーボルト工法ダクトは、アングルフランジ工法ダクトとダクトの寸法が同一の場合、薄 い板厚としてよい。"], "answerHints": [["薄 い板厚としてよい"]], "mnemonic": "正しくは：コーナーボルト工法ダクトの板厚は、同寸法のアングルフランジ工法ダクトと同じとする。", "block": 16, "group": 6}, {"id": "R07_kouki_38", "source": "R7後 No.38", "category": "施工管理法", "type": "single", "question": "異種管の接合に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配管用炭素鋼鋼管と銅管の接合は、絶縁フランジ接合等とする。"}, {"label": "2", "text": "配管用炭素鋼鋼管と硬質塩化ビニル管の接合は、バルブ用ソケット等を用いて接合する。"}, {"label": "3", "text": "ステンレス鋼管と銅管の接合は、フレア接合等とする。"}, {"label": "4", "text": "ステンレス鋼管と配管用炭素鋼鋼管の接合は、絶縁フランジ接合等とする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ステンレス鋼管と銅管の接合は、フレア接合等とする。"], "answerHints": [["フレア接合"]], "mnemonic": "正しくは：フレア接合は主に銅管（冷媒管）どうしの接合。ステンレス鋼管と銅管は電位差が小さく絶縁不要で、ろう付け等で接合する。（要確認）", "block": 16, "group": 6}, {"id": "R08_zenki_32", "source": "R8前 No.32", "category": "施工管理法", "type": "single", "question": "建設工事における安全管理に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "折りたたみ式の脚立は、脚と水平面との角度を確実に保つための金具等を備えたものとする。"}, {"label": "2", "text": "移動式クレーンに係る作業の実施について、強風のため危険が予想されるときは、当該作 業を中止する。"}, {"label": "3", "text": "建設業における労働災害は、長期的には減少傾向にあるものの、死亡者数の割合は全産業 の約3 割を占める。"}, {"label": "4", "text": "脚立の脚と水平面との角度は、80 度以下とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["脚立の脚と水平面との角度は、80 度以下とする。"], "answerHints": [["80 度以下"]], "mnemonic": "正しくは：脚立の脚と水平面との角度は75度以下。", "block": 16, "group": 6}, {"id": "R08_zenki_35", "source": "R8前 No.35", "category": "施工管理法", "type": "single", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクトの断面を変形させ縮小するときの傾斜角度は、30 度以下とする。"}, {"label": "2", "text": "外気取り入れチャンバーに設置する点検口は、外開きとする。"}, {"label": "3", "text": "フレキシブルダクトは、振動伝播防止のために使用する。"}, {"label": "4", "text": "厨房の排気ダクトには、ダクト内の点検ができるように点検口等を設ける。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["フレキシブルダクトは、振動伝播防止のために使用する。"], "answerHints": [["振動伝播防止"]], "mnemonic": "正しくは：フレキシブルダクトは吹出口等との接続の位置合わせ用。振動伝播防止はたわみ継手。", "block": 16, "group": 6}, {"id": "R08_zenki_38", "source": "R8前 No.38", "category": "施工管理法", "type": "single", "question": "風量調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ダクト内の風量測定は、一般的に、多点風速測定法で行う。"}, {"label": "2", "text": "ダクト系の風量調整は、吹出口・吸込口のシャッター、分岐部等の風量調整ダンパーを全 閉にしてから行う。"}, {"label": "3", "text": "シーリングディフューザーは、吹出気流の拡散が大きいため、一般的に、フード付の風量計 を用いて測定する。"}, {"label": "4", "text": "風量測定に使用する風速計は、熱線風速計、ピトー管等を用いる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ダクト系の風量調整は、吹出口・吸込口のシャッター、分岐部等の風量調整ダンパーを全 閉にしてから行う。"], "answerHints": [["全 閉にしてから"]], "mnemonic": "正しくは：風量調整は、シャッター・風量調整ダンパーを全開にしてから行う。", "block": 16, "group": 6}, {"id": "R07_zenki_51", "source": "R7前 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管の施工に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "給水管と排水管が平行して埋設される場合は、原則として、両配管の水平間隔は500 mm 以 上とする。"}, {"label": "2", "text": "臭気を防止するためには、器具トラップの他に、排水管にも配管トラップを設ける。"}, {"label": "3", "text": "配管の曲がり部、立上がり、立下がり、分岐部などの近傍で支持は行わない。"}, {"label": "4", "text": "ビニル管の接着(TS)接合は、接着剤により、受口と差口を一体化させる工法である。"}], "answer": ["2", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["臭気を防止するためには、器具トラップの他に、排水管にも配管トラップを設ける。", "配管の曲がり部、立上がり、立下がり、分岐部などの近傍で支持は行わない。"], "answerHints": [["配管トラップを設ける"], ["近傍で支持は行わない"]], "mnemonic": "正しくは：二重トラップは禁止（器具トラップがあれば配管トラップは設けない）。曲がり部・分岐部などの近傍で支持する。", "block": 16, "group": 6}, {"id": "R07_kouki_50", "source": "R7後 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "建物内に設置する飲料用受水タンク上部と天井との距離は、600 mm 以上とする。"}, {"label": "2", "text": "防振基礎には、地震時の機器の移動や転倒防止のため、一般的に、耐震ストッパーを設ける。"}, {"label": "3", "text": "小形軽量機器の基礎は、一般的に、躯体の床表面に目荒しを行い、水打ちのうえコンクリー トを打設する。"}, {"label": "4", "text": "高置タンクの架台の昇降タラップは、高さが1.8 m を超える場合に転落防止防護柵が必要と なる。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["建物内に設置する飲料用受水タンク上部と天井との距離は、600 mm 以上とする。", "高置タンクの架台の昇降タラップは、高さが1.8 m を超える場合に転落防止防護柵が必要と なる。"], "answerHints": [["600 mm 以上"], ["1.8 m を超える場合に"]], "mnemonic": "正しくは：受水タンク上部と天井の距離は1m以上。高置タンクの昇降タラップには高さにかかわらず転落防止防護柵を設ける。", "block": 16, "group": 6}, {"id": "R08_zenki_49", "source": "R8前 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程表に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "工程表作成時に考慮すべき事項としては、土日祝祭日の作業制限、試運転調整の期間等が ある。"}, {"label": "2", "text": "バーチャート工程表は、ネットワーク工程表に比べて各作業の順序関係が明確である。"}, {"label": "3", "text": "ネットワーク工程表は、工事途中での計画変更に対処しやすい。"}, {"label": "4", "text": "ガントチャート工程表は、全体進行度の把握に適している。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表は、ネットワーク工程表に比べて各作業の順序関係が明確である。", "ガントチャート工程表は、全体進行度の把握に適している。"], "answerHints": [["順序関係が明確"], ["全体進行度の把握に適している"]], "mnemonic": "正しくは：作業の順序関係が明確なのはネットワーク工程表。ガントチャートは各作業の進捗はわかるが全体進行度はつかみにくい。", "block": 16, "group": 6}, {"id": "R08_zenki_52", "source": "R8前 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "共板フランジ工法ダクトの接続は、フランジ押さえ金具のみで行い、ボルト・ナットを使用 しない。"}, {"label": "2", "text": "長方形ダクトの断面のアスペクト比(長辺と短辺の比)は、原則として、4 以下とする。"}, {"label": "3", "text": "長方形ダクトの板厚は、ダクトの周長により決定する。"}, {"label": "4", "text": "隠ぺい部に防火ダンパーを設置する場合には、450 mm × 450 mm 以上の点検口を設ける。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["共板フランジ工法ダクトの接続は、フランジ押さえ金具のみで行い、ボルト・ナットを使用 しない。", "長方形ダクトの板厚は、ダクトの周長により決定する。"], "answerHints": [["ボルト・ナットを使用 しない"], ["周長"]], "mnemonic": "正しくは：共板フランジは押さえ金具に加え四隅をボルト・ナットで締める。長方形ダクトの板厚は長辺の長さで決める。", "block": 16, "group": 6}, {"id": "R07_zenki_41", "source": "R7前 No.41", "category": "法規", "type": "single", "question": "建築物の用語に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "熱源機器の過半を更新する工事は、大規模の修繕である。"}, {"label": "2", "text": "基礎は、構造耐力上主要な部分である。"}, {"label": "3", "text": "建築物に設ける昇降機は、建築設備である。"}, {"label": "4", "text": "主要構造部が耐火構造である建築物は、耐火建築物である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["熱源機器の過半を更新する工事は、大規模の修繕である。"], "answerHints": [["熱源機器の過半"]], "mnemonic": "正しくは：大規模の修繕は主要構造部の一種以上の過半の修繕。熱源機器（建築設備）の更新は該当しない。", "block": 16, "group": 6}, {"id": "R07_zenki_44", "source": "R7前 No.44", "category": "法規", "type": "single", "question": "建設業に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "注文者は、自己の取引上の地位を不当に利用して、その注文した建設工事を施工するために 通常必要と認められる原価に満たない金額を請負代金の額とする請負契約を締結してはなら ない。"}, {"label": "2", "text": "建設業者は、共同住宅を新築する建設工事を請け負った場合、発注者から書面による承諾 を得れば、一括して他人に請け負わせることができる。"}, {"label": "3", "text": "請負人は、現場代理人を置く場合においては、当該現場代理人の権限に関する事項等を、書面 により注文者に通知しなければならない。"}, {"label": "4", "text": "建設工事の請負契約の当事者は、契約の締結に際して、工事内容、請負代金の額、工事着手 の時期及び工事完成の時期等を書面に記載し、相互に交付しなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設業者は、共同住宅を新築する建設工事を請け負った場合、発注者から書面による承諾 を得れば、一括して他人に請け負わせることができる。"], "answerHints": [["書面による承諾 を得れば"]], "mnemonic": "正しくは：共同住宅の新築工事は、発注者の書面承諾があっても一括下請負は禁止。", "block": 16, "group": 6}, {"id": "R07_zenki_47", "source": "R7前 No.47", "category": "法規", "type": "single", "question": "「騒音規制法」上、特定建設作業に伴って発生する騒音を規制する指定地域内において、 災害その他非常の事態の発生により当該特定建設作業を緊急に行う必要がある場合に あっても、当該騒音について規制が適用されるものはどれか。", "choices": [{"label": "1", "text": "深夜に行われる作業に伴って発生する騒音"}, {"label": "2", "text": "作業場所の敷地の境界線において、85 dB を超える大きさの騒音"}, {"label": "3", "text": "日曜日に行われる作業に伴って発生する騒音"}, {"label": "4", "text": "1日14 時間を超えて行われる作業に伴って発生する騒音"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適用されるもの"], "answerTexts": ["作業場所の敷地の境界線において、85 dB を超える大きさの騒音"], "answerHints": [["85 dB"]], "mnemonic": "緊急時でも敷地境界85dB超の規制は適用。深夜・日曜・1日の作業時間の規制は適用除外。", "block": 16, "group": 6}, {"id": "R07_kouki_40", "source": "R7後 No.40", "category": "法規", "type": "single", "question": "労働に関する記述のうち、「労働基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "労働条件は、労働者と使用者が、対等の立場において決定すべきものである。"}, {"label": "2", "text": "労働契約の締結の際に使用者から明示された労働条件が事実と相違する場合においては、労 働者は、即時に労働契約を解除することができる。"}, {"label": "3", "text": "未成年者の親権者又は後見人は、未成年者の賃金を代って受け取ってはならない。"}, {"label": "4", "text": "出来高払制その他の請負制で使用する労働者については、使用者は、労働時間に応じ一定額 の賃金の保障をする必要はない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["出来高払制その他の請負制で使用する労働者については、使用者は、労働時間に応じ一定額 の賃金の保障をする必要はない。"], "answerHints": [["保障をする必要はない"]], "mnemonic": "正しくは：出来高払制等の労働者には、労働時間に応じ一定額の賃金の保障をしなければならない。", "block": 16, "group": 6}, {"id": "R07_kouki_43", "source": "R7後 No.43", "category": "法規", "type": "single", "question": "建設業の許可に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "都道府県知事の許可を受けた建設業者と国土交通大臣の許可を受けた建設業者で、建設工事 を請け負うことができる工事現場の所在地について、都道府県の範囲に関する違いはない。"}, {"label": "2", "text": "都道府県知事の許可を受けた建設業者が営業所を設けることができるのは、許可を受けた都 道府県の区域内に限られる。"}, {"label": "3", "text": "建設業の許可を受けた建設業者が建設工事の一部を下請負人として請け負うとき、その下請 契約の請負代金が一定額以下の場合は、主任技術者を置く必要はない。"}, {"label": "4", "text": "一般建設業の許可を受けた建設業者が発注者から直接請け負う建設工事について、当該工 事を施工するために締結する下請契約の請負代金の額の総額に上限はあるが、発注者との請 負契約の請負金額の額に上限はない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設業の許可を受けた建設業者が建設工事の一部を下請負人として請け負うとき、その下請 契約の請負代金が一定額以下の場合は、主任技術者を置く必要はない。"], "answerHints": [["主任技術者を置く必要はない"]], "mnemonic": "正しくは：許可業者は、下請であっても請負金額にかかわらず主任技術者を置く。", "block": 16, "group": 6}, {"id": "R07_kouki_46", "source": "R7後 No.46", "category": "法規", "type": "single", "question": "建築物に係る建設工事のうち、「建設工事に係る資材の再資源化等に関する法律」上、特 定建設資材廃棄物をその種類ごとに分別しつつ施工しなければならない工事に 該当しないものはどれか。 ただし、都道府県が条例で、適用すべき建設工事の規模に関する基準を定めた区域を除 く。", "choices": [{"label": "1", "text": "新築工事で床面積の合計が500 m2 であるもの"}, {"label": "2", "text": "模様替工事で請負代金の額が1億円であるもの"}, {"label": "3", "text": "耐震改修工事で請負代金の額が1億円であるもの"}, {"label": "4", "text": "解体工事で解体部分の床面積の合計が40 m2 であるもの"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["解体工事で解体部分の床面積の合計が40 m2 であるもの"], "answerHints": [["40 m2"]], "mnemonic": "分別解体の対象：解体80m²以上、新築・増築500m²以上、修繕・模様替等1億円以上。", "block": 16, "group": 6}, {"id": "R08_zenki_39", "source": "R8前 No.39", "category": "法規", "type": "single", "question": "建設工事現場における作業のうち、「労働安全衛生法」上、作業主任者を選任すべき作 業に該当しないものはどれか。", "choices": [{"label": "1", "text": "ボイラー(小型ボイラーを除く。)の取扱いの作業"}, {"label": "2", "text": "掘削面の高さが1 m の地山の掘削(ずい道及びたて坑以外の坑の掘削を除く。)作業"}, {"label": "3", "text": "土止め支保工の切りばり又は腹起こしの取付け又は取り外しの作業"}, {"label": "4", "text": "石綿が 0.5 %含まれる保温材の除去作業"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["掘削面の高さが1 m の地山の掘削(ずい道及びたて坑以外の坑の掘削を除く。)作業"], "answerHints": [["1 m"]], "mnemonic": "地山の掘削作業主任者は掘削面の高さ2m以上で選任。", "block": 16, "group": 6}, {"id": "R08_zenki_42", "source": "R8前 No.42", "category": "法規", "type": "single", "question": "次のうち、「建築基準法」上、建築物に設ける中央管理方式の空気調和設備の性能と して、居室における基準が、定められていないものはどれか。", "choices": [{"label": "1", "text": "絶対湿度"}, {"label": "2", "text": "一酸化炭素の含有率"}, {"label": "3", "text": "浮遊粉じんの量"}, {"label": "4", "text": "気流"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["絶対湿度"], "answerHints": [["絶対湿度"]], "mnemonic": "中央管理方式の空調の基準は浮遊粉じん・CO・CO2・温度・相対湿度・気流。絶対湿度は定めなし。", "block": 16, "group": 6}, {"id": "R08_zenki_45", "source": "R8前 No.45", "category": "法規", "type": "single", "question": "屋内消火栓設備に関する文中、 内に当てはまる数値として、「消防法」 上、正しいものはどれか。 易操作性1 号消火栓の消防用ホースの長さは、当該易操作性1 号消火栓のホース接続 口からの水平距離が m の範囲内の当該階の各部分に有効に放水することがで きる長さとする。", "choices": [{"label": "1", "text": "15"}, {"label": "2", "text": "20"}, {"label": "3", "text": "25"}, {"label": "4", "text": "30"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["25"], "answerHints": [["25"]], "mnemonic": "易操作性1号消火栓（1号と同じ）は水平距離25m。2号（広範囲型除く）は15m。", "block": 16, "group": 6}, {"id": "R08_zenki_48", "source": "R8前 No.48", "category": "法規", "type": "single", "question": "廃棄物に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、 誤っているものはどれか。", "choices": [{"label": "1", "text": "建設工事の現場事務所から排出される生ごみ、新聞、雑誌等は、一般廃棄物である。"}, {"label": "2", "text": "事業活動に伴って生じた廃棄物で、金属くずは、産業廃棄物である。"}, {"label": "3", "text": "事業者は、産業廃棄物管理票を、産業廃棄物の種類ごとにせず、一括して交付することが できる。"}, {"label": "4", "text": "産業廃棄物管理票の交付者は、処分受諾者から、最終処分が終了した旨等を記載した産 業廃棄物管理票の写しの送付を受けたときは、当該管理票の写しを、当該送付を受けた日 から5 年間保存しなければならない。 せん。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、産業廃棄物管理票を、産業廃棄物の種類ごとにせず、一括して交付することが できる。"], "answerHints": [["種類ごとにせず、一括して"]], "mnemonic": "正しくは：産業廃棄物管理票（マニフェスト）は産業廃棄物の種類ごとに交付する。", "block": 16, "group": 6}, {"id": "R07_zenki_03", "source": "R7前 No.3", "category": "一般基礎", "type": "single", "question": "圧力3.0 ×105 Pa、体積4.0 Lの理想気体を、温度一定で圧力6.0 ×105 Pa にしたとき の体積の値として、適当なものはどれか。", "choices": [{"label": "1", "text": "1.0 L"}, {"label": "2", "text": "2.0 L"}, {"label": "3", "text": "4.0 L"}, {"label": "4", "text": "8.0 L"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["2.0 L"], "answerHints": [["2.0 L"]], "mnemonic": "ボイルの法則：温度一定ならPV一定。圧力2倍で体積1/2（4.0L→2.0L）。", "block": 17, "group": 6}, {"id": "R07_zenki_06", "source": "R7前 No.6", "category": "一般基礎", "type": "single", "question": "鉄筋コンクリート造に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "鉄筋の曲げ加工は、鋼材の品質が劣化しないよう常温で行う。"}, {"label": "2", "text": "コンクリートは、引張強度が圧縮強度より大きい。"}, {"label": "3", "text": "あばら筋は、梁のせん断力に対する補強筋である。"}, {"label": "4", "text": "帯筋は、柱のせん断力に対する補強筋である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["コンクリートは、引張強度が圧縮強度より大きい。"], "answerHints": [["引張強度が圧縮強度より大きい"]], "mnemonic": "正しくは：コンクリートは圧縮強度が引張強度より大きい（引張は圧縮の約1/10）。", "block": 17, "group": 6}, {"id": "R07_kouki_04", "source": "R7後 No.4", "category": "一般基礎", "type": "single", "question": "空気環境に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ホルムアルデヒドは、常温において無臭の気体である。"}, {"label": "2", "text": "室内で二酸化炭素が発生する要因の一つに、在室者の呼吸がある。"}, {"label": "3", "text": "臭気は、空気汚染を示す指標の一つであり、臭気強度や臭気指数等で表す。"}, {"label": "4", "text": "PM 2.5 は、大気中に浮遊する微小粒子状物質である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ホルムアルデヒドは、常温において無臭の気体である。"], "answerHints": [["無臭"]], "mnemonic": "正しくは：ホルムアルデヒドは常温で刺激臭のある気体。", "block": 17, "group": 6}, {"id": "R08_zenki_01", "source": "R8前 No.1", "category": "一般基礎", "type": "single", "question": "光化学スモッグの発生要因となるものとして、適当なものはどれか。", "choices": [{"label": "1", "text": "一酸化炭素"}, {"label": "2", "text": "二酸化炭素"}, {"label": "3", "text": "窒素酸化物"}, {"label": "4", "text": "水蒸気"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["窒素酸化物"], "answerHints": [["窒素酸化物"]], "mnemonic": "光化学スモッグは窒素酸化物（NOx）や炭化水素が紫外線で反応して生じる。", "block": 17, "group": 6}, {"id": "R08_zenki_04", "source": "R8前 No.4", "category": "一般基礎", "type": "single", "question": "次のうち、室内環境に関係のないものはどれか。", "choices": [{"label": "1", "text": "予想平均申告(PMV)"}, {"label": "2", "text": "化学的酸素要求量(COD)"}, {"label": "3", "text": "不快指数"}, {"label": "4", "text": "ホルムアルデヒドの量"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["化学的酸素要求量(COD)"], "answerHints": [["化学的酸素要求量(COD)"]], "mnemonic": "CODは水質（水の汚れ）の指標。PMV・不快指数・ホルムアルデヒドは室内環境の指標。", "block": 17, "group": 6}, {"id": "R07_zenki_07", "source": "R7前 No.7", "category": "空調・衛生", "type": "single", "question": "定風量単一ダクト方式に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "空気調和機は、一般的に、専用の機械室に設置されているため、維持管理がしやすい。"}, {"label": "2", "text": "送風量は変化させず、吹出し空気の温度・湿度を調節するものである。"}, {"label": "3", "text": "ファンコイル・ダクト併用方式に比べ、送風量が多いため室内の清浄度を保ちやすい。"}, {"label": "4", "text": "各室毎の温度制御が可能である。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["各室毎の温度制御が可能である。"], "answerHints": [["温度制御が可能"]], "mnemonic": "正しくは：定風量単一ダクト方式は全室同じ温度の空気を送るので、各室毎の温度制御は困難。", "block": 17, "group": 6}, {"id": "R07_zenki_11", "source": "R7前 No.11", "category": "空調・衛生", "type": "single", "question": "放射暖房に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "放射暖房は、天井、床、壁や室内パネルの表面を加熱し、主として赤外線による放射により 暖房するものである。"}, {"label": "2", "text": "天井の高いホール等の暖房に補助的に用いることで快適性が向上する。"}, {"label": "3", "text": "パイプ埋設式の場合は、配管に不具合が生じた際の修理が困難である。"}, {"label": "4", "text": "放射暖房は、室内における上下の温度差が大きくなる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["放射暖房は、室内における上下の温度差が大きくなる。"], "answerHints": [["大きくなる"]], "mnemonic": "正しくは：放射暖房は室内の上下の温度差が少ない。", "block": 17, "group": 6}, {"id": "R07_zenki_14", "source": "R7前 No.14", "category": "空調・衛生", "type": "single", "question": "換気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "居室の換気を行う場合は、外気の二酸化炭素濃度も考慮する。"}, {"label": "2", "text": "開放式燃焼器具を設けた室において、機械換気を行う場合、所定の排気フードを設けること により換気量を低減することができる。"}, {"label": "3", "text": "汚染度の高い室を換気する場合の室内圧は、周囲の室より高くなるようにする。"}, {"label": "4", "text": "第一種機械換気方式は、換気対象室の室内圧を正圧・負圧のいずれにも調整することができ る。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["汚染度の高い室を換気する場合の室内圧は、周囲の室より高くなるようにする。"], "answerHints": [["周囲の室より高くなる"]], "mnemonic": "正しくは：汚染度の高い室は周囲の室より室内圧を低く（負圧）して汚染を漏らさない。", "block": 17, "group": 6}, {"id": "R07_zenki_17", "source": "R7前 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飲料用受水タンクのオーバーフロー管は、トラップを設け、虫の侵入を防止する。"}, {"label": "2", "text": "ホースを接続して使用する水栓は、バキュームブレーカー付きとする。"}, {"label": "3", "text": "水道直結増圧方式の場合、節水型衛生器具を導入すると、ポンプ動力の削減が図れる。"}, {"label": "4", "text": "「建築物における衛生的環境の確保に関する法律」に基づく特定建築物において、雑用水槽 は法令上の点検が義務付けられている。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["飲料用受水タンクのオーバーフロー管は、トラップを設け、虫の侵入を防止する。"], "answerHints": [["トラップを設け"]], "mnemonic": "正しくは：受水タンクのオーバーフロー管はトラップを設けず、管端に防虫網を設けて間接排水とする。", "block": 17, "group": 6}, {"id": "R07_zenki_20", "source": "R7前 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水横主管の管径は、これに接続する排水立て管の管径以上とする。"}, {"label": "2", "text": "排水横主管及び排水横枝管の起点部には、掃除口を設ける。"}, {"label": "3", "text": "ドラムトラップは、サイホン式トラップの一種である。"}, {"label": "4", "text": "トラップの封水は、誘導サイホン作用、自己サイホン作用、蒸発、毛管現象等により損失す る。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ドラムトラップは、サイホン式トラップの一種である。"], "answerHints": [["サイホン式トラップの一種"]], "mnemonic": "正しくは：ドラムトラップは非サイホン式トラップ。", "block": 17, "group": 6}, {"id": "R07_zenki_23", "source": "R7前 No.23", "category": "空調・衛生", "type": "single", "question": "FRP 製浄化槽に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "浄化槽本体の埋め戻しは、槽に水を張らない状態で行う。"}, {"label": "2", "text": "槽は、満水状態にして24 時間以上漏水のないことを確認する。"}, {"label": "3", "text": "工場で製造する者は、原則として、浄化槽の型式について国土交通大臣の認定を受けなけれ ばならない。"}, {"label": "4", "text": "ブロワーは、隣家や寝室等から離れた場所に設置する。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["浄化槽本体の埋め戻しは、槽に水を張らない状態で行う。"], "answerHints": [["水を張らない状態"]], "mnemonic": "正しくは：FRP製浄化槽の埋め戻しは、槽に水を張った状態で行う（浮上・変形防止）。", "block": 17, "group": 6}, {"id": "R07_kouki_10", "source": "R7後 No.10", "category": "空調・衛生", "type": "single", "question": "自動制御に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水ポンプは、排水槽の減水時に空転防止を行う。"}, {"label": "2", "text": "排水槽は、満水時に警報の発報を行う。"}, {"label": "3", "text": "揚水ポンプは、受水タンクの減水時に空転防止を行う。"}, {"label": "4", "text": "揚水ポンプは、受水タンクの電極棒からの発停信号を受けて自動運転を行う。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["揚水ポンプは、受水タンクの電極棒からの発停信号を受けて自動運転を行う。"], "answerHints": [["受水タンクの電極棒"]], "mnemonic": "正しくは：揚水ポンプは高置タンクの電極棒からの発停信号で自動運転する（受水タンク減水時は空転防止）。", "block": 17, "group": 6}, {"id": "R07_kouki_13", "source": "R7後 No.13", "category": "空調・衛生", "type": "single", "question": "換気に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "便所の換気は、居室の換気と同一系統にまとめる。"}, {"label": "2", "text": "機械換気は、送風機や排風機を利用して、室内空気と外気の入替えを行うものである。"}, {"label": "3", "text": "吸収冷温水機室の換気は、第一種機械換気方式とする。"}, {"label": "4", "text": "自然換気は、風力及び温度差による浮力によって、室内空気と外気の入替えを行うものであ る。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["便所の換気は、居室の換気と同一系統にまとめる。"], "answerHints": [["同一系統にまとめる"]], "mnemonic": "正しくは：便所の換気は居室とは別系統とする（臭気の逆流防止）。", "block": 17, "group": 6}, {"id": "R07_kouki_16", "source": "R7後 No.16", "category": "空調・衛生", "type": "single", "question": "下水道に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水管の管内流速は、原則として、0.6〜1.5 m/s の範囲とする。"}, {"label": "2", "text": "管きょのますは、管きょの長さが、ますの内径又は内のり幅の120 倍を超えない範囲内に設け る。"}, {"label": "3", "text": "宅地ますは、内径又は内のり幅が15 cm 以上の円形又は角形とする。"}, {"label": "4", "text": "下水道本管に接続する取付管の最小管径は、65 mm を標準とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["下水道本管に接続する取付管の最小管径は、65 mm を標準とする。"], "answerHints": [["65 mm"]], "mnemonic": "正しくは：取付管の最小管径は150mmを標準とする。", "block": 17, "group": 6}, {"id": "R07_kouki_19", "source": "R7後 No.19", "category": "空調・衛生", "type": "single", "question": "排水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "排水立て管の管径は、下階になるに従い、排水負荷に応じて大きくする。"}, {"label": "2", "text": "建物内で、汚水と雑排水を合流して流す方式を合流式という。"}, {"label": "3", "text": "飲料水、食物、食器等を使用又は取り扱う機器からの排水は、間接排水とする。"}, {"label": "4", "text": "大便器に接続する汚水管の最小管径は、75 mm とする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水立て管の管径は、下階になるに従い、排水負荷に応じて大きくする。"], "answerHints": [["下階になるに従い"]], "mnemonic": "正しくは：排水立て管は最下部の最大排水負荷で決めた管径で、上から下まで同一管径とする。", "block": 17, "group": 6}, {"id": "R07_kouki_22", "source": "R7後 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "液化石油ガスは、常温・常圧では気体であるものに加圧等を行い、液化させたものである。"}, {"label": "2", "text": "マイコンガスメーターは、供給圧力が0.2 kPa を下回っていることを継続して検知した場合 等に遮断する機能を持つ。"}, {"label": "3", "text": "液化石油ガスのバルク供給方式は、工場、集合住宅等に用いられ、一般住宅では使用で きない。"}, {"label": "4", "text": "充填量が10 kg 以上の液化石油ガスの容器は、鉄鎖等により建物その他の構築物に固定す る。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化石油ガスのバルク供給方式は、工場、集合住宅等に用いられ、一般住宅では使用で きない。"], "answerHints": [["一般住宅では使用で きない"]], "mnemonic": "正しくは：LPGのバルク供給方式は一般住宅でも使用できる。", "block": 17, "group": 6}, {"id": "R08_zenki_09", "source": "R8前 No.9", "category": "空調・衛生", "type": "single", "question": "冷房時の熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "外壁からの熱負荷は、太陽日射の影響も考慮する。"}, {"label": "2", "text": "OA 機器による熱負荷は、顕熱である。"}, {"label": "3", "text": "構造体の空気層は、熱通過率に影響を与えない。"}, {"label": "4", "text": "窓ガラス面からの熱負荷は、ブラインドの有無を考慮する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["構造体の空気層は、熱通過率に影響を与えない。"], "answerHints": [["影響を与えない"]], "mnemonic": "正しくは：構造体の空気層は熱抵抗となり、熱通過率に影響を与える。", "block": 17, "group": 6}, {"id": "R08_zenki_12", "source": "R8前 No.12", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ガスエンジンヒートポンプ式は、一般的に、暖房時にガスエンジンの排気ガスや冷却水の排 熱を有効利用している。"}, {"label": "2", "text": "マルチパッケージ形は、1 台の屋外機で複数台の屋内機を接続することができる。"}, {"label": "3", "text": "ガスエンジンヒートポンプ式は、ガスエンジンで発電した電力を利用して圧縮機用電動機を 駆動する。"}, {"label": "4", "text": "圧縮機用電動機の回転数制御は、一般的に、インバーター方式が用いられている。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ガスエンジンヒートポンプ式は、ガスエンジンで発電した電力を利用して圧縮機用電動機を 駆動する。"], "answerHints": [["発電した電力を利用して"]], "mnemonic": "正しくは：ガスエンジンヒートポンプは、ガスエンジンで圧縮機を直接駆動する。", "block": 17, "group": 6}, {"id": "R08_zenki_15", "source": "R8前 No.15", "category": "空調・衛生", "type": "single", "question": "水道水の水質基準に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "pH 値は、5.8 以上 8.6 以下とされている。"}, {"label": "2", "text": "大腸菌は、1 mL の検水で形成される集落数が 100 以下であることとされている。"}, {"label": "3", "text": "臭気は、異常でないこととされている。"}, {"label": "4", "text": "色度は、5 度以下であることとされている。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["大腸菌は、1 mL の検水で形成される集落数が 100 以下であることとされている。"], "answerHints": [["100 以下"]], "mnemonic": "正しくは：大腸菌は「検出されないこと」。1mLで集落数100以下は一般細菌の基準。", "block": 17, "group": 6}, {"id": "R08_zenki_18", "source": "R8前 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "中央給湯方式の配管方式は、上向き供給方式と下向き供給方式がある。"}, {"label": "2", "text": "ヒートポンプ給湯機は、給湯機の排気ガスの潜熱を給湯の予熱として利用するものである。"}, {"label": "3", "text": "中央給湯方式の給湯配管の直管部には、湯温の変化による伸縮を吸収するため、伸縮 継手等を設ける。"}, {"label": "4", "text": "中央給湯方式の給湯用循環ポンプは、一般的に、貯湯タンクへの返湯管に設ける。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ヒートポンプ給湯機は、給湯機の排気ガスの潜熱を給湯の予熱として利用するものである。"], "answerHints": [["排気ガスの潜熱"]], "mnemonic": "正しくは：ヒートポンプ給湯機は大気中の熱を利用する。排気ガスの潜熱を予熱に使うのは潜熱回収型給湯器。", "block": 17, "group": 6}, {"id": "R08_zenki_21", "source": "R8前 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋内消火栓箱の位置表示灯は、赤色でなくてもよい。"}, {"label": "2", "text": "屋内消火栓設備の非常電源は、蓄電池設備でもよい。"}, {"label": "3", "text": "屋内消火栓の開閉弁の位置は、自動式のものでない場合、床面からの高さを 1.5 m 以下とす る。"}, {"label": "4", "text": "加圧送水装置は、直接操作によってのみ停止できるものとする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["屋内消火栓箱の位置表示灯は、赤色でなくてもよい。"], "answerHints": [["赤色でなくてもよい"]], "mnemonic": "正しくは：屋内消火栓箱の位置表示灯は赤色の灯火とする。", "block": 17, "group": 6}, {"id": "R07_zenki_24", "source": "R7前 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "送風機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "遠心送風機には、多翼送風機、後向き羽根送風機等がある。"}, {"label": "2", "text": "遠心送風機は、片吸込形と両吸込形がある。"}, {"label": "3", "text": "軸流送風機は、低圧力・小風量を扱うのに適している。"}, {"label": "4", "text": "消音ボックス付送風機は、消音ボックスに、小型の遠心送風機又は斜流送風機が内蔵された ものである。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["軸流送風機は、低圧力・小風量を扱うのに適している。"], "answerHints": [["小風量"]], "mnemonic": "正しくは：軸流送風機は低圧力・大風量に適している。", "block": 17, "group": 6}, {"id": "R07_zenki_27", "source": "R7前 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "シーリングディフューザー形吹出口は、ふく流吹出口の一種である。"}, {"label": "2", "text": "スパイラルダクトは、甲はぜが補強の役目をしている。"}, {"label": "3", "text": "コーナーボルト工法には、共板フランジ工法とスライドオンフランジ工法がある。"}, {"label": "4", "text": "防火ダンパーのケーシング及び可動羽根は、厚さ1.2 mm 以上の鋼板製とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火ダンパーのケーシング及び可動羽根は、厚さ1.2 mm 以上の鋼板製とする。"], "answerHints": [["1.2 mm"]], "mnemonic": "正しくは：防火ダンパーのケーシング・羽根は厚さ1.5mm以上の鋼板製。", "block": 17, "group": 6}, {"id": "R07_kouki_26", "source": "R7後 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "玉形弁は、仕切弁に比べ、全開時の圧力損失が小さい。"}, {"label": "2", "text": "水道用硬質ポリ塩化ビニル管の種類には、VP とHIVP がある。"}, {"label": "3", "text": "フレキシブルジョイントは、屋外埋設配管の建物導入部における変位吸収配管としても使 用される。"}, {"label": "4", "text": "排水用リサイクル硬質ポリ塩化ビニル管(REP―VU)は、使用済みの塩化ビニル管や塩化ビ ニル管継手をマテリアルリサイクルしたものである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["玉形弁は、仕切弁に比べ、全開時の圧力損失が小さい。"], "answerHints": [["圧力損失が小さい"]], "mnemonic": "正しくは：玉形弁は流れが曲がるため、仕切弁より全開時の圧力損失が大きい。", "block": 17, "group": 6}, {"id": "R08_zenki_25", "source": "R8前 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "遠心ポンプに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ポンプの吐出し側の調整弁を絞ると抵抗が増加し、吐出し量は減少する。"}, {"label": "2", "text": "揚程は、ポンプの回転速度の2乗に比例して変化する。"}, {"label": "3", "text": "ポンプ特性が同一のポンプを並列運転した場合、揚程は2 倍になる。"}, {"label": "4", "text": "軸動力は、ポンプの回転速度の3乗に比例して変化する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ポンプ特性が同一のポンプを並列運転した場合、揚程は2 倍になる。"], "answerHints": [["揚程は2 倍"]], "mnemonic": "正しくは：同一特性のポンプの並列運転は吐出し量が増える（揚程が増えるのは直列運転）。ただし2倍にはならない。", "block": 17, "group": 6}, {"id": "R07_zenki_29", "source": "R6前 No.29 / R7前 No.29", "category": "施工管理法", "type": "single", "question": "建設工事における施工計画等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "着工前の業務には、工事組織の編成、総合工程表の作成等がある。"}, {"label": "2", "text": "材料及び機器は、資材一覧表を作成し、発注、納期及び製品検査の日程を計画する。"}, {"label": "3", "text": "仮設に使用する機材は、新品でなくてもよい。"}, {"label": "4", "text": "工事に必要となる官公署への届出や申請は、工事完成時に提出できるように計画する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["工事に必要となる官公署への届出や申請は、工事完成時に提出できるように計画する。"], "answerHints": [["工事完成時"]], "mnemonic": "正しくは：官公署への届出・申請は、工事の工程に支障がないよう所定の時期（着工前等）に提出する。", "block": 17, "group": 6}, {"id": "R07_zenki_33", "source": "R7前 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "床置形のパッケージ形空気調和機は、一般的に、コンクリート基礎上に防振ゴムパットを敷 いて据え付ける。"}, {"label": "2", "text": "縦横比の大きい自立機器は、転倒防止金物等で機器頂部を構造躯体に支持する。"}, {"label": "3", "text": "ポンプを2台以上並列に設置する場合の基礎の間隔は、500 mm 以上とする。"}, {"label": "4", "text": "ボイラーは、コンクリート基礎上に防振架台を設置し据え付ける。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボイラーは、コンクリート基礎上に防振架台を設置し据え付ける。"], "answerHints": [["防振架台"]], "mnemonic": "正しくは：ボイラーは防振架台を用いず、コンクリート基礎上に直接据え付ける。", "block": 17, "group": 6}, {"id": "R07_zenki_36", "source": "R7前 No.36", "category": "施工管理法", "type": "single", "question": "保温及び塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ロックウール保温材は、グラスウール保温材に比べて、使用できる最高温度が高い。"}, {"label": "2", "text": "保温施工において、ポリエチレンフィルムは、保温材の脱落を防ぐために使用する。"}, {"label": "3", "text": "蒸気管や放熱器の塗装にはアルミニウムペイントを使用する。"}, {"label": "4", "text": "塗装は、原則として製造所において調合された塗料をそのまま使用する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["保温施工において、ポリエチレンフィルムは、保温材の脱落を防ぐために使用する。"], "answerHints": [["保温材の脱落を防ぐ"]], "mnemonic": "正しくは：ポリエチレンフィルムは防湿のために使用する。", "block": 17, "group": 6}, {"id": "R07_kouki_29", "source": "R6後 No.29 / R7後 No.29", "category": "施工管理法", "type": "single", "question": "公共工事における施工計画等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "施工計画書は実際の施工方法、使用する機材等を具体的に文書にしたもので、設計図書と異な る施工方法等で承諾された事項も記載する。"}, {"label": "2", "text": "標準仕様書と設計図面の内容に相違がある場合は、標準仕様書の内容を優先させる。"}, {"label": "3", "text": "仮設とは、現場事務所や現場内で作業に必要な足場、仮設水道、照明等を設置することであ る。"}, {"label": "4", "text": "設計図書及び工事関係図書は、監督員の承諾を受けた場合を除き、工事施工のために使用す る以外の目的で第三者に使用させない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["標準仕様書と設計図面の内容に相違がある場合は、標準仕様書の内容を優先させる。"], "answerHints": [["標準仕様書の内容を優先"]], "mnemonic": "正しくは：設計図面が標準仕様書より優先（質問回答書＞現場説明書＞特記仕様書＞図面＞標準仕様書）。", "block": 17, "group": 6}, {"id": "R07_kouki_33", "source": "R7後 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ユニット形空気調和機のコンクリート基礎の高さは、ドレン管の排水トラップの深さが確保 できるように、150 mm 程度とする。"}, {"label": "2", "text": "揚水ポンプの吐出し側には、ポンプに近い順に、防振継手、仕切弁、逆止弁を取り付ける。"}, {"label": "3", "text": "送風機は、レベルを水準器で確認し、水平が出ていない場合にはコンクリート基礎と共通架 台の間にライナーを入れて調整する。"}, {"label": "4", "text": "アンカーボルトは、機器の据付け後、ボルト頂部のねじ山がナットから3山程度出る長さと する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["揚水ポンプの吐出し側には、ポンプに近い順に、防振継手、仕切弁、逆止弁を取り付ける。"], "answerHints": [["仕切弁、逆止弁"]], "mnemonic": "正しくは：ポンプ吐出し側は、ポンプに近い順に防振継手→逆止弁→仕切弁。", "block": 17, "group": 6}, {"id": "R07_kouki_36", "source": "R7後 No.36", "category": "施工管理法", "type": "single", "question": "保温に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "防火区画を貫通する配管、ダクトの保温は、その貫通する部分をロックウール保温材で行う。"}, {"label": "2", "text": "保温の厚さは、保温材のみの厚さとし、補助材及び外装材の厚さは含まない。"}, {"label": "3", "text": "シートタイプの合成樹脂製カバーは、パンチ加工部をジョイナーに差込んで固定する。"}, {"label": "4", "text": "排水管の屋外露出部は、原則として、保温を行わない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["シートタイプの合成樹脂製カバーは、パンチ加工部をジョイナーに差込んで固定する。"], "answerHints": [["パンチ加工部をジョイナーに差込んで"]], "mnemonic": "正しくは：シートタイプの合成樹脂製カバーは、専用のピン等で固定する（パンチ加工部をジョイナーに差し込むのは別タイプ）。（要確認）", "block": 17, "group": 6}, {"id": "R08_zenki_29", "source": "R8前 No.29", "category": "施工管理法", "type": "single", "question": "建設工事における施工計画等に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "設計図書及び工事関係図書は、監督員の承諾を受けた場合を除き、工事の施工のために使用 する以外の目的で第三者に使用させない。"}, {"label": "2", "text": "工事写真は、後日の目視検査が容易でない箇所のほか、設計図書で定められている箇所につい ても撮影しなければならない。"}, {"label": "3", "text": "標準仕様書と特記仕様書の内容に相違がある場合、標準仕様書を優先させる。"}, {"label": "4", "text": "仮設計画は、設計図書に定めがない場合、受注者の責任において定める。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["標準仕様書と特記仕様書の内容に相違がある場合、標準仕様書を優先させる。"], "answerHints": [["標準仕様書を優先"]], "mnemonic": "正しくは：特記仕様書が標準仕様書より優先する。", "block": 17, "group": 6}, {"id": "R08_zenki_33", "source": "R8前 No.33", "category": "施工管理法", "type": "single", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "送風機やポンプの屋内コンクリート基礎をあと施工する場合、つなぎ鉄筋等で床スラブと一体 化する。"}, {"label": "2", "text": "送風機とモーターのプーリーの心出しは、プーリーの外側に定規、水糸等を当て調整する。"}, {"label": "3", "text": "ポンプとモーターの軸心の確認は、カップリングの外周に定規等を当てて行う。"}, {"label": "4", "text": "排水用水中モーターポンプの据付位置は、排水槽への排水の流入部に近い場所とする。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水用水中モーターポンプの据付位置は、排水槽への排水の流入部に近い場所とする。"], "answerHints": [["流入部に近い場所"]], "mnemonic": "正しくは：排水用水中ポンプは、流入部から離れた位置（吸込みピット）に据え付ける。", "block": 17, "group": 6}, {"id": "R08_zenki_36", "source": "R8前 No.36", "category": "施工管理法", "type": "single", "question": "塗装に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配管用炭素鋼鋼管(白)に塗装する場合、下塗り塗装は不要である。"}, {"label": "2", "text": "配管用炭素鋼鋼管(黒)は、下塗り塗料として、一般的に、さび止めペイントが使用される。"}, {"label": "3", "text": "塗装場所の相対湿度が 85 %以上の場合、原則として、塗装を行わない。"}, {"label": "4", "text": "塗装場所の気温が5 °C以下の場合、原則として、塗装を行わない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["配管用炭素鋼鋼管(白)に塗装する場合、下塗り塗装は不要である。"], "answerHints": [["下塗り塗装は不要"]], "mnemonic": "正しくは：白管（亜鉛めっき鋼管）に塗装する場合も、下塗り（プライマー）が必要。", "block": 17, "group": 6}, {"id": "R07_zenki_49", "source": "R7前 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程管理に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ガントチャート工程表は、作業間の関係性が分かりにくいが、各作業の現時点の進行状態 が分かりやすい。"}, {"label": "2", "text": "バーチャート工程表は、ネットワーク工程表に比べて、作業途中での計画変更に対応しや すい。"}, {"label": "3", "text": "タクト工程表は、同一作業が繰り返される工事に適している。"}, {"label": "4", "text": "バーチャート工程表に記載した予定進度曲線のことをバナナ曲線という。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["バーチャート工程表は、ネットワーク工程表に比べて、作業途中での計画変更に対応しや すい。", "バーチャート工程表に記載した予定進度曲線のことをバナナ曲線という。"], "answerHints": [["計画変更に対応しや すい"], ["予定進度曲線"]], "mnemonic": "正しくは：計画変更に対応しやすいのはネットワーク工程表。バナナ曲線は工程管理曲線の上方・下方許容限界曲線のこと。", "block": 17, "group": 6}, {"id": "R07_zenki_52", "source": "R7前 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "コーナーボルト工法の接合部には、フランジ用ガスケットを挿入しない。"}, {"label": "2", "text": "送風機とダクトを接続するたわみ継手の両端のフランジ間隔は、150 mm 以上とする。"}, {"label": "3", "text": "風量調整ダンパーを設ける場合は、原則として、気流が整流されたところに取り付ける。"}, {"label": "4", "text": "防火区画を貫通するダクトと壁のすき間には、グラスウール保温材を充てんする。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["コーナーボルト工法の接合部には、フランジ用ガスケットを挿入しない。", "防火区画を貫通するダクトと壁のすき間には、グラスウール保温材を充てんする。"], "answerHints": [["フランジ用ガスケットを挿入しない"], ["グラスウール保温材"]], "mnemonic": "正しくは：コーナーボルト工法の接合部にもガスケットを挿入する。防火区画貫通部のすき間はロックウール保温材で充てんする。", "block": 17, "group": 6}, {"id": "R07_kouki_51", "source": "R7後 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "あとで取外しが必要な水栓類等のねじ接合材には、テープシール材を使用する。"}, {"label": "2", "text": "呼び径65以下のステンレス鋼管の場合、形鋼振れ止め支持は、不要である。"}, {"label": "3", "text": "配管用炭素鋼鋼管の溶接接合は、原則として、下向き溶接とする。"}, {"label": "4", "text": "揚水管に防振継手を取り付けるのは、ウォーターハンマーを防止するためである。"}], "answer": ["2", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["呼び径65以下のステンレス鋼管の場合、形鋼振れ止め支持は、不要である。", "揚水管に防振継手を取り付けるのは、ウォーターハンマーを防止するためである。"], "answerHints": [["呼び径65以下"], ["ウォーターハンマーを防止する"]], "mnemonic": "正しくは：形鋼振れ止め支持が原則不要なのは呼び径40以下。揚水管の防振継手はポンプの振動伝播防止のため。", "block": 17, "group": 6}, {"id": "R08_zenki_50", "source": "R8前 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "アンカーボルトは、機器据付け後、頂部からねじ山が出ない長さとする。"}, {"label": "2", "text": "呼び番号3 の遠心送風機を天吊りする場合、形鋼を溶接枠組みした架台上に据え付け、架台 は上部スラブ鉄筋に緊結されたアンカーボルトで固定する。"}, {"label": "3", "text": "冷却塔の補給水口の高さは、補給水タンクの低水位から3 m 以上低くなるように据え付 ける。"}, {"label": "4", "text": "遠心送風機のコンクリート基礎の高さは、100 mm 程度とする。"}], "answer": ["1", "4"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["アンカーボルトは、機器据付け後、頂部からねじ山が出ない長さとする。", "遠心送風機のコンクリート基礎の高さは、100 mm 程度とする。"], "answerHints": [["ねじ山が出ない"], ["100 mm"]], "mnemonic": "正しくは：アンカーボルトはナットからねじ山が3山程度出る長さ。遠心送風機の基礎の高さは150mm程度。", "block": 17, "group": 6}, {"id": "R07_zenki_39", "source": "R7前 No.39", "category": "法規", "type": "single", "question": "建設工事における安全衛生管理に関する記述のうち、「労働安全衛生法」上、 誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、つり上げ荷重が5トン以上の移動式クレーンの運転の業務については、小型移 動式クレーン運転技能講習を修了した者を当該業務に就かせることができる。"}, {"label": "2", "text": "事業者は、型枠支保工の組立ての作業において、作業主任者を選任しなければならない。"}, {"label": "3", "text": "事業者は、研削といし作業を行う場合、その日の作業を開始する前には1分間以上試運転 をしなければならない。"}, {"label": "4", "text": "事業者は、明り掘削の作業を行うときは、物体の飛来又は落下による危険を防止するため、 当該作業に従事する労働者に保護帽を着用させなければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["事業者は、つり上げ荷重が5トン以上の移動式クレーンの運転の業務については、小型移 動式クレーン運転技能講習を修了した者を当該業務に就かせることができる。"], "answerHints": [["小型移 動式クレーン運転技能講習"]], "mnemonic": "正しくは：つり上げ荷重5t以上の移動式クレーンは移動式クレーン運転士免許が必要（技能講習は1t以上5t未満）。", "block": 17, "group": 6}, {"id": "R07_zenki_42", "source": "R7前 No.42", "category": "法規", "type": "single", "question": "建築物に設ける配管設備に関する記述のうち、「建築基準法」上、誤っているものはど れか。", "choices": [{"label": "1", "text": "コンクリートへの埋設等により腐食するおそれのある部分には、その材質に応じ有効な腐食 防止のための措置を講じなければならない。"}, {"label": "2", "text": "構造耐力上主要な部分を貫通して配管する場合においては、建築物の構造耐力上支障を 生じないようにしなければならない。"}, {"label": "3", "text": "給水管、配電管その他の管が、防火区画を貫通する場合、貫通する部分を難燃材料で造らな ければならない。"}, {"label": "4", "text": "排水のための配管設備には、排水トラップ、通気管等を設置する等衛生上必要な措置を講じ なければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["給水管、配電管その他の管が、防火区画を貫通する場合、貫通する部分を難燃材料で造らな ければならない。"], "answerHints": [["難燃材料"]], "mnemonic": "正しくは：防火区画を貫通する管は、貫通部分（両側1m以内）を準不燃材料で造る。", "block": 17, "group": 6}, {"id": "R07_zenki_45", "source": "R7前 No.45", "category": "法規", "type": "single", "question": "危険物に関する記述のうち、「消防法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "危険物を貯蔵し、又は取り扱う屋内タンクは、平屋建の建築物に設けられたタンク専用室に設 置する。"}, {"label": "2", "text": "屋内タンク貯蔵所には、見やすい箇所に屋内タンク貯蔵所である旨を表示した標識を設ける。"}, {"label": "3", "text": "指定数量以上の危険物は、原則として、貯蔵所以外の場所でこれを貯蔵してはならない。"}, {"label": "4", "text": "品名又は指定数量を異にする二以上の危険物を同一の場所で貯蔵する場合、それぞれの危険 物の指定数量未満であれば指定数量以上の貯蔵所とはならない。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["品名又は指定数量を異にする二以上の危険物を同一の場所で貯蔵する場合、それぞれの危険 物の指定数量未満であれば指定数量以上の貯蔵所とはならない。"], "answerHints": [["指定数量未満であれば"]], "mnemonic": "正しくは：複数の危険物は、各数量÷指定数量の合計が1以上なら指定数量以上として扱う。", "block": 17, "group": 6}, {"id": "R07_zenki_48", "source": "R7前 No.48", "category": "法規", "type": "single", "question": "廃棄物の処理に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、 誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、その事業活動に伴って生じた廃棄物を自らの責任において適正に処理しなければ ならない。"}, {"label": "2", "text": "事業者は、その産業廃棄物(特別管理産業廃棄物を除く。)が運搬されるまでの間、産業 廃棄物保管基準に従い、生活環境の保全上支障のないようにこれを保管しなければならな い。"}, {"label": "3", "text": "建設工事の元請業者が、当該工事において発生させた産業廃棄物を自ら処理施設へ運搬する 場合は、産業廃棄物収集運搬業の許可を受けなければならない。"}, {"label": "4", "text": "産業廃棄物管理票交付者は、管理票の写しの送付を受けたときは、当該運搬又は処分が終 了したことを当該管理票の写しにより確認しなければならない。 せん。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設工事の元請業者が、当該工事において発生させた産業廃棄物を自ら処理施設へ運搬する 場合は、産業廃棄物収集運搬業の許可を受けなければならない。"], "answerHints": [["許可を受けなければならない"]], "mnemonic": "正しくは：排出事業者（元請）が自ら運搬する場合は、収集運搬業の許可は不要。", "block": 17, "group": 6}, {"id": "R07_kouki_41", "source": "R7後 No.41", "category": "法規", "type": "single", "question": "建築に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "作業のために継続的に使用する室は、居室である。"}, {"label": "2", "text": "集会のために継続的に使用する室は、居室である。"}, {"label": "3", "text": "屋外階段は、主要構造部である。"}, {"label": "4", "text": "はりは、主要構造部である。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["屋外階段は、主要構造部である。"], "answerHints": [["屋外階段"]], "mnemonic": "正しくは：主要構造部に含まれるのは屋内階段。屋外階段は除かれる。", "block": 17, "group": 6}, {"id": "R07_kouki_44", "source": "R7後 No.44", "category": "法規", "type": "single", "question": "建設業の許可を受けた建設業者が、発注者から直接請け負った建設工事の現場に掲げ なければならない標識の記載事項として、「建設業法」上、定められていないものはど れか。", "choices": [{"label": "1", "text": "商号又は名称"}, {"label": "2", "text": "代表者の氏名"}, {"label": "3", "text": "現場代理人の氏名"}, {"label": "4", "text": "主任技術者又は監理技術者の氏名"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["現場代理人の氏名"], "answerHints": [["現場代理人の氏名"]], "mnemonic": "工事現場の標識：商号・名称、代表者氏名、許可番号等、主任技術者・監理技術者の氏名。現場代理人は不要。", "block": 17, "group": 6}, {"id": "R07_kouki_47", "source": "R7後 No.47", "category": "法規", "type": "single", "question": "「フロン類の使用の合理化及び管理の適正化に関する法律」上、第一種特定製品の管理者 がフロン類の管理の適正化のために取り組むべき事項として、定められていないものはど れか。", "choices": [{"label": "1", "text": "フロン類の破壊の実施及び破壊証明書の送付"}, {"label": "2", "text": "簡易点検の実施"}, {"label": "3", "text": "圧縮機を駆動する電動機の定格出力が一定規模以上のエアコンディショナーの定期点検の 実施"}, {"label": "4", "text": "フロン類の漏えいを確認した場合にあっては、当該漏えいに係る点検及び当該点検により漏え い箇所が特定された場合には当該箇所の修理の実施"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["フロン類の破壊の実施及び破壊証明書の送付"], "answerHints": [["フロン類の破壊"]], "mnemonic": "管理者の義務は簡易点検・定期点検・漏えい時の点検修理など。フロン類の破壊は破壊業者が行う。", "block": 17, "group": 6}, {"id": "R08_zenki_40", "source": "R8前 No.40", "category": "法規", "type": "single", "question": "労働契約の締結に際し、「労働基準法」上、使用者が労働者に対して明示しなければな らない労働条件として、定められていないものはどれか。", "choices": [{"label": "1", "text": "賃金に関する事項"}, {"label": "2", "text": "労働時間に関する事項"}, {"label": "3", "text": "福利厚生施設の利用に関する事項"}, {"label": "4", "text": "退職に関する事項"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["福利厚生施設の利用に関する事項"], "answerHints": [["福利厚生施設"]], "mnemonic": "明示すべき労働条件：契約期間・就業場所・業務・労働時間・賃金・退職など。福利厚生施設は定めなし。", "block": 17, "group": 6}, {"id": "R08_zenki_43", "source": "R8前 No.43", "category": "法規", "type": "single", "question": "請負契約書に記載しなければならない事項に関する記述のうち、「建設業法」上、 定められていないものはどれか。", "choices": [{"label": "1", "text": "工事内容"}, {"label": "2", "text": "請負代金の額"}, {"label": "3", "text": "天災その他不可抗力による工期の変更又は損害の負担及びその額の算定方法に関する定め"}, {"label": "4", "text": "下請契約を行う場合の下請負人の名称"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["下請契約を行う場合の下請負人の名称"], "answerHints": [["下請負人の名称"]], "mnemonic": "請負契約書の記載事項は工事内容・請負代金・工期・不可抗力時の定めなど。下請負人の名称は不要。", "block": 17, "group": 6}, {"id": "R08_zenki_46", "source": "R8前 No.46", "category": "法規", "type": "single", "question": "騒音の規制に関する記述のうち、「騒音規制法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "特定建設作業とは、建設業法の規定による特定建設業の許可を受けた業者が行う作業を いう。"}, {"label": "2", "text": "指定地域内における特定建設作業の実施の届出の事項には、騒音の防止の方法が含まれる。"}, {"label": "3", "text": "指定地域内では、特定工場等において発生する騒音及び特定建設作業に伴って発生する騒 音について規制される。"}, {"label": "4", "text": "指定地域内に特定工場等を設置している者は、当該特定工場等に係る規制基準を遵守しな ければならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["特定建設作業とは、建設業法の規定による特定建設業の許可を受けた業者が行う作業を いう。"], "answerHints": [["特定建設業の許可を受けた業者"]], "mnemonic": "正しくは：特定建設作業とは、建設工事のうち著しい騒音を発生する作業で政令で定めるもの（業者の許可区分とは無関係）。", "block": 17, "group": 6}, {"id": "R07_zenki_04", "source": "R7前 No.4", "category": "一般基礎", "type": "single", "question": "次の用語のうち、室内環境に関係のないものはどれか。", "choices": [{"label": "1", "text": "予想平均申告(PMV)"}, {"label": "2", "text": "ホルムアルデヒドの量"}, {"label": "3", "text": "浮遊粉じんの量"}, {"label": "4", "text": "化学的酸素要求量(COD)"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["化学的酸素要求量(COD)"], "answerHints": [["化学的酸素要求量(COD)"]], "mnemonic": "CODは水質（水の汚れ）の指標。PMV・ホルムアルデヒド・浮遊粉じんは室内環境の指標。", "block": 18, "group": 6}, {"id": "R07_kouki_01", "source": "R7後 No.1", "category": "一般基礎", "type": "single", "question": "熱中症の発症又は予防に関係する用語として、適当でないものはどれか。", "choices": [{"label": "1", "text": "暑さ指数"}, {"label": "2", "text": "キャビテーション"}, {"label": "3", "text": "暑熱順化"}, {"label": "4", "text": "身体作業強度"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["キャビテーション"], "answerHints": [["キャビテーション"]], "mnemonic": "キャビテーションはポンプ内で圧力低下により気泡が発生する現象。暑さ指数・暑熱順化・身体作業強度が熱中症関連。", "block": 18, "group": 6}, {"id": "R07_kouki_05", "source": "R7後 No.5", "category": "一般基礎", "type": "single", "question": "電気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "屋外に設置する機器の電源回路には、漏電遮断器を設置する。"}, {"label": "2", "text": "合成樹脂製可とう電線管(PF 管)は、コンクリートに埋設して使用することができる。"}, {"label": "3", "text": "合成樹脂製可とう電線管(PF 管)内では、電線に接続点を設けない。"}, {"label": "4", "text": "絶縁抵抗測定では、抵抗の測定値が規定値より小さい場合に良と判定する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["絶縁抵抗測定では、抵抗の測定値が規定値より小さい場合に良と判定する。"], "answerHints": [["規定値より小さい場合に良"]], "mnemonic": "正しくは：絶縁抵抗は測定値が規定値以上なら良（大きいほど絶縁が良い）。", "block": 18, "group": 6}, {"id": "R08_zenki_02", "source": "R8前 No.2", "category": "一般基礎", "type": "single", "question": "水平な円管の直管部を流れる流体について、次の「流体の密度」と「流速」の組合せ のうち動圧が最も大きくなるものとして、適当なものはどれか。 [流体の密度(kg/m3)] [流速(m/s)]", "choices": [{"label": "1", "text": "1.1 1.4"}, {"label": "2", "text": "1.2 1.3"}, {"label": "3", "text": "1.3 1.2"}, {"label": "4", "text": "1.4 1.1"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["1.1 1.4"], "answerHints": [["1.1 1.4"]], "mnemonic": "動圧＝（1/2）ρv²。速度の2乗で効くので、流速が最大の1.4m/sが最も大きい。", "block": 18, "group": 6}, {"id": "R08_zenki_05", "source": "R8前 No.5", "category": "一般基礎", "type": "single", "question": "電気設備工事に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "キュービクルは、受変電機器等を金属製の箱に収めたものである。"}, {"label": "2", "text": "ケーブルラックは、はしご形やトレー形等のケーブル支持材である。"}, {"label": "3", "text": "レースウェイは、一般的に、倉庫や機械室等で照明器具の取付けと配線等に使用する。"}, {"label": "4", "text": "ヒューズは、溶断したものでも繰り返し使用できる。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ヒューズは、溶断したものでも繰り返し使用できる。"], "answerHints": [["繰り返し使用できる"]], "mnemonic": "正しくは：ヒューズは溶断したら交換が必要（繰り返し使えるのは配線用遮断器）。", "block": 18, "group": 6}, {"id": "R07_zenki_09", "source": "R7前 No.9", "category": "空調・衛生", "type": "single", "question": "熱負荷に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "構造体の熱通過率の値が小さいほど、構造体負荷(通過熱負荷)は小さくなる。"}, {"label": "2", "text": "ガラス面からの熱負荷は、ガラス面を透過した日射による負荷のみである。"}, {"label": "3", "text": "外気による熱負荷は、顕熱と潜熱である。"}, {"label": "4", "text": "人体からの熱負荷は、顕熱と潜熱である。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ガラス面からの熱負荷は、ガラス面を透過した日射による負荷のみである。"], "answerHints": [["日射による負荷のみ"]], "mnemonic": "正しくは：ガラス面の熱負荷は透過日射に加え、室内外温度差による通過熱負荷もある。", "block": 18, "group": 6}, {"id": "R07_zenki_12", "source": "R7前 No.12", "category": "空調・衛生", "type": "single", "question": "パッケージ形空気調和機に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "空気熱源ヒートポンプ式は、外気温度が低いときの暖房運転において、屋外機コイルに霜が付 着することがある。"}, {"label": "2", "text": "業務用のパッケージ形空気調和機は、「フロン類の使用の合理化及び管理の適正化に関する 法律」に基づく「第一種特定製品」に該当しない。"}, {"label": "3", "text": "マルチパッケージ形空気調和機は、屋内機の保守管理のため、各室ごとに作業を行う必要が ある。"}, {"label": "4", "text": "パッケージ形空気調和機は、熱源により水熱源と空気熱源に分けられる。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["業務用のパッケージ形空気調和機は、「フロン類の使用の合理化及び管理の適正化に関する 法律」に基づく「第一種特定製品」に該当しない。"], "answerHints": [["該当しない"]], "mnemonic": "正しくは：業務用パッケージエアコンはフロン排出抑制法の第一種特定製品に該当する。", "block": 18, "group": 6}, {"id": "R07_zenki_15", "source": "R3後 No.15 / R7前 No.15", "category": "空調・衛生", "type": "single", "question": "上水道の取水施設から配水施設に至るまでのフローのうち、適当なものはどれか。", "choices": [{"label": "1", "text": "取水施設 → 導水施設 → 浄水施設 → 送水施設 → 配水施設"}, {"label": "2", "text": "取水施設 → 導水施設 → 送水施設 → 浄水施設 → 配水施設"}, {"label": "3", "text": "取水施設 → 送水施設 → 導水施設 → 浄水施設 → 配水施設"}, {"label": "4", "text": "取水施設 → 浄水施設 → 送水施設 → 導水施設 → 配水施設"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["取水施設 → 導水施設 → 浄水施設 → 送水施設 → 配水施設"], "answerHints": [["取水施設 → 導水施設 → 浄水施設 → 送水施設 → 配水施設"]], "mnemonic": "上水道は 取水→導水→浄水→送水→配水（導水は浄水前、送水は浄水後）。", "block": 18, "group": 6}, {"id": "R07_zenki_18", "source": "R6前 No.18 / R7前 No.18", "category": "空調・衛生", "type": "single", "question": "給湯設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "給湯用循環ポンプは、給湯温度を一定に保持するために設ける。"}, {"label": "2", "text": "給湯設備で使われる安全装置には、逃がし弁、逃がし管等がある。"}, {"label": "3", "text": "水中の気泡は、水温が高く圧力が高いほど発生しやすい。"}, {"label": "4", "text": "潜熱回収型給湯器は、排気ガスの潜熱を回収し給湯の予熱として利用することで、熱効率 を向上させている。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水中の気泡は、水温が高く圧力が高いほど発生しやすい。"], "answerHints": [["圧力が高いほど"]], "mnemonic": "正しくは：水中の気泡は、水温が高く圧力が低いほど発生しやすい。", "block": 18, "group": 6}, {"id": "R07_zenki_21", "source": "R7前 No.21", "category": "空調・衛生", "type": "single", "question": "屋内消火栓設備において、ポンプの仕様を決める際に関係のないものはどれか。", "choices": [{"label": "1", "text": "水源への給水圧力"}, {"label": "2", "text": "消防用ホースの摩擦損失水頭"}, {"label": "3", "text": "屋内消火栓の設置個数"}, {"label": "4", "text": "配管の摩擦損失水頭"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["水源への給水圧力"], "answerHints": [["水源への給水圧力"]], "mnemonic": "ポンプ仕様は消火栓個数（吐出量）、ホース・配管の摩擦損失、落差、ノズル放水圧で決まる。水源への給水圧力は無関係。", "block": 18, "group": 6}, {"id": "R07_kouki_07", "source": "R7後 No.7", "category": "空調・衛生", "type": "single", "question": "空気調和設備の計画に関する記述のうち、省エネルギーの観点から、適当でないものは どれか。", "choices": [{"label": "1", "text": "予冷・予熱時に外気を取り入れないように制御する。"}, {"label": "2", "text": "ユニット形空気調和機に全熱交換器を組み込む。"}, {"label": "3", "text": "成績係数が高い機器を採用する。"}, {"label": "4", "text": "冷房時に冷却減湿・再熱を行い、湿度を制御する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["冷房時に冷却減湿・再熱を行い、湿度を制御する。"], "answerHints": [["冷却減湿・再熱"]], "mnemonic": "冷却減湿後の再熱は冷やした空気を再び温めるのでエネルギーの無駄。省エネ上は避ける。", "block": 18, "group": 6}, {"id": "R07_kouki_11", "source": "R7後 No.11", "category": "空調・衛生", "type": "single", "question": "コールドドラフト対策に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "外壁からの熱損失を減らす。"}, {"label": "2", "text": "放熱器をインテリア側に設置する。"}, {"label": "3", "text": "温風暖房では、送風量をできるだけ多くする。"}, {"label": "4", "text": "建築構造を気密にし、屋外から侵入する隙間風を減らす。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["放熱器をインテリア側に設置する。"], "answerHints": [["インテリア側"]], "mnemonic": "正しくは：コールドドラフト対策の放熱器は、窓下などペリメーター（外壁）側に設置する。", "block": 18, "group": 6}, {"id": "R07_kouki_14", "source": "R7後 No.14", "category": "空調・衛生", "type": "single", "question": "換気の「対象となる室」と「換気の必要な主な要因」の組合せのうち、適当でないもの はどれか。 [対象となる室] [換気の必要な主な要因]", "choices": [{"label": "1", "text": "車庫 酸素供給"}, {"label": "2", "text": "電気室 熱"}, {"label": "3", "text": "浴室 湿気"}, {"label": "4", "text": "倉庫 臭気"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["車庫 酸素供給"], "answerHints": [["酸素供給"]], "mnemonic": "正しくは：車庫の換気の主な要因は排気ガス（有害ガス）。酸素供給はボイラー室など燃焼機器の室。", "block": 18, "group": 6}, {"id": "R07_kouki_17", "source": "R7後 No.17", "category": "空調・衛生", "type": "single", "question": "給水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "飲料用給水タンクには、内径60 cm 以上のマンホールを設ける。"}, {"label": "2", "text": "高置タンク方式は、他の給水方式に比べ、給水圧力の変動が大きくなる。"}, {"label": "3", "text": "水道直結増圧方式は、高置タンク方式に比べ、一般的に、ポンプの吐出し量が大きくなる。"}, {"label": "4", "text": "クロスコネクションとは、飲料水系統とその他の系統が、配管・装置により直接接続される ことをいう。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["高置タンク方式は、他の給水方式に比べ、給水圧力の変動が大きくなる。"], "answerHints": [["変動が大きくなる"]], "mnemonic": "正しくは：高置タンク方式は重力で給水するので、給水圧力の変動が小さい。", "block": 18, "group": 6}, {"id": "R07_kouki_20", "source": "R7後 No.20", "category": "空調・衛生", "type": "single", "question": "排水・通気設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "伸頂通気管は、排水立て管の上部を通気管として延長し、大気に開放する。"}, {"label": "2", "text": "通気管の末端は、建物外壁から大きく突き出している部分の下部に開放しない。"}, {"label": "3", "text": "通気管は、排水系統内の空気の流れを円滑にし、トラップ封水が破壊されるのを防止する。"}, {"label": "4", "text": "ループ通気管は、床下で横引きし、直接通気立て管に接続する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ループ通気管は、床下で横引きし、直接通気立て管に接続する。"], "answerHints": [["床下で横引き"]], "mnemonic": "正しくは：ループ通気管は最上流の器具排水管の下流から立ち上げ、器具のあふれ縁より150mm以上上方で横引きして通気立て管に接続する。", "block": 18, "group": 6}, {"id": "R07_kouki_23", "source": "R7後 No.23", "category": "空調・衛生", "type": "single", "question": "FRP 製浄化槽の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "寒冷地を除き、車庫、物置等の建築物内の設置は、できるだけ避ける。"}, {"label": "2", "text": "深く掘りすぎて埋め戻すと、設置後に不等沈下するおそれがある。"}, {"label": "3", "text": "槽に接続する流入管、流出管等は、管の敷設深さまで槽の周囲を埋め戻してから接続す る。"}, {"label": "4", "text": "槽の埋め戻しは、水張り試験の後、槽内の水を抜いてから行う。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["槽の埋め戻しは、水張り試験の後、槽内の水を抜いてから行う。"], "answerHints": [["水を抜いてから"]], "mnemonic": "正しくは：FRP製浄化槽の埋め戻しは、槽に水を張った状態で行う。", "block": 18, "group": 6}, {"id": "R08_zenki_10", "source": "R8前 No.10", "category": "空調・衛生", "type": "single", "question": "定風量単一ダクト方式のユニット形空気調和機を制御するために必要な自動制御機器の うち、関係のないものはどれか。", "choices": [{"label": "1", "text": "電動三方弁"}, {"label": "2", "text": "フロートスイッチ"}, {"label": "3", "text": "温度調節器"}, {"label": "4", "text": "湿度調節器"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["関係のないもの"], "answerTexts": ["フロートスイッチ"], "answerHints": [["フロートスイッチ"]], "mnemonic": "フロートスイッチは水位検出用。空調機の制御は温度・湿度調節器と電動三方弁（二方弁）。", "block": 18, "group": 6}, {"id": "R08_zenki_13", "source": "R8前 No.13", "category": "空調・衛生", "type": "single", "question": "床面積の合計が 100 m2 を超える住宅の調理室に設置するガスコンロ(開放式燃焼器 具)の廃ガス等を、換気扇等により排気する場合の必要有効換気量として、「建築基準 法」上、正しいものはどれか。 ただし、排気フードは設けないものとする。 ここで、K:燃料の単位燃焼量当たりの理論廃ガス量[m3/(kW・h)] Q:火を使用する器具の実況に応じた燃料消費量[kW]", "choices": [{"label": "1", "text": "2 KQ[m3/h]"}, {"label": "2", "text": "20 KQ[m3/h]"}, {"label": "3", "text": "30 KQ[m3/h]"}, {"label": "4", "text": "40 KQ[m3/h]"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["正しいもの"], "answerTexts": ["40 KQ[m3/h]"], "answerHints": [["40 KQ"]], "mnemonic": "必要換気量：排気フードなし40KQ、フードI型20KQ、フードII型10KQ、煙突2KQ。", "block": 18, "group": 6}, {"id": "R08_zenki_16", "source": "R8前 No.16", "category": "空調・衛生", "type": "single", "question": "下水道管きょの接合方法に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "水面接合は、管の中心を一致させて接合する方法である。"}, {"label": "2", "text": "管頂接合は、管の内面頂部の高さを合わせて接合する方法である。"}, {"label": "3", "text": "段差接合は、地表勾配に応じて適切な間隔でマンホールを設けて接合する方法である。"}, {"label": "4", "text": "管底接合は、管の内面底部の高さを合わせて接合する方法である。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["水面接合は、管の中心を一致させて接合する方法である。"], "answerHints": [["管の中心を一致"]], "mnemonic": "正しくは：水面接合は計画水位を一致させる方法。管の中心を一致させるのは管中心接合。", "block": 18, "group": 6}, {"id": "R08_zenki_19", "source": "R8前 No.19", "category": "空調・衛生", "type": "single", "question": "排水設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "オイル阻集器は、汚水中に含まれている動植物系の油脂類を除去するものである。"}, {"label": "2", "text": "阻集器にはトラップ機能を持つものが多く、器具にトラップを設けると二重トラップになる おそれがある。"}, {"label": "3", "text": "トラップますは、臭気が逆流しない構造とする。"}, {"label": "4", "text": "Uトラップは、排水配管の途中に設けるトラップである。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["オイル阻集器は、汚水中に含まれている動植物系の油脂類を除去するものである。"], "answerHints": [["動植物系の油脂類"]], "mnemonic": "正しくは：オイル阻集器はガソリン・油類を除去。動植物系の油脂はグリース阻集器。", "block": 18, "group": 6}, {"id": "R08_zenki_22", "source": "R8前 No.22", "category": "空調・衛生", "type": "single", "question": "ガス設備に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "都市ガスの導管の敷設位置による区分としての「内管」とは、需要家に引き込まれる導管のう ち、敷地境界線からガス栓までの導管をいう。"}, {"label": "2", "text": "液化石油ガス(LPG)のガス容器は、常に温度を 40 °C以下に保つ措置をとる。"}, {"label": "3", "text": "液化天然ガス(LNG)は、メタンを主成分とした天然ガスを冷却して液化したものである。"}, {"label": "4", "text": "液化天然ガス(LNG)は、液化石油ガス(LPG)より単位容積あたりの発熱量が大きい。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["液化天然ガス(LNG)は、液化石油ガス(LPG)より単位容積あたりの発熱量が大きい。"], "answerHints": [["発熱量が大きい"]], "mnemonic": "正しくは：LNG（メタン主体）はLPG（プロパン主体）より単位容積あたりの発熱量が小さい。", "block": 18, "group": 6}, {"id": "R07_zenki_25", "source": "R7前 No.25", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "設備系の制御に用いられる「機器」と「制御対象」の組合せのうち、適当でないものは どれか。 [機器] [制御対象]", "choices": [{"label": "1", "text": "電極棒 受水タンクの水位制御"}, {"label": "2", "text": "温度検出器 室内の温度制御"}, {"label": "3", "text": "電動三方弁 ユニット形空気調和機の冷温水流量制御"}, {"label": "4", "text": "フロートスイッチ 加湿器の二位置制御"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["フロートスイッチ 加湿器の二位置制御"], "answerHints": [["加湿器の二位置制御"]], "mnemonic": "フロートスイッチは水位制御用。加湿器の二位置制御には湿度調節器を使う。", "block": 18, "group": 6}, {"id": "R07_kouki_24", "source": "R7後 No.24", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "加湿器に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "スプレー形加湿器は、ノズルで水を直接噴霧して加湿する。"}, {"label": "2", "text": "気化式加湿器は、ノズルで蒸気を直接噴霧して加湿する。"}, {"label": "3", "text": "パン形加湿器は、電気ヒーターにより水を加熱蒸発させて加湿する。"}, {"label": "4", "text": "超音波加湿器は、超音波振動子により水を霧化させて加湿する。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["気化式加湿器は、ノズルで蒸気を直接噴霧して加湿する。"], "answerHints": [["ノズルで蒸気を直接噴霧"]], "mnemonic": "正しくは：気化式は水を含ませたエレメントに通風して気化させる。蒸気を噴霧するのは蒸気式。", "block": 18, "group": 6}, {"id": "R07_kouki_27", "source": "R7後 No.27", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "ダクト及びダクト附属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "シーリングディフューザーは、コーンに向かって吹き出された空気が室内空気を誘引しながら 拡散する。"}, {"label": "2", "text": "吸込口は、一般的に、固定羽根のものが使用される。"}, {"label": "3", "text": "長方形ダクトの板厚は、長辺と短辺で使い分ける。"}, {"label": "4", "text": "共板フランジ用ガスケットは、弾力性のあるものを使用する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["長方形ダクトの板厚は、長辺と短辺で使い分ける。"], "answerHints": [["使い分ける"]], "mnemonic": "正しくは：長方形ダクトの板厚は長辺の寸法で決め、長辺・短辺とも同じ板厚とする。", "block": 18, "group": 6}, {"id": "R08_zenki_26", "source": "R8前 No.26", "category": "設備（機器・材料・設計図書）", "type": "single", "question": "配管材料及び配管付属品に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "ボールタップは、タンク等の自動給水・止水に使用する。"}, {"label": "2", "text": "ボール弁は、流体を一方向のみに流し、逆流を防止する弁である。"}, {"label": "3", "text": "銅管は、肉厚によりK、L及びMタイプに分類される。"}, {"label": "4", "text": "ストレーナーは、配管内のゴミ等を取り除き、弁類や機器類の損傷を防ぐ。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["ボール弁は、流体を一方向のみに流し、逆流を防止する弁である。"], "answerHints": [["逆流を防止する"]], "mnemonic": "正しくは：一方向のみに流し逆流を防止するのは逆止弁。ボール弁は球状弁体を回転させて開閉する。", "block": 18, "group": 6}, {"id": "R07_zenki_31", "source": "R7前 No.31", "category": "施工管理法", "type": "single", "question": "施工の品質を確認するための試験又は検査に関する記述のうち、適当でないものはどれ か。", "choices": [{"label": "1", "text": "配管の吊り間隔、振れ止めは、抜取検査で確認する。"}, {"label": "2", "text": "排水用水中モーターポンプのレベルスイッチの信号による発停の確認は、全数検査とする。"}, {"label": "3", "text": "埋設排水配管の勾配は、抜取検査で確認する。"}, {"label": "4", "text": "品質基準が明確であり、再現性が確保される場合、抜取検査としてもよい。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["埋設排水配管の勾配は、抜取検査で確認する。"], "answerHints": [["抜取検査"]], "mnemonic": "正しくは：埋設排水配管の勾配は全数検査で確認する（埋設後は確認できないため）。", "block": 18, "group": 6}, {"id": "R07_zenki_34", "source": "R7前 No.34", "category": "施工管理法", "type": "single", "question": "配管の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "配管用炭素鋼鋼管のねじ加工後のねじ径の確認は、テーパねじリングゲージで行う。"}, {"label": "2", "text": "鋼管のねじ込み作業は、おねじ部分に塗布したペーストシール剤が硬化してからねじ込む。"}, {"label": "3", "text": "通気管の床下横走り配管は、できる限り短くなるような箇所で立上げる。"}, {"label": "4", "text": "銅管を鋼製金物で支持する場合は、ゴム又は絶縁テープ等で保護をする。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["鋼管のねじ込み作業は、おねじ部分に塗布したペーストシール剤が硬化してからねじ込む。"], "answerHints": [["硬化してから"]], "mnemonic": "正しくは：ペーストシール剤は硬化する前にねじ込む。", "block": 18, "group": 6}, {"id": "R07_zenki_37", "source": "R7前 No.37", "category": "施工管理法", "type": "single", "question": "渦巻ポンプの試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "膨張タンク等から注水して、機器及び配管系のエア抜きを行う。"}, {"label": "2", "text": "カップリングの水平度を確認する。"}, {"label": "3", "text": "メカニカルシール部からの水滴の滴下が一定量継続してあることを確認する。"}, {"label": "4", "text": "異常音、異常振動の無いことを確認する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["メカニカルシール部からの水滴の滴下が一定量継続してあることを確認する。"], "answerHints": [["水滴の滴下が一定量継続"]], "mnemonic": "正しくは：メカニカルシールは漏れがほとんどないことを確認。一定量の滴下を確認するのはグランドパッキン。", "block": 18, "group": 6}, {"id": "R07_kouki_31", "source": "R7後 No.31", "category": "施工管理法", "type": "single", "question": "施工の品質を確認するための試験又は検査に関する記述のうち、適当でないものはどれ か。", "choices": [{"label": "1", "text": "排水用水中モーターポンプの試験では、レベルスイッチからの信号により発停することを確 認する。"}, {"label": "2", "text": "防火区画を排水管が貫通する箇所において、貫通部の隙間がモルタルその他の不燃材料で埋 められていることを確認する。"}, {"label": "3", "text": "検査の方法には全数検査と抜取検査があり、ボイラー安全弁の作動試験は抜取検査で確認す る。"}, {"label": "4", "text": "完成時の立会検査には、契約書や設計図書の他、工事記録写真、試験運転記録等を用意しなけ ればならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["検査の方法には全数検査と抜取検査があり、ボイラー安全弁の作動試験は抜取検査で確認す る。"], "answerHints": [["ボイラー安全弁の作動試験は抜取検査"]], "mnemonic": "正しくは：ボイラー安全弁の作動試験は全数検査。", "block": 18, "group": 6}, {"id": "R07_kouki_34", "source": "R7後 No.34", "category": "施工管理法", "type": "single", "question": "「配管材」と「主な接合方法」の組合せのうち、適当でないものはどれか。 [配管材] [主な接合方法]", "choices": [{"label": "1", "text": "配管用炭素鋼鋼管 ねじ接合、フランジ接合"}, {"label": "2", "text": "排水用硬質塩化ビニルライニング鋼管 ねじ接合、溶接接合"}, {"label": "3", "text": "ステンレス鋼管 メカニカル接合、溶接接合"}, {"label": "4", "text": "銅管 メカニカル接合、差込接合"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["排水用硬質塩化ビニルライニング鋼管 ねじ接合、溶接接合"], "answerHints": [["ねじ接合、溶接接合"]], "mnemonic": "正しくは：排水用硬質塩化ビニルライニング鋼管は排水鋼管用可とう継手（MDジョイント）で接合する。", "block": 18, "group": 6}, {"id": "R07_kouki_37", "source": "R7後 No.37", "category": "施工管理法", "type": "single", "question": "試運転調整に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "高置タンク方式の給水設備では、末端の給水栓において残留塩素の測定を行う。"}, {"label": "2", "text": "屋外騒音の測定は、冷却塔等の騒音の発生源となる機器を運転して、敷地境界線上で行う。"}, {"label": "3", "text": "渦巻ポンプの試運転では、グランドパッキン部からの水滴の滴下量が適切かどうか確認する。"}, {"label": "4", "text": "多翼送風機の試運転では、吐出し側ダンパーが、全開になっていることを確認してから調整 を開始する。"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["多翼送風機の試運転では、吐出し側ダンパーが、全開になっていることを確認してから調整 を開始する。"], "answerHints": [["全開になっている"]], "mnemonic": "正しくは：多翼送風機は吐出し側ダンパーを全閉にしてから起動し、徐々に開いて調整する。", "block": 18, "group": 6}, {"id": "R08_zenki_31", "source": "R8前 No.31", "category": "施工管理法", "type": "single", "question": "施工の品質を確認するための検査に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "防火区画貫通箇所の穴埋めの確認は、抜取検査とする。"}, {"label": "2", "text": "排水用水中モーターポンプのレベルスイッチの信号による発停の確認は、全数検査とする。"}, {"label": "3", "text": "給水配管の水圧試験による確認は、全数検査とする。"}, {"label": "4", "text": "防火ダンパーの温度ヒューズの作動の確認は、抜取検査とする。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["防火区画貫通箇所の穴埋めの確認は、抜取検査とする。"], "answerHints": [["抜取検査"]], "mnemonic": "正しくは：防火区画貫通箇所の穴埋めの確認は全数検査とする。", "block": 18, "group": 6}, {"id": "R08_zenki_34", "source": "R8前 No.34", "category": "施工管理法", "type": "single", "question": "配管及び配管附属品の施工に関する記述のうち、適当でないものはどれか。", "choices": [{"label": "1", "text": "受水タンクの吐水側配管に設ける緊急遮断弁は、地震時の水の確保に有効である。"}, {"label": "2", "text": "敷地排水管の合流箇所、曲がる箇所等には、排水ますを設ける。"}, {"label": "3", "text": "給水横走り管より下方に供給する分岐管は、配管上部から取り出す。"}, {"label": "4", "text": "排水横枝管の管径が 75 mm の場合、大便器の接続は、2 個までとする。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["適当でないもの"], "answerTexts": ["給水横走り管より下方に供給する分岐管は、配管上部から取り出す。"], "answerHints": [["配管上部から"]], "mnemonic": "正しくは：給水横走り管から下方へ供給する分岐管は配管下部から取り出す（上方への分岐は上部から）。", "block": 18, "group": 6}, {"id": "R08_zenki_37", "source": "R8前 No.37", "category": "施工管理法", "type": "single", "question": "渦巻ポンプの試運転における一般的な実施順序として、適当なものはどれか。 A:機器および配管系のエア抜きを行い、満水状態にする。 B:吐出し側弁を全開にする。 C:吐出し側弁を全閉にする。 D:瞬時運転し、回転方向を確認する。 E:キャビテーション、サージング現象のないことを確認する。 F:連続運転を行い、吐出し側弁を徐々に閉じて規定水量に調整する。 G:連続運転を行い、吐出し側弁を徐々に開いて規定水量に調整する。", "choices": [{"label": "1", "text": "A → B → D → E → F"}, {"label": "2", "text": "A → B → D → F → E"}, {"label": "3", "text": "A → C → D → E → G"}, {"label": "4", "text": "A → C → D → G → E"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["適当なもの"], "answerTexts": ["A → C → D → G → E"], "answerHints": [["A → C → D → G → E"]], "mnemonic": "渦巻ポンプ：エア抜き満水→吐出し弁全閉→瞬時運転で回転方向確認→連続運転で弁を徐々に開き規定水量→異常現象の確認。", "block": 18, "group": 6}, {"id": "R07_zenki_50", "source": "R7前 No.50", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "機器の据付けに関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ポンプは、あらかじめ心出し調整されて出荷されているので、現場での調整は不要である。"}, {"label": "2", "text": "洗面器をコンクリート壁に取り付ける場合は、一般的に、エキスパンションボルト又は樹脂製 プラグを使用する。"}, {"label": "3", "text": "冷却塔は、一般的に、補給水口の高さが高置タンクの低水位の高さと同じとなるように据え 付ける。"}, {"label": "4", "text": "排水用水中モーターポンプは、排水流入口から離れた位置に据え付ける。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ポンプは、あらかじめ心出し調整されて出荷されているので、現場での調整は不要である。", "冷却塔は、一般的に、補給水口の高さが高置タンクの低水位の高さと同じとなるように据え 付ける。"], "answerHints": [["現場での調整は不要"], ["低水位の高さと同じ"]], "mnemonic": "正しくは：ポンプは据付け後に現場で心出し調整が必要。冷却塔の補給水口は高置タンクの低水位から3m以上低くする。", "block": 18, "group": 6}, {"id": "R07_kouki_49", "source": "R6後 No.49 / R7後 No.49", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "工程表に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "同一作業を繰り返し行う工事では、タクト工程表を作成する。"}, {"label": "2", "text": "ガントチャート工程表は、縦軸に作業名、横軸に暦日(工期)をとったものである。"}, {"label": "3", "text": "総合工程表の作成では、季節・天候についての考慮は必要ない。"}, {"label": "4", "text": "ネットワーク工程表は、各作業の相互関係が把握しやすい。"}], "answer": ["2", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["ガントチャート工程表は、縦軸に作業名、横軸に暦日(工期)をとったものである。", "総合工程表の作成では、季節・天候についての考慮は必要ない。"], "answerHints": [["横軸に暦日(工期)"], ["考慮は必要ない"]], "mnemonic": "正しくは：ガントチャートは横軸に達成度（%）をとる（暦日をとるのはバーチャート）。総合工程表は季節・天候を考慮する。", "block": 18, "group": 6}, {"id": "R07_kouki_52", "source": "R7後 No.52", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "ダクト及びダクト附属品の施工に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "遠心送風機の吐出し口直近においてダクトを曲げる場合は、送風機の回転方向と逆方向とす る。"}, {"label": "2", "text": "長辺が300 mm 以下の防火ダンパー本体の支持は、2点吊りとする。"}, {"label": "3", "text": "厨房の排気ダクトの防火ダンパーは、温度ヒューズの作動温度を72 °Cとする。"}, {"label": "4", "text": "風量測定口は、ダクトの長辺の寸法が300 mm を超え700 mm 以下の場合、原則として、2 個取り付ける。"}], "answer": ["1", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["遠心送風機の吐出し口直近においてダクトを曲げる場合は、送風機の回転方向と逆方向とす る。", "厨房の排気ダクトの防火ダンパーは、温度ヒューズの作動温度を72 °Cとする。"], "answerHints": [["逆方向"], ["72 °C"]], "mnemonic": "正しくは：送風機吐出し口直近の曲げは回転方向と同じ方向。厨房排気の防火ダンパーの温度ヒューズは120℃（一般は72℃）。", "block": 18, "group": 6}, {"id": "R08_zenki_51", "source": "R8前 No.51", "category": "施工管理法（基礎的な能力）", "type": "multi", "question": "配管の施工に関する記述のうち、適当でないものはどれか。 適当でないものは二つあるので、二つとも答えなさい。", "choices": [{"label": "1", "text": "ポリエチレン管の接合には、メカニカル接合や電気融着接合がある。"}, {"label": "2", "text": "雨水ますには、ます内に排水や固形物が滞留しないようにインバートを設ける。"}, {"label": "3", "text": "排水用硬質塩化ビニルライニング鋼管は、ねじ接合とする。"}, {"label": "4", "text": "鋼管のねじ加工には、切削ねじ加工と転造ねじ加工がある。"}], "answer": ["2", "3"], "selectCount": 2, "answerKeys": ["適当でないもの"], "answerTexts": ["雨水ますには、ます内に排水や固形物が滞留しないようにインバートを設ける。", "排水用硬質塩化ビニルライニング鋼管は、ねじ接合とする。"], "answerHints": [["インバートを設ける"], ["ねじ接合とする"]], "mnemonic": "正しくは：雨水ますは泥だめを設ける（インバートは汚水ます）。排水用塩ビライニング鋼管は排水鋼管用可とう継手（MDジョイント）で接合。", "block": 18, "group": 6}, {"id": "R07_zenki_40", "source": "R7前 No.40", "category": "法規", "type": "single", "question": "労働時間に関する記述のうち、「労働基準法」上、誤っているものはどれか。 ただし、労働組合等との協定等による別の定めがある場合を除く。", "choices": [{"label": "1", "text": "使用者は、労働者に、休憩時間を除き1 週間について40 時間を超えて、労働させてはなら ない。"}, {"label": "2", "text": "使用者は、その雇入れの日から起算して6箇月間継続勤務し全労働日の8割以上出勤した 労働者に対して、継続し、又は分割した10 労働日の有給休暇を与えなければならない。"}, {"label": "3", "text": "使用者は、労働者に対して、8 週間を通じ8日以上の休日を与えなければならない。"}, {"label": "4", "text": "使用者は、労働時間が6時間を超える場合においては少なくとも45 分、8時間を超える場合 においては少なくとも1時間の休憩時間を労働時間の途中に与えなければならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["使用者は、労働者に対して、8 週間を通じ8日以上の休日を与えなければならない。"], "answerHints": [["8 週間を通じ8日以上"]], "mnemonic": "正しくは：休日は毎週少なくとも1日、又は4週間を通じ4日以上。", "block": 18, "group": 6}, {"id": "R07_zenki_43", "source": "R7前 No.43", "category": "法規", "type": "single", "question": "管工事業に関する記述のうち、「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "管工事業の許可を受けた者が、工事1件の請負代金の額が500 万円未満の軽微な工事を施工 する場合は、主任技術者を置かなくてもよい。"}, {"label": "2", "text": "建設業の許可は、5年ごとにその更新を受けなければ、その期間の経過によって、その効力 を失う。"}, {"label": "3", "text": "2 級管工事施工管理技士は、管工事業に係る一般建設業の許可を受ける際、営業所ごとに 専任で置く技術者の要件を満たしている。"}, {"label": "4", "text": "管工事業の許可を受けた者が管工事を請け負う場合、当該工事に附帯する電気工事を請け負 うことができる。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["管工事業の許可を受けた者が、工事1件の請負代金の額が500 万円未満の軽微な工事を施工 する場合は、主任技術者を置かなくてもよい。"], "answerHints": [["主任技術者を置かなくてもよい"]], "mnemonic": "正しくは：許可業者は軽微な工事（500万円未満）でも主任技術者を置く必要がある。", "block": 18, "group": 6}, {"id": "R07_zenki_46", "source": "R7前 No.46", "category": "法規", "type": "single", "question": "建設資材のうち、「建設工事に係る資材の再資源化等に関する法律」上、再資源化が特に 必要とされる特定建設資材に該当しないものはどれか。", "choices": [{"label": "1", "text": "プラスチック"}, {"label": "2", "text": "アスファルト・コンクリート"}, {"label": "3", "text": "木材"}, {"label": "4", "text": "コンクリート"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["該当しないもの"], "answerTexts": ["プラスチック"], "answerHints": [["プラスチック"]], "mnemonic": "特定建設資材：コンクリート、コンクリート及び鉄から成る資材、木材、アスファルト・コンクリートの4種。", "block": 18, "group": 6}, {"id": "R07_kouki_39", "source": "R7後 No.39", "category": "法規", "type": "single", "question": "建設工事における安全管理体制に関する記述のうち「労働安全衛生法」上、 誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、移動はしごについては、幅30 cm 以上のものでなければ使用してはならない。"}, {"label": "2", "text": "事業者は、酸素欠乏危険作業に労働者を従事させる場合は、当該作業を行う場所の空気中 の酸素濃度を18 %以上に保つように換気しなければならない。"}, {"label": "3", "text": "ボール盤、面取り盤等を使用する作業において、手の滑りを防止するため、滑り止めを施し た手袋を労働者に着用させなければならない。"}, {"label": "4", "text": "事業者は、足場(つり足場を除く。)における作業を行うときは、点検者を指名しなければ ならない。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["ボール盤、面取り盤等を使用する作業において、手の滑りを防止するため、滑り止めを施し た手袋を労働者に着用させなければならない。"], "answerHints": [["手袋を労働者に着用させなければならない"]], "mnemonic": "正しくは：ボール盤・面取り盤等の回転刃物作業では、巻き込まれ防止のため手袋の使用を禁止する。", "block": 18, "group": 6}, {"id": "R07_kouki_42", "source": "R7後 No.42", "category": "法規", "type": "single", "question": "建築物に設ける配管設備に関する記述のうち、「建築基準法」上、誤っているものはど れか。", "choices": [{"label": "1", "text": "水飲器の排水管は、建築物に設ける排水管に直接連結しなければならない。"}, {"label": "2", "text": "給水立て主管からの各階への分岐管等主要な分岐管には、止水弁を設けなければならない。"}, {"label": "3", "text": "雨水排水立て管は、汚水排水管若しくは通気管と兼用し、又はこれらの管に連結してはならな い。"}, {"label": "4", "text": "排水トラップは、二重トラップとしてはならない。"}], "answer": ["1"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["水飲器の排水管は、建築物に設ける排水管に直接連結しなければならない。"], "answerHints": [["直接連結"]], "mnemonic": "正しくは：水飲器の排水管は排水管に直接連結せず、間接排水とする。", "block": 18, "group": 6}, {"id": "R07_kouki_45", "source": "R7後 No.45", "category": "法規", "type": "single", "question": "屋内消火栓設備の加圧送水装置の方式のうち、「消防法」上、定められていないものは どれか。", "choices": [{"label": "1", "text": "高架水槽方式"}, {"label": "2", "text": "圧力水槽方式"}, {"label": "3", "text": "ポンプ方式"}, {"label": "4", "text": "水道直結方式"}], "answer": ["4"], "selectCount": 1, "answerKeys": ["定められていないもの"], "answerTexts": ["水道直結方式"], "answerHints": [["水道直結方式"]], "mnemonic": "屋内消火栓の加圧送水装置は高架水槽・圧力水槽・ポンプ方式の3つ。", "block": 18, "group": 6}, {"id": "R07_kouki_48", "source": "R7後 No.48", "category": "法規", "type": "single", "question": "産業廃棄物に関する記述のうち、「廃棄物の処理及び清掃に関する法律」上、 誤っているものはどれか。", "choices": [{"label": "1", "text": "事業者は、その事業活動に伴って生じた廃棄物の再生利用等を行うことにより、廃棄物の減 量に努める責務がある。"}, {"label": "2", "text": "建設発生土(建設工事に伴い副次的に得られた土砂)は、産業廃棄物である。"}, {"label": "3", "text": "事業者が産業廃棄物(特別管理産業廃棄物を除く。)を処理する方法として、運搬を産業 廃棄物収集運搬業者に、処分を産業廃棄物処分業者に委託する方法がある。"}, {"label": "4", "text": "建築物等に用いられる材料であって石綿を含むもののうち石綿建材除去事業により除去され た石綿保温材は、特別管理産業廃棄物である。 せん。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建設発生土(建設工事に伴い副次的に得られた土砂)は、産業廃棄物である。"], "answerHints": [["産業廃棄物である"]], "mnemonic": "正しくは：建設発生土は廃棄物ではない（産業廃棄物に該当しない）。", "block": 18, "group": 6}, {"id": "R08_zenki_41", "source": "R8前 No.41", "category": "法規", "type": "single", "question": "建築物に関する記述のうち、「建築基準法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "建築しようとする場合に建築の確認の申請が必要な建築物について、大規模の模様替えをしよ うとする場合は、確認の申請が必要である。"}, {"label": "2", "text": "建築しようとする場合に建築の確認の申請を必要としない建築物であれば、建築基準法は適 用されない。"}, {"label": "3", "text": "建築の確認の申請が必要な建築物を建築する工事は、確認済証の交付を受けた後でなければ 工事をすることはできない。"}, {"label": "4", "text": "建築の確認の申請が必要な建築物を建築する工事の施工者は、当該工事に係る設計図書を当該 工事現場に備えておかなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["建築しようとする場合に建築の確認の申請を必要としない建築物であれば、建築基準法は適 用されない。"], "answerHints": [["建築基準法は適 用されない"]], "mnemonic": "正しくは：確認申請が不要な建築物でも、建築基準法の規定は適用される。", "block": 18, "group": 6}, {"id": "R08_zenki_44", "source": "R8前 No.44", "category": "法規", "type": "single", "question": "建設業の許可を受けた建設業者が、工事現場に置く主任技術者に関する記述のうち、 「建設業法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "主任技術者は、当該建設工事の施工計画の作成、工程管理、品質管理その他の技術上の管 理及び当該建設工事の施工に従事する者の技術上の指導監督の職務を誠実に行わなけれ ばならない。"}, {"label": "2", "text": "工事現場における建設工事の施工に従事する者は、主任技術者がその職務として行う指導 に従わなければならない。"}, {"label": "3", "text": "一級建築士免許の交付を受けた者は、管工事の工事現場に置く主任技術者の要件に該当す る。"}, {"label": "4", "text": "2級管工事施工管理技術検定の第二次検定に合格した者は、管工事の工事現場に置く主任技 術者の要件に該当する。"}], "answer": ["3"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["一級建築士免許の交付を受けた者は、管工事の工事現場に置く主任技術者の要件に該当す る。"], "answerHints": [["一級建築士免許"]], "mnemonic": "正しくは：一級建築士は管工事の主任技術者の要件に該当しない（管工事施工管理技士等が該当）。", "block": 18, "group": 6}, {"id": "R08_zenki_47", "source": "R8前 No.47", "category": "法規", "type": "single", "question": "浄化槽に関する記述のうち、「浄化槽法」上、誤っているものはどれか。", "choices": [{"label": "1", "text": "浄化槽工事業を営もうとする者は、当該業を行おうとする区域を管轄する都道府県知事 の登録を受けなければならない。"}, {"label": "2", "text": "浄化槽工事を行うときは、1級又は2級管工事施工管理技士が、自ら工事を行うか、実 地に監督しなければならない。"}, {"label": "3", "text": "浄化槽工事業者は、浄化槽工事の現場ごとに、その見やすい場所に、氏名又は名称、登録 番号等を記載した標識を掲げなければならない。"}, {"label": "4", "text": "浄化槽を新たに設置する場合、使用開始後3 か月を経過した日から5 か月間の期間内に、指 定検査機関の行う水質に関する検査を受けなければならない。"}], "answer": ["2"], "selectCount": 1, "answerKeys": ["誤っているもの"], "answerTexts": ["浄化槽工事を行うときは、1級又は2級管工事施工管理技士が、自ら工事を行うか、実 地に監督しなければならない。"], "answerHints": [["1級又は2級管工事施工管理技士"]], "mnemonic": "正しくは：浄化槽工事は浄化槽設備士が自ら行うか実地に監督する。", "block": 18, "group": 6}];
